local E = ns.DB.entries
E["item:a-letter-to-grelin-whitebeard"] = {t="item",n="A Letter to Grelin Whitebeard",z="dunmorogh",s="A letter from Ironforge reaches Grelin Whitebeard at his camp in Coldridge Valley. Its news and instructions bring the mountain capital close to the snowy frontier.",h="A letter from Ironforge reaches Grelin Whitebeard at his camp in Coldridge Valley.",sec={{t="A Dispatch from the Mountain",b="Grelin Whitebeard receives a dispatch from Ironforge at his camp in Coldridge Valley. Anvilmar offers shelter, but the valley lies far from its safety. Letters link scouts and scholars in the field with the halls of the mountain capital. This one has come south along the mountain paths to reach him.",sp=0}},faq={{q="Who is Grelin Whitebeard?",a="Grelin Whitebeard is a dwarven scout and explorer camped in southeastern Coldridge Valley. Messengers from Anvilmar bring him news and instructions from Ironforge.",al={"grelin whitebeard","who is grelin","recipient"},it="target"},{q="Where did this letter come from?",a="The letter comes from Ironforge, the dwarven capital. A local postal courier carries it through Coldridge Valley and out to the field.",al={"letter origin","who sent the letter","where is it from"},it="origin"},{q="What is inside the letter?",a="King Magni Bronzebeard sends Grelin a short note. With no time to spare, he gives Grelin authority to deal with the trolls as he sees fit, especially if Grelin can find a quick solution. Grelin welcomes the word; it has been a while since he last heard from Ironforge.",al={"letter contents","what does it say","letter text"},it="item"},{q="What is A Letter to Grelin Whitebeard?",a="It is a sealed missive sent from Ironforge, carried down through Coldridge Valley for delivery to Grelin Whitebeard at his camp along the road.",al={"what is grelin whitebeard letter","letter to grelin whitebeard","what is this letter"},it="identity",add="163f292d"},{q="Why does Grelin Whitebeard want this letter?",a="Grelin has been stationed out at his camp in Coldridge Valley for some time without news from the capital. He is eager to receive word from Ironforge.",al={"why deliver letter to grelin","why does grelin want the letter","who wants grelins letter"},it="why_wanted",add="b0fcb20c"}},ang={["race:Dwarf"]="As a dwarf, you may carry dispatches across Dun Morogh’s freezing passes. Young mountaineers and recruits do so as a basic duty, hoping to make a name for themselves."},kw={"coldridge valley","dun morogh","grelin whitebeard","ironforge","letter","mail delivery"},rel={"quest:233","npc:grelin-whitebeard","subzone:coldridge-valley","zone:ironforge","zone:dunmorogh"},src={"A Letter to Grelin Whitebeard","Coldridge Valley Mail Delivery (2)"}}
E["item:a-stack-of-letters"] = {t="item",n="A Stack of Letters",z="dunmorogh",s="In Coldridge Valley, a stack of letters has come through the mountain pass for scouts in the snowy wilderness.",h="In Coldridge Valley, a stack of letters has come through the mountain pass for scouts in the snowy wilderness.",sec={{t="Through the Pass",b="Letters for Coldridge Valley come from Anvilmar by way of travelers crossing the pass. The road to the remote camps in Dun Morogh's mountains is hard, so postal runners rely on travelers to carry each bundle onward. This one is bound for scouts deeper in Coldridge Valley.\n\nUntil the letters are sorted, Talin Keeneye at his lakeside camp is thought to be the only recipient. Among them is a missive for Grelin Whitebeard, a mountaineer.",sp=0}},faq={{q="What is inside the stack of letters?",a="The bundle holds personal letters and dispatches for dwarves in Coldridge Valley. Talin Keeneye at his camp near the frozen lake is thought to be the only recipient until the letters reveal one addressed to Grelin Whitebeard.",al={"what is in the letters","stack of letters contents","who are letters for"},it="item"},{q="Who sends these letters to Coldridge Valley?",a="The letters came through the pass into Coldridge Valley and reached Anvilmar. From there, a traveler willing to carry them down the road took them onward.",al={"where did the letters come from","who sent the letters"},it="origin"},{q="Who receives the letters?",a="The dwarf scout Talin Keeneye receives the parcel at his camp by the frozen lake. Looking through the stack, he finds a letter for Grelin Whitebeard.",al={"who gets the letters","letter delivery target"},it="target"},{q="What is A Stack of Letters?",a="It is a bundle of mail that arrived in Coldridge Valley through the mountain pass. Entrusted to you at Anvilmar, the stack contains correspondence meant for local mountaineers stationed out in the snowy wilderness.",al={"what is the stack of letters","stack of letters item","what are the letters"},it="identity",add="6f17116a"},{q="Why does anyone want A Stack of Letters?",a="The mountaineers living and patrolling out in the cold rely on regular post to stay informed. Talin Keeneye has been waiting by the frozen lake for these dispatches for quite some time, though upon inspection, not every letter in the bundle belongs solely to him.",al={"why deliver the letters","why does talin want the letters","stack of letters purpose"},it="why_wanted",add="9fce371d"}},ang={["race:Dwarf"]="As a young mountaineer starting out in Coldridge Valley, you carry mail between snowy camps. The journey introduces you to Dun Morogh's harsh roads and scattered watchers."},kw={"anvilmar","coldridge valley","coldridge valley mail delivery","grelin whitebeard","stack of letters","talin keeneye"},rel={"quest:233","subzone:coldridge-valley","npc:grelin-whitebeard","zone:dunmorogh"},src={"A Stack of Letters","Coldridge Valley Mail Delivery"}}
E["item:alterac-granite"] = {t="item",n="Alterac Granite",z="dunmorogh",s="Near Darrow Hill in the northern Hillsbrad Foothills, Alterac Granite draws master stonecutters with its resilience and grain. King Magni Bronzebeard’s royal mason insists on the stone for a tribute to fallen soldiers.",h="Near Darrow Hill in the northern Hillsbrad Foothills, Alterac Granite draws master stonecutters with its...",sec={{t="Stone of Memorials",b="King Magni Bronzebeard ordered a monument to Sully Balloo, a brave dwarven defender who died in the tragedy at the Thandol Span. Grand Mason Marblesten was charged with sculpting it in Ironforge. He insisted on Alterac Granite instead of ordinary quarry stone. Few stones in the Eastern Kingdoms are finer, and its durability keeps a fallen hero’s likeness and memory untarnished for generations.",sp=0},{t="Quarried in Peril",b="Alterac Granite lies around Darrow Hill in the northern Hillsbrad Foothills, near the ruined territories of Alterac. Hostile wildlife, syndicate brigands and lingering strife make the journey perilous. To bring unblemished slabs to Ironforge’s artisans, you must venture deep into contested lands.",sp=0}},faq={{q="What is Alterac Granite used for?",a="Grand Mason Marblesten in Ironforge requested Alterac Granite for a royal memorial to Sully Balloo, the dwarven soldier who fell defending the Thandol Span.",al={"alterac granite use","why alterac granite","marblesten stone"},it="why_wanted"},{q="Where can Alterac Granite be found?",a="You can gather Alterac Granite from deposits at Darrow Hill in the northern Hillsbrad Foothills, near the border of Alterac.",al={"alterac granite location","where to get alterac granite","darrow hill granite"},it="origin",gp=true},{q="Why did Grand Mason Marblesten specifically want this stone?",a="Grand Mason Marblesten considers Alterac Granite one of the finest and most resilient carving stones available. He deems it worthy of the lasting royal monument King Magni commissioned.",al={"why marblesten wants granite","why alterac stone"}},{q="Who was Sully Balloo?",a="Sully Balloo was a dwarven soldier who died during the fighting at the Thandol Span. King Magni Bronzebeard commissioned a monument to honor his sacrifice for the Alliance.",al={"sully balloo","who died at thandol span"}},{q="What is Alterac Granite?",a="Alterac Granite is a prized, high-quality quarry stone found in the northern hills. Renowned among master stonecutters as one of the finest carving stones available, it possesses the durability and pristine grain needed to craft epic, enduring monuments worthy of royal commissions.",al={"what is alterac granite","alterac granite item","alterac granite info"},it="identity",add="9814170d"},{q="Where does Alterac Granite come from, and who made it?",a="Alterac Granite is a natural stone quarried from Darrow Hill in the foothills of Hillsbrad, bordering the rugged mountains of Alterac. It is not manufactured by any craftsman; rather, it is hewn directly from the ancient rock of the hills, waiting for skilled masons to shape it into enduring works.",al={"alterac granite origin","where is alterac granite mined","who made alterac granite"},it="origin",add="842d3593"}},ang={["race:Dwarf"]="As a dwarf, you know why dwarven stonemasons prize quality. This robust mountain stone honors a fellow son of Ironforge.",["profession:Mining"]="As a miner or prospector, you can appreciate Alterac Granite’s clean fracture and extraordinary density. These qualities set it apart from common crag rock."},kw={"alterac granite","darrow hill","hillsbrad","ironforge","marblesten","sully balloo","thandol span"},rel={"npc:grand-mason-marblesten","quest:686","subzone:darrow-hill","subzone:thandol-span","quest:631","zone:ironforge","topic:alterac-kingdom","zone:dunmorogh"},src={"Alterac Granite","A King's Tribute (2)"}}
E["item:barrel-of-barleybrew-scalder"] = {t="item",n="Barrel of Barleybrew Scalder",z="dunmorogh",s="At Kharanos, Marleth Barleybrew sends a cask of Scalder toward the Thunderbrew Distillery. He means to prove his brewing can rival the Thunderbrews, his chief competitors.",h="At Kharanos, Marleth Barleybrew sends a cask of Scalder toward the Thunderbrew Distillery.",sec={{t="A Bitter Feud in Dun Morogh",b="The Thunderbrews and Barleybrews contend fiercely over brewing in Dun Morogh. The Thunderbrews are renowned for their busy distillery in Kharanos. Marleth Barleybrew will not live in their shadow. So he brews fiery Scalder to show his recipes can rival theirs. He hopes those who taste it will see the Thunderbrews do not own the art of fine dwarven drink.",sp=0},{t="Subterfuge in the Cellar",b="The barrel is bound for the cellars beneath the Thunderbrew Distillery. There it will take the place of a cask of Thunder Ale, a local favorite. Wounded pride has given rise to a prank, not poison or ruin. The next batch served upstairs will secretly be Barleybrew's potent Scalder.",sp=1}},faq={{q="What is inside the Barrel of Barleybrew Scalder?",a="The barrel holds Marleth Barleybrew's signature Scalder, a potent dwarven brew made to rival the Thunderbrew family's famed recipes.",al={"barleybrew scalder contents","what kind of ale","what is scalder"},it="item"},{q="Why does Marleth want this barrel swapped?",a="Marleth admits the Thunderbrews make good drinks, but he wants them to learn humility. He hopes cellar patrons will taste his brew without knowing it and find Barleybrew craftsmanship just as good, if not better.",al={"why swap barrels","bitter rivals reason","why marleth sneak brew"},it="why_wanted"},{q="Where does this barrel go?",a="The barrel goes into the cellar beneath the Thunderbrew Distillery in Kharanos. It takes the place on the racks of a cask of Thunder Ale due to be tapped.",al={"where do i put the barrel","scalder barrel location","distillery cellar"},it="purpose"},{q="Is the brew meant to harm anyone?",a="No. The brew is a strong dwarven ale meant to rival the Thunderbrews'. The families' rivalry is fierce, but it comes from professional pride, not malice.",al={"is scalder poisoned","is it poison","will it hurt anyone"},it="threat"},{q="What is the Barrel of Barleybrew Scalder?",a="It is a cask of potent ale crafted by Marleth Barleybrew. Rather than being sold through standard trade, this specific barrel serves as an instrument in a brewing rivalry, intended to be secretly substituted into a competitor's stock to win over unsuspecting drinkers.",al={"what is barleybrew scalder","barleybrew scalder barrel","barrel of barleybrew scalder"},it="identity",add="9f414f7e",nx={6}},{q="Where does the Barrel of Barleybrew Scalder come from, and who made it?",a="The cask was brewed and provided by Marleth Barleybrew. Proud of his family's craft, Marleth concocted the recipe to prove that the Barleybrews can match or exceed the renown of the rival Thunderbrew family.",al={"who made barleybrew scalder","where did barleybrew scalder come from","barleybrew scalder origin"},it="origin",add="00d1bcdd"}},ang={["race:Dwarf"]="As a dwarf, you know ale crafting as both an art and a bloodsport. Dun Morogh's recipe rivalries reach all the way into the cellar.",["class:Rogue"]="As a rogue, you can distract a cellar guard and slip heavy contraband into a guarded stash. Here, you get a taste of dwarven subterfuge with little at stake."},kw={"ale","barleybrew","distillery","dun morogh","kharanos","marleth","scalder","thunderbrew"},rel={"quest:310","quest:311","item:barrel-of-thunder-ale","subzone:thunderbrew-distillery","subzone:kharanos","quest:117","zone:dunmorogh"},src={"Barrel of Barleybrew Scalder","Bitter Rivals"}}
E["item:barrel-of-shimmer-stout"] = {t="item",n="Barrel of Shimmer Stout",z="dunmorogh",s="In Dun Morogh, a barrel of Shimmer Stout is bound for the mountain watch. Rejold Barleybrew sends his experimental ale to the high passes, where drinkers say it brightens their vision.",h="In Dun Morogh, a barrel of Shimmer Stout is bound for the mountain watch.",sec={{t="A Brewer's Pride",b="Rejold Barleybrew made Shimmer Stout from ingredients gathered across Dun Morogh. The recipe is the newest work of the Barleybrew family. Its dwarven brewers vie to make ales hearty enough for the mountain cold. Rejold brewed this stout to warm the gut and sharpen the senses of those posted in the wind.",sp=0},{t="Supplies for the Watch",b="The barrel is bound for Mountaineer Wellart Barleybrew at the southern tower on the pass into Loch Modan. Mountaineers there endure cold and long watches between skirmishes with troggs and wildlife. A cask of family ale brings a taste of home. Its kick can leave a tired sentry feeling able to see clearly in the dark.",sp=0}},faq={{q="What is in the Barrel of Shimmer Stout?",a="The barrel holds Shimmer Stout, an experimental dwarven ale brewed by Rejold Barleybrew. Drinkers say its potent kick brightens their vision.",al={"what is shimmer stout","what kind of ale is this","shimmer stout drink"},it="identity"},{q="Who made this barrel of stout?",a="Rejold Barleybrew brewed the stout. He belongs to the Barleybrew family of Dun Morogh and spent time perfecting the recipe to impress his kin.",al={"who brewed shimmer stout","shimmer stout brewer","rejold barleybrew"},it="origin"},{q="Who is this barrel meant for?",a="The barrel is meant for Rejold's brother, Mountaineer Wellart Barleybrew. Wellart guards the southern tower on the road into Loch Modan.",al={"who gets the barrel","where does the stout go","wellart barleybrew"},it="why_wanted"},{q="What effect does Shimmer Stout have on someone who drinks it?",a="Shimmer Stout gives drinkers a potent buzz and makes them feel as if they can see in pitch darkness. Its kick makes it popular among vigilant mountaineers.",al={"shimmer stout effect","does it make you see in dark","what does shimmer stout do"},it="power"}},ang={["race:Dwarf"]="As a dwarf, you know brewing is a cornerstone of Ironforge society. Bringing a newly perfected stout to a kinsman on watch is an honorable mountain tradition.",["profession:Cooking"]="As a cook, you know dwarven brewers experiment with hardy mountain ingredients and potent fermentation. They make ales for biting weather."},kw={"barrel of shimmer stout","dun morogh","dwarven ale","loch modan","mountaineer barleybrew","rejold barleybrew","shimmer stout"},rel={"quest:413","npc:mountaineer-barleybrew","quest:415","quest:414","zone:dunmorogh","zone:lochmodan"},src={"Barrel of Shimmer Stout","Shimmer Stout (quest)"}}
E["item:barrel-of-thunder-ale"] = {t="item",n="Barrel of Thunder Ale",z="dunmorogh",s="In Kharanos, the Thunderbrew Distillery has lost a barrel of Thunder Ale. Marleth's Barleybrew Scalder was meant to take its place, turning a brewing feud into foul play.",h="In Kharanos, the Thunderbrew Distillery has lost a barrel of Thunder Ale.",sec={{t="A Bitter Trade",b="The Thunderbrews of Kharanos and the Barleybrews of Brewnall Village are bitter rivals. Marleth Barleybrew tried to slip a barrel of his Barleybrew Scalder into the Thunderbrews' cellar. He hoped their patrons would choose his brew. The Thunder Ale barrel was seized in the exchange, proof that the switch succeeded despite the local guards.",sp=0}},faq={{q="What is inside this barrel?",a="The barrel holds Thunder Ale, the famous stout brewed by the Thunderbrew family in Kharanos. Across Dun Morogh, it is known as a potent dwarven ale.",al={"thunder ale contents","what is thunder ale"},it="identity"},{q="Where did this barrel come from?",a="The barrel came from cellar storage inside the Kharanos Distillery. It was taken during the secret delivery of Marleth's rival brew.",al={"where do you get it","thunder ale location"},it="origin"},{q="Who wants this barrel?",a="Marleth Barleybrew wants the barrel. He is in Brewnall Village to the west and expects it as proof that his Scalder was planted among the Thunderbrews' barrels.",al={"who do i bring thunder ale to","marleth barleybrew quest"},it="why_wanted"},{q="Why was the barrel taken?",a="Marleth wanted proof that someone entered the Thunderbrew cellar, slipped past the distillery guard, and sabotaged his rivals' supply.",al={"why steal thunder ale","bitter rivals story"},it="why_wanted"}},ang={["race:Dwarf"]="As a dwarf, you know brewing carries serious weight in both business and politics. Swapping a rival clan's prized cask in its own cellar is an audacious insult.",["class:Rogue"]="As a rogue, you can see the skill it takes to slip into a guarded cellar and switch heavy ale barrels without raising the alarm."},kw={"barrel of thunder ale","brewnall village","dun morogh","kharanos","marleth barleybrew","thunder ale","thunderbrew"},rel={"quest:311","quest:310","npc:marleth-barleybrew","subzone:kharanos","subzone:brewnall-village","zone:dunmorogh"},src={"Barrel of Thunder Ale","Return to Marleth"}}
E["item:cask-of-shimmer-stout"] = {t="item",n="Cask of Shimmer Stout",z="dunmorogh",s="In Dun Morogh's cold heights, Cask of Shimmer Stout is bound for the eastern mountains. Rejold Barleybrew brewed the potent new ale, and his brother sends a cask east as a gift for fellow dwarven mountaineers.",h="In Dun Morogh's cold heights, Cask of Shimmer Stout is bound for the eastern mountains.",sec={{t="A Spirited Delivery",b="Rejold Barleybrew brews Shimmer Stout in Brewnall Village. Local patrons and mountaineers who brave Dun Morogh's biting frosts take to it quickly. Impressed by the brew, his brother Mountaineer Barleybrew commissions a cask for the journey through the eastern pass into Loch Modan. Dwarves prize strong drink for company and warmth in the mountain chill. Sharing fresh ale with comrades on distant patrols is a military tradition.",sp=0},{t="A Dwarven Pick-Me-Up",b="During his watch in Thelsamar, Mountaineer Kadrell opens the cask and samples the brew. Shimmer Stout lives up to its name: one draught is said to lighten the limbs and make a soldier feel as though he could fly. A dwarven scout on a long, lonely patrol along the high roads might welcome such an invigorating drink.",sp=0}},faq={{q="What is Shimmer Stout?",a="Rejold Barleybrew brews Shimmer Stout in Dun Morogh's cold heights. Its potent kick is renowned for invigorating the body and keeping the cold at bay.",al={"what is shimmer stout","shimmer stout lore","who brewed shimmer stout"},it="identity"},{q="Who is the cask being sent to?",a="The cask is bound for Mountaineer Kadrell, a guard stationed along the road through Thelsamar in Loch Modan.",al={"who gets the cask","where does cask go","cask recipient"}},{q="Why send ale across the mountains?",a="Dwarven mountaineers often share fine brews with comrades on distant patrols. After tasting Rejold Barleybrew's new creation, his brother wants Kadrell to try it.",al={"why delivery","why deliver beer","why send to kadrell"}},{q="What effect does Shimmer Stout have on the drinker?",a="Shimmer Stout is surprisingly potent. After tasting it, Mountaineer Kadrell says it makes his head spin, lightens his limbs, and leaves him feeling as if he could fly.",al={"how strong is shimmer stout","shimmer stout effect"},it="power"},{q="Where does the Cask of Shimmer Stout come from, and who made it?",a="This potent brew was crafted by Rejold Barleybrew in Brewnall Village in Dun Morogh. His brother, Mountaineer Barleybrew, was so impressed with the concoction that he packaged up this cask to share outside their homeland, having an adventurer carry it all the way into Loch Modan.",al={"who made shimmer stout","where is shimmer stout from","cask of shimmer stout brewer"},it="origin",add="aa5543f0"},{q="Why does anyone want the Cask of Shimmer Stout?",a="Mountaineer Barleybrew loves his brother's new recipe and wants a fellow watchman, Mountaineer Kadrell, to sample the batch. Kadrell patrols the chilly roads around Thelsamar, and a sturdy dwarven ale that warms the blood, lightens the limbs, and turns the head makes fine cheer during long watches.",al={"why send shimmer stout","who wants the cask of shimmer stout","why does kadrell want shimmer stout"},it="why_wanted",add="3b29018e"}},ang={["race:Dwarf"]="As a dwarf, you know that sharing fine ale between patrols is a respected tradition. It binds the far-flung Mountaineers across the rugged peaks of Khaz Modan."},kw={"cask of shimmer stout","dun morogh","kadrell","loch modan","rejold barleybrew","shimmer stout","thelsamar"},rel={"quest:414","npc:mountaineer-kadrell","quest:413","quest:415","subzone:thelsamar","zone:lochmodan","zone:dunmorogh"},src={"Cask of Shimmer Stout","Stout to Kadrell"}}
E["item:consecrated-rune"] = {t="item",n="Consecrated Rune",z="dunmorogh",s="At Anvilmar in Coldridge Valley, the Consecrated Rune calls fledgling dwarven paladins to their formal duties as Knights of the Silver Hand.",h="At Anvilmar in Coldridge Valley, the Consecrated Rune calls fledgling dwarven paladins to their formal duties...",sec={{t="A Calling to the Silver Hand",b="Among the Knights of the Silver Hand, a Consecrated Rune marks a novice dwarf’s place. Dwarven paladins receive one in Coldridge Valley after proving their basic skill in arms. Sacred words are inscribed upon it, and the Holy Light blesses the rune.\n\nBromos Grummner, the paladin trainer inside Anvilmar, sends it as an official summons. Dwarves greatly respect the Holy Light traditions their human allies introduced to them. Reading the rune confirms a novice’s place in the order and marks the beginning of service.",sp=0}},faq={{q="What is the Consecrated Rune used for?",a="The Consecrated Rune summons novice dwarven paladins to seek Bromos Grummner inside Anvilmar and continue their paladin training.",al={"consecrated rune purpose","what does the rune do","consecrated rune quest item"},it="item",gp=true},{q="Who sends the Consecrated Rune?",a="Bromos Grummner sends the Consecrated Rune from Anvilmar in Coldridge Valley, where he trains dwarven paladins.",al={"who gave me consecrated rune","rune origin","bromos grummner rune"},it="origin"},{q="Why do dwarven paladins follow the traditions of the Silver Hand?",a="Dwarves learned much of the Holy Light and the Silver Hand’s ways from human mentors. They revere the order’s history, traditions, and belief that a single sacrifice can alter Azeroth’s fate.",al={"dwarf paladin silver hand","why are dwarves paladins","dwarves and holy light"},it="history"},{q="What is the Consecrated Rune?",a="It is an inscribed dwarven stone blessed in the Holy Light, sent as a formal summons to novice paladins training in Coldridge Valley. Dwarves blend runic craftsmanship with holy teachings, using stones like this one to impart solemn messages and call budding defenders of the Light to their mentors.",al={"what is consecrated rune","consecrated rune item","consecrated rune meaning"},it="identity",add="dda1df9e"},{q="Why does Bromos Grummner want you to have the Consecrated Rune?",a="Bromos Grummner sends the rune to test your readiness and direct you to Anvilmar for formal training. There is trouble brewing across Dun Morogh, and the Knights of the Silver Hand need capable, disciplined hands ready to uphold their sacred duty and safeguard Azeroth from harm.",al={"why consecrated rune","why bromos wants consecrated rune","why do i get consecrated rune"},it="why_wanted",add="924bde77"}},ang={["class:Paladin"]="As a dwarven paladin, receiving the rune marks your formal step into the Knights of the Silver Hand under Bromos Grummner’s guidance.",["race:Dwarf"]="As a dwarf, the rune reflects how human holy traditions have joined dwarven martial culture through the shared alliance and mutual respect between Ironforge and humanity."},kw={"anvilmar","bromos grummner","coldridge valley","consecrated rune","holy light","paladin","silver hand"},rel={"quest:3107","npc:bromos-grummner","subzone:anvilmar","subzone:coldridge-valley","topic:paladin","topic:light","topic:human","zone:dunmorogh"},src={"Consecrated Rune","Consecrated Rune (Classic)"}}
E["item:crate-of-inn-supplies"] = {t="item",n="Crate of Inn Supplies",z="dunmorogh",s="In Coldridge Valley, travelers are needed to carry the Crate of Inn Supplies to Kharanos. Troggs have closed the mountain pass, leaving the Thunderbrew Distillery dependent on their help.",h="In Coldridge Valley, travelers are needed to carry the Crate of Inn Supplies to Kharanos.",sec={{t="Through the Trogg Pass",b="Near Anvilmar, the Crate of Inn Supplies waits for a safe passage through Coldridge Pass. Troggs have cut off the route, keeping civilian couriers from carrying goods until the Mountaineers clear the road. Hands Springsprocket packed tavern provisions for Tannok Frosthammer in Kharanos, where the supplies are needed.",sp=0}},faq={{q="What is inside the crate?",a="The crate holds general tavern supplies for the inn in Kharanos, where travelers and locals seek warmth.",al={"crate contents","inn supplies contents","what is in the box"},it="item"},{q="Who sends the crate to Kharanos?",a="Hands Springsprocket packs the crate near Anvilmar and asks travelers leaving Coldridge Valley to carry it through the mountain pass.",al={"who gives the crate","hands springsprocket","sender"},it="origin"},{q="Why couldn't the normal courier deliver it?",a="Troggs have overrun Coldridge Pass, making it too dangerous for ordinary couriers without Mountaineer escorts. Travelers who can fight through are the inn's immediate hope of receiving the supplies.",al={"why can't hands deliver it","pass blocked","why use an adventurer"},it="motive"},{q="Who receives the supplies?",a="Tannok Frosthammer, the innkeeper's assistant at the Thunderbrew Distillery in Kharanos, receives the parcel.",al={"who gets the crate","tannok frosthammer","kharanos innkeeper"},it="target"},{q="What is the Crate of Inn Supplies?",a="It is a package of goods packed by Hands Springsprocket at Coldridge Pass, meant for the Thunderbrew Distillery and inn over in Kharanos. Because the pass out of Coldridge Valley has been choked off by troggs, the shipment sat delayed until an able-bodied traveler could haul it through.",al={"what is crate of inn supplies","crate of inn supplies quest item","what is this crate"},it="identity",add="bc2f2ebd"},{q="Why is the Crate of Inn Supplies needed in Kharanos?",a="Tannok Frosthammer, assistant at the Kharanos inn, has been waiting on fresh stock from Coldridge Valley while word has been scarce due to the trogg uprising. With regular courier lines cut off, the inn needs these provisions brought through the pass to keep travelers and locals supplied by the fire.",al={"why does tannok want the crate","why do they need inn supplies","crate of inn supplies purpose"},it="why_wanted",add="e676223e"}},ang={["race:Dwarf"]="As a young dwarf, carrying these supplies is your first service beyond Coldridge Valley. You brave the trogg-choked pass to help your kin in Kharanos.",["race:Gnome"]="As a newly arrived gnome, carrying Hands Springsprocket's package is a practical way to earn goodwill among the local dwarves who run Dun Morogh's inns."},kw={"anvilmar","coldridge","crate","frosthammer","hands","kharanos","springsprocket","supplies","tannok","troggs"},rel={"quest:2160","npc:tannok-frosthammer","subzone:kharanos","subzone:anvilmar","topic:trogg","zone:dunmorogh"},src={"Crate of Inn Supplies","Supplies to Tannok"}}
E["item:durnan-s-scalding-mornbrew"] = {t="item",n="Durnan's Scalding Mornbrew",z="dunmorogh",s="Inside Anvilmar, Durnan Furcutter waits for his mug of mornbrew as the mountain cold threatens to cool it before it arrives.",h="Inside Anvilmar, Durnan Furcutter waits for his mug of mornbrew as the mountain cold threatens to cool it...",sec={{t="A Race Against the Cold",b="A courier delayed on the way to Grelin Whitebeard leaves the fresh cup at risk in Coldridge Valley's frost. Carry it up the snowy path to the mountain hall within a few minutes, or Durnan's brew will go cold.",sp=0}},faq={{q="Who is the brew intended for?",a="The brew is meant for Durnan Furcutter, a dwarf stationed inside Anvilmar in Coldridge Valley.",al={"who gets mornbrew","durnan mornbrew receiver","where does brew go"},it="target"},{q="Why does the delivery need to happen so quickly?",a="Dun Morogh's icy air quickly cools an open mug. Durnan ordered scalding mornbrew, and a lukewarm cup will not satisfy him.",al={"why time limit","brew getting cold","why rush mornbrew"}},{q="Where does the delivery originate?",a="The drink is handed off near Grelin Whitebeard's camp outside Anvilmar, after the courier realizes they cannot reach the forge hall in time on their own.",al={"where is mornbrew from","who pours the brew"},it="origin"},{q="What happens once Durnan receives the mug?",a="Durnan pauses his duties inside Anvilmar to savor the steaming drink while it is still hot.",al={"durnan reaction","turn in mornbrew"},it="next_step"},{q="What is Durnan's Scalding Mornbrew?",a="It is a freshly poured mug of hot dwarven mornbrew intended specifically for Durnan Furcutter in Anvilmar. Brewed to warm the bones against Coldridge Valley's biting mountain chill, it must be drunk piping hot to truly hit the spot.",al={"what is scalding mornbrew","durnan mornbrew item","mornbrew drink"},it="identity",add="93832100"},{q="Why does Durnan want the Scalding Mornbrew?",a="Durnan Furcutter ordered the steaming brew to enjoy during a well-earned break from his labors inside Anvilmar. Dwarves take their morning drink seriously, and letting such a hearty mug go chilly would ruin the entire refreshment.",al={"why durnan wants mornbrew","why mornbrew needed","durnan drink purpose"},it="why_wanted",add="c7c22f23"}},ang={["race:Dwarf"]="As a dwarf of Dun Morogh, you know the sting of letting good ale or mornbrew grow cold in the mountain frost."},kw={"anvilmar","coldridge valley","dun morogh","durnan furcutter","mornbrew","scalding"},rel={"npc:durnan-furcutter","quest:3364","subzone:anvilmar","zone:dunmorogh"},src={"Durnan's Scalding Mornbrew","Scalding Mornbrew Delivery"}}
E["item:encrypted-memorandum"] = {t="item",n="Encrypted Memorandum",z="dunmorogh",s="In Coldridge Valley, the Encrypted Memorandum quietly guides new rogues to their trainer. Solm Hargrin disguises his invitation as official communication and calls scoundrels in exile to stand together.",h="In Coldridge Valley, the Encrypted Memorandum quietly guides new rogues to their trainer.",sec={{t="A Discrete Summons",b="In Anvilmar, rogues keep their presence quiet. Their trainer, Solm Hargrin, reaches recruits through the Encrypted Memorandum instead of approaching them in plain view. The coded parchment looks like a directive from distant superiors. It tells fledgling rogues where to find a mentor while keeping local guards and suspicious townsfolk from noticing.",sp=0},{t="Kinship in Coldridge",b="Solm Hargrin's cipher gives practical counsel to rogues in Coldridge Valley. Gnomeregan has fallen, and displaced gnomes now crowd into Dun Morogh's snowbound settlements beside their dwarven allies. Tensions remain close to the surface. Solm urges his students to look out for one another, because scapegoating and prejudice can make rogues answer for every missing trinket.",sp=1}},faq={{q="What is the Encrypted Memorandum?",a="The Encrypted Memorandum is a coded parchment delivered to beginning rogues in Coldridge Valley. It directs them to seek training while appearing to be an official dispatch.",al={"what is encrypted memorandum","memorandum item","rogue note"},it="identity"},{q="Who wrote this memorandum?",a="Solm Hargrin wrote the memorandum. The rogue trainer in Anvilmar disguises it as official orders to gather fellow scoundrels discreetly.",al={"who wrote the memorandum","who sent encrypted memorandum","author of memorandum"},it="origin"},{q="Why is the message encrypted?",a="Rogues in Coldridge Valley avoid public scrutiny. The disguise makes the invitation look like routine official business, so local authorities and curious onlookers do not notice the training.",al={"why encrypted","why ciphered","why is it coded"},it="motive"},{q="What does Solm Hargrin want?",a="Solm Hargrin wants to offer combat training, guidance, and mutual protection. He urges rogues to stick together in crowded Dun Morogh, where thieves are quickly blamed for missing items.",al={"what does solm want","why find solm","solm purpose"},it="wants"},{q="Why does anyone want the Encrypted Memorandum?",a="The memorandum is intended solely for you. Solm Hargrin, the rogue trainer in Coldridge Valley, crafted it as an invitation to fellow practitioners of your shared craft. Disguised as official correspondence, it is meant to draw you into contact with him without attracting unwanted scrutiny from the locals in Anvilmar.",al={"why want encrypted memorandum","who wants the encrypted memorandum","encrypted memorandum purpose"},it="why_wanted",add="88db5375"}},ang={["class:Rogue"]="As a rogue, you can follow this coded letter to your trainer in Anvilmar and answer his summons in Dun Morogh.",["race:Gnome"]="As a gnome, you live among dwarven allies after Gnomeregan's fall. This note gives gnomish rogues a quiet call to stand together and survive."},kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","gnomeregan","rogue trainer","solm hargrin"},rel={"quest:3113","npc:solm-hargrin","subzone:anvilmar","subzone:coldridge-valley","topic:rogue","zone:gnomeregan","zone:dunmorogh"},src={"Encrypted Memorandum","Encrypted Memorandum (quest)"}}
E["item:encrypted-rune"] = {t="item",n="Encrypted Rune",z="dunmorogh",s="In Coldridge Valley, the Encrypted Rune calls promising new rogues to Anvilmar. Its message bids them decipher the words and seek out Solm Hargrin.",h="In Coldridge Valley, the Encrypted Rune calls promising new rogues to Anvilmar.",sec={{t="A Coded Summons",b="A new rogue must read thieves' cant to understand the rune. In doing so, they meet the shadowy craft needed to survive Dun Morogh's harsh wilderness. Its ciphers bear a private summons from Solm Hargrin, the rogue mentor in Anvilmar, for those who show promise in stealth and cunning.",sp=0},{t="Eyes in the Shadows",b="Deciphering the rune leads new rogues to Solm Hargrin inside Anvilmar. He hopes to strengthen the valley's covert ranks as local tensions rise. Solm teaches bladecraft and stealth, but also vigilance and camaraderie. With peace strained, rogues need to stand together.",sp=0}},faq={{q="What is the Encrypted Rune?",a="The Encrypted Rune carries a coded message for fledgling rogues in Coldridge Valley. It directs them to report to Solm Hargrin inside Anvilmar for training.",al={"what is this rune","encrypted rune purpose","what does the rune do"},it="identity"},{q="Who sent the Encrypted Rune?",a="Solm Hargrin, the rogue trainer in Anvilmar, sends the Encrypted Rune to summon new recruits quietly.",al={"who wrote it","who gave this","sender of rune"},it="origin"},{q="Where should I take the rune?",a="Take the deciphered instructions to Solm Hargrin inside Anvilmar, in Coldridge Valley.",al={"where do i go","who do i bring it to","where is solm"},it="next_step",gp=true},{q="Why is the message encrypted?",a="The cipher lets only an aspiring rogue who can read it heed the call. It keeps rogue methods out of plain view.",al={"why cipher","why is it coded","why secret rune"}},{q="Why was the Encrypted Rune sent to you?",a="Solm Hargrin, the rogue trainer in Anvilmar, sent the rune to catch your attention as an up-and-coming rogue in Coldridge Valley. With increased trouble stirring in Dun Morogh, he is scouting capable hands among the dwarves and gnomes who know how to keep a cold blade and stick to the shadows, inviting you to seek him out for further training.",al={"why do i have the encrypted rune","why did solm send the encrypted rune","purpose of encrypted rune"},it="why_wanted",add="1ca7ae1e"}},ang={["class:Rogue"]="As a rogue, you meet Dun Morogh's rogues through this first formal contact. Your training begins in stealth, quick blades, and survival.",["race:Dwarf"]="As a dwarf, you are another child of Ironforge in Coldridge Valley. The rune calls you to master the shadows and protect the clan's interests from beneath the surface."},kw={"anvilmar","cipher","coldridge valley","dun morogh","encrypted rune","rogue","solm hargrin"},rel={"npc:solm-hargrin","quest:3109","subzone:anvilmar","subzone:coldridge-valley","topic:rogue","zone:dunmorogh","zone:ironforge","zone:gnomeregan"},src={"Encrypted Rune","Encrypted Rune (Classic)"}}
E["item:etched-rune"] = {t="item",n="Etched Rune",z="dunmorogh",s="In Coldridge Valley, the Etched Rune calls promising dwarven hunters to Anvilmar. Hunter trainer Thorgas Grimson sends it to begin their instruction in the wilderness.",h="In Coldridge Valley, the Etched Rune calls promising dwarven hunters to Anvilmar.",sec={{t="Call of the Wild",b="Dwarven runes mark the Etched Rune, sent to novices who show promise in Coldridge Valley’s snowdrifts. Mountaineer and hunter trainer Thorgas Grimson calls fledgling trackers to Anvilmar. There, they move beyond basic survival and learn the hunter’s craft: respect for Dun Morogh’s beasts, tracking mountain predators, care for ranged weapons, and endurance in the harsh elements.",sp=0}},faq={{q="What is the purpose of the Etched Rune?",a="The Etched Rune calls aspiring dwarven hunters to seek Thorgas Grimson inside Anvilmar for formal guidance in the hunter’s craft.",al={"what does etched rune do","etched rune use","why do i have etched rune"},it="purpose"},{q="Who wrote or sent the Etched Rune?",a="Thorgas Grimson, the hunter trainer in Anvilmar, sends the rune to novice outdoorsmen in Coldridge Valley who show a knack for surviving the frozen wilderness.",al={"who sent etched rune","who gave me this rune","etched rune author"},it="origin"},{q="Where do I take the Etched Rune once I have read it?",a="Take the Etched Rune to Anvilmar in Coldridge Valley. Thorgas Grimson waits near the forge and training halls to teach you tracking, weapon care, and dwarven hunting traditions.",al={"where do i bring etched rune","turn in etched rune","thorgas grimson location"},it="next_step",gp=true},{q="What is the Etched Rune?",a="The Etched Rune is an inscribed stone tablet passed to novice dwarven hunters beginning their training in Coldridge Valley. Rather than standard parchment, it serves as an enduring message summons carved with runes, reflecting the deep-rooted dwarven craft and tradition tied to the ways of wilderness survival.",al={"what is etched rune","etched rune item","etched rune lore"},it="identity",add="455fa37e"},{q="Why does Thorgas Grimson want you to bring the Etched Rune?",a="The rune is a formal call to training sent by Thorgas Grimson, the resident hunter trainer inside Anvilmar. Carrying it confirms that you have proven basic capability in the valley and are prepared to undertake serious instruction in tracking, weapon maintenance, and the traditions of the wild.",al={"why does thorgas want the rune","why want etched rune","purpose of etched rune summons"},it="why_wanted",add="537b1d7a"}},ang={["class:Hunter"]="As a hunter, the rune calls you into the craft of dwarven hunting. You learn to track, respect your animal companions, and survive the wilderness through your own wits.",["race:Dwarf"]="As a dwarf, you know carved stones and runes carry trade knowledge and urgent instructions through Coldridge Valley’s snows."},kw={"anvilmar","coldridge valley","dun morogh","dwarf hunter","etched rune","hunter training","thorgas grimson"},rel={"quest:3108","npc:thorgas-grimson","topic:hunter","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh"},src={"Etched Rune","Etched Rune (Classic)"}}
E["item:fang-of-vagash"] = {t="item",n="Fang of Vagash",z="dunmorogh",s="In Dun Morogh, Vagash stalks the rams above Amberstill Ranch. His fang proves the deadly predator has been slain.",h="In Dun Morogh, Vagash stalks the rams above Amberstill Ranch.",sec={{t="Trophy of the Hunt",b="Above Amberstill Ranch, Vagash hunts the rams under cover of darkness. The high crags shelter fierce predators, but none has troubled the local ranches as much as he has. Ironforge’s troops are stretched thin, so the herdsmen go without the city guard’s protection. His severed fang gives the breeders proof that Vagash is dead and their pasturelands are safe again.",sp=0}},faq={{q="What is the Fang of Vagash used for?",a="The breeders at Amberstill Ranch in Dun Morogh take Vagash’s fang as proof that he has been slain. They reward the hunter who protected their livelihood.",al={"fang of vagash use","what to do with fang of vagash","turn in vagash fang"},it="why_wanted",gp=true},{q="Who is Vagash?",a="Vagash is a deadly beast that dens in the snowy hills above Dun Morogh’s ram pastures. He raids the herds at night, and local dwarves fear him.",al={"what is vagash","where is vagash","vagash lore"},it="target"},{q="Why hasn't the Ironforge guard killed Vagash?",a="Ironforge’s troops are spread thin, with few soldiers to spare for rural patrols. The ranchers must rely on passing adventurers to deal with dangerous predators.",al={"why aren't guards helping","where is ironforge army","mountaineers vagash"},it="conflict"},{q="What is the Fang of Vagash?",a="The Fang of Vagash is a massive trophy taken from the mouth of Vagash, a vicious predator prowling the ridges of Dun Morogh. It serves as undeniable proof that the menacing beast has finally been hunted down and slain.",al={"what is fang of vagash","vagash fang lore","fang of vagash"},it="identity",add="fc16a334"},{q="Where does the Fang of Vagash come from?",a="This fang is not crafted; it is a natural tooth pried from the jaws of Vagash himself. The ferocious monster makes his lair in the snowy hills just above the Amberstill Ranch.",al={"where do you get fang of vagash","who made fang of vagash","origin of vagash fang"},it="origin",add="695a78ed"},{q="Why does Rudra Amberstill want the Fang of Vagash?",a="Rudra Amberstill seeks the fang as physical evidence of the predator's death. Vagash has been raiding the ranch in the night and devouring prized rams, threatening the Amberstill family's livelihood while Ironforge's guard is stretched too thin to defend them.",al={"why want fang of vagash","who wants vagash fang","rudra amberstill fang"},it="why_wanted",add="f04ec442"}},ang={["race:Dwarf"]="Amberstill Ranch raises hardy mountain rams for dwarven mountaineers and travelers. Bringing back Vagash’s fang helps preserve Ironforge’s prized breed of mount.",["class:Hunter"]="Tracking Vagash through Dun Morogh’s freezing crags tests a hunter’s skills at tracking, wilderness survival, and slaying beasts."},kw={"amberstill ranch","dun morogh","fang of vagash","ironforge","protecting the herd","ram","vagash"},rel={"quest:314","zone:dunmorogh","zone:ironforge","topic:alliance"},src={"Fang of Vagash","Protecting the Herd"}}
E["item:feather-charm"] = {t="item",n="Feather Charm",z="dunmorogh",s="In Anvilmar, Feather Charms catch a warlock instructor’s eye. Frostmane novices carry these crude trinkets, which hold a faint magical power.",h="In Anvilmar, Feather Charms catch a warlock instructor’s eye.",sec={{t="Troll Trinkets and Dark Studies",b="Southwest of Anvilmar, Frostmane novices carry feather charms through snowy caverns. Their tribe is known for territorial savagery, yet its young trolls practice primitive spellcraft. The charms hold a faint but unmistakable power. Alamar Grimm, the warlock instructor in Anvilmar, studies this crude trollcraft with interest. He uses the charms to test fledgling warlocks as they seek to bind their first imp.",sp=0}},faq={{q="Who carries these feather charms?",a="Frostmane novices carry the charms in a snowy cave southwest of Anvilmar, in Coldridge Valley.",al={"where do feather charms come from","who drops feather charm","frostmane novice charm"},it="residents"},{q="Why does Alamar Grimm want them?",a="Alamar Grimm finds the charms’ inherent magic intriguing and unexpected in troll craftsmanship. He tests aspiring warlocks’ physical fortitude and magical potential with them before teaching them to summon an imp.",al={"why does alamar need charms","alamar grimm feather charms","what does grimm do with them"},it="why_wanted"},{q="Are the Frostmane trolls adept magic users?",a="The Frostmane tribe is known as crude and hostile, but its novices practice rudimentary spellcasting. Their feather charms focus that basic magic, showing that even fledgling Frostmane casters harness arcane or shamanistic energies.",al={"can frostmane trolls use magic","frostmane novice magic"}},{q="What do the charms look like?",a="Frostmane novices make simple talismans from feathers and twine. They carry them as foci for early magical training in Dun Morogh’s cold caves.",al={"feather charm description","appearance of feather charm"},it="item"},{q="What is a Feather Charm?",a="A Feather Charm is a crude magical talisman crafted and carried by Frostmane troll novices in Dun Morogh. Though seemingly simple trinkets made by the primitive mountain trolls, these charms actually channel a distinct magical energy that catches the attention of scholars and spellcasters studying troll mysticism.",al={"what is feather charm","feather charms lore","about feather charm"},it="identity",add="a2188847"},{q="Where do Feather Charms come from, and who makes them?",a="These charms are fashioned by the fledgling casters of the Frostmane tribe, found dwelling in the icy caves southwest of Anvilmar. The young troll novices imbue the feathers with their own emerging powers, carrying them as focuses while they practice their rudimentary spellcraft in Coldridge Valley.",al={"who makes feather charms","where do feather charms come from","frostmane feather charm origin"},it="origin",add="6facee45"}},ang={["class:Warlock"]="As a novice warlock in Dun Morogh, you take feather charms from troll spellcasters as a test of discipline. After you pass, Alamar Grimm entrusts you with the ritual to summon an imp.",["race:Gnome"]="As a gnome warlock in Anvilmar, you study these rudimentary troll fetishes to examine the raw, unrefined magic channeled by primitive Frostmane casters."},kw={"alamar grimm","anvilmar","coldridge valley","dun morogh","feather charm","frostmane novice","warlock"},rel={"npc:alamar-grimm","quest:1599","subzone:anvilmar","topic:warlock","topic:troll","zone:dunmorogh"},src={"Feather Charm","Beginnings"}}
E["item:felix-s-box"] = {t="item",n="Felix's Box",z="dunmorogh",s="In Frostmane camps southwest of Anvilmar, Felix's Box lies far from the gnome refugee who lost it.",h="In Frostmane camps southwest of Anvilmar, Felix's Box lies far from the gnome refugee who lost it.",sec={{t="Lost in the Flight from Gnomeregan",b="Radiation swept through Gnomeregan during the failed attempt to purge the trogg menace. Felix Whindlebolt fled with the gnomes into Coldridge Valley, leaving his possessions and crafting gear along the snowy road to escape the fumes. Frostmane trolls plundered the goods before he could return. They carried his box, chest, and bucket of bolts to their settlements southwest of Anvilmar.",sp=0},{t="A Refugee's Quandary",b="Felix is unused to violence and poorly suited to Dun Morogh's wilderness. He needs passing adventurers in Anvilmar to help recover his belongings. Their return would restore some normalcy and give the displaced artisan the means to earn a living. He lost everything when Gnomeregan fell.",sp=0}},faq={{q="What is Felix's Box?",a="Felix's Box holds Felix Whindlebolt's personal belongings. He is a gnome artisan who fled Gnomeregan after radiation spread through the city.",al={"felixs box","what is this box","felix box lore"},it="identity"},{q="How did the box end up with the Frostmane trolls?",a="Felix left his gear while fleeing the radioactive fumes from Gnomeregan. Frostmane trolls carried the roadside goods to their camps southwest of Anvilmar.",al={"why do trolls have felixs box","who stole felixs box","how was it lost"}},{q="Who is Felix Whindlebolt?",a="Felix Whindlebolt is a gnome refugee in Anvilmar. Gnomeregan's fall traumatized him and left him without his tools or personal belongings.",al={"felix whindlebolt","who is felix"},it="people"},{q="What other items did Felix lose?",a="The Frostmane trolls took Felix's Chest and Bucket of Bolts along with the box. They carried all three to their camps southwest of Anvilmar.",al={"other felix items","felix belongings","felix lost gear"}},{q="Why does Felix Whindlebolt want his box back?",a="Felix Whindlebolt is a displaced gnome refugee who had to flee Gnomeregan in sheer panic after radiation flooded the city. In his desperate scramble for safety, he lost his tools and personal gear to the Frostmane trolls. As an ordinary artisan and refugee stranded in Anvilmar, he lacks the martial skill to brave the troll camps himself, yet he desperately needs his stolen box and belongings returned to rebuild his life.",al={"why does felix want the box","why find felix's box","felix box purpose"},it="why_wanted",add="8f76c19d"}},ang={["race:Gnome"]="As a gnome starting in Coldridge Valley, you can help a fellow exile by recovering Felix's belongings after Gnomeregan's evacuation.",["profession:Engineering"]="As an engineer, you know how hard it is for displaced gnome craftsmen to lose the tools and containers they rely on."},kw={"anvilmar","coldridge valley","dun morogh","felix whindlebolt","felix's box","frostmane","gnomeregan","refugee"},rel={"npc:felix-whindlebolt","quest:3361","item:felix-s-chest","item:felix-s-bucket-of-bolts","subzone:anvilmar","zone:dunmorogh","zone:gnomeregan","topic:gnome"},src={"Felix's Box","A Refugee's Quandary (Classic)"}}
E["item:felix-s-bucket-of-bolts"] = {t="item",n="Felix's Bucket of Bolts",z="dunmorogh",s="In Dun Morogh, Frostmane trolls carry Felix's Bucket of Bolts to their camps. Felix Whindlebolt is missing the tools he brought from Gnomeregan.",h="In Dun Morogh, Frostmane trolls carry Felix's Bucket of Bolts to their camps.",sec={{t="A Refugee's Scattered Tools",b="Felix Whindlebolt fled Gnomeregan with his tools after the disaster with the troggs. Radiation drove thousands of gnomes into Dun Morogh's freezing wilds with whatever they could carry. Felix headed for Anvilmar, but Frostmane trolls from the crags southwest of town ambushed him. They seized his belongings, including his bucket of bolts and parts, leaving the artisan without the materials he needs for his craft in exile.",sp=0}},faq={{q="What is Felix's Bucket of Bolts?",a="Felix Whindlebolt's bucket holds bolts, hardware, and tinkering supplies. The exiled gnome is taking refuge in Anvilmar.",al={"bucket of bolts","felixs bucket","felix bucket of bolts"},it="identity"},{q="Who stole the bucket?",a="Frostmane trolls stole Felix Whindlebolt's bucket and other belongings as he fled the disaster at Gnomeregan.",al={"who took the bolts","trolls stole bucket","who has felixs bolts"},it="conflict"},{q="Where did the trolls take it?",a="Frostmane trolls carried the bucket to their camps in the crags southwest of Anvilmar, in Coldridge Valley.",al={"where are the bolts","bucket location","felix bolts camp"},it="place",gp=true},{q="Why is this bucket important to Felix?",a="Felix needs the bolts and parts for his craft. Gnomish refugees fled Gnomeregan with little, so basic supplies matter as they survive and rebuild far from home.",al={"why does felix want bolts","felix whindlebolt bolts importance"},it="why_wanted"}},ang={["race:Gnome"]="As a gnome, every bucket of parts saved from Gnomeregan helps refugees find a new foothold in Coldridge Valley.",["profession:Engineering"]="As an engineer, you need basic hardware to work. A bucket of bolts matters when you start over in the snows of Dun Morogh."},kw={"anvilmar","bolts","dun morogh","felix","frostmane","gnomeregan","refugee","trolls","whindlebolt"},rel={"npc:felix-whindlebolt","quest:3361","item:felix-s-box","item:felix-s-chest","subzone:anvilmar","zone:dunmorogh","zone:gnomeregan","topic:gnome"},src={"Felix's Bucket of Bolts","A Refugee's Quandary (Classic)"}}
E["item:felix-s-chest"] = {t="item",n="Felix's Chest",z="dunmorogh",s="In a Frostmane camp southwest of Anvilmar, Felix's Chest holds what he lost fleeing Gnomeregan.",h="In a Frostmane camp southwest of Anvilmar, Felix's Chest holds what he lost fleeing Gnomeregan.",sec={{t="A Refugee's Losses",b="When troggs and toxic radioactive fallout drove the gnomes from Gnomeregan, refugees crossed snowy Dun Morogh carrying what they could. Frostmane trolls scavenged the roads and overtook scattered survivors. They took Felix Whindlebolt's sturdy chest to their camps in the crags, where his toolkits and personal belongings remain among their supplies.",sp=0}},faq={{q="What is inside Felix's Chest?",a="Felix Whindlebolt's chest holds the personal belongings he salvaged while fleeing Gnomeregan. He left them behind in his rush to escape the lethal radiation. The contents mean little to the trolls, but they remain from his former life.",al={"felix chest contents","what is in the chest","felix's chest loot"},it="item"},{q="Why do the Frostmane trolls have Felix's belongings?",a="Frostmane trolls ambushed scattered gnomish refugees and carried away their gear. They harass travelers and scavenge through Coldridge Valley, taking discarded luggage back to their campsites.",al={"why do trolls have felix chest","who stole felix chest","trolls felix whindlebolt"},it="why_here"},{q="Where is the chest located?",a="Felix's Chest lies southwest of Anvilmar in Coldridge Valley, near the tents of a Frostmane troll settlement and other looted supplies.",al={"where is felix chest","felix chest location","find felix chest"},it="place",gp=true},{q="What is Felix's Chest?",a="Felix's Chest is a container of personal belongings and tools owned by Felix Whindlebolt, a refugee gnome now taking shelter in Anvilmar. When Gnomeregan was irradiated, Felix fled into Dun Morogh, only to lose the chest to Frostmane trolls during his chaotic escape.",al={"what is felixs chest","felix chest","who owns felixs chest"},it="identity",add="cd14610d"},{q="Why does Felix want his chest back?",a="Felix Whindlebolt fled the tragic fall of Gnomeregan with virtually nothing to his name. The chest holds his personal effects and practical tools, essential supplies he needs to survive and start anew while displaced among the dwarves of Coldridge Valley. Lacking the martial prowess to fight the Frostmane trolls himself, he relies on willing adventurers to recover it.",al={"why does felix want his chest","why is felixs chest needed","why retrieve felix chest"},it="why_wanted",add="bcb95cf5"}},ang={["race:Gnome"]="As a gnome, you can see Felix's Chest as a reminder of Gnomeregan's chaotic evacuation. Fleeing gnomes lost almost everything to the wilderness and scavengers."},kw={"a refugee's quandary","anvilmar","coldridge valley","felix whindlebolt","felix's chest","frostmane","gnomeregan"},rel={"npc:felix-whindlebolt","quest:3361","item:felix-s-box","item:felix-s-bucket-of-bolts","subzone:anvilmar","zone:dunmorogh","zone:gnomeregan","topic:gnome"},src={"Felix's Chest","A Refugee's Quandary (Classic)"}}
E["item:glyphic-memorandum"] = {t="item",n="Glyphic Memorandum",z="dunmorogh",s="In Coldridge Valley, the Glyphic Memorandum calls novice mages to Anvilmar. Marryk Nurribit wrote it to guide new spellcasters into formal arcane instruction.",h="In Coldridge Valley, the Glyphic Memorandum calls novice mages to Anvilmar.",sec={{t="A Summons to Anvilmar",b="Novice spellcasters receive the Glyphic Memorandum after their first tasks in Coldridge Valley. Marryk Nurribit, the local mage trainer, summons them inside Anvilmar. He gives plain counsel: learn your incantations, save coin for training and tavern ale, and keep clear of Gnomeregan, ruined by radiation.",sp=0}},faq={{q="What is the Glyphic Memorandum?",a="The Glyphic Memorandum summons newly arrived mages in Coldridge Valley. It directs them to the arcane trainer inside Anvilmar.",al={"glyphic memo","mage note","what is glyphic memorandum"},it="identity"},{q="Who wrote this memorandum?",a="Marryk Nurribit wrote the memorandum. He trains mages in Anvilmar, in Dun Morogh.",al={"who wrote it","who sent glyphic memorandum","author of note"},it="origin"},{q="What advice does the trainer give when answering the memorandum?",a="When you present the note, Marryk advises restraint. Save coin for spells and tavern ale, and avoid Gnomeregan's radioactive halls.",al={"marryk advice","what does marryk say"}},{q="Why does Marryk Nurribit want you to bring him the Glyphic Memorandum?",a="The memorandum serves as an invitation and summons for aspiring mages starting out in Coldridge Valley. By delivering it to Marryk Nurribit in Anvilmar, you establish contact with your local mage trainer. He uses the opportunity to offer novice advice, remind you to stay clear of fallen Gnomeregan, and offer formal instruction in the arcane arts whenever you have the coin to spare.",al={"why bring glyphic memorandum","why does marryk want the memorandum","why want glyphic memorandum"},it="why_wanted",add="c67a7a55"}},ang={["class:Mage"]="As a mage in Dun Morogh, you begin your formal arcane apprenticeship under Marryk Nurribit with this note.",["race:Gnome"]="As a gnome mage beginning your journey in exile, your trainer urges you to focus on your studies and stay away from Gnomeregan, your lost homeland."},kw={"anvilmar","coldridge valley","dun morogh","glyphic memorandum","mage","marryk nurribit"},rel={"quest:3114","npc:marryk-nurribit","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:gnomeregan","topic:mage"},src={"Glyphic Memorandum","Glyphic Memorandum (quest)"}}
E["item:grelin-s-report"] = {t="item",n="Grelin's Report",z="dunmorogh",s="In Coldridge Valley, Grelin's Report carries word of the Frostmane trolls to Kharanos. It joins the scouts at Anvilmar with Senir Whitebeard and Ironforge.",h="In Coldridge Valley, Grelin's Report carries word of the Frostmane trolls to Kharanos.",sec={{t="A Dispatch Past the Troggs",b="Grelin Whitebeard has watched the Frostmane trolls in Coldridge Valley and judges them no great threat. Mountaineers already stationed there can handle them, with mercenaries paid from Senate funds. So Grelin entrusts his report to a capable traveler instead of his fumbling apprentice. The journey leads through trogg-infested Coldridge Pass.\n\nThe paper shows Mountaineer Thalos that you travel on urgent business. With it, you may pass his blockade and enter the snowy reaches of Dun Morogh.",sp=0},{t="Ruffling Feathers in Kharanos",b="At the Thunderbrew Distillery in Kharanos, Senir Whitebeard receives Grelin's field report for Ironforge. His brother has invoked King Magni Bronzebeard's name throughout the document, and Senir takes note with amused resignation. Grelin claims the King's sanction for his actions. Senir expects that appeal to royal authority to ruffle feathers in the Ironforge Senate.",sp=0}},faq={{q="What is the purpose of Grelin's Report?",a="Grelin's Report carries Grelin Whitebeard's assessment of the Frostmane trolls from Coldridge Valley to Senir in Kharanos. It says they pose no great threat and can be handled by local Mountaineers and mercenaries paid by the Senate.",al={"what is grelins report","why send the report","grelin report purpose"},it="purpose"},{q="Why can't Grelin deliver it himself?",a="Grelin remains in Coldridge Valley to watch the trolls. He first considered sending his apprentice, but the dangerous passage through the trogg-infested tunnel led him to entrust the papers to a battle-tested traveler.",al={"why not deliver it","why entrust it to an adventurer"}},{q="Why does Mountaineer Thalos let you pass with the report?",a="Mountaineer Thalos guards the tunnel from Coldridge Valley to protect civilians from vicious troggs. Grelin's Report proves you travel on urgent dwarven defense business, so Thalos lets you pass.",al={"why does thalos let me through","tunnel blockade","coldridge pass troggs"}},{q="Why is the Ironforge Senate annoyed by the report?",a="Senir Whitebeard says Grelin invoked King Magni's name throughout the report. Though the brothers agree that Ironforge's politicians need a wake-up call, Senir expects Grelin's appeal to royal authority to ruffle feathers in the Senate.",al={"why senate mad","ruffle feathers","senir reaction"}},{q="What is Grelin's Report?",a="It is a written dispatch penned by Grelin Whitebeard in Coldridge Valley, addressed to his brother Senir Whitebeard in Kharanos. It details local observations and pressing matters in the valley, though Grelin invoked King Magni Bronzebeard's name liberally enough within its pages to stir up controversy among the senators back in Ironforge.",al={"what is grelins report","grelin report"},it="identity",add="cdcce173"},{q="Where does Grelin's Report come from, and who made it?",a="The document was drafted by Grelin Whitebeard while stationed at Coldridge Valley. Rather than entrusting it to his apprentice, Grelin decided to place it into the hands of a capable traveler to guarantee its safe journey east through the trogg-infested tunnel leading into greater Dun Morogh.",al={"who wrote grelins report","where did grelins report come from","who made grelins report"},it="origin",add="9a092709"},{q="Why does anyone want Grelin's Report?",a="His brother, Senir Whitebeard, is waiting for the dispatch in Kharanos to coordinate their findings before forwarding their combined reports to Ironforge. The document is also vital for you personally: presenting evidence of official Whitebeard business is the only reason Mountaineer Thalos permits you passage through the dangerous, trogg-plagued tunnel out of Coldridge Valley.",al={"why is grelins report needed","why does senir want grelins report"},it="why_wanted",add="6be6ebf1"}},ang={["race:Dwarf"]="As a dwarf, carrying this report takes you from Coldridge's safe training grounds into Dun Morogh's heartland and the service of Ironforge.",["race:Gnome"]="As a gnome refugee, delivering Grelin's message lets you prove your mettle to dwarven mountaineers as you cross Dun Morogh's shared mountain passes."},kw={"coldridge valley","grelin whitebeard","grelin's report","ironforge senate","kharanos","mountaineer thalos","senir whitebeard"},rel={"npc:senir-whitebeard","quest:282","npc:mountaineer-thalos","subzone:kharanos","subzone:anvilmar","topic:trogg","zone:dunmorogh","zone:ironforge"},src={"Grelin's Report","Senir's Observations","Senir's Observations (2)"}}
E["item:grelin-whitebeard-s-journal"] = {t="item",n="Grelin Whitebeard's Journal",z="dunmorogh",s="Grelin Whitebeard records Frostmane troll activity in a field journal in Coldridge Valley. Grik'nir the Cold steals the journal and carries it into the troll cave.",h="Grelin Whitebeard records Frostmane troll activity in a field journal in Coldridge Valley.",sec={{t="A Scout's Ledger",b="Grelin Whitebeard watches the Frostmane trolls near Coldridge Valley and writes down what they do. His leatherbound notebook records their strength, their organization, and the danger they pose. Grik'nir the Cold takes the journal during a confrontation or ambush. The marked troll brute carries it into the troll cave, leaving Grelin without the notes he needs to finish his report. So he asks passing adventurers to retrieve the book.",sp=0},{t="Dispatch to Senir",b="Grelin Whitebeard studies the recovered notes and judges the Frostmane threat in Coldridge Valley temporarily contained. With his jottings, he finishes a dispatch about the Frostmane uprising. Couriers carry the sealed message to his brother, Senir Whitebeard, who is stationed elsewhere in Dun Morogh.",sp=1}},faq={{q="Who stole Grelin Whitebeard's journal?",a="Grik'nir the Cold stole Grelin Whitebeard's journal. The heavily marked Frostmane troll brute took it into the troll cave in Coldridge Valley.",al={"who took the journal","who has grelin's journal","thief of grelin's journal"},it="target"},{q="What is written in the journal?",a="Grelin Whitebeard's journal holds field notes on the local Frostmane trolls, the threat they pose, and the safety of Coldridge Valley.",al={"journal contents","what is inside the journal","grelin whitebeard notes"}},{q="What happens after the journal is recovered?",a="Grelin uses the recovered notes to finish a report on the trolls. He asks an adventurer to carry it to his brother, Senir Whitebeard.",al={"what does grelin do with the journal","after the stolen journal"},sp=1,it="next_step"},{q="Why is this journal so important to Grelin?",a="Grelin needs his journal to prepare an accurate report on the Frostmane uprising for the dwarven authorities and his brother Senir. Without it, the state of Coldridge Valley's defenses is uncertain.",al={"why does grelin want it back","importance of the journal"},it="why_wanted"},{q="What is Grelin Whitebeard's Journal?",a="It is a personal notebook kept by Grelin Whitebeard, an observer stationed in Coldridge Valley. Inside, Grelin records his findings regarding the local Frostmane troll activity and prepares field reports detailing the valley's defensive situation.",al={"what is grelin whitebeard journal","grelin journal","grelins notebook"},it="identity",add="15978139"},{q="Where does Grelin Whitebeard's Journal come from, and who made it?",a="The journal was compiled directly by the dwarf Grelin Whitebeard during his watch over Coldridge Valley. However, it was snatched from him and carried deep into the nearby troll cave by the Frostmane brute Grik'nir the Cold.",al={"who made grelin journal","where did grelin journal come from","grelin journal origin"},it="origin",add="9ed18e74"}},ang={["race:Dwarf"]="As a dwarf, recovering Grelin's journal preserves vital knowledge of the Frostmane threat near Ironforge's training grounds."},kw={"coldridge valley","dun morogh","frostmane hold","grelin whitebeard","grik'nir the cold","senir whitebeard","stolen journal"},rel={"quest:218","npc:grelin-whitebeard","subzone:coldridge-valley","zone:dunmorogh","quest:182","quest:282","topic:troll"},src={"Grelin Whitebeard's Journal","The Stolen Journal"}}
E["item:gyromechanic-gear"] = {t="item",n="Gyromechanic Gear",z="dunmorogh",s="In Kharanos, inventors seek Gyromechanic Gears for a bold experiment. They hope to reverse the mutations of leper gnomes.",h="In Kharanos, inventors seek Gyromechanic Gears for a bold experiment.",sec={{t="Components for Recombobulation",b="Radiation swept through Gnomeregan while gnomes fought to drive out the troggs. Many survivors became mad, irradiated leper gnomes. Ozzie Togglevolt and Razzle Sprysprocket will not abandon their twisted kin, so they have planned the Recombobulator. The machine is meant to undo radiation's effects.\n\nIts prototype needs precise mechanisms that can bear the volatile pressure inside, including Gyromechanic Gears and Restabilization Cogs. Gnomeregan's fall ended local manufacturing. Now the inventors must salvage these delicate parts from hostile leper gnomes roaming Dun Morogh.",sp=0}},faq={{q="What is a Gyromechanic Gear used for?",a="Razzle Sprysprocket in Kharanos needs Gyromechanic Gears as core parts for the Recombobulator. The prototype will use them with Restabilization Cogs in an attempt to cure irradiated leper gnomes.",al={"gyromechanic gear purpose","what does gyromechanic gear do","gyromechanic gear quest"},it="why_wanted"},{q="Where do these gears come from?",a="The gears are salvaged from Leper Gnomes outside Gnomeregan and from Gibblewilt in Dun Morogh.",al={"where to find gyromechanic gear","gyromechanic gear drop","who drops gyromechanic gear"},it="origin"},{q="Can the Recombobulator actually cure leper gnomes?",a="Razzle Sprysprocket trusts Ozzie's schematics and believes changes to the combustion pistons and electrogum gel can restore their kin. The machine has not been tested against radiation poisoning on a wide scale.",al={"does the recombobulator work","can leper gnomes be cured","recombobulation success"}},{q="Why can't gnomes simply forge new gears?",a="Gnomeregan's fall shattered gnomish industry and put its finest tools, workshops, and automated foundries out of reach. Salvaging intact precision hardware around the city's edge is often faster than making parts by hand.",al={"why scavenge gears","why not craft gyromechanic gears"}},{q="What is a Gyromechanic Gear?",a="A Gyromechanic Gear is an intricately engineered component crafted for complex gnomish machinery. Originally utilized within Gnomeregan's vast mechanical works, these precision parts are now scattered amidst the ruins and scavenged by the wretched creatures lurking outside the fallen tech-city.",al={"what is gyromechanic gear","gyromechanic gear info","about gyromechanic gears"},it="identity",add="93a017f3"}},ang={["race:Gnome"]="As a gnome, each gear you salvage brings tinkerers closer to a chance to rescue their radioactive kin in the snows outside Gnomeregan.",["profession:Engineering"]="As an engineer, you know the intricate design and tight tolerances of gnomish gyromechanic parts. They regulate unstable prototype machinery."},kw={"gnomeregan","gyromechanic gear","kharanos","leper gnome","operation recombobulation","razzle sprysprocket","recombobulator","restabilization cog"},rel={"quest:412","item:restabilization-cog","npc:razzle-sprysprocket","topic:leper-gnome","subzone:kharanos","zone:gnomeregan","zone:dunmorogh","topic:gnome"},src={"Gyromechanic Gear","Operation Recombobulation (Classic)"}}
E["item:hallowed-rune"] = {t="item",n="Hallowed Rune",z="dunmorogh",s="In Coldridge Valley, Branstock Khalder sends novice priests the Hallowed Rune to begin their training at Anvilmar.",h="In Coldridge Valley, Branstock Khalder sends novice priests the Hallowed Rune to begin their training at...",sec={{t="A Calling to the Light",b="The Hallowed Rune bears teachings of the Holy Light. A young priest proves their resolve by aiding the valley’s mountaineers and defenders. Then Branstock sends them to Anvilmar, where he teaches them to mend wounds and wield holy power against the troggs threatening Dun Morogh.",sp=0}},faq={{q="What is the Hallowed Rune?",a="The Hallowed Rune is a sacred stone inscribed with guidance for novice priests. Branstock Khalder sends it to call them to begin their spiritual and magical instruction inside Anvilmar.",al={"what is this item","hallowed rune item","rune purpose"},it="identity"},{q="Who sends the Hallowed Rune to you?",a="Branstock Khalder, the dwarven priest trainer in Anvilmar, sends the Hallowed Rune to novice priests in Coldridge Valley.",al={"who sent the rune","who gave me this rune","branstock rune"},it="origin"},{q="What should I do after receiving the Hallowed Rune?",a="Read the rune, then go to Anvilmar’s main hall and present yourself to Branstock Khalder. He offers to teach you new prayers and spells.",al={"where do i take the rune","what to do with hallowed rune"},it="next_step",gp=true},{q="Why does Branstock want novice priests trained so quickly?",a="Branstock wants novice priests trained because troggs keep invading Coldridge Valley. The mountaineers need healing and holy power to defend Dun Morogh.",al={"why need priests","trogg problem priests"},it="motive"},{q="Why was the Hallowed Rune given to me?",a="The rune acts as a formal summons and message directed to novice priests working in Coldridge Valley. Branstock Khalder sends it along to call aspiring acolytes of the Holy Light into Anvilmar so he can instruct them in their faith and teach them sacred spells vital for defending the valley.",al={"why do i have the hallowed rune","hallowed rune purpose","why hallowed rune"},it="why_wanted",add="fac25589"}},ang={["class:Priest"]="As a priest, you begin your formal mentorship under the Holy Light in Coldridge Valley with the Hallowed Rune.",["race:Dwarf"]="As a dwarf, you bring reverence for the Light and duty to Ironforge together as you defend your mountain homeland from troggs."},kw={"anvilmar","branstock khalder","coldridge valley","dun morogh","hallowed rune","priest","troggs"},rel={"quest:3110","npc:branstock-khalder","subzone:anvilmar","subzone:coldridge-valley","topic:priest","topic:light","topic:trogg","zone:dunmorogh"},src={"Hallowed Rune","Hallowed Rune (Classic)"}}
E["item:hildelve-s-journal"] = {t="item",n="Hildelve's Journal",z="dunmorogh",s="In Dun Morogh, Hildelve's Journal bears the last words of a dwarf lost to a fierce bear. Its pages tell of the attack and his plea for vengeance.",h="In Dun Morogh, Hildelve's Journal bears the last words of a dwarf lost to a fierce bear.",sec={{t="A Pilot's Final Words",b="Dwarven pilot Hildelve went alone into Dun Morogh after his steam tank broke down. He left his partner, Hammerfoot, with the tanks and searched the snow-swept crags for rumored chiron ore. In his journal, Hildelve writes that Mangeclaw, a monstrous ice claw bear, stalked him for days before attacking.\n\nHildelve fought bravely and drove the bear off, but Mangeclaw mauled him and left him gravely wounded in the cold. His final hours were agonizing. Before the bear returned, Hildelve made one plea: whoever found his body should hunt Mangeclaw and avenge his death.",sp=0},{t="Return to the Siege Brigade",b="Pilot Hammerfoot, Hildelve's comrade, is stationed near North Gate Outpost in eastern Dun Morogh. Hammerfoot belongs to the Ironforge Siege Brigade and feared the worst when his partner did not return from the search for ore. The journal and Mangeclaw's severed claw prove that Hildelve's final wish has been honored and his spirit put to rest.",sp=1}},faq={{q="Who was Hildelve?",a="Hildelve was a dwarf who piloted a steam tank for the Ironforge Siege Brigade. After his tank broke down, he went alone into Dun Morogh in search of chiron ore. Mangeclaw killed him before he could return.",al={"hildelve lore","who is hildelve","dwarf pilot hildelve"},it="people"},{q="What is Mangeclaw?",a="Mangeclaw is an unusually large, savage ice claw bear that stalks Dun Morogh's snowy ridges. The bear ambushed Hildelve while he was stranded and mauled him severely. Then Mangeclaw returned to end his life.",al={"who is mangeclaw","what killed hildelve","bear that killed hildelve"},it="threat"},{q="Who receives the journal once it is found?",a="Pilot Hammerfoot receives the journal. Hildelve's comrade is a siege engine pilot stationed near North Gate Outpost in eastern Dun Morogh. He had sought word of the missing pilot.",al={"where do i take the journal","who gets hildelves journal","turn in hildelves journal"},it="target"},{q="What does Hildelve ask for in the journal?",a="Hildelve asks whoever finds his remains to hunt Mangeclaw and avenge his death. In the journal's final pages, he names the beast that attacked him and makes his plea, knowing his wounds are mortal.",al={"hildelves final wish","what is in the journal","pilot dying wish"},it="motive"},{q="What is Hildelve's Journal?",a="This battered logbook belonged to Hildelve, a downed dwarven pilot of the Ironforge Siege Brigade. Found beside his remains in the frozen reaches of Dun Morogh, it records his harrowing final moments—documenting his survival of an initial brutal mauling by the great bear Mangeclaw, and penning his dying wish for vengeance before the beast returned to finish him off.",al={"what is this journal","hildelves journal lore","about hildelves journal"},it="identity",add="b58cc0e1"},{q="Where does Hildelve's Journal come from, and who made it?",a="The journal was authored by Pilot Hildelve himself during his ordeal in Dun Morogh. After his steam tank broke down, he went searching for chiron ore on foot and was mauled by the bear Mangeclaw; he kept this personal record right up until his death, leaving behind a written testament of his struggle and his final request.",al={"who wrote the journal","where did hildelves journal come from","origin of hildelves journal"},it="origin",add="308c8265"},{q="Why does anyone want Hildelve's Journal?",a="His fellow steam tank pilot, Pilot Hammerfoot, was desperately searching for word of his lost comrade. The journal offers definitive proof of Hildelve's fate and honors his final request for retribution against the monster that took his life, bringing closure to his friends in the Ironforge Siege Brigade.",al={"why keep hildelves journal","who wants the journal","why bring hildelves journal back"},it="why_wanted",add="856dae3f"}},ang={["race:Dwarf"]="As a dwarf, you can honor the unyielding spirit of pilots who brave freezing weather and wild beasts to secure the heights of Khaz Modan.",["faction:Alliance"]="As an Alliance member, you strengthen the bond between the Alliance and the Ironforge Siege Brigade by recovering the personal effects of fallen soldiers like Hildelve."},kw={"dun morogh","hildelve","ice claw bear","journal","mangeclaw","pilot hammerfoot","siege brigade"},rel={"quest:417","quest:419","npc:pilot-hammerfoot","item:mangy-claw","zone:dunmorogh","zone:ironforge"},src={"Hildelve's Journal","A Pilot's Revenge (Classic)"}}
E["item:jordan-s-refined-ore-shipment"] = {t="item",n="Jordan's Refined Ore Shipment",z="dunmorogh",s="Jordan's Refined Ore Shipment arrives in Ironforge for the Test of Righteousness. The metal is prepared for blacksmith Jordan Stilwell to forge a holy weapon.",h="Jordan's Refined Ore Shipment arrives in Ironforge for the Test of Righteousness.",sec={{t="A Smith's Materials",b="Jordan Stilwell needs rare materials for a weapon worthy of a paladin. He requires a Purified Kor Gem, sturdy Whitestone Oak lumber, his lost smithing hammer, and refined ore. The shipment brings the metal to Ironforge for this sacred labor.",sp=0}},faq={{q="What is Jordan's Refined Ore Shipment used for?",a="The refined ore goes to Jordan Stilwell outside Ironforge. It is one of four key components for a masterwork weapon for paladins undertaking the Test of Righteousness.",al={"refined ore purpose","what does jordan do with ore","ore shipment use"},it="why_wanted"},{q="Who prepares the refined ore?",a="Bailor arranges the shipment and oversees the refining and dispatch of the specialist metal Jordan Stilwell needs.",al={"who made the ore","bailor ore","who refines jordan's ore"},it="origin"},{q="Why does Jordan need this specific shipment?",a="Jordan Stilwell plans to craft a symbol of paladinhood and the Light. He needs superior materials beyond ordinary forge scraps, and the specially processed metal gives the blade or hammer head the balance and purity worthy of a holy knight.",al={"why special ore","why cant jordan use regular iron","refined ore reason"},it="why_wanted"},{q="What is Jordan's Refined Ore Shipment?",a="Jordan's Refined Ore Shipment is a crate of high-grade, specially processed metal prepared for weaponsmith Jordan Stilwell. Intended for fine smithing rather than common forge work, this refined ore provides the pure metallic foundation Jordan requires to craft an exceptional weapon worthy of a dedicated paladin of the Light.",al={"what is jordans refined ore shipment","jordans refined ore shipment lore","what is jordan refined ore"},it="identity",add="ec64bb0f"}},ang={["class:Paladin"]="As a paladin, you must show patience and dedication to obtain this refined shipment. It is one of the physical trials required to craft your symbolic weapon of the Light.",["profession:Blacksmithing"]="As a blacksmith, you know masterwork forging calls for flawless, carefully prepared ingots instead of raw field ore."},kw={"bailor","ironforge","jordan stilwell","paladin weapon","refined ore","test of righteousness"},rel={"quest:1653","quest:1655","npc:jordan-stilwell","item:jordan-s-smithing-hammer","item:whitestone-oak-lumber","item:purified-kor-gem","zone:ironforge"},src={"Jordan's Refined Ore Shipment","The Test of Righteousness (2)"}}
E["item:jordan-s-smithing-hammer"] = {t="item",n="Jordan's Smithing Hammer",z="dunmorogh",s="Jordan Stilwell waits outside Ironforge for his father's hammer, lost within Shadowfang Keep.",h="Jordan Stilwell waits outside Ironforge for his father's hammer, lost within Shadowfang Keep.",sec={{t="A Craftsman's Legacy",b="Jordan Stilwell is a human blacksmith who works outside Ironforge. His father’s hammer lies within Shadowfang Keep in Silverpine Forest. Without it, Jordan cannot forge a sacred weapon fit for a holy champion, the masterwork he hopes to make.",sp=0}},faq={{q="Where is Jordan's Smithing Hammer located?",a="Jordan's Smithing Hammer lies inside Shadowfang Keep in the forests of Silverpine. Paladins taking the Test of Righteousness must enter the occupied fortress to recover it.",al={"hammer location","where is jordan's hammer","where to find jordan's smithing hammer"},it="place",gp=true},{q="Why is this hammer so important to Jordan Stilwell?",a="Jordan inherited the hammer from his father, and it means much to him. He needs it to forge his finest work, a holy weapon consecrated to the Light.",al={"why does jordan want the hammer","jordan stilwell hammer lore"},it="ties"},{q="What is the hammer used for once recovered?",a="Bring the hammer to Jordan outside the gates of Ironforge with lumber, ore, and a gem. He will forge a sacred armament for the paladin who helped him.",al={"what does the hammer make","test of righteousness hammer use"},it="purpose"},{q="What is Jordan's Smithing Hammer?",a="Jordan's Smithing Hammer is a cherished forging tool belonging to the master smith Jordan Stilwell. Beyond its practical use at the anvil, it carries profound sentimental value as an heirloom passed down to Jordan directly from his father.",al={"what is jordans smithing hammer","jordans hammer item","about jordans smithing hammer"},it="identity",add="126e648c"},{q="Where does Jordan's Smithing Hammer come from, and who made it?",a="The hammer was passed down to Jordan Stilwell by his father. Its exact maker is unrecorded, but before you recover it, the heirloom had somehow ended up far from Ironforge, tucked away within the dark ramparts of Shadowfang Keep.",al={"where did jordans hammer come from","who made jordans smithing hammer","origin of jordans smithing hammer"},it="origin",add="1df19239"}},ang={["class:Paladin"]="As a paladin, you must venture into perilous lands to retrieve the heirloom hammer and prove your resolve in the trials of righteousness.",["profession:Blacksmithing"]="As a blacksmith, you know the bond between a master smith and a hammer passed down by their forebears."},kw={"dun morogh","ironforge","jordan stilwell","paladin weapon","shadowfang keep","smithing hammer","test of righteousness"},rel={"quest:1653","npc:jordan-stilwell","zone:shadowfang","zone:dunmorogh","zone:ironforge","item:purified-kor-gem","item:whitestone-oak-lumber","item:jordan-s-refined-ore-shipment"},src={"Jordan's Smithing Hammer","The Test of Righteousness (2)"}}
E["item:macgrann-s-dried-meats"] = {t="item",n="MacGrann's Dried Meats",z="dunmorogh",s="In Dun Morogh, Old Icebeard has carried off Tundra MacGrann’s winter meat.",h="In Dun Morogh, Old Icebeard has carried off Tundra MacGrann’s winter meat.",sec={{t="A Winter Cache",b="Tundra MacGrann hunted game and salted it for the winter. He packed weeks of provisions into a sturdy chest inside a thorium meat locker, to keep scavenging bears and prowling predators from his homestead. Yet he never expected an intruder strong enough to carry away the whole chest.",sp=0},{t="Into the Yeti's Lair",b="Old Icebeard raided MacGrann’s camp while the dwarf tracked deer. The yeti dragged the heavy chest to his den in Chill Breeze Valley. Its solid thorium plating holds, but MacGrann’s injured leg keeps him from making a swift rescue into the cavern. Without help retrieving his cache before winter, the stranded hunter faces starvation in the mountain snows.",sp=0}},faq={{q="What are MacGrann's Dried Meats?",a="Tundra MacGrann salted and preserved a month’s provisions to carry him through winter in Dun Morogh.",al={"what is macgrann's dried meats","tundra's meat","macgrann meat stash"},it="identity"},{q="Why were the meats locked in a chest?",a="Hungry predators in Dun Morogh, including mountain bears, might tear into the dried meat. MacGrann locked his winter supply in a reinforced thorium meat locker to keep them out.",al={"why lock the meat","why thorium locker","macgrann chest"}},{q="Who stole the meat locker?",a="Old Icebeard stole the whole locker while MacGrann was away hunting deer, then dragged it to his den in Chill Breeze Valley.",al={"who took the meat","who stole it","meat locker thief"},it="threat"},{q="Why can't Tundra MacGrann get his meats back himself?",a="His leg is injured, so he can't go into Old Icebeard's cavern and carry the chest out himself.",al={"why doesn't macgrann get it","why does tundra need help","tundra injured"},it="motive"},{q="Where did MacGrann's Dried Meats come from, and who prepared them?",a="These dried meats were prepared and salted by Tundra MacGrann, a mountaineer living out in the cold wilds of Dun Morogh. He cured an entire month's worth of rations to see himself through the harsh freezing season ahead, storing them carefully away in a heavy thorium locker before the local beast Old Icebeard intervened.",al={"who made macgrann dried meats","where did the dried meat come from","macgrann meat origin"},it="origin",add="1f8f3b04"},{q="Why does Tundra MacGrann want his dried meats back?",a="Without this preserved stash, Tundra MacGrann faces starvation when the severe snow flurries sweep across Dun Morogh. It represents a whole month's supply of salted provisions. Since a bad leg prevents him from braving Old Icebeard's den to fetch it, recovering the meats is vital to his survival throughout the upcoming winter.",al={"why does tundra want the meat","why get the dried meats","why are macgrann's meats needed"},it="why_wanted",add="6a0307bf"}},ang={["profession:Cooking"]="As a cook, you can salt and cure game to preserve meat through Dun Morogh’s freezing cold. Hunters like MacGrann rely on it to keep food for winter.",["race:Dwarf"]="As a dwarf, you know preparation means survival in the high peaks. Losing a winter cache can mean the difference between life and death."},kw={"chill breeze valley","dun morogh","macgrann's dried meats","meat locker","old icebeard","tundra macgrann"},rel={"quest:312","subzone:chill-breeze-valley","zone:dunmorogh"},src={"MacGrann's Dried Meats","Tundra MacGrann's Stolen Stash"}}
E["item:mangy-claw"] = {t="item",n="Mangy Claw",z="dunmorogh",s="In Dun Morogh, Mangy Claw marks the end of a deadly hunt. The great ice claw bear Mangeclaw killed a stranded dwarven pilot, and the severed claw proves the beast was slain.",h="In Dun Morogh, Mangy Claw marks the end of a deadly hunt.",sec={{t="A Dying Pilot's Wish",b="Pilot Hildelve’s steam tank broke down in Dun Morogh’s frozen hills. He searched for ore on foot and faced the mountain wilderness alone. In his journal, he tells how he fought off Mangeclaw, an ice claw bear, but was savagely mauled. The bear returned and killed the weakened pilot. Hildelve’s final entry pleaded for vengeance. Taking Mangy Claw from the fallen bear fulfills his request.",sp=0},{t="Vengeance for the Siege Brigade",b="Pilot Hammerfoot sent searchers into the snowdrifts, hoping to find his friend Hildelve alive. Hildelve’s journal and Mangy Claw show that he died and his final request was honored. Bringing them to Hammerfoot gives the Ironforge Siege Brigade closure and earns the gratitude of Ironforge’s pilots.",sp=1}},faq={{q="What is the Mangy Claw?",a="Mangy Claw is the severed claw of Mangeclaw, a savage ice claw bear in Dun Morogh. It proves the beast was hunted and killed.",al={"mangy claw purpose","what is this claw","mangeclaw item"},it="identity"},{q="Who wants the Mangy Claw?",a="Pilot Hammerfoot wants Mangy Claw and the journal of his fallen friend Hildelve. They confirm that the killer bear is dead. Hammerfoot is stationed near Dun Morogh’s mountain passes.",al={"who takes the mangy claw","mangy claw hand in","pilot hammerfoot turn in"},it="why_wanted"},{q="Why did Mangeclaw need to be hunted?",a="Mangeclaw mauled and eventually killed Hildelve, a dwarf pilot searching for ore on foot after his steam tank broke down. Hildelve’s journal records his dying wish for someone to avenge him.",al={"why kill mangeclaw","who died to mangeclaw","hildelve lore"},it="motive"},{q="Where does the beast Mangeclaw roam?",a="Mangeclaw prowls Dun Morogh’s snowy ridges and hills, near where Pilot Hildelve’s remains were found.",al={"mangeclaw location","where is mangeclaw","mangeclaw dun morogh"},it="place",gp=true},{q="Where does the Mangy Claw come from?",a="The Mangy Claw is taken directly from Mangeclaw, a savage ice claw bear that prowls the frozen wilderness of Dun Morogh. It is not an crafted artifact, but a grisly physical trophy carved from the beast after it is slain.",al={"mangy claw source","where does mangy claw drop","who has mangy claw"},it="origin",add="554d85fa"}},ang={["race:Dwarf"]="As a dwarf, honoring a fallen comrade’s dying wish and avenging a member of the Ironforge Siege Brigade carry deep personal and clan honor.",["class:Hunter"]="As a hunter, tracking Mangeclaw through Dun Morogh’s brutal mountain blizzards tests your skill against dangerous, territorial beasts."},kw={"dun morogh","hildelve","ice claw bear","mangeclaw","mangy claw","pilot hammerfoot","siege brigade"},rel={"quest:417","item:hildelve-s-journal","npc:pilot-hammerfoot","quest:419","zone:dunmorogh","zone:ironforge"},src={"Mangy Claw","A Pilot's Revenge (Classic)"}}
E["item:nori-s-mug"] = {t="item",n="Nori's Mug",z="dunmorogh",s="In Dun Morogh, Nori Pridedrift sends a mug of mornbrew to Anvilmar. Travelers bring the drink to Durnan Furcutter, then return the empty mug to its owner.",h="In Dun Morogh, Nori Pridedrift sends a mug of mornbrew to Anvilmar.",sec={{t="A Courier's Return",b="Nori Pridedrift lends his mug for a delivery through Dun Morogh's freezing passes. It carries hot mornbrew to Durnan Furcutter in Anvilmar, where the drink comforts him against the bitter cold. After Durnan drains it, the mug returns to Nori. He reminds travelers that mugs do not grow on trees and expects his sturdy drinking vessel back.",sp=0}},faq={{q="What is Nori's Mug used for?",a="Nori's Mug carries scalding mornbrew to Durnan Furcutter in Anvilmar. After Durnan drinks it, the empty mug goes back to Nori Pridedrift.",al={"purpose of noris mug","what was in the mug","noris cup"},it="item",gp=true},{q="Who owns this mug?",a="Nori Pridedrift owns the mug. He expects travelers to return it after delivering his drink to Anvilmar.",al={"who is nori","owner of mug","whose mug is it"},it="identity"},{q="Why does Nori insist on getting the mug back?",a="Nori expects the mug back because, as he says, mugs do not grow on trees. He wants his borrowed drinking vessel returned to him.",al={"why return the mug","why does nori want it back","mugs dont grow on trees"},it="why_wanted"},{q="What was drunk from the mug?",a="The mug held scalding mornbrew, a warm drink meant to ward off Dun Morogh's biting cold.",al={"what was in the cup","what is mornbrew","mornbrew drink"}}},ang={["race:Dwarf"]="As a dwarf, you know a warm drink can comfort you in Dun Morogh's storms. Nori expects you to bring his mug back."},kw={"bring back the mug","dun morogh","durnan furcutter","mornbrew","nori pridedrift","nori's mug"},rel={"quest:3365","npc:nori-pridedrift","zone:dunmorogh"},src={"Nori's Mug","Bring Back the Mug"}}
E["item:purified-kor-gem"] = {t="item",n="Purified Kor Gem",z="dunmorogh",s="At Jordan Stilwell’s forge outside Ironforge, a Purified Kor Gem is needed to shape a weapon of the Light. First, elven magic must cleanse the corrupted stone.",h="At Jordan Stilwell’s forge outside Ironforge, a Purified Kor Gem is needed to shape a weapon of the Light.",sec={{t="From Corruption to Sanctity",b="Naga hold the Corrupted Kor Gem in Blackfathom Deeps, beneath Ashenvale’s coast. A paladin carries it to Thundris Windweaver, a night elf in Auberdine. There, Thundris draws on arcane and natural arts to purge its aquatic and shadowy taint. The stone emerges purified, ready to channel holy power.",sp=0},{t="The Smith's Masterpiece",b="Jordan Stilwell, a human weaponsmith outside Ironforge, needs the gem for a masterwork weapon. He has long held designs for a weapon worthy of the Silver Hand, but lacked the rare materials to forge it. The Purified Kor Gem, Whitestone Oak Lumber, and rare ore give the weapon its spiritual core, to channel a paladin’s righteous wrath.",sp=0}},faq={{q="What is the Purified Kor Gem used for?",a="The gem goes to Jordan Stilwell, the blacksmith outside Ironforge in Dun Morogh. He uses it to forge a consecrated weapon for a paladin undertaking their trials.",al={"purified kor gem use","why do i need kor gem","what is kor gem for"},it="why_wanted"},{q="Where does the gem originate?",a="Naga hold the corrupted stone in Blackfathom Deeps, beneath the coast of Ashenvale.",al={"kor gem origin","where does kor gem drop","who drops kor gem"},it="origin"},{q="Who purifies the gem?",a="Thundris Windweaver, a night elf in Auberdine, cleanses the Corrupted Kor Gem and restores it to a purified state.",al={"how to cleanse kor gem","who cleanses kor gem","thundris windweaver kor gem"}},{q="Can any adventurer make use of the Purified Kor Gem?",a="Paladins undergoing the Test of Righteousness seek the gem. Jordan Stilwell crafts for holy warriors who bring him the purified crystal and other rare materials.",al={"is kor gem paladin only","can anyone use purified kor gem"},it="for_you"},{q="What is a Purified Kor Gem?",a="The Purified Kor Gem is a rare, sanctified mineral component cleansed of foul taint. Originally recovered as a corrupted stone held by the naga in Blackfathom Deeps, it has been painstakingly cleansed of its dark influence by Thundris Windweaver in Auberdine so that its latent properties can be safely harnessed for sacred works.",al={"what is purified kor gem","purified kor gem meaning","purified kor gem info"},it="identity",add="a30b14db"}},ang={["class:Paladin"]="As a paladin, you prove your devotion by acquiring and cleansing this gem. Then you carry it from Kalimdor to Dun Morogh, where it helps forge a weapon of the Light.",["faction:Alliance"]="As an Alliance member, you rely on night elven wisdom in Auberdine to aid a human smith on the slopes of Dun Morogh."},kw={"auberdine","blackfathom deeps","corrupted kor gem","dun morogh","jordan stilwell","purified kor gem","test of righteousness","thundris windweaver"},rel={"item:corrupted-kor-gem","quest:1442","npc:jordan-stilwell","quest:4761","zone:blackfathom","subzone:auberdine","zone:dunmorogh"},src={"Purified Kor Gem","The Test of Righteousness (2)"}}
E["item:restabilization-cog"] = {t="item",n="Restabilization Cog",z="dunmorogh",s="At Gnomeregan's gates, leper gnomes still carry Restabilization Cogs. In Kharanos, tinkerers need intact cogs for a machine meant to reverse leper mutation.",h="At Gnomeregan's gates, leper gnomes still carry Restabilization Cogs.",sec={{t="Components for a Cure",b="Radiation flooded Gnomeregan in a failed attempt to wipe out the invading troggs. Countless gnomes fell sick and hostile, then fled their home as exiles. Even in their madness, they carry intricate gnomish machinery.\n\nOzzie Togglevolt and Razzle Sprysprocket believe the terrible change can be undone. Their prototype Recombobulation Device needs parts taken from the afflicted outside Gnomeregan's gates. Intact Restabilization Cogs will balance its inner combustion systems.",sp=0}},faq={{q="What is a Restabilization Cog used for?",a="In Kharanos, Tinker Razzle Sprysprocket needs Restabilization Cogs for the Recombobulator. Along with Gyromechanic Gears, they form part of the experimental machine meant to cure irradiated leper gnomes.",al={"cog purpose","what does restabilization cog do","why collect cogs"},it="why_wanted"},{q="Where can these cogs be found?",a="Leper gnomes and the deranged Gibblewilt carry these cogs. They roam the exterior gates and trenches outside Gnomeregan in western Dun Morogh.",al={"restabilization cog location","who drops cogs","where to farm cogs"},gp=true},{q="Can the Recombobulator actually cure the leper gnomes?",a="Razzle Sprysprocket and Ozzie Togglevolt believe calibrated machinery can reverse the mutation. Whether the Recombobulator can restore leper gnomes' minds and bodies remains untested, and the search for a cure continues.",al={"does recombobulator work","is there a cure for leper gnomes"}},{q="What is a Restabilization Cog?",a="A Restabilization Cog is a precision mechanical component salvaged from the fallen machines and irradiated leper gnomes wandering outside the ruined city of Gnomeregan. Designed to maintain structural and rotational equilibrium in complex gnomish devices, these cogs are prized by tinkerers seeking sturdy, pre-machined parts to stabilize temperamental inventions like Ozzie Togglevolt's Recombobulator.",al={"what is restabilization cog","restabilization cog lore","about restabilization cog"},it="identity",add="8ac7e8f1"},{q="Where do Restabilization Cogs come from?",a="These cogs originate from Gnomeregan's vast mechanical works. When the city was evacuated following the disastrous radiation venting, countless automated devices and the tragic survivors who succumbed to leper madness carried these standardized components out onto the snow outside the gates.",al={"who made restabilization cog","restabilization cog origin","where did restabilization cog come from"},it="origin",add="ceb0040c"}},ang={["race:Gnome"]="As a gnome exiled in Dun Morogh, you take machinery from corrupted kin in the hope of finding a cure for Gnomeregan's fallen.",["profession:Engineering"]="As an engineer, you can see how Restabilization Cogs fit into gnomish machines such as the Recombobulator."},kw={"dun morogh","gibblewilt","gnomeregan","kharanos","leper gnome","operation recombobulation","razzle sprysprocket","restabilization cog"},rel={"quest:412","item:gyromechanic-gear","npc:razzle-sprysprocket","topic:leper-gnome","zone:gnomeregan","subzone:kharanos","zone:dunmorogh","topic:gnome"},src={"Restabilization Cog","Operation Recombobulation (Classic)"}}
E["item:rumbleshot-s-ammo"] = {t="item",n="Rumbleshot's Ammo",z="dunmorogh",s="Near the Grizzled Den, Rumbleshot's Ammo lies abandoned in the snow. Its courier fled from hungry wendigos before the crate could reach gunsmith Hegnar Rumbleshot in Dun Morogh.",h="Near the Grizzled Den, Rumbleshot's Ammo lies abandoned in the snow.",sec={{t="A Stranded Shipment",b="Hegnar Rumbleshot keeps a roadside arms shop on the mountain path from Coldridge Pass toward Anvilmar. Ironforge riflemen, mountaineers, and dwarven mortar teams drill in the snowy heights, so his supplies run low as quickly as powder burns.\n\nLoslor sent the shot from Kharanos, but the shipment never reached the shelves. Its courier camped too close to the Grizzled Den. When the wendigos attacked, the courier fled in panic and left the heavy crate in their hunting grounds.",sp=0}},faq={{q="Who is Hegnar Rumbleshot?",a="Hegnar Rumbleshot is a dwarven gunsmith with a shop off the road toward Anvilmar. He supplies local marksmen, hunters, and military gunners who practice in Dun Morogh's crags.",al={"rumbleshot","who is hegnar","gun vendor"},it="people"},{q="How did the ammo crate get lost?",a="A courier carrying the crate camped near the Grizzled Den. When its wendigos attacked, the frightened courier fled and left the heavy crate in the snow.",al={"why was ammo lost","what happened to the ammo","courier ammo"},it="history"},{q="Where is the Grizzled Den?",a="The Grizzled Den is a cavern system in the mountains southwest of Kharanos. Wendigos make their lair there, putting solitary travelers on the surrounding slopes in danger.",al={"grizzled den location","where is wendigo cave"},it="place",gp=true},{q="What is Rumbleshot's Ammo?",a="It is a crate of fresh ammunition packed for Hegnar Rumbleshot's shop out along the road to Anvilmar. With local dwarven riflemen and mortar teams constantly practicing nearby, Hegnar depends on steady bulk shipments like this to keep his shelves stocked and his customers armed.",al={"what is rumbleshots ammo","rumbleshot ammo crate","what are these munitions"},it="identity",add="4221fe47"},{q="Where does Rumbleshot's Ammo come from?",a="The crate was supplied and sent out by Loslor Rudge from Kharanos. Unfortunately, the courier tasked with bringing it southwest toward Anvilmar was ambushed by ferocious wendigos near the Grizzled Den and fled, abandoning the entire shipment in the snow.",al={"who made rumbleshots ammo","where did rumbleshots ammo come from","who sent the ammo"},it="origin",add="008970c2"},{q="Why does Hegnar Rumbleshot need this ammo?",a="Hegnar is on the verge of running out of stock entirely. The nearby mountaineers, riflemen, and mortar teams burn through gunpowder and shot at a blistering pace during target practice, leaving plenty of eager buyers waiting the moment the fresh shipment arrives.",al={"why is rumbleshots ammo needed","why want rumbleshot ammo","who needs rumbleshots ammo"},it="why_wanted",add="6d6b5eaa"}},ang={["class:Hunter"]="As a hunter in Dun Morogh, keep Hegnar's powder dry and his shot stocked. Dwarven firearms need a steady supply of ammunition.",["profession:Engineering"]="As an engineer, you rely on shot and powder to test crafted firearms and experimental weaponry."},kw={"ammo","crate","dun morogh","grizzled den","hegnar","loslor","rumbleshot","wendigo"},rel={"quest:5541","npc:hegnar-rumbleshot","subzone:grizzled-den","quest:313","subzone:kharanos","subzone:anvilmar","zone:dunmorogh"},src={"Rumbleshot's Ammo","Ammo for Rumbleshot"}}
E["item:sara-balloo-s-plea"] = {t="item",n="Sara Balloo's Plea",z="dunmorogh",s="In her grief, Sara Balloo asks an Alliance champion to carry her handwritten appeal to King Magni Bronzebeard.",h="In her grief, Sara Balloo asks an Alliance champion to carry her handwritten appeal to King Magni Bronzebeard.",sec={{t="A Widow's Appeal",b="Grief keeps Sara from facing the High Seat, so she entrusts her words to an adventurer loyal to the Alliance. She asks King Magni to remember the private mourning and sacrifices of ordinary dwarven families who serve the kingdom.",sp=0}},faq={{q="What is Sara Balloo's Plea?",a="Sara Balloo's Plea is a handwritten letter for King Magni Bronzebeard. Sara asks for his attention while she mourns in private.",al={"sara balloo plea","widow note ironforge","sara note"},it="identity"},{q="Why does Sara Balloo need someone else to deliver it?",a="Sara is overcome with grief and believes appearing before the King of Ironforge in that state would hinder her plea. So she trusts an Alliance champion to deliver it.",al={"why deliver note","why cant sara go","sara grief"},it="motive"},{q="Who receives this message?",a="King Magni Bronzebeard receives Sara's letter at the High Seat of Ironforge.",al={"who gets plea","who to deliver to","magni letter"},it="target"},{q="What does delivering the letter lead to?",a="Presenting the letter brings Sara Balloo's bereavement to King Magni's attention and begins a royal response honoring her fallen family.",al={"plea questline","a kings tribute link","what happens next"},sp=1,it="next_step"},{q="Where does Sara Balloo's Plea come from, and who made it?",a="This written note was penned directly by Sara Balloo, a grieving dwarven woman in Ironforge. Devastated by loss, she prepared the message herself to petition Ironforge's throne, entrusting it to an Alliance champion rather than attempting the emotional journey to the high seat on her own.",al={"who wrote sara balloos plea","where did sara balloos plea come from","who made sara balloos plea"},it="origin",add="2b83ea9f"},{q="Why does anyone want Sara Balloo's Plea?",a="King Magni Bronzebeard requires the letter to hear the petition of one of his grieving subjects. Sara Balloo cannot bring herself to appear before the monarch in her sorrowful state, so she relies on you to present the appeal directly into the hands of Ironforge's ruler.",al={"why is sara balloos plea needed","who wants sara balloos plea","why deliver sara balloos plea"},it="why_wanted",add="4ac5e6cf"}},ang={["race:Dwarf"]="As a dwarf, you carry Sara's message to the High Seat so King Magni hears every mountaineer or citizen, even in grief.",["faction:Alliance"]="As an Alliance champion, you carry Sara's petition before royalty. She trusts you because of your service to the Alliance."},kw={"a king's tribute","high seat","ironforge","magni bronzebeard","sara balloo","sara balloo's plea"},rel={"npc:sara-balloo","quest:683","npc:magni-bronzebeard","quest:686","zone:ironforge","topic:alliance","zone:dunmorogh"},src={"Sara Balloo's Plea","Sara Balloo's Plea (quest)"}}
E["item:shimmerweed"] = {t="item",n="Shimmerweed",z="dunmorogh",s="On Shimmer Ridge, Frostmane trolls gather shimmerweed for their rituals. Rejold Barleybrew of Brewnall Village wants to test its sharp flavor in his stout.",h="On Shimmer Ridge, Frostmane trolls gather shimmerweed for their rituals.",sec={{t="A Trollish Crop",b="High above Dun Morogh's lowlands, Frostmane trolls tend shimmerweed on Shimmer Ridge's icy crags. They harvest the plant and keep it in woven baskets throughout their camps. There, it fuels their sacred rituals. Few mountaineers beyond troll society pay the herb much mind, though inventive outsiders have taken an interest.",sp=0},{t="A Secret Ingredient",b="In Brewnall Village, brewmaster Rejold Barleybrew suspects shimmerweed may be the missing piece in his attempt to brew the ultimate dwarven stout. He has detected the herb's pungent, unmistakable flavor and wants to test it in his fermenting vats. So Rejold hires travelers to slip into Frostmane camps, evade the hostile trolls and bring back bushels.",sp=0}},faq={{q="Where does shimmerweed grow?",a="Shimmerweed grows on Shimmer Ridge, an icy rise northwest of Brewnall Village in Dun Morogh. Frostmane trolls tend it and store what they gather in baskets around their camps.",al={"shimmerweed location","where to find shimmerweed","shimmer ridge plant"},it="place"},{q="What do the Frostmane trolls use shimmerweed for?",a="Frostmane trolls use shimmerweed in their mysterious tribal rites and ceremonies. Outsiders do not know the precise details, but the herb has a place in their cultural and spiritual practices on Shimmer Ridge.",al={"troll shimmerweed use","why do trolls want shimmerweed"},it="motive"},{q="Why does Rejold Barleybrew want shimmerweed?",a="Rejold Barleybrew wants shimmerweed for his attempt to brew the perfect dwarven stout in Brewnall Village. He has detected its unique taste and hopes fresh bushels will give his experimental mash the bold profile his recipe needs.",al={"rejold barleybrew quest","who wants shimmerweed","why brew with shimmerweed"},it="why_wanted"},{q="Does shimmerweed grow anywhere outside Dun Morogh?",a="Shimmerweed has also been gathered in arid lands like Durotar, where farseers such as Drek'Thar value it for potent herbal concoctions and medicinal brews. The plant grows beyond the frozen peaks of Khaz Modan.",al={"shimmerweed durotar","shimmerweed outside dun morogh"}},{q="What is Shimmerweed?",a="Shimmerweed is a distinctive plant cultivated high in the snowy heights of Dun Morogh by the Frostmane trolls, particularly around Shimmer Ridge. Notable for its unusual flavor and properties, the herb is gathered in troll baskets and plays a role in local tribal rituals, though ambitious dwarven brewers have recently taken an interest in testing its potent qualities in experimental ales.",al={"what is shimmerweed","shimmerweed plant","about shimmerweed"},it="identity",add="1978b4f9"},{q="Where does Shimmerweed come from, and who made it?",a="Shimmerweed is naturally cultivated by the Frostmane trolls in Dun Morogh, who tend and harvest the plant in baskets up on Shimmer Ridge. While the Frostmane maintain crops of it for their own rituals, wild varieties of the potent herb have also been known to grow in distant lands like Durotar, where wilderness herbalists and shamans prize it for brewing potions.",al={"where does shimmerweed come from","who made shimmerweed","shimmerweed origin"},it="origin",add="d2fd1cd1"}},ang={["race:Dwarf"]="As a dwarf, you can see how ingenuity turns a strange plant from a nearby cliffside into a brewing experiment.",["profession:Herbalism"]="As an herbalist, you can see how regional plants find uses in local brewing traditions and ritual alchemy."},kw={"brewnall village","dun morogh","frostmane","perfect stout","rejold barleybrew","shimmer ridge","shimmerweed"},rel={"quest:315","subzone:shimmer-ridge","npc:rejold-barleybrew","subzone:brewnall-village","zone:dunmorogh","topic:troll","zone:durotar"},src={"Shimmerweed","The Perfect Stout"}}
E["item:simple-memorandum"] = {t="item",n="Simple Memorandum",z="dunmorogh",s="In Coldridge Valley, novice gnome warriors are sent to train with Thran Khorman in Anvilmar. They prepare for the war to take back Gnomeregan.",h="In Coldridge Valley, novice gnome warriors are sent to train with Thran Khorman in Anvilmar.",sec={{t="A Summons to Anvilmar",b="Young gnome fighters face wildlife and troggs in Coldridge Valley with letters of introduction in hand. The Simple Memorandum directs its bearer to Thran Khorman, the warrior trainer in Anvilmar.\n\nGnomes bring intellect and contraptions to battle, but taking back Gnomeregan calls for strength and martial discipline. The memorandum sends its bearer beyond early training to learn the art of war from Thran.",sp=0}},faq={{q="What is the Simple Memorandum?",a="The Simple Memorandum is a written message for novice gnome warriors in Coldridge Valley. It directs them to report to the dwarven warrior trainer in Anvilmar.",al={"simple memorandum","what is this note","memorandum item"},it="identity"},{q="Who wrote the Simple Memorandum?",a="The Simple Memorandum bears no signature. Sten Stoutarm guesses Thran Khorman wrote it, but its words about taking back Gnomeregan mark it as a gnomish directive. It orders you to report to Thran, the dwarven warrior trainer in Anvilmar.",al={"who wrote memorandum","who sent note","author of simple memorandum"},it="origin"},{q="What happens after reading the Simple Memorandum?",a="After reading the Simple Memorandum, you take it to Thran Khorman in Anvilmar. He recognizes your resolve to reclaim your lost home and offers to teach you the basics of warrior combat.",al={"what do i do with memorandum","where do i take it","turn in simple memorandum"},it="next_step"},{q="Why is a dwarf training gnome warriors?",a="A dwarf trains gnome warriors because gnome refugees settled in Ironforge and Anvilmar after Gnomeregan fell. Dwarven veterans such as Thran Khorman lend their martial skill to help their exiled allies train and take back their irradiated city.",al={"why thran training gnomes","dwarves training gnomes"}},{q="Why was the Simple Memorandum given to me?",a="The memorandum is a gnomish directive ordering you to report to Thran Khorman, the dwarven warrior trainer inside Anvilmar. As a displaced gnome warrior, your prime directive is to prepare for the war to take back Gnomeregan, and Thran has given his word to help ready you and your people for it. Sten Stoutarm passed the note along while you were helping him in Coldridge Valley.",al={"why simple memorandum","purpose of simple memorandum","why do i need simple memorandum"},it="why_wanted",rc="Gnome",add="b027c55a"}},ang={["class:Warrior"]="As a warrior, you begin formal combat training with Thran Khorman in Anvilmar. You move beyond rudimentary skirmishing.",["race:Gnome"]="As a gnome exile, you share the aim of sharpening your battle skills beside your dwarven allies. You prepare for Gnomeregan's liberation."},kw={"anvilmar","coldridge valley","dun morogh","gnomeregan","simple memorandum","thran khorman","warrior training"},rel={"quest:3112","npc:thran-khorman","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:ironforge"},src={"Simple Memorandum","Simple Memorandum (quest)"}}
E["item:simple-rune"] = {t="item",n="Simple Rune",z="dunmorogh",s="In Coldridge Valley, Thran Khorman sends promising young dwarven warriors to Anvilmar for training with the Simple Rune.",h="In Coldridge Valley, Thran Khorman sends promising young dwarven warriors to Anvilmar for training with the...",sec={{t="A Summons to Arms",b="Young fighters who have begun clearing threats from Coldridge Valley receive Thran’s formal summons. The rune’s martial marks hold no magic; they tell each recruit to report to Thran inside Anvilmar. There, he teaches basic combat and gives practical advice for surviving Dun Morogh’s hostile wilds.",sp=0}},faq={{q="What is the purpose of the Simple Rune?",a="The Simple Rune directs recruits to seek formal instruction from Thran Khorman inside Anvilmar. Young warriors in Coldridge Valley receive it as an instructional tablet.",al={"simple rune use","what does rune do","simple rune quest item"},it="purpose"},{q="Who sends the Simple Rune?",a="Thran Khorman sends the Simple Rune. The dwarf warrior trainer inside Anvilmar watches for promising fighters who help around the valley.",al={"who wrote rune","who gave me simple rune","sender of rune"},it="origin"},{q="Where do I take the Simple Rune?",a="Take the Simple Rune to Thran Khorman inside Anvilmar, in central Coldridge Valley.",al={"where do i go","rune turn in","thran khorman location"},it="next_step",gp=true},{q="What is the Simple Rune?",a="The Simple Rune is an inscribed dwarven stone passed to promising warriors in Coldridge Valley. Rather than bearing mystical enchantments, it functions as a written summons from Thran Khorman, calling novice fighters to report to him in Anvilmar to begin their formal martial training.",al={"what is simple rune","simple rune lore","simple rune item"},it="identity",add="0f0eb9fb"},{q="Why does Thran Khorman want you to have the Simple Rune?",a="Thran Khorman sends the rune to recruit you into formal warrior instruction. Seeing potential in your early deeds around Coldridge Valley, he wants to ground you in proper dwarven martial discipline and teach you what it truly takes to fight for Ironforge amidst rising local threats.",al={"why thran sends rune","why do i need simple rune","why want simple rune"},it="why_wanted",add="2d1fc984"}},ang={["class:Warrior"]="As a dwarven warrior, the Simple Rune marks your first step into formal training under veteran instructor Thran Khorman.",["race:Dwarf"]="As a dwarf, Thran Khorman’s rune offers you the basics of the fight: an axe’s grip, armor’s weight, and the sweat of real battle."},kw={"anvilmar","coldridge valley","dun morogh","dwarf rune","simple rune","thran khorman","warrior training"},rel={"quest:3106","npc:thran-khorman","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","topic:warrior","topic:dwarf"},src={"Simple Rune","Simple Rune (Classic)"}}
E["item:steelgrill-s-tools"] = {t="item",n="Steelgrill's Tools",z="dunmorogh",s="At Steelgrill's Depot, Beldin Steelgrill needs fresh tools to keep his workshop at work. He puts siege engines and equipment through hard use, so Kharanos keeps sending replacements.",h="At Steelgrill's Depot, Beldin Steelgrill needs fresh tools to keep his workshop at work.",sec={{t="A Heavy-Handed Craftsman",b="Beldin Steelgrill is one of Dun Morogh's finest siege engine technicians. Merchants know his rough touch, though. He works without pause on armored tanks and mechanical contraptions, and delicate tools soon break in his hands. Arclight spanners snap and fang-ratchets wear out, so he keeps ordering replacements from Kharanos for his repair benches.",sp=0},{t="Keeping the Engines Rolling",b="At his depot northeast of Kharanos, Beldin services combat vehicles for experienced drivers such as Pilot Stonegear. The tools keep Ironforge's war machines in working order. Fresh wrenches and ratchets keep repairs moving on the siege engines assembled there, supporting local defenses.",sp=0}},faq={{q="What are Steelgrill's Tools used for?",a="The tools replace worn mechanic implements at Steelgrill's Depot. Beldin Steelgrill uses them to overhaul heavy dwarven machinery, including Pilot Stonegear's damaged siege engine.",al={"what are these tools","steelgrill tools purpose"},it="purpose"},{q="Why does Beldin Steelgrill go through so many tools?",a="Beldin works roughly and pushes his tools hard. Arclight spanners snap and fang-ratchets break so often that suppliers in Kharanos struggle to keep up.",al={"why broken tools","why does beldin need tools"},it="motive"},{q="Where did this crate of tools come from?",a="The crate is assembled and filled in nearby Kharanos, then carried northeast to Steelgrill's Depot.",al={"where do i get tools","tool shipment origin"},it="origin"},{q="Who is Beldin Steelgrill?",a="Beldin is a master dwarf mechanic who runs Steelgrill's Depot northeast of Kharanos. He is regarded as the region's finest siege engine technician.",al={"who is beldin","beldin steelgrill lore"},it="people"},{q="What is Steelgrill's Tools?",a="Steelgrill's Tools is a freshly packaged order of heavy mechanical equipment, including arclight spanners and fang-ratchets. It has been prepped for delivery directly to Beldin Steelgrill, the master siege engine technician working out of Steelgrill's Depot near Kharanos.",al={"what are steelgrills tools","steelgrills tools crate","what is steelgrill's tools"},it="identity",add="8eb066d8"},{q="Why does Beldin Steelgrill need this crate of tools?",a="Beldin is an expert mechanic, but he works his gear to the breaking point while servicing heavy machinery. Having just snapped his last fang-ratchet, he urgently needs this fresh shipment to complete critical repairs on siege engines like Pilot Stonegear's.",al={"why does beldin want tools","why need steelgrills tools","why are tools wanted"},it="why_wanted",add="11454cb4"}},ang={["profession:Engineering"]="As an engineer, you know how repairs on heavy siege engines wear down arclight spanners and delicate wrenches.",["race:Dwarf"]="As a dwarf, you know the pride of maintaining the Alliance's armored siege engines. Keeping Beldin supplied helps Ironforge's armored vanguard stay ready for combat."},kw={"beldin","depot","kharanos","ratchet","siege engine","spanner","steelgrill","tools"},rel={"npc:beldin-steelgrill","subzone:steelgrill-s-depot","quest:400","subzone:kharanos","npc:pilot-stonegear","zone:dunmorogh"},src={"Steelgrill's Tools","Tools for Steelgrill"}}
E["item:sully-balloo-s-letter"] = {t="item",n="Sully Balloo's Letter",z="dunmorogh",s="Beneath the Thandol Span, Sully Balloo's Letter carries a soldier's farewell to Sara in Ironforge. His words hold the love he bore her through his final days.",h="Beneath the Thandol Span, Sully Balloo's Letter carries a soldier's farewell to Sara in Ironforge.",sec={{t="A Final Farewell Beneath the Waves",b="Beneath the Thandol Span, the road from the Wetlands crosses toward the Arathi Highlands. Under the rushing water, a dwarf's skeletal remains lie pinned. A fragile, waterlogged envelope rests in his grasp. Inside, the letter begins, “My dear Sara...” The parchment has suffered beneath the water, yet the ink still bears the care of the dwarven defender in his final days or hours. He never returned to Ironforge.",sp=0},{t="Delivery to Ironforge",b="In Ironforge, Sara Balloo has waited without knowing what became of her husband after he marched off to war. Sully's final thoughts bring her somber closure and confirm the fear she carried: he died far from home beneath the currents of the northern crossing. His devotion reaches her in his own words.",sp=1}},faq={{q="Where is Sully Balloo's Letter found?",a="You find the letter in a waterlogged envelope clutched in a skeletal dwarf's hand beneath the waters of the Thandol Span, between the Wetlands and the Arathi Highlands.",al={"letter location","where is sullys letter","where to find sully balloo letter"},gp=true},{q="Who was Sully Balloo?",a="Sully Balloo was a dwarven soldier who died while defending the northern crossing near the Thandol Span. His remains lie pinned beneath the river currents.",al={"who is sully balloo","sully balloo lore","what happened to sully"},it="people"},{q="Who is the letter addressed to?",a="The letter is addressed to Mrs. Sara Balloo, Sully's wife, who lives in Ironforge.",al={"who gets the letter","who is sara balloo","where to turn in sully letter"}},{q="What happens when you deliver the letter to Sara Balloo?",a="When Sara Balloo reads the letter, she is heartbroken to learn her husband died beneath the waters. She can still read the final words he lovingly wrote to her.",al={"sara balloo reaction","turning in the letter","quest completion sully letter"},sp=1,it="next_step",gp=true},{q="What is Sully Balloo's Letter?",a="It is a tender, war-torn letter penned with painstaking care by a dwarf soldier named Sully Balloo. Found preserved beneath the icy waters of the Thandol Span, it contains the final heartfelt words written to his wife in Ironforge before his death in battle.",al={"what is sullys letter","sully balloos letter","about sully balloo letter"},it="identity",add="efe638b9"},{q="Where does Sully Balloo's Letter come from, and who made it?",a="The letter was written by Sully Balloo, an Alliance soldier serving on the front lines at the Thandol Span between the Wetlands and Arathi Highlands. It survived submerged in a waterlogged envelope held in the grasp of his submerged remains beneath the great bridge.",al={"who wrote sully balloos letter","where did sully letter come from","creator of sully balloo letter"},it="origin",add="b8624ec6"},{q="Why does anyone want Sully Balloo's Letter?",a="Its recipient, Sara Balloo, resides in Ironforge unaware of her husband's tragic demise. Delivering the letter fulfills a fallen soldier's last wish and brings bittersweet closure to a grieving widow awaiting news of her beloved.",al={"why deliver sully balloo letter","who wants sullys letter","why bring letter to sara balloo"},it="why_wanted",add="b54d6872"}},ang={["race:Dwarf"]="As a dwarf, you can see in this letter the sacrifice ordinary mountaineers and soldiers make while guarding Khaz Modan's high bridges and mountain passes.",["faction:Alliance"]="As an Alliance member, you can carry a fallen soldier's last thoughts to his widow, so they are not forgotten beneath the bridge."},kw={"arathi highlands","ironforge","letter","sara balloo","sully balloo","thandol span","waterlogged envelope","wetlands"},rel={"npc:sara-balloo","quest:637","subzone:thandol-span","zone:ironforge","zone:arathi","quest:631","zone:dunmorogh"},src={"Sully Balloo's Letter","Sully Balloo's Letter (quest)"}}
E["item:tainted-memorandum"] = {t="item",n="Tainted Memorandum",z="dunmorogh",s="In Coldridge Valley, Alamar Grimm urges novice gnome warlocks to leave old paths behind and seek power through the dark arts.",h="In Coldridge Valley, Alamar Grimm urges novice gnome warlocks to leave old paths behind and seek power...",sec={{t="A Discreet Summons",b="At Anvilmar, few celebrate fel practitioners, and many distrust them. Alamar Grimm gives the Tainted Memorandum to young gnomes who study forbidden arts. He rejects the Holy Light and ordinary weapons. To him, Gnomeregan’s fall proves that old ways and tinkering failed their people.\n\nGrimm sees reliance on dwarven charity as a dead end. He urges gnomes to claim undeniable power and summon minions who obey without question. Only then, he believes, can they secure their own future.",sp=0}},faq={{q="Who wrote the Tainted Memorandum?",a="Alamar Grimm, the gnome warlock trainer in Anvilmar, wrote the Tainted Memorandum.",al={"author tainted memorandum","who sent tainted memorandum","alamar grimm note"},it="origin"},{q="Why is the memorandum considered 'tainted'?",a="The memorandum deals with forbidden warlock magic. Its title reflects the distrust of demonic and fel power in Dun Morogh, where dwarven hosts keep practitioners at arm’s length.",al={"why tainted","tainted letter lore"}},{q="What does Alamar Grimm say about Gnomeregan?",a="Alamar Grimm blames traditional arcane magic and careless tinkering for bringing gnomes close to extinction when Gnomeregan fell. He believes dwarves see gnomes as second-class citizens, and urges warlocks to claim their own absolute power instead of waiting for Alliance help.",al={"alamar grimm gnomeregan","alamar grimm views"}},{q="What is the Tainted Memorandum?",a="The Tainted Memorandum is a discrete, personal message intended for promising gnome warlocks who are just beginning their training in Coldridge Valley. Passed along quietly by allies on the surface, the note serves as an invitation to look past the conventional traditions of the Holy Light or physical combat and seek out kindred, open-minded practitioners who harbor darker arts.",al={"what is tainted memorandum","tainted memo","what is this note"},it="identity",add="0c729b68"},{q="Why does someone want you to have the Tainted Memorandum?",a="The memorandum is given to recruit you into the fold of the warlock arts. The warlock trainer Alamar Grimm sends it to identify novice spellcasters who reject ordinary dwarf and gnome dogmas, urging you to meet him in Anvilmar to master obedient, summoned allies and unlock the true source of demonic power.",al={"why was i given the memorandum","why tainted memorandum","who wants the tainted memorandum"},it="why_wanted",add="e7be2e4a"}},ang={["class:Warlock"]="As a warlock, you train under Alamar Grimm. He presents dark summoning as a path to control and power.",["race:Gnome"]="As a gnome, you hear Grimm appeal to resentment over Gnomeregan’s loss and your people’s perceived place as dependent refugees in dwarven lands."},kw={"alamar grimm","anvilmar","coldridge valley","gnome warlock","gnomeregan","tainted memorandum"},rel={"npc:alamar-grimm","quest:3115","subzone:anvilmar","subzone:coldridge-valley","topic:warlock","zone:dunmorogh"},src={"Tainted Memorandum","Tainted Memorandum (quest)"}}
E["item:thick-bear-fur"] = {t="item",n="Thick Bear Fur",z="dunmorogh",s="In Dun Morogh, Thick Bear Fur helps travelers and soldiers endure the mountain cold. Bears roam the snowfields, and their pelts make insulated clothing and bedding.",h="In Dun Morogh, Thick Bear Fur helps travelers and soldiers endure the mountain cold.",sec={{t="Warmth Against the Mountain Frost",b="Bears roam Dun Morogh's ridges through some of the harshest snowfields in the Eastern Kingdoms. Their thick coats shield them from blizzards, and locals and travelers put the pelts to use. Hunters gather them to line clothing, insulate drafty outposts, and pad cold sleeping rolls.",sp=0},{t="Bedding for the Siege Brigade",b="Pilot Bellowfiz outfitted his siege tank, Jetsteam, at Steelgrill's Depot for a month in the field on a long mission for the Siege Brigade. Cold iron offered little comfort in the high snowbanks, so he hired local scouts to gather thick bear fur from the snowfields south of the Grizzled Den. The pelts would make warm bedding for his cabin quarters.",sp=0}},faq={{q="Where does Thick Bear Fur come from?",a="Thick Bear Fur comes from Dun Morogh's bears, including Young Black Bears and Ice Claw Bears. They hunt in snowy tundra and pine groves south of the Grizzled Den.",al={"where to get thick bear fur","who drops thick bear fur","bear fur location"},it="origin",gp=true},{q="Why does Pilot Bellowfiz need this fur?",a="Pilot Bellowfiz needs thick bear fur to make warm bedding inside his tank, Jetsteam. He is outfitting it for a month-long mission with the Siege Brigade, and the bedding will help against the cold mountain nights.",al={"bellowfiz fur","why does bellowfiz need fur","stocking jetsteam fur"},it="why_wanted"},{q="What creatures in Dun Morogh yield this pelt?",a="Young Black Bears and Ice Claw Bears yield Thick Bear Fur. Both roam Dun Morogh's highland snows, and their dense fur is used for winter bedding and insulation.",al={"which bears drop fur","dun morogh bear types"},it="target",gp=true},{q="What is Thick Bear Fur?",a="Thick Bear Fur is the heavy, insulated pelt harvested from the wild bears roaming the frigid crags and snowdrifts of Dun Morogh. Adapted to survive biting sub-zero blizzards, this dense hide provides vital warmth and protection against Khaz Modan's relentless alpine cold.",al={"thick bear fur","what is this fur","dun morogh bear fur"},it="identity",add="a2edc513"}},ang={["class:Hunter"]="As a hunter, you learn to move through Dun Morogh's cold brush, stalk dangerous mountain beasts, and gather durable materials from the wild.",["race:Gnome"]="As a gnome, you know pilots like Bellowfiz at Steelgrill's Depot rely on practical hunting in dwarf country to keep their machines survivable during long alpine deployments."},kw={"bellowfiz","dun morogh","grizzled den","ice claw bear","jetsteam","steelgrill's depot","thick bear fur"},rel={"quest:317","npc:pilot-bellowfiz","subzone:steelgrill-s-depot","subzone:grizzled-den","zone:dunmorogh","quest:318"},src={"Thick Bear Fur","Stocking Jetsteam"}}
E["item:wendigo-mane"] = {t="item",n="Wendigo Mane",z="dunmorogh",s="Across Dun Morogh, wendigos roam the frozen crags, and their manes keep the mountain cold at bay. Pilot Stonegear has a use for them.",h="Across Dun Morogh, wendigos roam the frozen crags, and their manes keep the mountain cold at bay.",sec={{t="Warmth for the Ironworks",b="Wendigos roam the snowdrifts of Dun Morogh, their coarse fur guarding them from bitter drafts. Outside Kharanos, Pilot Stonegear sends adventurers to Grizzled Den for their heavy manes. He means to weave them into an insulating rug for the interior deck of Trollplow, his prized dwarven siege engine.",sp=0}},faq={{q="What creatures yield a Wendigo Mane?",a="Wendigo manes come from wendigos in Dun Morogh’s snows. They include Young Wendigos, adult Wendigos, and alpha beasts such as Vagash, Edan the Howler, and Old Icebeard.",al={"where do wendigo manes drop","who drops wendigo mane","wendigo mane sources"},it="origin",gp=true},{q="Why does Pilot Stonegear want these manes?",a="Pilot Stonegear wants the manes for an insulating rug on the interior deck of Trollplow, his siege engine. The thick fur will help keep his station warm as the machine travels through frozen terrain.",al={"why stonegear wants manes","pilot stonegear rug","what are manes used for"},it="why_wanted"},{q="Where is the best place to find wendigos for their manes?",a="Pilot Stonegear recommends Grizzled Den, a cave system in the mountains directly west of Kharanos. Wendigos fill the cavern and its surrounding slopes.",al={"grizzled den location","where to hunt wendigos","wendigo cave dun morogh"},it="place",gp=true},{q="Are wendigos dangerous to hunt?",a="Yes. Wendigos are feral, territorial predators with great strength and thick hides. Dwarven trainers regard facing them in their dens as an early test of a mountaineer’s courage and fighting grit.",al={"are wendigos hard to kill","fighting wendigos"},it="danger"},{q="What is a Wendigo Mane?",a="A Wendigo Mane is a thick, shaggy patch of coarse fur harvested from the fierce wendigos prowling the snowy crags of Dun Morogh. Known for insulating the savage beasts against biting mountain blizzards, this durable pelt is tough, warm, and highly prized for rough craftwork.",al={"what is wendigo mane","wendigo mane item","wendigo fur"},it="identity",add="9c5452b4"},{q="Where does a Wendigo Mane come from?",a="These manes are harvested directly from the wild wendigos that roam Dun Morogh, notably around dens such as the Grizzled Den west of Kharanos. They are natural beast pelts, taken by hunters willing to brave the claws and fangs of the mountain creatures.",al={"where do wendigo manes come from","who drops wendigo mane","origin of wendigo mane"},it="origin",add="e05af805"}},ang={["profession:Engineering"]="Dwarven machinery in Dun Morogh has freezing metal cockpits. Wendigo pelts make practical insulating linings.",["race:Dwarf"]="Young dwarves hunt the wendigos of Grizzled Den to prove their toughness to Kharanos veterans."},kw={"dun morogh","fur","grizzled den","kharanos","mane","pelt","stonegear","trollplow","wendigo"},rel={"quest:313","npc:pilot-stonegear","subzone:grizzled-den","subzone:kharanos","zone:dunmorogh"},src={"Wendigo Mane","The Grizzled Den (quest)"}}
E["item:whitestone-oak-lumber"] = {t="item",n="Whitestone Oak Lumber",z="dunmorogh",s="Beneath Moonbrook, the Defias shape Whitestone Oak Lumber for their fleet. Its strength also draws Alliance smiths seeking a haft for a sacred weapon.",h="Beneath Moonbrook, the Defias shape Whitestone Oak Lumber for their fleet.",sec={{t="A Sacred Haft",b="Jordan Stilwell, outside Ironforge, needs Whitestone Oak Lumber for a weapon worthy of a champion of the Light. He joins it with a purified Kor gem and refined metals to form a balanced, unyielding haft. The haft must bear the holy energies channeled during the Test of Righteousness.",sp=1},{t="Timber of the Under-Docks",b="Deep in the Deadmines beneath Moonbrook, Goblin Woodcarvers shape Whitestone Oak for the Defias Brotherhood's hidden war fleet. Its dense grain can bear strain and hard blows. Armorers use it when they need stronger timber than common ash or pine for ceremonial and martial work.",sp=1,bt={"defias.hideout"}}},faq={{q="Where is Whitestone Oak Lumber found?",a="Goblin Woodcarvers work Whitestone Oak Lumber deep in the Deadmines beneath Moonbrook in Westfall. There, the Defias Brotherhood builds its hidden juggernaut.",al={"where to get whitestone oak","whitestone oak location","who drops whitestone oak lumber"},sp=1,it="place",gp=true,bt={"defias.hideout"}},{q="Who uses this lumber?",a="Jordan Stilwell, a blacksmith near Ironforge's gates in Dun Morogh, needs the timber to make a specialized weapon for rising paladins.",al={"who needs whitestone oak","whitestone oak turn in"},it="people"},{q="What is the wood used to make?",a="Jordan Stilwell makes the resilient timber into the haft of a two-handed holy hammer. He forges it for those who complete the Test of Righteousness.",al={"whitestone oak purpose","what does jordan stilwell forge"},it="item"},{q="Why is goblin lumber suitable for a holy weapon?",a="The Defias Brotherhood uses dense timber strong enough for warships. Jordan Stilwell sees that this wood can withstand the force of divine power.",al={"why goblin wood","why deadmines lumber"}},{q="What is Whitestone Oak Lumber?",a="Whitestone Oak Lumber is a fine, specialized timber sought after by skilled craftsmen. Prized for its sturdiness and quality, it serves as the essential wooden shaft or grip for forging a masterwork weapon of the Holy Light.",al={"what is whitestone oak lumber","whitestone oak lumber","what is whitestone lumber"},it="identity",add="3fba151d"},{q="Where does Whitestone Oak Lumber come from, and who made it?",a="The lumber is harvested and prepared deep within the Deadmines in Westfall. It is shaped by the goblin woodcarvers employed by the Defias Brotherhood, who cut and craft the timber amidst their illicit construction projects beneath the earth.",al={"where does whitestone oak come from","whitestone oak lumber source","who made whitestone oak lumber"},it="origin",add="9364a134"},{q="Why does Jordan Stilwell want Whitestone Oak Lumber?",a="The weaponsmith Jordan Stilwell requires this specific wood to forge a grand weapon fit for a holy paladin. Paired with refined ore, a purified Kor gem, and his father's hammer, the durable oak forms the foundation for what he considers his finest work.",al={"why is whitestone oak lumber wanted","why does jordan need whitestone oak","whitestone oak lumber use"},it="why_wanted",add="e7d39b03"}},ang={["class:Paladin"]="As a paladin, you must procure this timber from the Defias under-docks for Jordan Stilwell's Test of Righteousness. He uses it to craft a sacred hammer for defenders of the Light.",["profession:Blacksmithing"]="Whitestone oak, refined ore, and a gem come together in Stilwell's weapon schematics. Together, they balance weight, durability, and metaphysical resonance."},kw={"deadmines","goblin woodcarver","jordan stilwell","paladin hammer","test of righteousness","whitestone oak lumber"},rel={"quest:1653","npc:jordan-stilwell","zone:deadmines","item:purified-kor-gem","item:jordan-s-smithing-hammer","item:jordan-s-refined-ore-shipment","topic:paladin","zone:dunmorogh"},src={"Whitestone Oak Lumber","The Test of Righteousness (2)"}}
E["npc:alamar-grimm"] = {t="npc",n="Alamar Grimm",z="dunmorogh",s="At Anvilmar in Coldridge Valley, Alamar Grimm teaches young gnomes to wield fel magic. Since Gnomeregan fell, he has grown bitter toward outsiders and means to teach his students to summon an imp.",h="At Anvilmar in Coldridge Valley, Alamar Grimm teaches young gnomes to wield fel magic.",sec={{t="A Bitter Exile",b="At Anvilmar, Alamar Grimm still resents the fall of Gnomeregan. While other gnomes in Coldridge Valley work to recover and tinker, he distrusts ordinary adventurers and even the Ironforge dwarves sheltering his people. He grumbles that their allies care more for diplomacy with humans than for reclaiming the fallen city. Alamar seeks those who share his belief that his people may need ruthless power.",sp=0},{t="Master of the Dark Arts",b="Alamar Grimm guides young gnomes who take up fel magic. A tainted memorandum earns a rare warm welcome, and he begins teaching basic spells. Before sharing the dangerous knowledge needed to bind a demonic imp, he demands proof of each novice's magical and physical endurance. He sends them to retrieve strange feather charms carried by local Frostmane troll novices.",sp=0}},faq={{q="Who is Alamar Grimm?",a="Alamar Grimm trains gnome warlocks at Anvilmar in Coldridge Valley. He teaches new students basic fel magic and how to summon their first imp.",al={"alamar grimm","who is alamar","gnome warlock trainer anvilmar"},it="identity"},{q="Why is Alamar Grimm angry at the dwarves?",a="Alamar resents the Ironforge dwarves because he believes reclaiming Gnomeregan matters less to them than their alliance with humans. Though they shelter the displaced gnomes, he feels they do not put his people's homeland first.",al={"why does alamar hate dwarves","alamar dwarf opinion","why angry"}},{q="What does Alamar Grimm ask new warlocks to do?",a="Alamar Grimm asks novice warlocks to gather feather charms from local Frostmane troll novices. He uses the charms to test their stamina and magical ability before teaching them to summon an imp.",al={"alamar grimm imp quest","feather charms quest","frostmane charms warlock"}},{q="Whose side is Alamar Grimm on?",a="Alamar Grimm stands firmly with the exiled gnomish people, though he harbors sharp bitterness toward their current allies. While the dwarves shelter the displaced gnomes in Dun Morogh, Alamar resents Ironforge's leadership, believing they prioritize ties with distant humans over reclaiming Gnomeregan. He operates within the Alliance purely to rebuild gnomish strength on his own terms.",al={"alamar grimm faction","alamar grimm allegiance","who does alamar grimm fight for"},it="side",add="04c944ae"},{q="What does Alamar Grimm want?",a="Alamar wants nothing less than the reclamation of Gnomeregan and the empowerment of his people through dark magical arts. Dismissing conventional adventurers as ineffective failures who allowed the city to fall, he seeks to cultivate disciplined, capable warlocks who possess the true magical and physical strength required to take their homeland back.",al={"alamar grimm goals","what does alamar want","alamar grimm motive"},it="wants",add="949ab41a"},{q="Why is Alamar Grimm in Coldridge Valley?",a="Following the tragic fall of Gnomeregan, Alamar sought refuge alongside his fellow survivors in the safety of Coldridge Valley. Stationed near Anvilmar, he acts as a mentor and trainer to newly arrived gnomes who feel the pull toward fel magic, testing their potential and arming them with the dark spells needed to survive the harsh road ahead.",al={"why is alamar grimm here","why is alamar in anvilmar","alamar grimm purpose here"},it="why_here",add="1846448c"}},ang={["class:Warlock"]="As a gnome warlock starting in Coldridge Valley, you learn your first spells from Alamar Grimm. You must prove your worth to earn your first imp.",["race:Gnome"]="As a gnome, you may share the bitterness of exiles who feel abandoned by their allies while Gnomeregan remains in trogg hands."},kw={"alamar","anvilmar","coldridge","gnomeregan","grimm","imp","trainer","warlock"},rel={"subzone:anvilmar","zone:dunmorogh","zone:gnomeregan","topic:gnome","quest:1599","npc:sten-stoutarm"},src={"Alamar Grimm"}}
E["npc:azar-stronghammer"] = {t="npc",n="Azar Stronghammer",z="dunmorogh",s="At the Thunderbrew Distillery in Kharanos, Azar Stronghammer guides new dwarven paladins in the Holy Light. He sends promising recruits to Ironforge for further instruction after their training.",h="At the Thunderbrew Distillery in Kharanos, Azar Stronghammer guides new dwarven paladins in the Holy Light.",sec={{t="A Guide in the Cold",b="Azar Stronghammer guides newly inducted dwarven paladins on Dun Morogh's freezing slopes. Humans are often linked to the great cathedrals, yet the dwarves of Khaz Modan have embraced the Holy Light. Having mastered his own martial and spiritual vows, Azar helps novices find their way. When a recruit shows dedication and spiritual maturity, he sends them up the mountain path to Ironforge, where veteran champions such as Tiza Battleforge can teach them further.",sp=0}},faq={{q="Who is Azar Stronghammer?",a="Azar Stronghammer trains dwarven paladins at the Thunderbrew Distillery in Kharanos. He guides them through their earliest instruction, then sends promising recruits to Ironforge for further study.",al={"who is azar","azar stronghammer role","kharanos paladin trainer"},it="identity"},{q="Where can Azar Stronghammer be found?",a="You can find Azar Stronghammer inside the Thunderbrew Distillery in Kharanos, among the snowy hills of Dun Morogh.",al={"azar stronghammer location","where is azar","find azar stronghammer"},gp=true},{q="What training does he provide to young paladins?",a="Azar teaches novices basic paladin martial arts and spells. When an apprentice is ready for the trials of the Tome of Divinity and its sacred rites of resurrection, he directs them to Tiza Battleforge in Ironforge.",al={"what does azar do","azar quest","paladin quests azar"},it="purpose",gp=true},{q="Why is a paladin trainer stationed at a distillery?",a="The Thunderbrew Distillery brings Kharanos's defenders and mentors together. Dwarven life joins civic duties and fellowship with stout drink, and the distillery lies at the heart of the village's social life and defense.",al={"why is paladin in distillery","paladin in bar","distillery trainer"},it="why_here"},{q="Whose side is Azar Stronghammer on?",a="Azar Stronghammer stands firmly with the Kingdom of Ironforge and the Alliance. As an experienced dwarven paladin, his loyalties lie with his people, King Magni Bronzebeard, and the holy tenets of the Light.",al={"azar stronghammer faction","azar stronghammer allegiance","who does azar fight for"},it="side",add="38fe723c"},{q="What does Azar Stronghammer want?",a="Having completed his own extensive training in the Light, Azar aims to guide the next generation of dwarven paladins. He watches over promising apprentices in Dun Morogh and ensures they are prepared before sending them onward to master trainers like Tiza Battleforge in Ironforge.",al={"azar stronghammer goals","what is azar trying to do","azar stronghammer purpose"},it="wants",add="56baf4f4"},{q="Who is Azar Stronghammer tied to?",a="Azar maintains strong ties to his fellow dwarven paladins, notably coordinating with Tiza Battleforge in the Hall of Mysteries in Ironforge to advance the education of promising initiates.",al={"azar stronghammer connections","azar stronghammer allies","who does azar know"},it="ties",add="132f6bb2"}},ang={["class:Paladin"]="As a dwarven paladin beginning in Dun Morogh, you can learn from Azar before he directs you to Ironforge to earn the sacred Tome of Divinity.",["race:Dwarf"]="Azar shows how the dwarves of Khaz Modan embrace the Holy Light. For you, devotion to holy righteousness belongs alongside a warm hearth and a mug of Thunderbrew."},kw={"azar","distillery","dun morogh","kharanos","paladin","stronghammer","thunderbrew","tome of divinity","trainer"},rel={"subzone:kharanos","subzone:thunderbrew-distillery","npc:tiza-battleforge","quest:2997","zone:ironforge","topic:light","topic:dwarf"},src={"Azar Stronghammer"}}
E["npc:balir-frosthammer"] = {t="npc",n="Balir Frosthammer",z="dunmorogh",s="In Coldridge Valley, Balir Frosthammer rallies recruits as Rockjaw troggs press into dwarven lands.",h="In Coldridge Valley, Balir Frosthammer rallies recruits as Rockjaw troggs press into dwarven lands.",sec={{t="Holding Coldridge Valley",b="Balir Frosthammer calls new recruits to defend Coldridge Valley. Dwarven and gnomish novices have long found safety and training there. But trouble underground has driven violent Rockjaw troggs to the surface. Balir is among the first to raise the alarm, urging recruits to thin their numbers before they push farther into Dun Morogh.",sp=0},{t="Kin of the Frosthammers",b="Balir Frosthammer shares his name with Tannok Frosthammer of Kharanos. The two may belong to the same family, whose members stand by Ironforge. They help keep the cold mountain passes safe for travelers, miners, and mountaineers as threats grow across the region.",sp=0}},faq={{q="Who is Balir Frosthammer?",a="Balir Frosthammer guards Coldridge Valley in Dun Morogh. He calls on incoming recruits to thin the hostile Rockjaw troggs threatening the valley's defenses.",al={"balir frosthammer who is he","who is balir"},it="identity"},{q="Why is Balir concerned about the troggs?",a="Rockjaw troggs have recently surfaced in force, disturbing Coldridge Valley and attacking dwarven settlements. Balir sees a growing danger that must be contained early.",al={"why troggs","trogg problem coldridge"},it="why_here"},{q="Is Balir related to Tannok Frosthammer?",a="Possibly. Balir shares the Frosthammer name with Tannok Frosthammer of Kharanos, which suggests a family connection, though none is confirmed.",al={"tannok relative","frosthammer family"},it="ties"},{q="Whose side is Balir Frosthammer on?",a="Balir stands firmly with Ironforge and the Alliance. Stationed in Coldridge Valley, he looks out for the safety of the dwarven homeland and works alongside fellow mountaineers and recruits to keep Dun Morogh secure against emerging dangers.",al={"balir frosthammer faction","who does balir serve","is balir alliance"},it="side",add="c02dfef8"},{q="What does Balir Frosthammer want?",a="Balir wants to drive back the Rockjaw troggs that have begun infesting the valley. Deeply alarmed by their sudden emergence and aggression, he enlists able-bodied adventurers to cull the invaders before they overrun Coldridge.",al={"balir frosthammer motive","what does balir need","why does balir need help"},it="wants",add="14c400d2"}},ang={["race:Dwarf"]="As a dwarf, you can help Balir Frosthammer defend your homeland from threats rising underground. His call offers an early chance to protect Dun Morogh.",["faction:Alliance"]="As an Alliance recruit, you train in Khaz Modan, while Balir works to keep Coldridge Valley secure as a staging ground."},kw={"a new threat","balir frosthammer","coldridge valley","dun morogh","rockjaw troggs","tannok frosthammer"},rel={"quest:170","subzone:coldridge-valley","zone:dunmorogh","npc:tannok-frosthammer","topic:trogg","topic:dwarf"},src={"Balir Frosthammer"}}
E["npc:beldin-steelgrill"] = {t="npc",n="Beldin Steelgrill",z="dunmorogh",s="At Steelgrill's Depot in Dun Morogh, Beldin Steelgrill keeps dwarven war machines running. Across Khaz Modan, he is renowned as a master technician, repairing siege engines and armored wagons with a steady supply of specialized tools.",h="At Steelgrill's Depot in Dun Morogh, Beldin Steelgrill keeps dwarven war machines running.",sec={{t="Master of the Treaded Beast",b="Just down the road from Kharanos, Steelgrill's Depot tests and services steam tanks and siege engines. The work strains heavy wrenches, cutters, and precision instruments against metal and rumbling boilers. Beldin needs replacements constantly, keeping local ironworkers busy at his bench.",sp=0}},faq={{q="Who is Beldin Steelgrill?",a="Beldin Steelgrill runs Steelgrill's Depot in Dun Morogh as its proprietor and master technician. Across Khaz Modan, he is famed for maintaining dwarven siege engines and war wagons.",al={"beldin steelgrill","who is beldin","tank mechanic dun morogh"},it="identity"},{q="What happens at Steelgrill's Depot?",a="Just northeast of Kharanos, Steelgrill's Depot is a yard where the Alliance tests and maintains steam tanks and heavy mechanized machines.",al={"steelgrills depot","what is steelgrill depot","depot purpose"},it="why_here"},{q="Why does Beldin go through so many tools?",a="Beldin's work on heavy armor, complex gears, and steam boilers wears through specialized tools quickly. Nearby smiths fill his demanding orders and keep his bench supplied.",al={"why does he need tools","steelgrill tools","tools for steelgrill"},it="wants"},{q="Whose side is Beldin Steelgrill on?",a="Beldin is loyal to the Bronzebeard clan of Ironforge and stands firmly with the Alliance. Working just down the road from Kharanos, he keeps the dwarven military and local defense forces outfitted with heavy mechanized armor and siege engines.",al={"beldin steelgrill faction","who does beldin serve","is beldin steelgrill alliance"},it="side",add="c08b01c8"},{q="Why is Beldin Steelgrill famous?",a="Beldin is renowned across Dun Morogh as the finest siege engine technician alive. His mastery over war machines and heavy mechanics gives him an unmatched reputation among dwarven engineers, though it also makes him notoriously demanding on local toolmakers.",al={"beldin steelgrill reputation","why is beldin known","greatest siege technician"},it="fame",add="940fd3ae"}},ang={["profession:Engineering"]="As an engineer, you can see dwarven vehicle craft at work in Beldin's yard, where the Alliance's formidable war machines are maintained.",["race:Dwarf"]="As a dwarf, you can see Ironforge's industrial craft at Beldin's yard, where dwarven skill reaches beyond hand tools to siege artillery."},kw={"beldin steelgrill","dun morogh","ironforge","kharanos","mechanic","siege engine","steam tank","steelgrill"},rel={"subzone:steelgrill-s-depot","quest:400","zone:dunmorogh","topic:dwarf"},src={"Beldin Steelgrill"}}
E["npc:bink"] = {t="npc",n="Bink",z="dunmorogh",s="In Ironforge's Hall of Mysteries, Bink teaches aspiring mages the arcane arts. Her quick mind helps promising students find wizards across the Alliance.",h="In Ironforge's Hall of Mysteries, Bink teaches aspiring mages the arcane arts.",sec={{t="A Beacon in the Hall of Mysteries",b="In Ironforge's Hall of Mysteries, Bink teaches the path of the mage. She works among the scholars, priests, and arcanists gathered in the Mystic Ward. Like many gnomes driven from Gnomeregan, she has made her home in the dwarven mountain stronghold. Her keen mind and skill in arcane craft guide those learning magic.\n\nBink knows wizards across the Eastern Kingdoms and Kalimdor. She points promising apprentices toward mentors such as High Sorcerer Andromath in Stormwind and Tabetha in Dustwallow Marsh.",sp=0}},faq={{q="Who is Bink?",a="Bink trains Alliance gnome mages in Ironforge's Hall of Mysteries. She teaches arcane spellcraft and guides mages as they develop.",al={"bink lore","who is bink","bink ironforge"},it="identity"},{q="Where can I find Bink?",a="You can find Bink in the Hall of Mysteries, in the western wing of Ironforge's Mystic Ward.",al={"bink location","where is bink","find bink"},gp=true},{q="What quests involve Bink?",a="Developing mages are directed to Bink by Speak with Bink. She sends them to study with authorities such as High Sorcerer Andromath in Stormwind's Wizard's Sanctum or the hermit mage Tabetha in Dustwallow Marsh.",al={"bink quests","speak with bink quest"},gp=true},{q="What does Bink say to non-mages?",a="If you do not practice the arcane, Bink cheerfully advises, 'Befriend a mage! We have a trick or two up our sleeves, we do...'",al={"bink gossip","bink dialogue"}},{q="Whose side is Bink on?",a="Bink stands firmly with the Alliance and the Gnomeregan Exiles sheltered within Ironforge. Operating out of the Hall of Mysteries alongside fellow scholars and sorcerers, she dedicates her magical talents to aiding her allies and instructing promising new mages who fight under the Alliance banner.",al={"bink faction","who does bink serve","bink alliance or horde"},it="side",add="cf09b30e"},{q="Why is Bink in the Hall of Mysteries?",a="Bink resides in Ironforge's Hall of Mysteries to serve as a gnome mage trainer. Following the fall of Gnomeregan, the displaced gnomes found refuge among the Bronzebeard dwarves, and Bink lends her arcane expertise to train aspiring mages and dispatch students on tasks vital to the arcane community.",al={"why is bink here","what is bink doing in ironforge","why is bink in ironforge"},it="why_here",add="d0de8b26"}},ang={["class:Mage"]="As an Alliance mage in Ironforge, you can learn from Bink and follow her guidance to powerful mentors across Azeroth.",["race:Gnome"]="As a gnome, you share Bink's pursuit of arcane mastery among exiles sheltered in the halls of their dwarven allies."},kw={"andromath","bink","gnome","hall of mysteries","ironforge","mage trainer","mystic ward","tabetha"},rel={"subzone:hall-of-mysteries","subzone:mystic-ward","zone:ironforge","quest:1879","quest:1939","npc:tabetha","topic:gnome","zone:dunmorogh"},src={"Bink"}}
E["npc:branstock-khalder"] = {t="npc",n="Branstock Khalder",z="dunmorogh",s="At Anvilmar in Coldridge Valley, Branstock Khalder guides dwarven priests in the Holy Light and watches the trogg threat beyond the outpost.",h="At Anvilmar in Coldridge Valley, Branstock Khalder guides dwarven priests in the Holy Light and watches the...",sec={{t="A Guiding Hand in Coldridge",b="At Anvilmar, Branstock Khalder teaches novice priests their first prayers and sacred runes. He guides them in the Light while troggs menace the local mountaineers. When a novice has learned enough, Branstock sends them through Coldridge Pass to Kharanos. There, they can seek further guidance from his superior, Father Maxan Anvol.",sp=0}},faq={{q="Who is Branstock Khalder?",a="At Anvilmar in Coldridge Valley, Branstock Khalder trains young dwarven priests in the Holy Light and counsels them through the valley’s hardships.",al={"branstock lore","who is branstock","anvilmar priest trainer"},it="identity"},{q="Where does Branstock send his students next?",a="Branstock sends young priests through Coldridge Pass to Kharanos for further guidance from his superior, Father Maxan Anvol.",al={"where do i go after branstock","branstock next quest","priest path from anvilmar"},it="next_step"},{q="What is Branstock concerned about in Coldridge Valley?",a="Branstock is concerned about the growing trogg threat in Coldridge Valley and the danger it poses to local mountaineers.",al={"anvilmar problems","branstock worries","trogg threat coldridge"},it="danger"},{q="What does he say to non-priests?",a="Branstock advises you never to turn your back on the Light. Faith may save your life someday.",al={"branstock quote","branstock gossip text"}},{q="Whose side is Branstock Khalder on?",a="Branstock stands firmly with Ironforge and the Alliance. As a priest of the Holy Light, he dedicates himself to nurturing novice dwarven priests while safeguarding Coldridge Valley against outside threats.",al={"branstock khalder faction","who does branstock khalder serve","branstock khalder allegiance"},it="side",add="ac45145a"},{q="What does Branstock Khalder want?",a="Branstock aims to instruct fledging acolytes in the ways of the Holy Light and ensure they possess the fortitude to survive outside Anvilmar. He also wants the local trogg menace subdued before it completely overwhelms Coldridge Valley.",al={"branstock khalder goals","what does branstock want","branstock khalder purpose"},it="wants",add="48c1936a"},{q="Why is Branstock Khalder in Coldridge Valley?",a="Branstock is stationed at Anvilmar to welcome newly awakened priests and train them in basic prayers and holy disciplines. From this quiet post, he prepares young initiates before directing them onward to Kharanos.",al={"why is branstock khalder here","branstock anvilmar purpose","why is branstock in anvilmar"},it="why_here",add="0b38c258"},{q="Who is Branstock Khalder tied to?",a="Branstock serves under Priest Maxan Anvol, his superior stationed further down the mountain in Kharanos. He also cooperates closely with local defenders like Sten Stoutarm to identify promising candidates among new recruits.",al={"branstock khalder connections","who does branstock report to","branstock khalder superior"},it="ties",add="15965ad4"}},ang={["class:Priest"]="As a priest, you meet Branstock Khalder as your first spiritual guide. He teaches you an initial sacred rune and introduces you to the healing and defensive arts of the Holy Light.",["race:Dwarf"]="As a dwarf, you find in Branstock a practical devotion to the Light and resilience against the cold and trogg threat."},kw={"anvilmar","branstock","coldridge","dun morogh","khalder","light","priest","trainer"},rel={"subzone:anvilmar","subzone:coldridge-valley","npc:maxan-anvol","quest:5623","npc:sten-stoutarm","subzone:kharanos","subzone:coldridge-pass","topic:light"},src={"Branstock Khalder"}}
E["npc:bromos-grummner"] = {t="npc",n="Bromos Grummner",z="dunmorogh",s="In Anvilmar, Bromos Grummner guides young dwarven paladins in the Holy Light and welcomes them to its discipline. He teaches steadfast faith and the bond between dwarves and humans in the Knights of the Silver Hand.",h="In Anvilmar, Bromos Grummner guides young dwarven paladins in the Holy Light and welcomes them to its...",sec={{t="A Beacon in Coldridge",b="In Anvilmar, Bromos teaches young paladins the rites of battle and sacred invocations. Yet he speaks of more than combat. The Knights of the Silver Hand unite Ironforge and the human kingdoms of the Alliance in a shared righteous purpose.",sp=0}},faq={{q="Who is Bromos Grummner?",a="Bromos Grummner trains new dwarven paladins in Anvilmar, in Coldridge Valley within Dun Morogh. He gives them basic training, spells, and spiritual guidance.",al={"who is bromos","bromos grummner lore","anvilmar paladin trainer"},it="identity"},{q="What order does Bromos represent?",a="Bromos represents the Knights of the Silver Hand. He teaches the bond between humans and dwarves, forged beneath the holy order's banner.",al={"bromos silver hand","is bromos silver hand"},it="ties"},{q="What does he teach new recruits?",a="Bromos teaches new paladins basic combat arts and divine spells. He sets early trials for initiates to prove their devotion to the Light and their readiness to protect Dun Morogh.",al={"bromos quests","what does bromos grummner do"}},{q="Whose side is Bromos Grummner on?",a="Bromos stands firmly with Ironforge and the Grand Alliance. As a devout member of the Knights of the Silver Hand, he places immense value on the enduring bond forged between dwarves and humans, believing their shared faith in the Holy Light is essential to holding their realms together.",al={"bromos grummner faction","bromos alliance","who does bromos fight for"},it="side",add="73c3e4de"},{q="Why is Bromos Grummner here in Coldridge Valley?",a="Bromos is stationed at Anvilmar to instruct novice dwarven paladins answering the call of the Holy Light. Amid the encroaching cold and local trogg threats, he ensures every aspiring defender learns to wield martial prowess and righteous blessings in service to their people.",al={"why is bromos in anvilmar","bromos grummner purpose","what is bromos doing here"},it="why_here",add="830a5136"},{q="What does Bromos Grummner want?",a="Bromos wants to foster a disciplined, unyielding generation of dwarven paladins. He aims to instill in his students not only mastery over the Light's holy powers, but also deep dedication to the sacred alliance between dwarves and humans within the Silver Hand.",al={"what does bromos want","bromos goals","bromos motive"},it="wants",add="33b2371f"}},ang={["class:Paladin"]="As a dwarven paladin, you can look to Bromos as your first spiritual mentor. He introduces you to the sacred duties of the Silver Hand.",["race:Dwarf"]="As a dwarf, you follow a long tradition of devotion to the Light and fight beside your human allies."},kw={"anvilmar","bromos","coldridge","dun morogh","grummner","paladin","silver hand","trainer"},rel={"subzone:anvilmar","zone:dunmorogh","topic:knights-of-the-silver-hand","topic:light","topic:dwarf","topic:alliance","quest:3107"},src={"Bromos Grummner"}}
E["npc:durnan-furcutter"] = {t="npc",n="Durnan Furcutter",z="dunmorogh",s="At Anvilmar in Coldridge Valley, Durnan Furcutter outfits young dwarves and gnomes for the mountain cold. He sells light clothing and leather goods from inside the settlement.",h="At Anvilmar in Coldridge Valley, Durnan Furcutter outfits young dwarves and gnomes for the mountain cold.",sec={{t="A Warm Stitch in the Cold",b="Inside Anvilmar, young dwarves and exiled gnomes prove themselves. Some need more freedom of movement than heavy iron allows. Durnan Furcutter sells light, pliable layers to scouts, rogues, and spellcasters who want to stay agile in Dun Morogh's bitter winds. Near the hearth, he offers everyday tailoring and stitched leather. He claims his stock is the finest in the valley.",sp=0},{t="A Mug in Hand",b="Durnan likes a strong drink as much as an honest trade. To warm himself against the freezing draft, he orders steaming mugs of Scalding Mornbrew from Nori Pridedrift, who sells the brew piping hot across Coldridge Valley. Adventurers hurrying through the valley with errands often bring Durnan a hot mug before it cools. Then they carry the empty back to Nori.",sp=0}},faq={{q="Who is Durnan Furcutter?",a="Durnan Furcutter sells basic cloth and leather gear to novice adventurers setting out in Dun Morogh. He is a dwarven clothier and leather merchant at Anvilmar in Coldridge Valley.",al={"durnan","furcutter","who is durnan furcutter"},it="identity"},{q="Where can I find Durnan Furcutter?",a="You can find Durnan Furcutter inside Anvilmar in Coldridge Valley, near the training masters and local tradesfolk.",al={"durnan location","where is durnan","anvilmar cloth vendor"},it="place",gp=true},{q="What does Durnan sell?",a="Durnan sells introductory cloth and leather armor for adventurers who depend on agility or spellcasting instead of heavy mail.",al={"durnan wares","what does durnan sell"},gp=true},{q="Why is he involved with Scalding Mornbrew deliveries?",a="Durnan works long hours in Coldridge Valley's icy winds. He orders hot Scalding Mornbrew from Nori Pridedrift, who sells it across the valley, to stay warm and sharp.",al={"durnan beer quest","scalding mornbrew durnan","durnan drink"},it="motive"},{q="Whose side is Durnan Furcutter on?",a="Durnan stands firmly with Ironforge and the Alliance. Stationed inside Anvilmar, he outfits the young dwarven and gnomish recruits who begin their journeys in Coldridge Valley.",al={"durnan faction","durnan furcutter alliance","who does durnan serve"},it="side",add="d97cf4a2"},{q="What does Durnan Furcutter want?",a="First and foremost, Durnan aims to ply his trade, boasting that he provides the finest cloth and leather garb this side of the valley. Beyond business, he never turns down a mug of steaming Scalding Mornbrew to fend off the biting chill of Coldridge Valley.",al={"what does durnan want","durnan furcutter goals","durnan purpose"},it="wants",add="afaf309b"},{q="Why is Durnan Furcutter in Anvilmar?",a="Anvilmar serves as the training hall and gathering hub for novitiates starting out in Coldridge Valley. Durnan remains here to supply fresh adventurers with essential garments and basic armor before they venture out into the snowy wilderness.",al={"why is durnan here","why is durnan in coldridge valley","durnan location why"},it="why_here",add="9750ade9"}},ang={["race:Dwarf"]="As a dwarf in Coldridge Valley, you see Durnan's practical craft and his fondness for a hot brew. His friendly banter carries through the snow.",["profession:Tailoring"]="As a budding tailor, you can learn from Durnan's basic garments. They help keep scouts and apprentices alive in the snowy passes before mastercrafted cloth takes over."},kw={"anvilmar","cloth vendor","coldridge valley","dun morogh","durnan furcutter","leather vendor","scalding mornbrew"},rel={"subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","quest:3364","quest:3365","quest:59","topic:dwarf"},src={"Durnan Furcutter"}}
E["npc:elder-goldwell"] = {t="npc",n="Elder Goldwell",z="dunmorogh",s="During the Lunar Festival, Elder Goldwell appears near Kharanos. The ancient earthen spirit recalls the beginnings of modern dwarven civilization.",h="During the Lunar Festival, Elder Goldwell appears near Kharanos.",sec={{t="A Spirit of the Earthen",b="Near Kharanos, Elder Goldwell watches over the snowy slopes as a translucent earthen spirit. His stony form recalls the Titan-forged ancestors of the Bronzebeard clan. During the ancestor celebrations, travelers can honor that heritage in his presence.",sp=0}},faq={{q="Who is Elder Goldwell?",a="Elder Goldwell is an earthen ancestor spirit who appears near Kharanos in Dun Morogh. During seasonal ancestor observances, travelers can pay respect to dwarven forebears.",al={"elder goldwell identity","who is goldwell","goldwell lore"},it="identity"},{q="Where is Elder Goldwell located?",a="Elder Goldwell stands outside Kharanos in Dun Morogh, usually near the local inn and gathering areas.",al={"elder goldwell location","where to find elder goldwell","find goldwell"},it="place",gp=true},{q="Why does Elder Goldwell look like an earthen rather than a dwarf?",a="Dwarves trace their ancestry to the stone-skinned earthen created by the Titans. As an ancient spirit honoring past generations, Goldwell keeps the earthen form rather than the flesh of living dwarves.",al={"why is goldwell earthen","is goldwell an earthen","goldwell rock dwarf"},it="origin"}},ang={["race:Dwarf"]="As a dwarf, meeting Elder Goldwell offers a rare look at your stone-wrought heritage and the lineage connecting modern Ironforge to the earthen.",["faction:Alliance"]="As an Alliance traveler passing through Kharanos, you can seek out Goldwell to pay your respects and receive traditional blessings of good fortune."},kw={"ancestor","dun morogh","earthen","elder goldwell","goldwell","kharanos","lunar festival"},rel={"quest:8653","subzone:kharanos","zone:dunmorogh"},src={"Elder Goldwell"}}
E["npc:felix-whindlebolt"] = {t="npc",n="Felix Whindlebolt",z="dunmorogh",s="At Anvilmar in Coldridge Valley, Felix Whindlebolt seeks shelter after fleeing Gnomeregan's radiation. Frostmane trolls have taken his belongings.",h="At Anvilmar in Coldridge Valley, Felix Whindlebolt seeks shelter after fleeing Gnomeregan's radiation.",sec={{t="A Displaced Traveler",b="Felix Whindlebolt fled Gnomeregan when radiation flooded the city. In the rush, he left his belongings and tools behind.\n\nFrostmane ice trolls carried his chest, box and bucket of bolts to their camps southwest of Anvilmar. Without his gear, Felix depends on travelers to retrieve it.",sp=0}},faq={{q="Who is Felix Whindlebolt?",a="Felix Whindlebolt is a gnome refugee sheltered at Anvilmar in Coldridge Valley. He lost his belongings while fleeing Gnomeregan, and Frostmane trolls took them.",al={"who is felix","felix whindlebolt lore","gnome at whitebeard camp"},it="identity"},{q="Where was Felix trying to go?",a="Felix fled the radiation that overran Gnomeregan after the gnomes' attempt to drive out the troggs went horribly wrong. He reached Anvilmar, a dwarven outpost in Coldridge Valley, but finds it poorly suited to a gnome.",al={"where was felix heading","felix destination","why is felix in coldridge valley"},it="why_here"},{q="What happened to his possessions?",a="In his haste to escape Gnomeregan, Felix lost his chest, box and bucket of bolts. Frostmane ice trolls carried them to their camps southwest of Anvilmar, leaving him without supplies.",al={"who stole felix stuff","felix stolen gear","frostmane trolls felix"},it="wants"},{q="What does Felix sell to adventurers?",a="Felix sells nothing. He lost all his belongings while fleeing Gnomeregan, and at Anvilmar he can only thank anyone who recovers his chest, box and bucket of bolts.",al={"felix vendor items","what does felix offer","felix inventory"},gp=true},{q="Whose side is Felix Whindlebolt on?",a="Felix is aligned with the Gnomeregan Exiles and the Grand Alliance. Like many displaced gnomes, he fled the irradiated ruins of Gnomeregan and now shelters at Anvilmar in Coldridge Valley, hoping to rejoin his people.",al={"felix faction","is felix alliance","who does felix work for"},it="side",add="b1540142"}},ang={["race:Gnome"]="As a gnome, you share the plight of your kin, driven into the cold of Dun Morogh after Gnomeregan's fall.",["race:Dwarf"]="As a dwarf, you can see Frostmane trolls striking at gnome refugees near Anvilmar. Their attacks grow bolder across Coldridge Valley."},kw={"anvilmar","coldridge valley","felix whindlebolt","frostmane","gnomeregan","refugee","whitebeard's encampment"},rel={"quest:3361","subzone:coldridge-valley","zone:dunmorogh","zone:gnomeregan","subzone:anvilmar","topic:gnome","topic:troll","topic:refugee"},src={"Felix Whindlebolt"}}
E["npc:foreman-stonebrow"] = {t="npc",n="Foreman Stonebrow",z="dunmorogh",s="At Gol'Bolar Quarry, Foreman Stonebrow faces a trogg attack that has driven miners from the pits. He speaks for the Miners' League and needs help defending the excavation.",h="At Gol'Bolar Quarry, Foreman Stonebrow faces a trogg attack that has driven miners from the pits.",sec={{t="The Crisis at Gol'Bolar",b="Foreman Stonebrow directs the Miners' League's work at Gol'Bolar Quarry, east of Kharanos. Deep digging broke into trogg burrows beneath the quarry. The creatures swarmed the pits and drove miners from their tools. Stonebrow remains at the quarry rim, seeking travelers willing to push the troggs back.",sp=0}},faq={{q="Who is Foreman Stonebrow?",a="Foreman Stonebrow oversees the Miners' League's work at Gol'Bolar Quarry in Dun Morogh. He coordinates the digging and works to keep the site secure.",al={"stonebrow","who is stonebrow","foreman stonebrow lore"},it="identity"},{q="Why is Foreman Stonebrow asking for help?",a="The digging broke into trogg caverns beneath Gol'Bolar Quarry. Troggs swept across the lower terraces, killing workers and driving the surviving miners back to the camp at the rim.",al={"gol bolar trogg problem","why need help","quarry quest"},it="wants"},{q="What is the Miners' League?",a="The Miners' League is a dwarven guild and trade organization based in Ironforge. It oversees mining expeditions, resource gathering, and quarry work throughout Khaz Modan.",al={"miners league","what is miners league"},it="ties"},{q="Where can Foreman Stonebrow be found?",a="Foreman Stonebrow is at the camp on the rim of Gol'Bolar Quarry, in eastern Dun Morogh, just off the road to Loch Modan.",al={"stonebrow location","where is foreman stonebrow"},it="place",gp=true},{q="Whose side is Foreman Stonebrow on?",a="Foreman Stonebrow is loyal to the Miners' League and the dwarven kingdom of Ironforge, placing him firmly in the Alliance. He oversees civic excavation work in Dun Morogh and seeks Alliance adventurers to clear threats from Ironforge's mining operations.",al={"stonebrow faction","who does stonebrow serve","stonebrow alliance"},it="side",add="2635f3c5"},{q="Why is Foreman Stonebrow at Gol'Bolar Quarry?",a="Foreman Stonebrow was sent to Gol'Bolar Quarry to supervise excavation and resource extraction on behalf of the Miners' League. He remains stationed near the quarry pit to rally assistance and coordinate efforts to retake the site after a sudden trogg infestation overwhelmed the workforce.",al={"why is stonebrow here","stonebrow golbolar","what is stonebrow doing here"},it="why_here",add="c868fd05"}},ang={["race:Dwarf"]="For a dwarf, the trogg attack on Gol'Bolar Quarry strikes at Ironforge's stone industry and recalls the ancient dangers beneath dwarven lands.",["profession:Mining"]="As a miner, you have a stake in helping Stonebrow reclaim the quarry's stone and ore deposits, vital to Khaz Modan's guild operations."},kw={"dun morogh","foreman stonebrow","gol bolar","gol'bolar quarry","miners' league","stonebrow","troggs"},rel={"subzone:gol-bolar-quarry","quest:432","topic:trogg","topic:dwarf","zone:dunmorogh"},src={"Foreman Stonebrow"}}
E["npc:grelin-whitebeard"] = {t="npc",n="Grelin Whitebeard",z="dunmorogh",s="In Coldridge Valley, Grelin Whitebeard keeps watch over the Frostmane threat by royal decree. Ironforge is busy fighting troggs, so his isolated camp depends on local recruits.",h="In Coldridge Valley, Grelin Whitebeard keeps watch over the Frostmane threat by royal decree.",sec={{t="A Royal Mandate",b="Grelin Whitebeard and his brother Senir came to Coldridge Valley under orders from the Senate of Ironforge and King Magni Bronzebeard. Their charge was to assess and quell the threat from the native Frostmane trolls. Ironforge's soldiers are busy fighting trogg outbreaks across Dun Morogh, leaving the brothers short of supplies. So Grelin made camp in the snowy hills and relies on local recruits and passing initiates to do the work.",sp=0},{t="Trouble in the South",b="From his camp, Grelin watches the Frostmane tribe press south from Coldridge Valley. The trolls grow bolder and raid beyond their mountain caverns. During one raid, Grik'nir the Cold, a heavily painted troll, slipped into the unattended camp and stole Grelin's field journal of observations.\n\nGrelin will not fail the King. He sends travelers into the Frostmane caves to recover his writings and carry his final report to Senir in Kharanos.",sp=0}},faq={{q="Why is Grelin Whitebeard out here in the snow?",a="The Senate of Ironforge and King Magni Bronzebeard sent Grelin to assess and quell the Frostmane threat in Coldridge Valley. With Ironforge's soldiers busy fighting troggs elsewhere, he relies on local recruits.",al={"why is grelin here","grelin whitebeard purpose","who is grelin whitebeard"},it="why_here"},{q="Who stole Grelin's journal?",a="A Frostmane troll named Grik'nir the Cold stole Grelin's journal during a raid on his unattended camp. Grelin saw the heavily marked brute flee toward the southern troll caves with his field notes.",al={"who stole the journal","stolen journal thief","grelin journal"}},{q="Who is Grelin's brother?",a="Grelin's brother is Senir Whitebeard, stationed in Kharanos farther down the mountain. Grelin sends trusted runners there with reports on troll movements.",al={"grelin brother","senir whitebeard","who is senir"},it="ties"},{q="Who is with Grelin at his camp?",a="No companions are recorded at Grelin's camp. Grelin and Senir were sent to face the trolls with little help, and the camp was unattended when the trolls raided it.",al={"whitebeard camp npcs","who is with grelin","grelin companions"}},{q="Why doesn't Ironforge send regular soldiers to help him?",a="Ironforge's defenders and Senate forces are busy with trogg infestations across Dun Morogh. Scouts like Grelin rely on local recruits to face regional threats.",al={"why no dwarven army","where is the ironforge guard","why no soldiers"}},{q="Who is Grelin Whitebeard?",a="Grelin Whitebeard is an investigator sent into Coldridge Valley on behalf of the Ironforge Senate and King Magni Bronzebeard. Tasked with assessing the aggressive movements of the Frostmane trolls, he maintains a remote camp in the snowy valley, relying on fresh mountaineer recruits to push back the trolls while the main dwarven army is preoccupied elsewhere.",al={"who is grelin","grelin whitebeard lore","who is whitebeard"},it="identity",add="bc052fbe"},{q="Whose side is Grelin Whitebeard on?",a="Grelin is entirely loyal to the Kingdom of Ironforge and the Grand Alliance. He answers directly to the Senate of Ironforge and carries dispatches stamped by King Magni's own hand, working tirelessly to secure dwarven lands against external threats.",al={"grelin whitebeard faction","who does grelin work for","is grelin alliance"},it="side",add="d217c46a"},{q="What does Grelin Whitebeard want?",a="Grelin wants an expedient resolution to the Frostmane troll problem in southern Coldridge Valley. Because the dwarven guard is tied down fighting trogg incursions, he needs able-bodied adventurers to cull the aggressive trolls, recover his stolen journal from the troll leader Grik'nir, and deliver his finalized reconnaissance report to his brother in Kharanos.",al={"what is grelin trying to do","grelin whitebeard goal","what does grelin need"},it="wants",add="6d2fc414"}},ang={["race:Dwarf"]="As a dwarf, you see Grelin serving King Magni and guarding Dun Morogh's borders against threats within Ironforge's reach.",["race:Gnome"]="As a gnome newly arrived from Gnomeregan's tragedy, you may find Grelin glad for any capable hand against the Frostmane.",["faction:Alliance"]="As an Alliance member, you see how thin Alliance and Ironforge forces are stretched across Dun Morogh. Scouts like Grelin face the trolls with little help."},kw={"coldridge valley","dun morogh","frostmane","grelin whitebeard","grik'nir","ironforge senate","senir whitebeard","the stolen journal"},rel={"subzone:coldridge-valley","npc:senir-whitebeard","quest:218","quest:182","quest:282","subzone:kharanos","zone:dunmorogh","topic:troll"},src={"Grelin Whitebeard"}}
E["npc:grif-wildheart"] = {t="npc",n="Grif Wildheart",z="dunmorogh",s="Outside the Thunderbrew Distillery in Kharanos, Grif Wildheart guides young hunters toward life with a beast companion. He teaches tracking, marksmanship, and how to tame beasts to hunters arriving from Coldridge Valley.",h="Outside the Thunderbrew Distillery in Kharanos, Grif Wildheart guides young hunters toward life with a beast...",sec={{t="A Life in the Wilds",b="Grif Wildheart has spent his life in Dun Morogh’s frozen wilds. While many Ironforge dwarves choose the forge or the mines, local mountaineers say he spends too much time among four-legged beasts. Still, none question his command of the wild. Years spent tracking snowbound ridges with seasoned hunting companions have taught him the ways of the predators among the crags.",sp=0},{t="The Way of the Beast",b="Young dwarf hunters finish their first trials in Coldridge Valley, then travel to Kharanos for Grif’s guidance. He sharpens their aim and teaches them to survive in the wild. His deepest craft, though, is joining hunter and beast. He sends his pupils into Dun Morogh’s freezing wastes with a taming rod to face Large Crag Boars, Snow Leopards, and Ice Claw Bears.",sp=0},{t="Journey to the Hall of Arms",b="Once a hunter has calmed three kinds of wild beasts, Grif’s training in Kharanos is complete. A hunter must also learn to feed, discipline, and train a new companion. So Grif sends his graduates up the mountainside to Ironforge. Beneath the capital’s vaulted roofs, they report to master beast trainers and learn to care for a companion meant to stay with them for life.",sp=0}},faq={{q="Who is Grif Wildheart?",a="Grif Wildheart trains hunters in Kharanos, Dun Morogh. He guides novice Alliance hunters who have finished their first trials in Coldridge Valley.",al={"who is grif","grif wildheart identity","about grif"},it="identity"},{q="Where can I find Grif Wildheart?",a="You can find Grif outside the Thunderbrew Distillery in Kharanos, along the snowy road from Coldridge Pass to Ironforge.",al={"grif wildheart location","where is grif","grif in kharanos"},gp=true},{q="What does Grif teach novice hunters?",a="Grif teaches young hunters to sharpen their aim, survive in the wild, and tame beasts. His lessons include wild boars, leopards, and bears.",al={"what does grif teach","grif hunter training","grif skills"},it="purpose",gp=true},{q="What beasts does Grif send hunters to tame?",a="Grif sends hunters into Dun Morogh to tame a Large Crag Boar, a Snow Leopard, and an Ice Claw Bear.",al={"grif taming quests","which animals to tame dun morogh","taming the beast targets"},gp=true},{q="Where does Grif send hunters after completing their taming trials?",a="After their taming trials, hunters go to Ironforge. There, advanced beast trainers teach them to feed and command their companions.",al={"where after grif","training the beast next step","grif follow up quest"},it="next_step",gp=true},{q="What do the Ironforge mountaineers think of Grif?",a="Local Ironforge Mountaineers say Grif spends too much time with animals. Yet they readily admit he knows the hunter’s craft better than almost anyone.",al={"mountaineer opinion of grif","is grif respected","grif reputation"},it="ties"},{q="Whose side is Grif Wildheart on?",a="Grif Wildheart is firmly loyal to Ironforge and the Grand Alliance. He serves his people by mentoring young dwarven hunters in Kharanos, ensuring they have the discipline and survival skills needed to protect the mountain kingdom and its territories.",al={"grif wildheart faction","is grif alliance","grif wildheart loyalty"},it="side",add="5a030de6"},{q="What does Grif Wildheart want?",a="Grif is dedicated to passing on the craft of the wild. He wants aspiring hunters to master beast taming and wilderness survival, sending novitiates into the snows of Dun Morogh to learn respect, patience, and how to forge lifelong bonds with the creatures of the crags.",al={"grif wildheart goal","what does grif want","grif wildheart motive"},it="wants",add="a3b5e7f5"},{q="Why is Grif Wildheart in Kharanos?",a="Grif is stationed in Kharanos to train fresh recruits who venture down from Coldridge Valley. As a central crossroads in Dun Morogh, Kharanos is the ideal proving ground for young hunters ready to test their wits against the mountain's boars, leopards, and bears.",al={"why is grif here","grif wildheart dun morogh why","why is grif in kharanos"},it="why_here",add="20183458"}},ang={["class:Hunter"]="As a hunter, you learn to tame beasts from Grif and can bond with wild predators across Dun Morogh.",["race:Dwarf"]="As a dwarf, you can follow Grif’s mountaineer tradition and live alongside wild mountain beasts.",["faction:Alliance"]="As an Alliance scout or sharpshooter, you can learn from Grif in Kharanos and prepare for the wilderness around Ironforge."},kw={"beast taming","dun morogh","grif wildheart","hunter trainer","kharanos","mountaineer","taming the beast","thunderbrew distillery"},rel={"subzone:kharanos","quest:6061","quest:6081","quest:6065","zone:dunmorogh","zone:ironforge","topic:dwarf","topic:alliance"},src={"Grif Wildheart"}}
E["npc:hands-springsprocket"] = {t="npc",n="Hands Springsprocket",z="dunmorogh",s="At Coldridge Pass, Hands Springsprocket struggles to keep supplies moving between the valley and Kharanos. Rockjaw troggs have blocked the route.",h="At Coldridge Pass, Hands Springsprocket struggles to keep supplies moving between the valley and Kharanos.",sec={{t="A Bottleneck in the Pass",b="At the mouth of Coldridge Pass, Hands Springsprocket finds his supply runs stopped by Rockjaw troggs. He usually carries provisions to the Thunderbrew distillery and the inn in Kharanos. The troggs have overrun the underground tunnel out of Coldridge Valley, halting trade and foot traffic. Now Hands depends on travelers who can carry essential crates through the dangerous mountain passage.",sp=0}},faq={{q="Who is Hands Springsprocket?",a="Hands Springsprocket is a gnome stationed in Coldridge Valley, just outside Coldridge Pass. He carries supplies to the lower reaches of Dun Morogh.",al={"who is hands springsprocket","hands springsprocket lore","who is this gnome"},it="identity"},{q="Why does he need help moving supplies?",a="Rockjaw troggs have infested the pass between Coldridge Valley and the rest of Dun Morogh. Routine transport is too dangerous without armed escorts or capable travelers.",al={"why does hands need help","coldridge pass supplies","why are supplies stuck"},it="why_here"},{q="Where are his supplies destined?",a="Hands arranges shipments to Kharanos, including goods for Tannok Frosthammer and the local innkeepers who depend on provisions from across the snowy peaks.",al={"where do supplies go","hands supply route","who gets the crate"},it="target"},{q="Whose side is Hands Springsprocket on?",a="Hands is a loyal member of the Alliance and a friend to the dwarven folk of Dun Morogh. Like many gnomes displaced by the tragedy at Gnomeregan, he works closely alongside his Ironforge allies, handling logistics and deliveries to support local communities like Kharanos.",al={"hands springsprocket faction","is hands springsprocket alliance"},it="side",add="d7333ab8"},{q="What does Hands Springsprocket want?",a="Hands wants his deliveries safely shuttled through Coldridge Pass to Tannok Frosthammer at the Thunderbrew Distillery in Kharanos. The recent surge of hostile Rockjaw troggs throughout the tunnel has completely stalled his shipments, leaving him desperate for an adventurer willing to carry the crate through the danger.",al={"what does hands want","hands springsprocket goal"},it="wants",add="8576a218"},{q="Who is Hands Springsprocket tied to?",a="Hands regularly does business with Tannok Frosthammer, the innkeeper at the Thunderbrew Distillery in Kharanos. Whenever supplies are needed down in the lowlands, Hands coordinates the shipments through the pass, relying on travelers to help bridge the gap when the road turns hazardous.",al={"who does hands work with","hands springsprocket ties"},it="ties",add="d21580a2"}},ang={["race:Gnome"]="Hands shows the determination of gnomes building trade ties in Dun Morogh alongside their dwarven allies.",["faction:Alliance"]="Hands keeps supplies moving between the dwarven recruits in Coldridge Valley and settlements deeper in Dun Morogh."},kw={"coldridge pass","coldridge valley","dun morogh","hands springsprocket","kharanos","springsprocket","supplies to tannok"},rel={"subzone:coldridge-pass","subzone:coldridge-valley","quest:2160","subzone:kharanos","zone:dunmorogh","topic:trogg","topic:gnome","topic:alliance"},src={"Hands Springsprocket"}}
E["npc:hegnar-rumbleshot"] = {t="npc",n="Hegnar Rumbleshot",z="dunmorogh",s="On the snowy road from Coldridge Pass to Kharanos, Hegnar Rumbleshot supplies hunters and mountaineers with firearms and ammunition.",h="On the snowy road from Coldridge Pass to Kharanos, Hegnar Rumbleshot supplies hunters and mountaineers with...",sec={{t="A Gunsmith on the Road",b="Between Coldridge Pass and Kharanos, Hegnar's small camp serves dwarven marksmen, travelers, and the local militia. Mountain folk use its popular range to practice against Dun Morogh's wild beasts. The steady stream of shooters keeps Hegnar reliant on fresh ammunition from Loslor Rudge, a dwarf engineer.",sp=0}},faq={{q="Who is Hegnar Rumbleshot?",a="Hegnar Rumbleshot keeps a gunsmith's camp and outdoor shooting range on the road between Coldridge Pass and Kharanos.",al={"who is hegnar","hegnar rumbleshot npc","gunsmith in dun morogh"},it="identity"},{q="Where does Hegnar get his ammunition?",a="Hegnar gets ammunition from Loslor Rudge, a dwarf engineer elsewhere in Dun Morogh who supplies the range.",al={"hegnar supplier","who supplies rumbleshot","ammo for rumbleshot quest"},it="ties"},{q="What does Hegnar do for the local dwarves?",a="Hegnar supplies local hunters and militia members with firearms and shot. He also offers a practice range for marksmen traveling through Dun Morogh.",al={"why is hegnar here","hegnar shooting range","rumbleshot role"},it="purpose"},{q="Whose side is Hegnar Rumbleshot on?",a="Hegnar is firmly loyal to Ironforge and the Alliance. Stationed along the mountain road, he equips Dun Morogh's local militia, defenders, and hunters with reliable firearms to keep the kingdom's snowy passes safe from encroaching threats.",al={"hegnar rumbleshot faction","is hegnar alliance","who does hegnar serve"},it="side",add="f158c8ab"},{q="What does Hegnar Rumbleshot want?",a="Hegnar needs a steady supply of ammunition to keep his workshop and practice range running. Because local marksmen and militia constantly train and restock at his camp, his supplies drain rapidly, requiring regular deliveries from his engineer partner, Loslor Rudge.",al={"what does hegnar need","hegnar rumbleshot goal","hegnar quest"},it="wants",add="932ff4bf"},{q="Why is Hegnar Rumbleshot here along the road?",a="He set up his camp and shooting range along the well-traveled road between Coldridge Pass and Kharanos. This ideal location allows him to furnish fresh recruits coming out of the valley as well as patrolmen defending the central snows of Dun Morogh.",al={"why is hegnar out here","hegnar camp location","why did hegnar set up camp"},it="why_here",add="3c40a283"}},ang={["class:Hunter"]="As a hunter traveling from Coldridge Valley into Dun Morogh's snowy peaks, you can get shot, ammunition pouches, and spare firearms from Hegnar.",["race:Dwarf"]="As a dwarf, you can practice your marksmanship alongside travelers at Hegnar's roadside range."},kw={"ammo","coldridge pass","dun morogh","gunsmith","hegnar rumbleshot","kharanos","shooting range"},rel={"quest:5541","npc:loslor-rudge","zone:dunmorogh","subzone:coldridge-pass","subzone:kharanos","topic:dwarf"},src={"Hegnar Rumbleshot"}}
E["npc:jordan-stilwell"] = {t="npc",n="Jordan Stilwell",z="dunmorogh",s="Outside Ironforge’s gates, Jordan Stilwell tends his forge in Dun Morogh. Once expected to join the Church of the Holy Light, he followed his father into smithing and learned from Bailor Stonehand. Now his craft arms paladins across the Alliance.",h="Outside Ironforge’s gates, Jordan Stilwell tends his forge in Dun Morogh.",sec={{t="A Calling at the Anvil",b="Jordan Stilwell was expected to take holy vows and become a paladin in the Church of the Holy Light. Instead, he followed his father into smithing and took up his father’s enchanted hammer. Bailor Stonehand, a dwarven blacksmith, helped him refine his craft. Jordan remains deeply faithful to the Light and puts his skill to work for champions who fight in its name.",sp=0},{t="Flight from Silverpine",b="Jordan once worked as a smith at Baron Silverlaine’s keep in Silverpine Forest. Then Archmage Arugal unleashed feral worgen upon the fortress and made it Shadowfang Keep. Jordan escaped the bloodshed, leaving his forge and former home behind. In time, he found refuge among the dwarves of Dun Morogh.",sp=0},{t="Forging Verigan's Fist",b="Near Ironforge’s gates, Jordan keeps his forge outdoors. He favors the alpine air over the heat of the Great Forge inside the mountain. The Church of the Holy Light sends worthy paladins to him, and he sets them to recover rare materials from across the world for a legendary two-handed warhammer. Jordan named the weapon Verigan’s Fist in honor of his old friend, Bosch Verigan. Its steel joins faith with masterful craft.",sp=1}},faq={{q="Who is Jordan Stilwell?",a="Jordan Stilwell works as a human blacksmith outside the Gates of Ironforge in Dun Morogh. He crafts sacred arms for paladins of the Church of the Holy Light, including Verigan’s Fist.",al={"who is jordan stilwell","jordan stilwell lore","who is this blacksmith outside ironforge"},it="identity"},{q="Why does Jordan Stilwell work outside in the snow instead of inside Ironforge?",a="Duthorian Rall in Stormwind says Jordan prefers Dun Morogh’s crisp mountain air to the stifling Great Forge inside Ironforge.",al={"why is jordan outside ironforge","why work in dun morogh","why is he in the snow"},it="why_here"},{q="What is Jordan Stilwell's connection to Shadowfang Keep?",a="Jordan once served as an armorer and blacksmith at Baron Silverlaine’s estate in Silverpine Forest. He escaped before or during the uprising, when Archmage Arugal and his feral worgen slaughtered the garrison and took the fortress.",al={"jordan stilwell shadowfang keep","jordan stilwell silverpine","did he live in pyrewood"}},{q="What is Verigan's Fist?",a="Verigan’s Fist is a powerful two-handed holy hammer Jordan Stilwell forged for Alliance paladins. He named it for his old friend, Bosch Verigan.",al={"verigans fist","verigan hammer","who is verigan"}},{q="Who trained Jordan Stilwell in blacksmithing?",a="Jordan inherited his smithing craft and an enchanted hammer from his father. He refined his skill under Bailor Stonehand, a dwarven blacksmith.",al={"who trained jordan stilwell","jordan stilwell teacher","where did he learn smithing"},it="origin"},{q="Who is Jordan Stilwell's wife?",a="Jordan is married to Daphne Stilwell. Together, they have aided the Church of the Holy Light greatly over the years, and both are revered as deeply devout servants of the faith.",al={"jordan stilwell wife","daphne stilwell husband","daphne stilwell"},it="ties"},{q="Whose side is Jordan Stilwell on?",a="Jordan is steadfastly loyal to the Alliance and the Church of the Holy Light. Though he lives among the dwarves in Dun Morogh and plies his trade outside Ironforge, he remains deeply connected to Stormwind's paladins, dedicating his craft to arming the faithful against the darkness threatening the realm.",al={"jordan stilwell faction","is jordan stilwell alliance","jordan stilwell allegiance"},it="side",add="49deb919"},{q="What does Jordan Stilwell want?",a="Jordan seeks to honor his old friend Bosch Verigan by forging an extraordinary weapon for deserving paladins. To craft the holy warhammer Verigan's Fist, he requires rare materials gathered across Azeroth: refined ore from his old teacher Bailor Stonehand, whitestone oak lumber, a purified Kor gem, and his father's lost smithing hammer.",al={"what does jordan stilwell need","jordan stilwell goal","jordan stilwell purpose"},it="wants",add="dd0bfe26"},{q="Why is Jordan Stilwell famous?",a="Jordan is renowned as an exceptional weaponsmith whose devotion to the Holy Light matches his skill at the forge. Originally meant to become a paladin, he chose to follow in his father's footsteps, and with his wife Daphne he has aided the Church of the Holy Light so greatly that it still counts him among its most faithful.",al={"is jordan stilwell famous","jordan stilwell renown","why is jordan stilwell known"},it="fame",add="3def62e7"}},ang={["class:Paladin"]="As a paladin, Jordan Stilwell may send you to seek rare materials across Azeroth for Verigan’s Fist, your signature warhammer.",["profession:Blacksmithing"]="Jordan learned from Bailor Stonehand and wields an enchanted hammer inherited from his father. His work is among the finest holy smithing practiced by mortals.",["faction:Alliance"]="After fleeing Arugal’s worgen in Silverpine Forest, Jordan found refuge among the dwarves of Dun Morogh. He now lends his craft to Alliance champions."},kw={"bailor stonehand","bosch verigan","daphne stilwell","dun morogh","ironforge","jordan stilwell","shadowfang keep","tome of valor","verigan's fist","verigans fist"},rel={"quest:1653","quest:1649","npc:duthorian-rall","npc:daphne-stilwell","npc:bailor-stonehand","zone:shadowfang","subzone:gates-of-ironforge","topic:church-of-the-holy-light"},src={"Jordan Stilwell"}}
E["npc:loslor-rudge"] = {t="npc",n="Loslor Rudge",z="dunmorogh",s="At Steelgrill's Depot, Loslor Rudge keeps Dun Morogh's tinkerers supplied. His goods travel across the snowy ridges to craftsmen such as gunsmith Hegnar Rumbleshot.",h="At Steelgrill's Depot, Loslor Rudge keeps Dun Morogh's tinkerers supplied.",sec={{t="A Supplier in the Snow",b="Loslor Rudge supplies engineering goods from Steelgrill's Depot, just down the road from Kharanos. His stock holds copper modulators, bronze tubing, blasting powder, and spanners. Harsh weather and scattered tinker operations keep these parts in demand, so Loslor works to supply local gearheads.\n\nDeliveries through the wilderness between outposts can be perilous. Near the Grizzled Den, wendigos drove off a courier taking a shortcut. The courier left behind an ammunition shipment meant for Loslor's valued client, gunsmith Hegnar Rumbleshot.",sp=0}},faq={{q="Who is Loslor Rudge?",a="Loslor Rudge supplies engineering goods from Steelgrill's Depot in Dun Morogh. His shop carries tools, parts, and munitions for the region's tinkerers and craftsmen.",al={"loslor rudge","who is rudge","steelgrills depot engineer"},it="identity"},{q="What trouble does Loslor need help with?",a="Loslor needs someone to recover an ammunition shipment left in the snow. Wendigos chased away a courier bound for gunsmith Hegnar Rumbleshot near the Grizzled Den, and the courier abandoned the crate.",al={"ammo for rumbleshot quest","what does rudge want","rudge courier"},it="wants"},{q="Where is Steelgrill's Depot?",a="Steelgrill's Depot lies just east of Kharanos, along the main road toward Loch Modan. It is a dwarven staging ground and machine workshop.",al={"where is steelgrills depot","steelgrill location"},it="place",gp=true},{q="Who is Hegnar Rumbleshot?",a="Hegnar Rumbleshot is a dwarven gunsmith at a camp in Dun Morogh. He relies on Loslor Rudge for fresh ammunition and mechanical components.",al={"who is hegnar","rumbleshot"},it="ties"},{q="Whose side is Loslor Rudge on?",a="Loslor Rudge is a loyal member of the Ironforge dwarven community and the Alliance. Based at Steelgrill's Depot, he conducts business directly supporting dwarven marksmen, crafters, and nearby settlements across Dun Morogh.",al={"loslor rudge faction","is loslor rudge alliance","who does loslor rudge serve"},it="side",add="774accc1"},{q="Why is Loslor Rudge at Steelgrill's Depot?",a="Loslor operates out of Steelgrill's Depot as an engineering supplier and merchant. The depot serves as a bustling hub of dwarven machinery, repair, and industry outside Ironforge, making it an ideal location for him to sell tinkers' parts, powder, and craft ammunition for regional gunsmiths.",al={"why is loslor rudge here","loslor rudge role steelgrill","why is loslor at the depot"},it="why_here",add="1a06e65e"}},ang={["profession:Engineering"]="Loslor stocks useful engineering supplies, including fluxes, blasting powders, tubes, and tinker's kits. His depot is a handy stop for engineers traveling through Dun Morogh.",["race:Dwarf"]="Like many artisans in Dun Morogh, Loslor depends on reliable pack routes between scattered dwarf camps. Wendigos can disrupt mountain trade."},kw={"ammo","dun morogh","engineering","grizzled den","hegnar rumbleshot","loslor rudge","steelgrill's depot"},rel={"subzone:steelgrill-s-depot","quest:5541","npc:hegnar-rumbleshot","subzone:grizzled-den","zone:dunmorogh","topic:dwarf"},src={"Loslor Rudge"}}
E["npc:magis-sparkmantle"] = {t="npc",n="Magis Sparkmantle",z="dunmorogh",s="In Kharanos, Magis Sparkmantle teaches gnome mages inside the Thunderbrew Distillery. He guides new spellcasters who come from Coldridge Valley into Dun Morogh.",h="In Kharanos, Magis Sparkmantle teaches gnome mages inside the Thunderbrew Distillery.",sec={{t="A Spellcaster in the Distillery",b="Dwarves come to the Thunderbrew Distillery for ale, and Magis Sparkmantle teaches among its casks and kegs. Across Dun Morogh, gnome mages work closely with their dwarven allies. Magis helps new spellcasters deepen their knowledge of the arcane and put it to practice.",sp=0},{t="Directing Young Arcanists",b="Magis teaches beginners their first incantations, then points promising students toward broader studies of magic. When they outgrow his early lessons or need special guidance, he sends them to other practitioners, including Bink, or to mentors in the Alliance’s main hubs.",sp=0}},faq={{q="Who is Magis Sparkmantle?",a="Magis Sparkmantle trains gnome mages in Kharanos and teaches novice spellcasters the fundamentals of the arcane.",al={"magis sparkmantle","who is magis","kharanos mage trainer"},it="identity"},{q="Where can Magis Sparkmantle be found?",a="You can find Magis inside the Thunderbrew Distillery, Kharanos’s main inn and gathering hall.",al={"magis location","where is magis","find sparkmantle"},it="place",gp=true},{q="Why is a gnome mage trainer staying in a dwarven distillery?",a="After Gnomeregan fell, many gnomes settled among their dwarven cousins in Dun Morogh. The Thunderbrew Distillery is Kharanos’s central gathering place, so Magis can guide spellcasters who travel through.",al={"why in distillery","gnome in distillery","why thunderbrew distillery"},it="why_here"},{q="Does Magis Sparkmantle offer any quests?",a="Magis sends developing mages to other arcane mentors as their studies advance, including Bink and instructors in human territories.",al={"sparkmantle quests","magis quests"},gp=true},{q="Whose side is Magis Sparkmantle on?",a="Magis Sparkmantle stands firmly with Gnomeregan and the Grand Alliance. Like many exiled gnomes who fled the catastrophe in their home city, he lives and works alongside Ironforge's dwarves, offering his arcane knowledge to the Alliance's defenders.",al={"magis sparkmantle faction","is magis alliance","who does sparkmantle serve"},it="side",add="1189c3a2"},{q="What does Magis Sparkmantle want?",a="Magis is dedicated to tutoring fledging mages in the arcane arts. While lodging at the distillery, he prepares novice spellcasters for the road ahead, instructing them in foundational magic before directing them toward senior masters like Jennea Cannon in Stormwind.",al={"what does magis want","magis sparkmantle goals","why train mages magis"},it="wants",add="e3e37731"},{q="Who is Magis Sparkmantle tied to?",a="As part of the wider network of Alliance mages, Magis maintains connections with fellow trainers across the realm, including Bink in the dwarven lands and Jennea Cannon in Stormwind's Mage Quarter, ensuring promising students find advanced instruction.",al={"magis sparkmantle allies","who is sparkmantle connected to","sparkmantle connections"},it="ties",add="318a77dd"}},ang={["class:Mage"]="As an Alliance mage traveling through Dun Morogh, you can turn to Magis for spell training and introductions to broader arcane studies.",["race:Gnome"]="As a gnome living among the dwarves, you can look to mentors like Magis to keep your scholarly and arcane traditions alive."},kw={"dun morogh","gnome mage","kharanos","mage trainer","magis","magis sparkmantle","sparkmantle","thunderbrew distillery"},rel={"subzone:thunderbrew-distillery","subzone:kharanos","zone:dunmorogh","npc:bink","quest:1879","topic:gnome"},src={"Magis Sparkmantle"}}
E["npc:magni-bronzebeard"] = {t="npc",n="Magni Bronzebeard",z="dunmorogh",s="In Ironforge, Magni Bronzebeard bears his people's grief and political strain. Lord of Ironforge, Thane of the Bronzebeard clan, and ruler of Khaz Modan, he is a veteran of the Second War who champions dwarven archaeology across Azeroth.",h="In Ironforge, Magni Bronzebeard bears his people's grief and political strain.",sec={{t="Lord of the Mountain",b="Magni Bronzebeard grew up the eldest of three brothers, knowing the mountain would one day be his to rule. When the Horde invaded during the Second War, he held Ironforge behind its impenetrable gates. Once the siege broke, he pledged Khaz Modan to the Alliance of Lordaeron. In the peace that followed, Magni welcomed his gnomish allies after Gnomeregan fell. He gave High Tinker Gelbin Mekkatorque and the refugees sanctuary beneath the mountain.\n\nMagni then sought to unite the fractured northern and southern kingdoms. He asked Mekkatorque to build the Deeprun Tram, an unprecedented route beneath the earth that connects Ironforge directly to Stormwind.",sp=0},{t="A Brother Lost",b="Magni carries deep sorrow beneath his regal bearing. During the Third War, word came from Northrend that his beloved younger brother, Muradin, had perished on Prince Arthas Menethil's expedition. Grief overwhelmed Magni, but he and his youngest brother, Brann, remained steadfast in their duty to the dwarven people. Magni still rules wisely, with that loss weighing upon him.",sp=0},{t="Excavating the Past",b="Magni has turned dwarven society from commercial mining toward the unearthing of ancient history. Strange titan relics found deep beneath the earth inspired him to found the explorers' league with his surviving brother, Brann Bronzebeard. Dwarven dig sites now span the continents, from Dun Morogh to Kalimdor, as the League seeks the truth of the dwarves' fabled origins.\n\nPeace at home remains fragile. Magni's daughter, Princess Moira, has gone missing, believed kidnapped by the hated Dark Iron clan.",sp=0}},faq={{q="Who is Magni Bronzebeard?",a="Magni Bronzebeard rules Khaz Modan as King, leads the Bronzebeard clan as Thane, and is Lord of Ironforge. From the High Seat in Ironforge, he stands among the Grand Alliance's staunchest pillars.",al={"king of ironforge","dwarf king","who is magni"}},{q="Who forged the Ashbringer?",a="Ironforge's records keep no account of who forged the Ashbringer. The sword is remembered as the weapon of Highlord Alexandros Mograine of the Silver Hand, and no record ties its making to King Magni.",al={"did magni make ashbringer","ashbringer creator","who made the ashbringer"}},{q="What happened to Magni's brothers?",a="Magni is the eldest of three brothers. Muradin served as an Alliance ambassador to Lordaeron and was reported killed by Prince Arthas in Northrend. Brann, the youngest, is a renowned explorer who travels the far corners of the world leading the explorers' league.",al={"muradin and brann","magni brothers","muradin bronzebeard fate"}},{q="Where is Princess Moira?",a="Princess Moira Bronzebeard, Magni's only child, has disappeared from Ironforge. Official reports in the mountain say the antagonistic Dark Iron dwarves abducted her and hold her captive deep within Blackrock Mountain.",al={"magni daughter","where is moira","what happened to moira bronzebeard"}},{q="Why are gnomes living in Ironforge?",a="After the trogg invasion and Gnomeregan's horrific irradiation, King Magni opened Ironforge's gates to High Tinker Gelbin Mekkatorque and the gnomish survivors. He gave them an entire city district, now known as Tinker Town.",al={"tinker town","why are gnomes in the dwarf city","gnome refugees ironforge"}},{q="What is the Explorers' League?",a="The explorers' league is an archaeological organization founded by King Magni and his brother Brann. After ancient titan ruins were discovered, Magni turned dwarven industries toward uncovering their race's origins and sent survey teams across Azeroth.",al={"explorers guild","dwarf archaeologists","why are dwarves digging"}}},ang={["race:Dwarf"]="As a dwarf, you have Magni as your undisputed sovereign and protector of Khaz Modan. He leads the Bronzebeard clan through external wars and the search for your race's ancient heritage.",["race:Gnome"]="As a gnome, you know King Magni offered Ironforge as a refuge to Gnomeregan's survivors. He remains a close friend and technological ally of High Tinker Mekkatorque.",["faction:Alliance"]="As a member of the Alliance, you have Magni as a stalwart founder alongside Lordaeron and Stormwind. He brings martial strength, engineering prowess, and steadfast loyalty to the coalition.",["profession:Blacksmithing"]="As a blacksmith, you know the Great Anvil burns at the heart of Magni's city. The smiths who work under the king's rule are counted among the finest in the Alliance."},kw={"brann","bronzebeard","explorers league","ironforge","khaz modan","magni","moira","muradin"},rel={"zone:ironforge","topic:bronzebeard-clan","topic:dwarf","npc:gelbin-mekkatorque","topic:explorers-league","subzone:deeprun-tram","topic:arthas-menethil","topic:alliance"},src={"Magni Bronzebeard"}}
E["npc:marleth-barleybrew"] = {t="npc",n="Marleth Barleybrew",z="dunmorogh",s="At Brewnall Village, Marleth Barleybrew works to prove her family’s ale can rival Thunder Ale. The Thunderbrew clan’s hold on local beer trade frustrates her, and she seeks to put Barleybrew brew before drinkers.",h="At Brewnall Village, Marleth Barleybrew works to prove her family’s ale can rival Thunder Ale.",sec={{t="The Brewing Rivalry",b="In Dun Morogh, beer matters as much as steel, and the Barleybrew and Thunderbrew rivalry is legendary. Ragnar Thunderbrew and his kin control nearly all the beer trade from their Kharanos distillery. Marleth Barleybrew believes her family’s brew is just as strong, but she will not challenge the Thunderbrews openly. Instead, she recruits travelers to secretly replace Kharanos tavern casks with Barleybrew kegs.",sp=0}},faq={{q="Who is Marleth Barleybrew?",a="Marleth Barleybrew is a dwarf brewmaster at Brewnall Village in western Dun Morogh. She represents the Barleybrew family and challenges the Thunderbrew family’s hold on the local beer trade.",al={"who is marleth","marleth lore","marleth barleybrew"},it="identity"},{q="Where can I find Marleth Barleybrew?",a="You can find Marleth Barleybrew in Brewnall Village, in western Dun Morogh near Iceflow Lake.",al={"marleth location","where is marleth","find marleth"},it="place",gp=true},{q="Why does Marleth want to swap Thunderbrew's beer?",a="Marleth believes her family’s ale is as good as, or better than, Thunder Ale. The Thunderbrews dominate Kharanos’s beer trade, so she hires travelers to secretly replace the tavern’s kegs with Barleybrew stock and bring back a sample of Thunder Ale for her to study.",al={"why swap the beer","bitter rivals quest reason","why hate thunderbrews"},it="wants"},{q="Who are the other members of the Barleybrew family?",a="Marleth’s extended clan includes the brewers and tradesmen Malgin, Rejold, Wellart, and Yorus Barleybrew. They are all devoted to traditional dwarven brewing.",al={"barleybrew family","marleth relatives"},it="ties"},{q="Whose side is Marleth Barleybrew on?",a="Marleth is a proud Ironforge dwarf and loyal to the Alliance, though her immediate daily focus is entirely commercial. She belongs to the Barleybrew brewing family and fiercely champions their craft against their local rivals.",al={"marleth barleybrew allegiance","who does marleth barleybrew serve","marleth faction"},it="side",add="c401045b"},{q="Why is Marleth Barleybrew in Brewnall Village?",a="Brewnall Village serves as a regional brewing outpost in the snowy hills of Dun Morogh. Marleth operates from here to produce her craft beer and plot ways to break into the larger markets monopolized by the Thunderbrews.",al={"why is marleth here","marleth barleybrew brewnall village","why is marleth barleybrew in dun morogh"},it="why_here",add="716c9dd7"}},ang={["race:Dwarf"]="As a dwarf, you know brewing is an art tied to clan prestige. Marleth’s feud with the Thunderbrews is a matter of fierce family pride."},kw={"bitter rivals","brewnall village","dwarf brewer","kharanos","marleth barleybrew","thunder ale","thunderbrew"},rel={"subzone:brewnall-village","quest:310","quest:311","quest:308","subzone:thunderbrew-distillery","npc:ragnar-thunderbrew","subzone:kharanos","topic:dwarf"},src={"Marleth Barleybrew"}}
E["npc:marryk-nurribit"] = {t="npc",n="Marryk Nurribit",z="dunmorogh",s="At Anvilmar in Coldridge Valley, Marryk Nurribit teaches young gnomes the first steps in arcane magic. Local brews often draw his attention from lessons, and he asks pupils for spare coins to buy a drink.",h="At Anvilmar in Coldridge Valley, Marryk Nurribit teaches young gnomes the first steps in arcane magic.",sec={{t="Arcane Studies and Ale",b="Every newly arrived gnome mage in Coldridge Valley starts out as Marryk's pupil. Yet a flagon of dwarven ale can win more of his attention than a lesson. He asks new pupils for spare pocket change, and warns aspiring spellcasters about Gnomeregan's radioactive, trogg-infested ruins beyond Coldridge Valley.",sp=0}},faq={{q="Who is Marryk Nurribit?",a="Marryk Nurribit teaches gnomes the fundamentals of arcane magic at Anvilmar in Coldridge Valley, Dun Morogh. He trains newly arrived gnome mages.",al={"marryk nurribit","who is marryk","anvilmar mage trainer"},it="identity"},{q="Why does Marryk keep asking for money for beer?",a="Marryk enjoys local spirits and often asks his students for spare change to buy beer at the tavern.",al={"marryk drinking","marryk beer","why does he ask for coins"},it="wants"},{q="What does Marryk say about Gnomeregan?",a="Marryk warns new mages not to underestimate the dangers in Gnomeregan's irradiated ruins.",al={"marryk gnomeregan","gnomeregan warning"}},{q="Whose side is Marryk Nurribit on?",a="Marryk is loyal to the Gnomeregan Exiles and stands squarely with the Alliance. Taking shelter alongside his dwarven hosts in Dun Morogh, he offers his arcane instruction to fledgling gnomes stepping forth into Coldridge Valley.",al={"marryk nurribit faction","who does marryk serve","marryk allegiance"},it="side",add="42f80152"},{q="Why is Marryk Nurribit in Anvilmar?",a="Following the tragic fall of Gnomeregan to the trogg infestation and toxic fallout, Marryk and his surviving kin fled into Dun Morogh. He now stays at Anvilmar in Coldridge Valley, nominally tasked with instructing novice gnome mages in the arcane arts.",al={"why is marryk here","marryk nurribit anvilmar","marryk purpose dun morogh"},it="why_here",add="241b0acf"}},ang={["class:Mage"]="As a gnome mage starting out in Coldridge Valley, you turn to Marryk for your first spells and your Glyphic Memorandum.",["race:Gnome"]="As a gnome taking shelter in Dun Morogh, you know Marryk as a scholar who has taken readily to dwarven tavern life."},kw={"anvilmar","beer","coldridge","gnome","mage","marryk","nurribit","trainer"},rel={"subzone:anvilmar","quest:3114","zone:dunmorogh","zone:gnomeregan","topic:gnome"},src={"Marryk Nurribit"}}
E["npc:maxan-anvol"] = {t="npc",n="Maxan Anvol",z="dunmorogh",s="At the Thunderbrew Distillery in Kharanos, Maxan Anvol teaches dwarven priests the ways of the Holy Light. Before acolytes earn the Church’s vestments, he puts their faith to the test.",h="At the Thunderbrew Distillery in Kharanos, Maxan Anvol teaches dwarven priests the ways of the Holy Light.",sec={{t="A Priest in the Pub",b="From the Thunderbrew Distillery, Maxan Anvol tends to the spiritual needs of Kharanos. Travelers, mountaineers, and acolytes gather there, for the hamlet lies between Coldridge Valley and Ironforge. Its inn draws those passing through. Maxan offers prayer and counsel to all who enter, with stout close at hand.",sp=0},{t="Testing the Faithful",b="Before novice priests venture into the wider world, Maxan Anvol tests their faith and skill. He sends initiates to use simple healing prayers on Dun Morogh’s wounded defenders. Those who prove devoted and skilled receive their first priestly vestments, a mark of their place in the Church of the Holy Light.",sp=0}},faq={{q="Where can I find Maxan Anvol?",a="You can find Maxan Anvol inside the Thunderbrew Distillery in Kharanos. The inn is a gathering place for the town and for travelers crossing Dun Morogh.",al={"maxan anvol location","where is maxan","priest trainer kharanos"},it="place",gp=true},{q="What does Maxan Anvol teach?",a="Maxan Anvol teaches novice and journeyman priests holy healing, shadow control, and divine protection. Dwarven priests can also learn prayers such as Desperate Prayer.",al={"what does he train","maxan anvol spells"},it="purpose",gp=true},{q="Why is a holy priest hanging out in a distillery?",a="Dwarven life and celebration gather around brewing and taverns. The Thunderbrew Distillery is Kharanos’s public gathering place and a rest for travelers, where Maxan offers spiritual comfort to townsfolk, guards, and passersby.",al={"why distillery","priest in a bar"},it="why_here"},{q="Does Maxan Anvol offer any special tasks?",a="Yes. Maxan Anvol tests aspiring priests in trials such as 'In Favor of the Light' and 'Garments of the Light.' He sends them to heal injured mountaineers in the snow, and those who succeed earn their acolyte robes.",al={"maxan quests","garments of the light"},gp=true},{q="What does he say to non-priests?",a="Maxan Anvol warns adventurers never to turn their backs on the Holy Light. Divine grace may save their lives in battle.",al={"maxan dialogue","maxan quote"},gp=true},{q="Can gnomes learn from Maxan Anvol?",a="Yes. Gnomes can train as priests, and Maxan welcomes any member of the Alliance who has pledged to the Light.",al={"can gnomes talk to him","gnome priest trainer"},gp=true},{q="Who is Maxan Anvol?",a="Maxan Anvol is a dwarven priest of the Holy Light stationed in Kharanos. He serves as an instructor for fledgling devotees within Dun Morogh, testing young acolytes on their discipline and communion with the Light before granting them vestments fitting their station in the church.",al={"who is maxan","maxan anvol lore","priest trainer kharanos"},it="identity",add="32034ea0"},{q="Whose side is Maxan Anvol on?",a="He stands loyally with the Kingdom of Ironforge, the Holy Light, and the Grand Alliance. He dedicates his service to safeguarding the local populace of Dun Morogh and preparing new priests to uphold the faith across the Alliance's lands.",al={"maxan faction","is maxan alliance","maxan anvol allegiance"},it="side",add="310c3ecc"},{q="What does Maxan Anvol want?",a="Maxan seeks to foster devotion to the Holy Light and ensure novice priests are thoroughly prepared for the trials of the world. He tests aspiring students to ensure they are worthy of their sacred robes, while reminding all passersby never to abandon the Light's grace.",al={"maxan anvol goal","what does maxan want","maxan anvol motive"},it="wants",add="1141108e"}},ang={["class:Priest"]="As a priest, you meet Maxan Anvol early in Dun Morogh and begin learning the foundations of holy discipline. He teaches racial prayers such as Desperate Prayer and gives you your first church robes.",["race:Dwarf"]="As a dwarf, you see Ironforge’s practical faith where people gather, beside Kharanos’s ale kegs.",["faction:Alliance"]="As an Alliance member, you find Maxan tending to the physical and spiritual readiness of mountaineers and scouts who guard Dun Morogh from troggs, frost trolls, and wilderness beasts."},kw={"desperate prayer","dun morogh","garments of the light","holy light","kharanos","maxan anvol","priest trainer","thunderbrew distillery"},rel={"subzone:kharanos","subzone:thunderbrew-distillery","zone:dunmorogh","quest:5624","quest:5623","quest:5634","topic:light","topic:dwarf"},src={"Maxan Anvol"}}
E["npc:milli-featherwhistle"] = {t="npc",n="Milli Featherwhistle",z="dunmorogh",s="At Steelgrill's Depot, Milli Featherwhistle builds and maintains mechanostriders for Gnomeregan's displaced people. She sells these clockwork mounts to her kin and to trusted allies among the exiles.",h="At Steelgrill's Depot, Milli Featherwhistle builds and maintains mechanostriders for Gnomeregan's displaced...",sec={{t="Master of Mechanostriders",b="Just east of Kharanos, Milli works outdoors in Dun Morogh's biting chill. She tunes each mount's gears, pistons, and balancing gyros to carry riders across the snowy crags. Dwarves and night elves favor living mounts. For Gnomeregan's displaced people, Milli's clockwork steeds meet a different need.",sp=0},{t="Legacy of Mekkatorque",b="Milli follows the blueprints first drawn by High Tinker Gelbin Mekkatorque. She has improved each mechanostrider's performance by lightening its chassis and refining its exhaust vents. Yet she keeps to the High Tinker's original designs. Her work carries gnomish ambition forward, even in exile.",sp=0}},faq={{q="Who is Milli Featherwhistle?",a="Milli is Gnomeregan's primary mechanostrider breeder and engineer. At Steelgrill's Depot in Dun Morogh, she builds and sells clockwork mounts to eligible riders.",al={"milli featherwhistle","who is milli","mechanostrider vendor"},it="identity"},{q="Where can I find Milli Featherwhistle?",a="Milli works at Steelgrill's Depot in Dun Morogh, a short walk east along the road from Kharanos.",al={"milli location","where is milli featherwhistle","find milli"},it="place",gp=true},{q="Who is allowed to purchase mounts from her?",a="Gnomish adventurers can buy Milli's creations directly. Riders of other Alliance races must earn her utmost trust and exalted standing with the Gnomeregan Exiles before she entrusts them with a mechanostrider.",al={"can i buy a mechanostrider","mechanostrider requirements","who can ride mechanostriders"},gp=true},{q="How are mechanostriders made?",a="Milli builds each mechanostrider herself from High Tinker Gelbin Mekkatorque's blueprints. She has improved the engines and balance.",al={"how mechanostriders are built","who makes mechanostriders","mechanostrider origins"}},{q="What mount varieties does she offer?",a="Milli offers standard mechanostriders with unpainted, blue, green, and red frames. She also offers swift models finished in white, green, and yellow.",al={"milli mount colors","mechanostrider models","what mounts does milli sell"},gp=true},{q="Why is she working out in the snow at Steelgrill's Depot?",a="After a radioactive catastrophe and a trogg invasion drove the gnomes from Gnomeregan, refugees gathered wherever they could. Steelgrill's Depot outside Kharanos became a natural staging hub, where they could test vehicles and maintain machinery alongside dwarven engineers.",al={"why is milli in dun morogh","why steelgrills depot"},it="why_here"},{q="Whose side is Milli Featherwhistle on?",a="Milli Featherwhistle is devoted to Gnomeregan and the Grand Alliance. Working out of Steelgrill's Depot alongside dwarven craftsmen, she provides mechanostriders directly to her fellow gnomes and trusted Alliance champions who have earned the full respect of the Gnomeregan Exiles.",al={"milli featherwhistle faction","who does milli featherwhistle serve","is milli alliance"},it="side",add="2267a2b3"},{q="What does Milli Featherwhistle want?",a="Milli wants to build and maintain the finest mechanostriders in Dun Morogh. Basing her creations on High Tinker Mekkatorque's original schematics, she continuously refines their engineering so reliable mechanized mounts remain readily available to gnome travelers and proven allies.",al={"what does milli featherwhistle do","milli featherwhistle goal","what is milli trying to do"},it="wants",add="f07f7c95"}},ang={["race:Gnome"]="As a gnome, you can see Milli carry forward High Tinker Mekkatorque's technological genius. She is your people's premier mount engineer, still at work in exile from your subterranean home.",["profession:Engineering"]="Milli's mechanostriders are the pinnacle of gnomish locomotion. They have gyroscopic balance units and high-torque mechanical limbs.",["faction:Alliance"]="As an Alliance hero, you can seek out Milli after earning the utmost respect of the Gnomeregan Exiles. Then you can command one of Azeroth's swiftest mechanical mounts."},kw={"dun morogh","gnomeregan","kharanos","mechanostrider","mekkatorque","milli featherwhistle","mount vendor","steelgrill's depot"},rel={"subzone:steelgrill-s-depot","subzone:kharanos","zone:dunmorogh","zone:gnomeregan","npc:gelbin-mekkatorque","topic:gnome"},src={"Milli Featherwhistle"}}
E["npc:mountaineer-barleybrew"] = {t="npc",n="Mountaineer Barleybrew",z="dunmorogh",s="At South Gate Outpost, Mountaineer Barleybrew keeps watch over the pass from Dun Morogh to Loch Modan. Dwarven brews help sentries endure the cold.",h="At South Gate Outpost, Mountaineer Barleybrew keeps watch over the pass from Dun Morogh to Loch Modan.",sec={{t="A Watch on the Eastern Pass",b="Mountaineer Wellart Barleybrew watches the snowy road to Loch Modan from South Gate Outpost. He serves in Ironforge's border watch. Like other mountaineers in Dun Morogh's bitter winds, he values fine dwarven drink. His name ties him to the renowned Barleybrew clan. He also helps send potent Shimmer Stout to watchmen who need warmth and stamina through long shifts in the mountain passes.",sp=0}},faq={{q="Where can I find Mountaineer Barleybrew?",a="You can find Mountaineer Barleybrew at South Gate Outpost, the dwarven fortification guarding the eastern pass between Dun Morogh and Loch Modan.",al={"barleybrew location","where is mountaineer barleybrew","barleybrew npc"},it="place",gp=true},{q="What is his duty at South Gate Outpost?",a="At South Gate Outpost, he watches the roadway and helps arrange supplies. These include Shimmer Stout for mountaineers stationed throughout the passes.",al={"barleybrew purpose","what does barleybrew do"},it="purpose"},{q="Is he related to the other Barleybrews?",a="Yes. Rejold Barleybrew, the brewer, is his brother. He may also be related to Marleth, Malgin, and Yorus Barleybrew.",al={"barleybrew family","yorus barleybrew relative"},it="ties"},{q="Who is Mountaineer Barleybrew?",a="Mountaineer Wellart Barleybrew is a dwarven sentry stationed to defend the eastern borders of Dun Morogh. Like all mountaineers of Ironforge, he stands vigilant against the beasts, troggs, and frost troll raiders that threaten the mountain roads, balancing his rigorous frontier duty with a distinct dwarven fondness for good ale.",al={"who is mountaineer barleybrew","who is barleybrew","mountaineer barleybrew lore"},it="identity",add="583559ff"},{q="Whose side is Mountaineer Barleybrew on?",a="He is a steadfast soldier of Ironforge and loyal to the Alliance. He follows the commands of the Bronzebeard clan and King Magni, ensuring the safety of travellers and key mountain passes across the realm.",al={"mountaineer barleybrew faction","who does barleybrew serve","is barleybrew alliance"},it="side",add="399d0350"},{q="What does Mountaineer Barleybrew want?",a="Beyond keeping the roadway secured from intruders, Mountaineer Barleybrew appreciates a hardy brew to cut through the freezing mountain air. He relies on passing travelers to courier word and supplies—including a draught of potent Shimmer Stout—between his station and nearby allies.",al={"barleybrew wants","what does wellart barleybrew need","what is barleybrew looking for"},it="wants",add="fc186c57"},{q="Why is Mountaineer Barleybrew here?",a="He is posted along the South Gate Outpost pass to guard the vital thoroughfare connecting Dun Morogh to Loch Modan. The high passes face regular peril from roving wildlife and aggressive trogg warbands, requiring disciplined mountaineers to keep the gates fortified and secure.",al={"why is barleybrew at south gate","why is mountaineer barleybrew stationed here","barleybrew location why"},it="why_here",add="b2269341"}},ang={["race:Dwarf"]="As a dwarf, you know the demands of frontier duty and the strong drink that helps keep Khaz Modan secure."},kw={"barleybrew","dun morogh","mountaineer","shimmer stout","south gate outpost","wellart"},rel={"subzone:south-gate-outpost","quest:413","quest:414","npc:marleth-barleybrew","quest:1698","zone:dunmorogh","zone:lochmodan","topic:dwarf"},src={"Mountaineer Barleybrew"}}
E["npc:mountaineer-thalos"] = {t="npc",n="Mountaineer Thalos",z="dunmorogh",s="At Coldridge Pass, Mountaineer Thalos guards the road toward Kharanos, where couriers bring urgent reports. Troggs have overrun the tunnel, and he decides who may cross safely.",h="At Coldridge Pass, Mountaineer Thalos guards the road toward Kharanos, where couriers bring urgent reports.",sec={{t="Guardian of Coldridge Pass",b="Troggs have burrowed up from below and made Coldridge Pass dangerous. At its snowy mouth, where Coldridge Valley gives way to Dun Morogh’s deeper crags, Thalos turns back travelers who are not ready. He tests whether couriers have the grit to face the infested tunnel. If they cannot get through, their reports may never reach the wider kingdom.",sp=0},{t="A Courier's Checkpoint",b="Grelin Whitebeard reports Frostmane troll movements in the secluded valley. A courier carries his account to Grelin’s brother Senir in Kharanos, but first must speak with Mountaineer Thalos. Thalos sends capable travelers through the pass toward Kharanos, where regional commanders coordinate Dun Morogh’s defense. Vital intelligence must reach Ironforge’s military leaders, not vanish in the snow.",sp=0}},faq={{q="Who is Mountaineer Thalos?",a="Mountaineer Thalos guards the southern opening of Coldridge Pass for Ironforge. He watches the boundary between Coldridge Valley and the rest of Dun Morogh.",al={"thalos lore","who is thalos","mountaineer thalos"},it="identity"},{q="Why is Mountaineer Thalos warning travelers away?",a="Rockjaw troggs have overrun Coldridge Pass. Thalos warns civilians and novice fighters away, while capable couriers and hardened fighters may enter.",al={"why is pass closed","troggs in pass","coldridge pass danger"},it="why_here"},{q="Where does Mountaineer Thalos send adventurers?",a="Thalos sends travelers through Coldridge Pass toward Kharanos, the nearest settlement on the road to Ironforge.",al={"where do i go after thalos","thalos destination","next town"},it="next_step"},{q="What report does Thalos receive from Senir Whitebeard?",a="Thalos receives no report from Senir himself. A courier carries Grelin Whitebeard’s account of the Frostmane troll threat in Coldridge Valley to Grelin’s brother Senir in Kharanos. Thalos warns the messenger about the troggs and sends them through the tunnel.",al={"senirs observations","senir dispatch","what does thalos read"}},{q="What faction does Mountaineer Thalos belong to?",a="Thalos belongs to the Ironforge Mountaineers, frontier rangers who patrol Dun Morogh’s borders, tunnels, and mountain trails for the Alliance.",al={"thalos faction","is thalos ironforge","mountaineers alliance"},it="side"},{q="Is Coldridge Pass impassable without speaking to Thalos?",a="Anyone can enter Coldridge Pass, but speaking with Thalos lets a traveler carry vital reconnaissance to Kharanos and learn the dangers ahead.",al={"do i need to talk to thalos","bypass thalos"},gp=true},{q="What does Mountaineer Thalos want?",a="Mountaineer Thalos wants to keep travelers safe by warning them away from the treacherous Coldridge Pass. The tunnel has been overrun by hostile troggs, making passage dangerous for anyone unprepared. When he encounters adventurers with urgent business, he urges them to tread cautiously through the tunnel and carry Grelin Whitebeard's report safely onward to his brother Senir in the dwarven town of Kharanos.",al={"what does thalos want","thalos goal","mountaineer thalos purpose"},it="wants",add="37207617"},{q="Who is Mountaineer Thalos tied to?",a="Thalos serves as a sentry for the Ironforge mountaineers, guarding the pathway leading out of Coldridge Valley. Couriers carrying Grelin Whitebeard's report on the Frostmane trolls to Grelin's brother, Senir Whitebeard in Kharanos, are sent to speak with Thalos before braving the trogg-infested tunnel.",al={"thalos allies","who does thalos work with","thalos senir whitebeard"},it="ties",add="ae07b8df"}},ang={["race:Dwarf"]="As a young dwarf leaving your homeland’s nursery, you meet Thalos, a reminder that the trogg threat presses against Ironforge’s thresholds.",["race:Gnome"]="As a gnome traveling from Gnomeregan’s refugee shelters, you find Thalos guarding the main overland route toward Kharanos and Ironforge.",["faction:Alliance"]="As an Alliance member, you rely on Thalos to keep communication open between the valley’s defensive forces and central Ironforge command."},kw={"coldridge pass","coldridge valley","dun morogh","ironforge mountaineer","kharanos","mountaineer thalos","senir whitebeard","troggs"},rel={"subzone:coldridge-pass","subzone:coldridge-valley","quest:282","subzone:kharanos","zone:dunmorogh","topic:trogg","topic:dwarf"},src={"Mountaineer Thalos"}}
E["npc:nori-pridedrift"] = {t="npc",n="Nori Pridedrift",z="dunmorogh",s="In Coldridge Valley, Nori Pridedrift sends warm Mornbrew out to those who face the cold. He brews and sells the drink, hiring swift couriers to carry it while it is still hot.",h="In Coldridge Valley, Nori Pridedrift sends warm Mornbrew out to those who face the cold.",sec={{t="A Steaming Cup in the Snow",b="Nori Pridedrift sends Scalding Mornbrew across the frozen reaches of Coldridge Valley. The cold bites hard, and a cup brings welcome warmth to mountaineers and freezing sentries. Nori brews the coffee-like drink, then sends it out with couriers who must race the mountain air to keep it scalding. His supply of sturdy mugs is limited, so he expects runners to bring them back promptly.",sp=0}},faq={{q="Who is Nori Pridedrift?",a="Nori Pridedrift is a dwarf peddler in Coldridge Valley. He brews and sells Scalding Mornbrew, a hot, coffee-like drink for the local guards and miners.",al={"who is nori","nori pridedrift lore","scalding mornbrew vendor"},it="identity"},{q="What is Scalding Mornbrew?",a="Scalding Mornbrew is a hot drink brewed by Nori Pridedrift. Valley folk favor it for warmth against the bitter cold of Dun Morogh.",al={"scalding mornbrew","what drink does nori sell","mornbrew"},it="item"},{q="Why are deliveries so urgent?",a="Scalding Mornbrew is prized while piping hot. The mountain winds in Coldridge Valley cool each cup quickly, so Nori's couriers must hurry to their customers.",al={"why rush the delivery","mornbrew delivery rush","why does the drink go cold"},it="motive"},{q="Why does Nori care so much about returning mugs?",a="Nori has only a limited supply of drinking mugs in the valley. If customers keep them or break them in the snow, his morning trade soon falters.",al={"why bring back the mug","nori's mugs","mug return"}},{q="Whose side is Nori Pridedrift on?",a="Nori stands squarely with the Ironforge dwarves and the Alliance. He is an independent local merchant operating out of Coldridge Valley, serving the mountaineers, trainees, and residents who defend and live in the valley.",al={"nori pridedrift faction","who does nori work for","nori pridedrift alliance"},it="side",add="ddac60d5"},{q="What does Nori Pridedrift want?",a="Nori wants to run a profitable brewing business in Coldridge Valley. His main concern is ensuring his signature Scalding Mornbrew reaches his thirsty customers while it is still piping hot, and making certain that every empty mug makes its way back to his inventory.",al={"nori pridedrift goal","what does nori want","nori motivations"},it="wants",add="26ccfe8e"},{q="Why is Nori Pridedrift here?",a="Nori wanders Coldridge Valley because that is where his thirsty patrons are. The harsh, freezing mountain climate makes his piping-hot morning drink especially popular with the local guards and trainees, providing him with a steady trade.",al={"why is nori in coldridge valley","why is nori here","nori pridedrift location"},it="why_here",add="10ad6fd1"}},ang={["race:Dwarf"]="As a dwarf, you know the comfort of a strong drink in freezing weather. Nori's hot Mornbrew is welcome at mountain watch posts.",["profession:Cooking"]="As a cook in Dun Morogh, you can appreciate Nori's care in serving his specialty drink piping hot in the freezing air."},kw={"brew","coldridge valley","dun morogh","dwarf","mornbrew mug","nori pridedrift","scalding mornbrew"},rel={"subzone:coldridge-valley","zone:dunmorogh","quest:3364","quest:3365","topic:dwarf"},src={"Nori Pridedrift"}}
E["npc:pilot-bellowfiz"] = {t="npc",n="Pilot Bellowfiz",z="dunmorogh",s="At Steelgrill's Depot, Pilot Bellowfiz keeps Ironforge's war machine ready. The Siege Brigade calls him “Fizzer,” and he tends Jetsteam, the heavy dwarven machine he pilots.",h="At Steelgrill's Depot, Pilot Bellowfiz keeps Ironforge's war machine ready.",sec={{t="Master of the Jetsteam",b="Just outside Ironforge, Bellowfiz tunes Jetsteam and gathers what the machine needs in the field. Pilot Stonegear, his fellow driver, joins him in debating vehicle designs, armor plating, and engine output. Their work keeps Khaz Modan's mechanized strength ready across the kingdom.",sp=0}},faq={{q="Who is Pilot Bellowfiz?",a="Pilot Bellowfiz serves in the Ironforge Siege Brigade. At Steelgrill's Depot in Dun Morogh, he maintains and operates heavy siege engines for Khaz Modan's defense.",al={"pilot bellowfiz","fizzer","who is fizzer"},it="identity"},{q="What machine does Bellowfiz drive?",a="Bellowfiz pilots Jetsteam, a dwarven siege engine. Before a long Siege Brigade journey, he stocks it with a month's supplies, including boar meat and bear fur. He keeps Rejold Barleybrew's Evershine on hand to throw into its furnace for a burst of power.",al={"bellowfiz tank","jetsteam","what siege engine does bellowfiz pilot"}},{q="Where can Pilot Bellowfiz be found?",a="You can find Pilot Bellowfiz at Steelgrill's Depot in Dun Morogh, down the road east of Kharanos. The depot is an engineering and staging yard.",al={"bellowfiz location","where is pilot bellowfiz","find bellowfiz"},it="place",gp=true},{q="What does he do with Pilot Stonegear?",a="Pilot Bellowfiz and Pilot Stonegear are fellow Siege Brigade drivers. When they are not tending their vehicles, they banter and debate siege engine design, armor, and mechanics.",al={"stonegear and bellowfiz","bellowfiz conversation"},it="ties"},{q="Whose side is Pilot Bellowfiz on?",a="Bellowfiz serves the Kingdom of Ironforge and the Grand Alliance as an active driver in the Ironforge Siege Brigade. His loyalties lie firmly with King Magni Bronzebeard and the dwarven defense forces safeguarding Dun Morogh.",al={"pilot bellowfiz faction","who does bellowfiz serve","is bellowfiz alliance"},it="side",add="8ff6759c"},{q="What does Pilot Bellowfiz want?",a="Bellowfiz focuses on keeping his siege tank, Jetsteam, battle-ready and fueled. He relies on travelers to gather supplies for a long Siege Brigade mission—boar meat for food, bear fur for bedding, and a cask of Rejold Barleybrew's Evershine to keep him warm and give Jetsteam's furnace a burst of power.",al={"what does bellowfiz need","pilot bellowfiz goals","why does bellowfiz need supplies"},it="wants",add="292f21ec"},{q="Why is Pilot Bellowfiz here at Steelgrill's Depot?",a="Steelgrill's Depot serves as the staging ground and proving yard for Ironforge's heavy armored vehicles. Bellowfiz is stationed here to tune, test, and stock his siege engine alongside fellow mechanics and drivers before deploying out into the snow.",al={"why is bellowfiz at steelgrills depot","why is pilot bellowfiz in dun morogh","bellowfiz purpose dun morogh"},it="why_here",add="53346562"}},ang={["profession:Engineering"]="As a dwarf or gnome tinkerer, you can see field engineering in Bellowfiz's work. He keeps powerful siege engines running in freezing mountain weather.",["race:Dwarf"]="As a dwarf, you can take pride in Ironforge's mechanized brigades. Their engineering skill and heavy firepower guard Khaz Modan."},kw={"bellowfiz","dun morogh","fizzer","jetsteam","pilot bellowfiz","pilot stonegear","siege brigade","steelgrill's depot"},rel={"subzone:steelgrill-s-depot","npc:pilot-stonegear","quest:317","quest:318","quest:415","zone:dunmorogh","zone:ironforge","topic:dwarf"},src={"Pilot Bellowfiz"}}
E["npc:pilot-hammerfoot"] = {t="npc",n="Pilot Hammerfoot",z="dunmorogh",s="At North Gate Outpost, Pilot Hammerfoot watches the pass and searches for a missing fellow pilot. The Siege Brigade’s engines guard the route, but the mountain hills are dangerous.",h="At North Gate Outpost, Pilot Hammerfoot watches the pass and searches for a missing fellow pilot.",sec={{t="Eyes in the Mountains",b="At North Gate Outpost, Pilot Hammerfoot watches the passes between Dun Morogh and Loch Modan. He guards Ironforge’s siege engines for the Siege Brigade. The rough mountain ground makes those engines dangerous to drive. Now one pilot is missing, and savage beasts roam the nearby hills. Finding him matters.",sp=0},{t="Avenging a Comrade",b="Pilot Hammerfoot was close friends with Pilot Mori Hildelve, another siege engine pilot. They searched for rare ore when Hildelve broke his engine on a steep hill and went on alone. Hammerfoot learned that a huge ice claw bear named Mangeclaw mauled Hildelve to death. Now he seeks retribution against the beast that killed his friend.",sp=1}},faq={{q="Who is Pilot Hammerfoot?",a="Pilot Hammerfoot is a dwarven siege engine pilot serving Ironforge. He watches the border from North Gate Outpost, along the pass between Dun Morogh and Loch Modan, and keeps watch over the region and the other pilots.",al={"hammerfoot lore","who is hammerfoot","pilot hammerfoot info"},it="identity"},{q="Where can Pilot Hammerfoot be found?",a="Pilot Hammerfoot can be found at North Gate Outpost, beside the mountain highway and tunnel pass between Dun Morogh and Loch Modan.",al={"hammerfoot location","where is pilot hammerfoot","where is hammerfoot"},it="place",gp=true},{q="What happened to Hammerfoot's partner, Pilot Hildelve?",a="Pilot Mori Hildelve broke his siege engine on a steep hill while searching for rare ore, then continued on foot. Hammerfoot has heard nothing from him and asks travelers to search for him.",al={"pilot morter fate","what happened to morter","morter death"},it="ties"},{q="Why is Hammerfoot worried about his partner?",a="Hammerfoot and Mori Hildelve are close friends and fellow Siege Brigade pilots. Hildelve went missing in dangerous mountain country, and Hammerfoot needs someone to find out what happened.",al={"pilot revenge why","why avenge morter","mangeclaw grudge"},it="wants"},{q="Whose side is Pilot Hammerfoot on?",a="Pilot Hammerfoot is a loyal dwarf of Ironforge and serves the Alliance. Stationed at the outpost guarding the pass between Dun Morogh and Loch Modan, he works to keep the mountaineers supplied and the local mountain passes clear of encroaching threats.",al={"hammerfoot faction","who does pilot hammerfoot serve","is hammerfoot alliance"},it="side",add="9955f46b"},{q="Why is Pilot Hammerfoot stationed here?",a="Hammerfoot guards the siege engines at North Gate Outpost near the pass between Dun Morogh and Loch Modan. He and Mori Hildelve came to the hills looking for rare ore, but Hildelve continued on foot after his engine broke down and has not returned.",al={"why is hammerfoot here","hammerfoot post","why is pilot hammerfoot at the outpost"},it="why_here",add="4a134edc"}},ang={["race:Dwarf"]="As a dwarf, you share the fierce camaraderie of Ironforge’s mountaineers. You refuse to let a fallen brother’s murder go unanswered.",["faction:Alliance"]="When you aid Hammerfoot, you help secure vital reconnaissance outposts along the main highway between Dun Morogh and Loch Modan."},kw={"dun morogh","ironforge","loch modan","mangeclaw","morter","north gate outpost","pilot hammerfoot","troggs"},rel={"subzone:north-gate-outpost","quest:419","quest:417","zone:dunmorogh","zone:lochmodan","topic:dwarf","subzone:south-gate-outpost"},src={"Pilot Hammerfoot"}}
E["npc:pilot-stonegear"] = {t="npc",n="Pilot Stonegear",z="dunmorogh",s="At Steelgrill's Depot, Pilot Stonegear readies the Trollplow for battle. Called “Stone,” the dwarf mechanic and driver serves in the Ironforge Siege Brigade. He seeks rare materials to improve the machine's engine and armor, and travelers in Dun Morogh help him find them.",h="At Steelgrill's Depot, Pilot Stonegear readies the Trollplow for battle.",sec={{t="Master of the Trollplow",b="At Steelgrill's Depot, Pilot Stonegear drives for Ironforge's Siege Brigade. His pride is Trollplow, a heavy siege tank built to break enemy lines. Stone knows a driver's life in battle depends on sound gears, strong plates, and steady steam pressure. So he keeps improving the tank's fighting power and making its cramped cockpit more livable.",sp=0},{t="Tinkering and Metallurgy",b="Off duty, Pilot Stonegear debates engineering plans with fellow pilots such as Pilot Bellowfiz. The depot's standard designs never satisfy him. He seeks unusual ores and volatile minerals to improve Trollplow's armor and munitions. Travelers cross Dun Morogh's snowy wilderness and dangerous caves to find the supplies he needs.",sp=0}},faq={{q="Who is Pilot Stonegear?",a="Often called “Stone,” Pilot Stonegear is a dwarf in the Ironforge Siege Brigade. At Steelgrill's Depot in Dun Morogh, he maintains and drives his siege engine, Trollplow.",al={"pilot stonegear lore","who is stonegear","pilot stone"},it="identity"},{q="Where is Pilot Stonegear located?",a="Pilot Stonegear is at Steelgrill's Depot, just outside Kharanos in Dun Morogh. Siege tanks, spare parts, and fellow pilots surround him there.",al={"pilot stonegear location","where is stonegear","find stonegear"},it="place",gp=true},{q="What is the Trollplow?",a="Trollplow is Pilot Stonegear's personal siege engine. He works to improve its reliability, armor, and interior comfort for front-line combat.",al={"what is trollplow","trollplow tank","stonegear's tank"},it="item"},{q="What does Stonegear need adventurers for?",a="Stonegear asks travelers to scout nearby threats and gather rare minerals, including incendicite ore. He uses those supplies to maintain and improve the Siege Brigade's heavy war machines.",al={"pilot stonegear quests","why does stonegear have quests","stonegear's search"},it="wants"},{q="Who does Pilot Stonegear work with?",a="Pilot Stonegear serves in the Ironforge Siege Brigade with drivers such as Pilot Bellowfiz and Pilot Hammerfoot. At the depot, he often discusses mechanical improvements and machine designs with Bellowfiz.",al={"stonegear friends","siege brigade pilots","bellowfiz and stonegear"},it="ties"},{q="What is the Ironforge Siege Brigade?",a="The Ironforge Siege Brigade is the dwarven military's mechanized armor division. Its steam tanks, siege engines, and heavy artillery defend Dun Morogh and project Ironforge's military might across Khaz Modan.",al={"ironforge siege brigade","siege brigade lore","dwarf tank brigade"},it="allies"},{q="Whose side is Pilot Stonegear on?",a="Pilot Stonegear serves Ironforge and the Alliance as a dedicated driver in the Ironforge Siege Brigade. Stationed at Steelgrill's Depot, his loyalty lies entirely with the dwarven kingdom, defending the snowy ridges of Dun Morogh and working to keep the city's heavy war machines tuned for any threat to his people.",al={"pilot stonegear faction","stonegear allegiance","who does pilot stonegear serve"},it="side",add="6ae24a1f"},{q="Why is Pilot Stonegear here at Steelgrill's Depot?",a="Stonegear is stationed at Steelgrill's Depot to test, maintain, and refine his siege engine, the Trollplow. Alongside fellow brigade drivers, he uses the depot's workshops to oversee repairs, talk shop about engine mechanics, and acquire the rare ores and minerals needed to improve his machine's resilience in the field.",al={"why is stonegear in dun morogh","why is pilot stonegear here","stonegear steelgrills depot"},it="why_here",add="5e3743ba"}},ang={["race:Dwarf"]="As a dwarf, you can share Stonegear's love of heavy steel, roaring engines, and crushing mountain foes beneath iron treads.",["race:Gnome"]="As a gnome serving alongside the Siege Brigade, you may find a kindred spirit in Stonegear. He eagerly tinkers with designs and seeks greater output.",["profession:Engineering"]="As an engineer, you can appreciate how Stonegear adapts Trollplow in the field, balancing combat power with the driver's comfort.",["profession:Mining"]="As a miner, you can supply the raw ores and volatile underground deposits Stonegear needs for reinforced plating and munitions."},kw={"dun morogh","ironforge siege brigade","pilot bellowfiz","pilot hammerfoot","pilot stonegear","siege engine","steelgrill's depot","stonegear","trollplow"},rel={"subzone:steelgrill-s-depot","npc:pilot-bellowfiz","npc:pilot-hammerfoot","zone:dunmorogh","zone:ironforge","quest:467","quest:466","quest:313"},src={"Pilot Stonegear"}}
E["npc:ragnar-thunderbrew"] = {t="npc",n="Ragnar Thunderbrew",z="dunmorogh",s="At the Thunderbrew Distillery in Kharanos, Ragnar Thunderbrew keeps the family tavern supplied and its patrons fed. Across Dun Morogh, the dwarven brewer is known for the family's Beer Basted Boar Ribs.",h="At the Thunderbrew Distillery in Kharanos, Ragnar Thunderbrew keeps the family tavern supplied and its...",sec={{t="A Pillar of Kharanos Hospitality",b="Ragnar Thunderbrew tends the kitchen and brewing work at the Thunderbrew Distillery in Kharanos. Mountaineers, travelers, and gnome refugees fleeing Gnomeregan gather there. His Beer Basted Boar Ribs, made with dwarven ale, are a Dun Morogh specialty.\n\nSupplies have grown hard to find since his usual meat provider enlisted in the King's Army. Ragnar now depends on wandering mountaineers and hunters to bring fresh crag boar flanks to the kitchen.",sp=0},{t="The Thunderbrew Legacy",b="Across Ironforge territory, the Thunderbrew name is known for dwarven drink and tavern life. Ragnar has kept the distillery running since his older brother, Grimbooze Thunderbrew, disappeared in a drunken haze a few harvests ago.\n\nHe guards the family's brewing heritage against thieves such as the Dark Iron dwarves, who stole the recipe for Thunderbrew Lager. With patrons restless, supplies scarce, and disputes breaking out in the tavern, Ragnar keeps the taps flowing and travelers fed in Kharanos.",sp=0}},faq={{q="Who is Ragnar Thunderbrew?",a="Ragnar Thunderbrew brews and tends the tavern at the Thunderbrew Distillery in Kharanos. He also prepares the clan's famous ale-basted boar ribs.",al={"who is ragnar","ragnar thunderbrew role","ragnar kharanos"},it="identity"},{q="Why is Ragnar looking for boar ribs?",a="Ragnar's regular meat supplier enlisted in King Magni's army, leaving the kitchen short of ingredients. He buys fresh flanks from passing hunters and travelers to feed the tavern's patrons.",al={"why need boar meat","beer basted ribs quest","boar rib supply"},it="wants"},{q="How is Ragnar related to Grimbooze Thunderbrew?",a="Grimbooze is Ragnar's older brother. Their father, Arkilus, founded the Thunderbrew Distillery. Ragnar has kept it running since Grimbooze disappeared in a drunken haze a few harvests ago.",al={"ragnar and grimbooze","grimbooze thunderbrew relation"},it="ties"},{q="Where is Ragnar Thunderbrew located?",a="Ragnar works inside the Thunderbrew Distillery in Kharanos, in the central snowy hills of Dun Morogh.",al={"ragnar location","where to find ragnar thunderbrew"},it="place",gp=true},{q="Whose side is Ragnar Thunderbrew on?",a="Ragnar stands firmly with Ironforge and the Grand Alliance. Operating out of Kharanos, he proudly caters to dwarven travelers, mountaineers, and local patrols who frequent the distillery.",al={"ragnar thunderbrew faction","ragnar alliance","is ragnar friendly to alliance"},it="side",add="a4e8a35c"},{q="Why is Ragnar Thunderbrew here in Kharanos?",a="Ragnar is in Kharanos to run the Thunderbrew Distillery. As co-owner, he works out of the local inn to brew dwarven ales, prepare hearty meals, and manage the family's busy trade in Dun Morogh.",al={"why is ragnar in kharanos","ragnar thunderbrew location motive","what does ragnar do in kharanos"},it="why_here",add="6e9b3705"},{q="Why is Ragnar Thunderbrew famous?",a="Ragnar is renowned for holding the secret family recipe for Beer Basted Boar Ribs, one of Dun Morogh's most famous and beloved dwarven culinary traditions.",al={"what is ragnar famous for","ragnar thunderbrew fame","why is thunderbrew famous"},it="fame",add="6804fc69"}},ang={["profession:Cooking"]="As a cook, you can turn to Ragnar for the Thunderbrew family's Beer Basted Boar Ribs recipe and hearty dwarven tavern cooking.",["race:Dwarf"]="As a dwarf passing through Dun Morogh, you can find a taste of home in Ragnar's tavern, with the clan's ale and rib cooking."},kw={"ale","beer basted boar ribs","dun morogh","dwarf","grimbooze thunderbrew","kharanos","ragnar thunderbrew","thunderbrew distillery"},rel={"subzone:thunderbrew-distillery","subzone:kharanos","quest:384","npc:grimbooze-thunderbrew","zone:dunmorogh","topic:dwarf"},src={"Ragnar Thunderbrew"}}
E["npc:razzle-sprysprocket"] = {t="npc",n="Razzle Sprysprocket",z="dunmorogh",s="In Kharanos, Razzle Sprysprocket searches for the machinery lost when Gnomeregan fell. With Ozzie Togglevolt, he gathers parts scattered through Dun Morogh’s snowy hills.",h="In Kharanos, Razzle Sprysprocket searches for the machinery lost when Gnomeregan fell.",sec={{t="Tinkering in Kharanos",b="After Gnomeregan fell, Razzle found refuge in Dun Morogh and opened a workshop in Kharanos. Skilled with delicate mechanisms, he works beside fellow engineer Ozzie Togglevolt. Together, they seek gyro-mechanisms and cog assemblies lost or scavenged during the flight from their irradiated homeland.",sp=0},{t="Defense of the Workshop",b="Wild beasts roam Dun Morogh’s frozen ridges, and Frostmane trolls raid the area. Their presence makes Razzle’s work dangerous. Still, he labors to keep gnomish contraptions working and recover the lost wonders of Gnomeregan.",sp=0}},faq={{q="Who is Razzle Sprysprocket?",a="Razzle Sprysprocket tinkers in Kharanos, Dun Morogh, alongside Ozzie Togglevolt.",al={"razzle sprysprocket","who is razzle","razzle kharanos"},it="identity"},{q="What does Razzle Sprysprocket need help with?",a="Razzle needs travelers to search Dun Morogh for lost gizmos, cog assemblies, and parts for gnomish engineering projects.",al={"razzle quest","operation recombobulation help","what does razzle want"},it="wants"},{q="Where can I find Razzle Sprysprocket?",a="Razzle works outdoors near the tinker's post in Kharanos, just outside the inn and forge in central Dun Morogh.",al={"razzle location","where is razzle","razzle sprysprocket map"},it="place",gp=true},{q="Is Razzle Sprysprocket related to other Sprysprockets?",a="No relatives of Razzle are named. Rizzle Sprysprocket shares his surname, but the two are apparently unrelated.",al={"sprysprocket family","razzle relatives"},it="ties"},{q="Whose side is Razzle Sprysprocket on?",a="Razzle Sprysprocket is aligned with Gnomeregan Exiles and the Alliance. Stationed in Kharanos alongside his fellow refugees, he works closely with other gnomish inventors like Ozzie Togglevolt to aid their displaced people in Dun Morogh.",al={"razzle sprysprocket faction","is razzle alliance","razzle sprysprocket allegiance"},it="side",add="b527298b"},{q="Why is Razzle Sprysprocket in Kharanos?",a="Like many gnomes, Razzle Sprysprocket took refuge in Kharanos following the tragic fall of Gnomeregan. Setting up shop in the snowy town, he continues his tinkerings and seeks materials to support ongoing gnomish recovery efforts.",al={"why is razzle here","razzle sprysprocket kharanos why","what brought razzle to kharanos"},it="why_here",add="fcfe3829"}},ang={["race:Gnome"]="For an exiled gnome in Dun Morogh, Razzle shows the inventive spirit and resolve to rebuild and recover after Gnomeregan fell.",["profession:Engineering"]="Engineers may recognize a kindred spirit in Razzle. His projects show how close gnomish invention can come to miscalculation and explosion."},kw={"dun morogh","engineer","kharanos","ozzie togglevolt","razzle","recombobulation","sprysprocket"},rel={"subzone:kharanos","zone:dunmorogh","npc:ozzie-togglevolt","quest:412","topic:gnome","topic:troll"},src={"Razzle Sprysprocket"}}
E["npc:rejold-barleybrew"] = {t="npc",n="Rejold Barleybrew",z="dunmorogh",s="At Brewnall Village, Rejold Barleybrew keeps working toward the perfect mountain spirit. He gathers ingredients from western Dun Morogh and tests each recipe.",h="At Brewnall Village, Rejold Barleybrew keeps working toward the perfect mountain spirit.",sec={{t="A Master of the Craft",b="Dwarves in Dun Morogh take brewing seriously. Rejold works in Brewnall Village, near the frozen lake of the Iceflow River. He keeps refining his blends with rare hops, mountain minerals, and pristine ice water. His aim is a stout hearty enough to warm even the stoutest dwarven warriors.",sp=0},{t="The Search for the Perfect Stout",b="Rejold seeks the right flavors for drinks such as Shimmer Stout. He sends travelers across Dun Morogh for ingredients and trades favors with the siege pilots of Steelgrill's Depot. He also arranges deliveries to thirsty patrons. So hearty ale keeps flowing along Dun Morogh's cold, trogg-plagued roads.",sp=0}},faq={{q="Who is Rejold Barleybrew?",a="Rejold Barleybrew brews ales in Brewnall Village, Dun Morogh. He works to perfect his recipes and sends travelers to gather ingredients and deliver experimental brews.",al={"rejold","who is rejold","rejold barleybrew info"},it="identity"},{q="Where can Rejold Barleybrew be found?",a="Rejold Barleybrew can be found in Brewnall Village, in western Dun Morogh beside the frozen waters of the Iceflow Basin.",al={"rejold location","where is rejold barleybrew","rejold barleybrew brewnall"},it="place",gp=true},{q="What is Rejold working on?",a="Rejold is perfecting potent mountain recipes, including Shimmer Stout and other experimental ales. He needs cold mountain flora and brewing components from across the snowy hills.",al={"rejold quest","perfect stout quest","what is rejold brewing"},it="wants"},{q="Why does Rejold send travelers to gnomes?",a="Rejold's errands connect him to fellow dwarves, not gnomes. Pilot Bellowfiz of Steelgrill's Depot sends travelers to Rejold for Evershine, while Rejold's Shimmer Stout goes to his brother, Mountaineer Barleybrew.",al={"rejold gnomes","rejold evershine","bellowfiz rejold"},it="motive"},{q="What is Shimmer Stout?",a="Shimmer Stout is a potent dwarven drink brewed by Rejold Barleybrew. Its mountain ingredients give it a distinctive kick in freezing winter weather.",al={"what is shimmer stout","shimmer stout lore"},it="item"},{q="Whose side is Rejold Barleybrew on?",a="Rejold is a proud Ironforge dwarf aligned firmly with the Alliance. Like many of his kin in Dun Morogh, he spends his days perfecting dwarven craft and serving travelers passing through Brewnall Village, maintaining friendly ties with fellow dwarves such as Pilot Bellowfiz of Steelgrill's Depot.",al={"rejold faction","rejold alliance or horde","is rejold barleybrew alliance"},it="side",add="86e90b5e"},{q="Why is Rejold Barleybrew here in Brewnall Village?",a="Rejold is stationed in Brewnall Village pursuing his life's passion: crafting the finest ales in Khaz Modan. Brewnall Village provides him access to fresh mountain water and local ingredients for his ambitious brews.",al={"why is rejold here","rejold brewnall village why","what brought rejold to brewnall"},it="why_here",add="ede674a2"}},ang={["race:Dwarf"]="As a dwarf, you know Rejold's work belongs to Khaz Modan's mountaineering tradition. Strong ales bring warmth and strength against the bitter winter chill.",["profession:Cooking"]="As a cook, you can appreciate Rejold's care with ingredients and recipes. He treats brewing as a precise and venerable art.",["faction:Alliance"]="As an Alliance traveler, you can count on Rejold's stout to lift spirits across Dun Morogh. It strengthens guards and travelers facing trogg raids and harsh blizzards."},kw={"ale","barleybrew","brewer","brewnall","dun morogh","rejold","shimmer stout","stout"},rel={"subzone:brewnall-village","quest:315","quest:413","quest:415","quest:318","quest:319","zone:dunmorogh","topic:dwarf"},src={"Rejold Barleybrew"}}
E["npc:sara-balloo"] = {t="npc",n="Sara Balloo",z="dunmorogh",s="In Ironforge's Military Ward, Sara Balloo grieves for Sully and holds to the words he left behind.",h="In Ironforge's Military Ward, Sara Balloo grieves for Sully and holds to the words he left behind.",sec={{t="A Widow's Vigil",b="Sara Balloo keeps vigil in Ironforge's Military Ward, where weapons ring and soldiers drill. Her husband, Sully Balloo, fell in battle far from home, leaving her with grief and memories. A final letter crossed the mountains from the place where he died. Sully's words from his last days bring Sara some measure of closure.",sp=0},{t="A Cry for Remembrance",b="Sara Balloo wants Sully's sacrifice remembered. She appeals to King Magni Bronzebeard to honor Sully and the other fallen soldiers from the throne. She wants the cost borne by ordinary dwarven families to be remembered.",sp=1}},faq={{q="Who is Sara Balloo?",a="Sara Balloo lives in Ironforge's Military Ward. She is the widow of Sully Balloo, a dwarven soldier who fell in battle.",al={"sara balloo","who is sara balloo","sara balloo ironforge"},it="identity"},{q="Where can I find Sara Balloo?",a="You can find Sara Balloo in Ironforge's Military Ward, near the training grounds and barracks.",al={"where is sara balloo","sara balloo location","find sara balloo"},it="place",gp=true},{q="What happened to her husband?",a="Sully Balloo died during military service. An adventurer recovered his belongings and a final waterlogged letter after they had been lost.",al={"sara balloo husband","who is sully balloo","what happened to sully"},sp=1,it="ties"},{q="What does Sara do with Sully's letter?",a="After reading Sully's heartfelt words, Sara writes to King Magni Bronzebeard and asks him to recognize and remember Sully's sacrifice.",al={"sully balloo letter","sara balloos plea","what does sara balloo want"},sp=1,it="wants"},{q="Whose side is Sara Balloo on?",a="Sara Balloo is a loyal citizen of Ironforge and an adherent of the Alliance. Her late husband, Sully Balloo, died in service to the dwarven kingdom while his unit stood watch over the Thandol Span, and she remains among her people under King Magni Bronzebeard's rule.",al={"sara balloo faction","sara balloo alliance","who does sara balloo serve"},it="side",add="736253da"},{q="Why is Sara Balloo in the Military Ward?",a="Sara makes her home in Ironforge's Military Ward, living among the kingdom's soldiers and veterans. Having lost her husband Sully to war, she remains close to the civic and martial heart of the mountain city, where memories of those who fell defending the realm are honored.",al={"why is sara balloo in ironforge","why is sara balloo here","sara balloo military ward"},it="why_here",add="658d468d"}},ang={["race:Dwarf"]="As a dwarf passing through Ironforge's Military Ward, you can see in Sara Balloo the toll on families whose kin defend Khaz Modan.",["faction:Alliance"]="As an Alliance soldier, you see how news can bring closure to a fallen soldier's family. Battles across Azeroth wound those at home."},kw={"dun morogh","ironforge","magni bronzebeard","military ward","sara balloo","sully balloo","widow"},rel={"quest:637","quest:683","zone:ironforge","subzone:military-ward","topic:dwarf","zone:dunmorogh"},src={"Sara Balloo"}}
E["npc:senator-mehr-stonehallow"] = {t="npc",n="Senator Mehr Stonehallow",z="dunmorogh",s="At Gol'Bolar Quarry, Senator Mehr Stonehallow has arrived at the front lines to face a trogg infestation. The Ironforge politician and Explorers' League member oversees its containment and calls on eager adventurers to cull the beasts before they overrun the quarry.",h="At Gol'Bolar Quarry, Senator Mehr Stonehallow has arrived at the front lines to face a trogg infestation.",sec={{t="A Politician in the Pits",b="Senator Mehr Stonehallow has left Ironforge's Senate halls for Gol'Bolar Quarry. A dwarf devoted to governance and the Explorers' League's historical pursuits, he knows the dangers facing the realm. When Rockjaw troggs clawed up from deep rock, Stonehallow came to the mining pit himself. He believes debate alone cannot protect the workers. So he offers bounties to capable travelers who can drive back the aggressive troggs and reclaim the quarry.",sp=0}},faq={{q="Who is Senator Mehr Stonehallow?",a="Senator Mehr Stonehallow serves in Ironforge's Senate and belongs to the Explorers' League. He has come to Gol'Bolar Quarry to organize its defense.",al={"stonehallow role","who is the senator","mehr stonehallow"},it="identity"},{q="Why is a senator stationed at Gol'Bolar Quarry?",a="Senator Mehr Stonehallow has come to Gol'Bolar Quarry to take charge of a crisis. Rockjaw troggs burrowed up from beneath the earth and invaded the mining site, threatening dwarven workers and valuable excavations. Stonehallow will not leave the problem to distant officials.",al={"why is stonehallow here","why is he at the quarry","senator in dun morogh"},it="why_here"},{q="What does Senator Stonehallow want adventurers to do?",a="Senator Mehr Stonehallow hires newly arrived adventurers to cull Rockjaw troggs in and around Gol'Bolar Quarry. Clearing the lower levels helps secure the excavation site and protect the remaining miners.",al={"the public servant quest","stonehallow task","quarry quests"},it="wants"},{q="What organization does Stonehallow belong to besides the Senate?",a="Mehr Stonehallow belongs to the Explorers' League as well as the Ironforge Senate. His interest in subterranean excavations helps explain why he ventured beyond the capital.",al={"stonehallow faction","is stonehallow explorers league","stonehallow affiliation"},it="ties"},{q="Whose side is Senator Mehr Stonehallow on?",a="Senator Mehr Stonehallow stands firmly with the Kingdom of Ironforge and the Grand Alliance. As a sitting member of the Ironforge Senate and an active associate of the Explorers' League, his loyalties lie directly with King Magni Bronzebeard and the safety of the dwarven homeland.",al={"senator stonehallow faction","who does stonehallow serve","is stonehallow alliance"},it="side",add="67284ec7"}},ang={["race:Dwarf"]="For dwarves, a senator standing in quarry mud instead of drinking ale in Ironforge's High Seat shows the grit expected of their leaders.",["faction:Alliance"]="Stonehallow offers young Alliance heroes a glimpse of dwarven leadership: protect working citizens by slaying monsters."},kw={"dun morogh","explorers' league","gol'bolar","ironforge senate","mehr","quarry","rockjaw","senator","stonehallow","trogg"},rel={"subzone:gol-bolar-quarry","quest:433","topic:explorers-league","topic:trogg","zone:dunmorogh","zone:ironforge","topic:dwarf"},src={"Senator Mehr Stonehallow"}}
E["npc:senir-whitebeard"] = {t="npc",n="Senir Whitebeard",z="dunmorogh",s="Outside the Thunderbrew Distillery in Kharanos, Senir Whitebeard watches the threats growing across Dun Morogh. The Senate of Ironforge sent him to assess the Frostmane troll offensive and report their movements to the dwarven leadership.",h="Outside the Thunderbrew Distillery in Kharanos, Senir Whitebeard watches the threats growing across Dun...",sec={{t="Envoy of the Senate",b="Senir Whitebeard brings the Senate of Ironforge's authority to Kharanos. The city's halls watch as unrest grows across Dun Morogh. Senir carries news from scouts on the snowy frontier to the lawmakers behind Ironforge's stone gates.",sp=0},{t="Eyes on the Frostmanes",b="The Frostmane trolls grow more aggressive, pressing close to dwarven settlements and roads from the frozen crags where they are displaced and desperate. Senir gathers reports on their positions, especially around their stronghold, for Ironforge's military commanders. His work is to gather intelligence, not charge into battle.",sp=0}},faq={{q="Who is Senir Whitebeard?",a="Senir Whitebeard is an envoy from the Senate of Ironforge, stationed outside Kharanos to gather intelligence on threats in Dun Morogh, especially the Frostmane trolls.",al={"who is this dwarf","senir whitebeard lore","who is senir"},it="identity"},{q="What is Senir doing in Kharanos?",a="Senir Whitebeard observes troll activity in Kharanos and coordinates scout reports. Kharanos is a crossroads in Dun Morogh, where he receives field intelligence before sending it to the Senate in Ironforge.",al={"why is senir here","senir kharanos role","what does senir do"},it="why_here"},{q="Why does the Senate of Ironforge need an envoy here?",a="The Senate of Ironforge needs Senir Whitebeard to gather firsthand reports from the field. He assesses whether the Frostmane threat calls for an immediate military response from the capital.",al={"why envoy","ironforge senate kharanos","senate business"},it="ties"},{q="What is Senir's primary concern in Dun Morogh?",a="Senir Whitebeard's chief concern is the Frostmane troll incursions. The trolls are pushing out of their camps into dwarf territory and threatening nearby settlements such as Kharanos.",al={"senir main problem","what threat is senir watching","senir trolls"},it="wants"},{q="Does Senir fight the trolls himself?",a="No. Senir Whitebeard gathers intelligence and depends on local scouts, Mountaineers, and passing adventurers to enter hostile sites like Frostmane Hold and bring him reports.",al={"does senir fight","is senir a warrior","senir combat"}},{q="Where do Senir's reports go?",a="Senir Whitebeard sends reports on troll positions and strengths up the mountain road to the Senate and leadership in Ironforge.",al={"where do reports go","senir reports destination","who gets the reports"},it="purpose"},{q="Whose side is Senir Whitebeard on?",a="Senir Whitebeard serves the Kingdom of Ironforge and the Grand Alliance. Operating as an official envoy under the direct authority of the Senate of Ironforge, his loyalty lies entirely with the dwarven government and the defense of the realm's heartland.",al={"senir whitebeard allegiance","who does senir serve","senir faction"},it="side",add="40f66e19"}},ang={["race:Dwarf"]="As a dwarf, you can see Senir Whitebeard link frontier defenders with Ironforge's governing body.",["faction:Alliance"]="As an Alliance recruit in Dun Morogh, you can help Senir Whitebeard protect Ironforge's heartland from being cut off by troll uprisings."},kw={"dun morogh","frostmane","ironforge","kharanos","reports","senate","senir","whitebeard"},rel={"subzone:kharanos","zone:dunmorogh","zone:ironforge","topic:dwarf","quest:282","quest:287","quest:291"},src={"Senir Whitebeard"}}
E["npc:solm-hargrin"] = {t="npc",n="Solm Hargrin",z="dunmorogh",s="At Anvilmar in Coldridge Valley, Solm Hargrin prepares young dwarves and gnomes for the work of a rogue. As tensions rise across Azeroth, he believes covert operatives will be vital.",h="At Anvilmar in Coldridge Valley, Solm Hargrin prepares young dwarves and gnomes for the work of a rogue.",sec={{t="A Mentor in the Shadows",b="Solm Hargrin teaches his pupils to decipher coded messages and use techniques such as Eviscerate. Ironforge relies on mountaineers and warriors, yet some threats call for quieter methods. So he teaches loyalty to the craft and to one another, preparing his pupils for a more unsettled world.",sp=0}},faq={{q="Who is Solm Hargrin?",a="Solm Hargrin trains young dwarves and gnomes in rogue work at Anvilmar in Coldridge Valley. He teaches them stealth and bladecraft.",al={"who is solm","solm hargrin lore","anvilmar rogue trainer"},it="identity"},{q="What is Solm Hargrin's philosophy on rogue work?",a="Solm Hargrin teaches honor among thieves. He believes loyalty to the craft and to one another matters, even when their methods are underhanded.",al={"solm beliefs","honor among thieves","solm view"}},{q="What quests does Solm Hargrin provide or receive?",a="Novice dwarven rogues bring Solm Hargrin an Encrypted Rune, while new gnomish rogues bring him an Encrypted Memorandum. He deciphers the orders, then sends trainees to master offensive maneuvers in the field.",al={"solm quests","encrypted rune solm","encrypted memorandum solm"},gp=true},{q="Does Solm Hargrin train races other than dwarves?",a="Yes. Solm Hargrin trains gnomes alongside dwarves in Coldridge Valley.",al={"can gnomes train with solm","gnome rogue trainer anvilmar"},gp=true},{q="Whose side is Solm Hargrin on?",a="Solm Hargrin is loyal to Ironforge and the Alliance. Stationed in Coldridge Valley, he prepares fledgling operatives to defend dwarven lands, firmly believing that shadowy arts are essential tools for securing the realm amidst growing political unrest.",al={"solm hargrin faction","solm hargrin loyalty","is solm hargrin alliance"},it="side",add="3b6a2fc5"},{q="What does Solm Hargrin want?",a="Hargrin aims to instruct promising new rogues in the fundamentals of stealth, precision, and personal honor. Watching tensions escalate across the world, he believes practitioners of the subtle craft will soon play a vital role, and he wants his students properly honed and disciplined.",al={"solm hargrin goal","what does solm hargrin want","solm hargrin motive"},it="wants",add="7da5d6e5"},{q="Why is Solm Hargrin in Coldridge Valley?",a="He is stationed at Anvilmar to mentor newly arrived adventurers who walk the path of the shadows. As a trainer, he inspects encrypted missives sent by covert contacts and initiates young dwarves and gnomes into the art of silent combat.",al={"why is solm hargrin here","solm hargrin anvilmar purpose","why is solm hargrin in anvilmar"},it="why_here",add="d84d95b0"}},ang={["class:Rogue"]="As a dwarf or gnome beginning rogue training, you can learn the basics from Solm Hargrin. He also deciphers your first guild orders.",["race:Dwarf"]="As a dwarf, you can follow a quieter path in Dun Morogh, where stealth and cunning have their place alongside armor and axes."},kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","encrypted rune","rogue trainer","solm hargrin"},rel={"subzone:anvilmar","zone:dunmorogh","quest:3109","quest:3113","topic:dwarf","topic:gnome"},src={"Solm Hargrin"}}
E["npc:sten-stoutarm"] = {t="npc",n="Sten Stoutarm",z="dunmorogh",s="Outside Anvilmar, Sten Stoutarm keeps recruits equipped and messages moving through Coldridge Valley. Winter blizzards cut off the valley, and dangers nearby make warmth, food, and clear instructions vital.",h="Outside Anvilmar, Sten Stoutarm keeps recruits equipped and messages moving through Coldridge Valley.",sec={{t="A Helping Hand in the Snow",b="Near the tavern outside Anvilmar, Sten Stoutarm meets new dwarven and gnomish recruits. Winter blizzards cut off Coldridge Valley, and dangers lie close at hand. So Sten gives green apprentices sturdy gear to face the snow prepared.",sp=0},{t="Keeping the Lines Open",b="Sten gathers wolf hides for winter clothing and carries messages through Coldridge Valley. He takes dispatches through dangerous Coldridge Pass, then brings official runes, memoranda, and orders to class trainers across the basin. Troggs block the tunnels, yet young warriors, priests, and mages still need their instructions.",sp=0}},faq={{q="Who is Sten Stoutarm?",a="Outside Anvilmar in Coldridge Valley, Sten Stoutarm outfits recruits and carries messages. He helps new arrivals get warm clothing and local mail delivered.",al={"sten stoutarm","who is sten","anvilmar postman"},it="identity"},{q="What role does he play in Coldridge Valley?",a="Sten outfits apprentices and carries messages for Anvilmar. He gathers wolf meat and pelts for protective gear, then routes correspondence and training memoranda across the valley.",al={"sten job","what does sten do","sten role"},it="purpose"},{q="Why does Sten need mail delivered?",a="Troggs and winter weather make Coldridge Pass dangerous, hindering mail and supplies bound for the valley. When messages arrive, Sten asks dependable newcomers to deliver parcels and letters to residents such as Talin Keeneye.",al={"why coldridge mail delivery","sten mail","coldridge valley mail delivery"}},{q="What does Sten think about the troggs in the valley?",a="Sten is weary of the troggs in the surrounding hills. He says that once you have seen one trogg, you have seen them all.",al={"sten troggs","trogg quote","sten on troggs"},it="threat"},{q="Why does he ask for wolf meat?",a="Sten trades warm, durable gloves for tough wolf meat. The meat feeds the valley's defenders, while the gloves protect them from Dun Morogh's cold.",al={"dwarven outfitters quest","wolf meat quest","sten wolf meat"},it="why_wanted"},{q="What are the runes and memoranda Sten gives to new adventurers?",a="The runes and memoranda are sealed letters and training tokens sent by superiors across Ironforge and Dun Morogh. They direct young apprentices to report to their class trainers inside Anvilmar.",al={"consecrated rune","simple memorandum","sten notes"},it="item"},{q="Whose side is Sten Stoutarm on?",a="Sten Stoutarm is a loyal dwarf of Ironforge and stands firmly with the Alliance. Stationed at Anvilmar in Coldridge Valley, he supports the local training grounds and ensures that freshly arrived dwarven and gnomish recruits have the supplies and orders they need to defend the valley.",al={"sten stoutarm faction","who does sten stoutarm serve","sten stoutarm alliance"},it="side",add="be997a27"},{q="What does Sten Stoutarm want?",a="Sten wants to keep logistics running smoothly in Coldridge Valley despite the surrounding perils. With the valley pressed by troggs and wild beasts, he looks for capable new recruits to distribute critical mail from the pass, collect wolf meat for rugged outfitter gloves, and carry written orders to their respective class trainers.",al={"what does sten want","sten stoutarm goals","why does sten need help"},it="wants",add="9084afa8"},{q="Why is Sten Stoutarm here in Coldridge Valley?",a="Sten is stationed at Anvilmar to act as a vital coordinator and postman for Coldridge Valley. Because the pass connecting the valley to the rest of Dun Morogh is dangerous and infested, incoming communications and dispatches require someone on-site to direct traffic, outfit novice defenders, and route messages to Anvilmar's instructors.",al={"why is sten here","why is sten stoutarm in coldridge valley","sten stoutarm location reason"},it="why_here",add="d8d60996"}},ang={["race:Dwarf"]="As a dwarf, you can count on Sten's practical hospitality in Dun Morogh. He gives you thick leather and food before you head into the snow.",["race:Gnome"]="As a gnomish refugee training alongside dwarves in Anvilmar, you face Sten's practical expectations too. He sends you with mail and gear for the elements.",["faction:Alliance"]="As an Alliance member, you depend on messages through Coldridge Pass to keep Ironforge's training grounds connected. Sten carries mail across the valley."},kw={"anvilmar","coldridge","dun morogh","mail","outfitter","sten","stoutarm","trogg"},rel={"subzone:anvilmar","subzone:coldridge-valley","quest:179","quest:233","subzone:coldridge-pass","quest:3107","topic:dwarf","topic:trogg"},src={"Sten Stoutarm"}}
E["npc:tannok-frosthammer"] = {t="npc",n="Tannok Frosthammer",z="dunmorogh",s="At Thunderbrew Distillery near Kharanos, Tannok Frosthammer waits for supplies from Coldridge Valley. Trogg attacks have closed the roads to Anvilmar.",h="At Thunderbrew Distillery near Kharanos, Tannok Frosthammer waits for supplies from Coldridge Valley.",sec={{t="A Severed Supply Line",b="At Thunderbrew Distillery in Kharanos, Tannok Frosthammer watches for deliveries and listens for news. Troggs have poured through Coldridge Pass, closing the usual route from Coldridge Valley and cutting off regular word from Anvilmar. Hands Springsprocket, a gnome tinkerer, carries supplies and news through the dangerous, snowy pass. Tannok shares the worry of many Bronzebeards as subterranean troggs creep closer to their doorsteps.",sp=0}},faq={{q="Where is Tannok Frosthammer located?",a="Tannok Frosthammer waits outside Thunderbrew Distillery, just east of Kharanos's main crossroads in Dun Morogh.",al={"tannok location","where is tannok","find tannok frosthammer"},it="place",gp=true},{q="Why is Tannok worried about Coldridge Valley?",a="Troggs have overrun Coldridge Pass, cutting off regular communication and trade between Anvilmar and the rest of Dun Morogh.",al={"tannok concerns","why is tannok worried","coldridge pass troggs"},it="wants"},{q="Who does Tannok work with in Coldridge Valley?",a="Tannok receives deliveries from Hands Springsprocket, a gnomish supplier in Coldridge Valley. Hands asks passing travelers to carry goods through the dangerous pass.",al={"tannok supplier","hands springsprocket delivery","who supplies tannok"},it="ties"},{q="Who is Tannok Frosthammer?",a="Tannok Frosthammer is an Ironforge dwarf residing in Kharanos, stationed at Thunderbrew Distillery. He helps oversee the flow of local goods and supplies through Dun Morogh, maintaining vital logistical links between the central towns and more isolated outposts like Coldridge Valley.",al={"who is tannok","tannok frosthammer lore","tannok identity"},it="identity",add="22aa1045"},{q="Whose side is Tannok Frosthammer on?",a="Tannok is a loyal subject of Ironforge and a steadfast member of the Alliance. His chief concern is the safety and well-being of Dun Morogh's townsfolk and ensuring their trade routes remain functional despite rising threats in the snow.",al={"tannok faction","is tannok alliance","tannok frosthammer allegiance"},it="side",add="93f9fc20"},{q="Why is Tannok Frosthammer here?",a="Tannok conducts business out of Thunderbrew Distillery in Kharanos. He remains here to receive critical shipments and maintain communication with distant suppliers, though recent disruptions in Coldridge Pass have cut off deliveries and left him waiting anxiously for word.",al={"why is tannok in kharanos","why is tannok here","tannok frosthammer purpose"},it="why_here",add="eebd916b"}},ang={["race:Dwarf"]="As a dwarf leaving Anvilmar, carrying supplies to Tannok at Thunderbrew Distillery is one of your first steps into the heart of Dun Morogh.",["faction:Alliance"]="As an Alliance member, you can see how rising trogg attacks strain even heartland settlements like Kharanos."},kw={"anvilmar","coldridge","distillery","frosthammer","kharanos","tannok","thunderbrew","troggs"},rel={"quest:2160","npc:hands-springsprocket","subzone:thunderbrew-distillery","subzone:kharanos","subzone:coldridge-pass","subzone:coldridge-valley","subzone:anvilmar","topic:trogg"},src={"Tannok Frosthammer"}}
E["npc:tharek-blackstone"] = {t="npc",n="Tharek Blackstone",z="dunmorogh",s="At the forge in Kharanos, Tharek Blackstone makes and repairs tools for local craftsmen. His trade keeps him busy, so he hires travelers to carry finished crates to Beldin Steelgrill at Steelgrill's Depot.",h="At the forge in Kharanos, Tharek Blackstone makes and repairs tools for local craftsmen.",sec={{t="A Busy Toolsmith in Kharanos",b="Beldin's mechanostrider depot just outside town needs heavy wrenches, gears, and replacement tools. Tharek sends each crate there with a passing traveler, keeping deliveries moving while he stays at the forge. Craftsmen across Kharanos also rely on the tools he makes and repairs.",sp=0},{t="A Community Figure",b="Tharek has earned respect across Dun Morogh through his work at the anvil. He holds no military title, yet people in town turn to him for odd jobs, supply runs, and help coordinating local efforts.",sp=0}},faq={{q="Who is Tharek Blackstone?",a="Tharek Blackstone is a dwarven toolsmith in Kharanos, Dun Morogh. He makes and repairs heavy tools for local workers, and hires passing travelers to deliver supplies around the valley.",al={"tharek blackstone","who is tharek","blackstone dun morogh"},it="identity"},{q="What is his relationship with Beldin Steelgrill?",a="Beldin Steelgrill runs Steelgrill's Depot just east of Kharanos, where mechanostriders and siege engines are repaired. He is Tharek's main customer and orders so much ironware that Tharek often hires travelers to deliver finished shipments to the depot.",al={"tharek and beldin","steelgrill tools","why beldin"},it="ties"},{q="Where can I find Tharek Blackstone?",a="Tharek Blackstone stands outside near the center of Kharanos in Dun Morogh, within easy walking distance of the local inn and forge.",al={"tharek location","where is tharek blackstone","tharek blackstone loc"},it="place",gp=true},{q="Does Tharek hold any official rank in Ironforge?",a="Tharek holds no military commission or political office. He is a busy toolsmith who hires newcomers in need of coin to carry supplies for him.",al={"is tharek a leader","tharek authority","blackstone rank"}},{q="Whose side is Tharek Blackstone on?",a="Tharek is a loyal dwarf of Ironforge and stands firmly with the Alliance. Based in Kharanos, he serves his community through honest labor, outfitting local craftsmen and lending a hand to travelers and neighbors across Dun Morogh whenever troubles arise.",al={"tharek blackstone faction","who does tharek blackstone serve","tharek alliance"},it="side",add="cb940f84"},{q="What does Tharek Blackstone want?",a="Tharek mostly wants to keep up with his relentless workload. As a hardworking toolsmith, he is constantly swamped with orders—especially from demanding clients like Beldin Steelgrill. He looks for reliable travelers willing to run deliveries and take on odd jobs so he can keep his forge running smoothly.",al={"what does tharek want","tharek blackstone motive","why does tharek need help"},it="wants",add="eaa270fb"},{q="Why is Tharek Blackstone here in Kharanos?",a="Kharanos is the central hub for Dun Morogh's travelers and tradesfolk, making it the natural place for Tharek to set up shop. From here, he can supply nearby hubs like Steelgrill's Depot with essential gear.",al={"why is tharek in kharanos","tharek blackstone kharanos"},it="why_here",add="fa8e7e80"}},ang={["profession:Blacksmithing"]="For smiths passing through Kharanos, Tharek shows the daily work of a toolsmith, making sturdy wrenches and iron fittings for dwarven machinery.",["race:Dwarf"]="As a dwarf, you share Dun Morogh's working spirit. Local industry depends on people who keep at the anvil."},kw={"beldin","blackstone","dun morogh","kharanos","steelgrill","tharek","toolsmith"},rel={"npc:beldin-steelgrill","subzone:kharanos","subzone:steelgrill-s-depot","quest:400","quest:415","zone:dunmorogh","topic:dwarf","subzone:anvilmar"},src={"Tharek Blackstone"}}
E["npc:thorgas-grimson"] = {t="npc",n="Thorgas Grimson",z="dunmorogh",s="Inside Anvilmar in Coldridge Valley, Thorgas Grimson teaches new hunters to face Dun Morogh's frozen wilds. The seasoned outdoorsman trusts experience in the cold to teach survival.",h="Inside Anvilmar in Coldridge Valley, Thorgas Grimson teaches new hunters to face Dun Morogh's frozen wilds.",sec={{t="A Guide in the Cold",b="Inside Anvilmar, Thorgas Grimson guides new mountaineers and scouts. He leaves dry lessons behind and sends young hunters into the freezing winds. With bow or gun in hand, they track Dun Morogh's rugged beasts firsthand.",sp=0}},faq={{q="Who is Thorgas Grimson?",a="Thorgas Grimson trains hunters inside Anvilmar, Coldridge Valley's central outpost in Dun Morogh. He gives new Alliance hunters their first guidance and teaches basic field skills.",al={"thorgas grimson","who is thorgas","anvilmar hunter trainer"},it="identity"},{q="What training does Thorgas offer?",a="Thorgas teaches new hunters wilderness skills, from tracking beasts across snowy ground to improving their ranged marksmanship. He sets them on the path to becoming mountaineers.",al={"what does thorgas teach","hunter skills anvilmar"},gp=true},{q="What is his training philosophy?",a="Thorgas believes the wild teaches more than theory. Hunters must enter the freezing drifts and face Dun Morogh's beasts to master the wild.",al={"thorgas personality","how does thorgas train"},it="purpose"},{q="Will Thorgas Grimson speak with non-hunters?",a="Thorgas politely tells adventurers of other callings that he cannot train them. He advises them to seek a mentor suited to their path.",al={"can other classes talk to thorgas","thorgas gossip"},gp=true},{q="Whose side is Thorgas Grimson on?",a="Thorgas stands firmly with the Ironforge dwarves and the broader Alliance. Stationed at Anvilmar in Coldridge Valley, he devotes his skills to preparing novice hunters to defend the realm and safeguard dwarven lands from encroaching beasts and hostiles.",al={"thorgas grimson faction","thorgas grimson allegiance","who does thorgas grimson serve"},it="side",add="c3cc0970"},{q="What does Thorgas Grimson want?",a="Thorgas wants to mold green recruits into self-reliant, capable marksmen. He believes true skill cannot be taught merely through talk, seeking instead to push new hunters out into the snowy wilderness where real field experience can forge their tracking and combat instincts.",al={"thorgas grimson goals","what does thorgas want","thorgas grimson purpose"},it="wants",add="8eae34e9"},{q="Why is Thorgas Grimson in Anvilmar?",a="He is stationed at Anvilmar to guide newly recruited hunters stepping out into Coldridge Valley. With the valley cut off by harsh weather and threatened by troggs and wild beasts, seasoned trackers like Thorgas are needed to ensure new recruits learn to survive and fight.",al={"why is thorgas in anvilmar","thorgas grimson location why","why is thorgas grimson here"},it="why_here",add="d81e027b"}},ang={["class:Hunter"]="As a dwarf hunter, you may meet Thorgas Grimson as your first mentor. He offers early guidance in tracking beasts and surviving the freezing valley.",["race:Dwarf"]="As a dwarf, you share the hardy, self-reliant spirit of the Ironforge mountaineers who patrol Dun Morogh's frozen peaks."},kw={"anvilmar","coldridge valley","dun morogh","dwarf hunter","hunter trainer","thorgas grimson"},rel={"subzone:anvilmar","zone:dunmorogh","quest:3108","topic:dwarf"},src={"Thorgas Grimson"}}
E["npc:thorvald-deepforge"] = {t="npc",n="Thorvald Deepforge",z="dunmorogh",s="At the Valley of Kings, travelers bound for Loch Modan find Thorvald Deepforge ready with weapons. He helps defend the pass between Dun Morogh and Loch Modan.",h="At the Valley of Kings, travelers bound for Loch Modan find Thorvald Deepforge ready with weapons.",sec={{t="Arming the Eastern Pass",b="Thorvald Deepforge supplies weapons at the Valley of Kings. Troggs and roaming wildlife threaten the mountain passes between Khaz Modan's heartland and its outlying lands. Travelers from Dun Morogh and those bound deeper into Loch Modan can find blades and axes here, ready to defend dwarven lands.",sp=0}},faq={{q="Who is Thorvald Deepforge?",a="Thorvald Deepforge sells weapons at the Valley of Kings, where the road leaves Dun Morogh for Loch Modan. He supplies travelers and defenders along the border.",al={"who is thorvald","thorvald deepforge npc","deepforge loch modan"},it="identity"},{q="What role does he play in the region's defense?",a="Thorvald Deepforge supplies weapons to travelers crossing the mountain passes. He also helps arm recruits bound for outposts across Loch Modan.",al={"what does thorvald do","thorvald purpose","supplying the front"},it="why_here"},{q="Is he related to the other Deepforges in Khaz Modan?",a="Thorvald Deepforge may be related to other dwarves who share the Deepforge name, including Murgot and Bengus Deepforge, but no family tie is confirmed. Tormus Deepforge of the Great Forge calls Thorvald his colleague.",al={"deepforge family","thorvald deepforge relatives","murgot deepforge relative"},it="ties"},{q="Whose side is Thorvald Deepforge on?",a="Thorvald Deepforge is a loyal dwarf of Ironforge and stands firmly with the Alliance. Positioned at the Valley of Kings, he aids the Mountaineers and defends Khaz Modan by supplying weapons and equipment to local forces battling troggs and other threats.",al={"thorvald deepforge faction","thorvald deepforge alliance","who does thorvald serve"},it="side",add="7578ebb9"},{q="What does Thorvald Deepforge want?",a="Thorvald focuses on keeping Alliance defenders armed and ready. From his post at Loch Modan's southern guard tower, he keeps the Mountaineers fighting the troggs supplied with weapons and armor, and he welcomes smiths who bring new gear for the troops.",al={"thorvald deepforge goals","what does thorvald need","thorvald deepforge motive"},it="wants",add="2f5ea740"}},ang={["race:Dwarf"]="As a dwarf, you find Thorvald beneath the ancestral monoliths of the Valley of Kings, helping keep Khaz Modan's borders supplied and secure.",["profession:Blacksmithing"]="As a blacksmith, you know the Deepforge name and the reliable iron goods dwarven smiths are known for."},kw={"deepforge","dun morogh","loch modan","mountaineers","thorvald deepforge","valley of kings","weaponsmith"},rel={"subzone:valley-of-kings","zone:lochmodan","zone:dunmorogh","quest:1578","topic:dwarf"},src={"Thorvald Deepforge"}}
E["npc:thran-khorman"] = {t="npc",n="Thran Khorman",z="dunmorogh",s="At Anvilmar, Thran Khorman readies new warriors for the dangers of Coldridge Valley.",h="At Anvilmar, Thran Khorman readies new warriors for the dangers of Coldridge Valley.",sec={{t="Drillmaster of Coldridge Valley",b="Thran Khorman drills dwarven recruits and visiting gnomes on Anvilmar’s grounds. Gruff and demanding, he has little patience for anyone without the grit for front-line fighting. The Third War has ended, yet troggs still press into Coldridge Pass. So Thran demands relentless practice with axe, mace, and shield, keeping Ironforge’s defenders ready.",sp=0}},faq={{q="Who is Thran Khorman?",a="At Anvilmar in Dun Morogh, Thran Khorman trains warriors. He gives novice warriors their first combat instruction in Coldridge Valley.",al={"thran khorman role","who is thran","anvilmar warrior trainer"},it="identity"},{q="What training does he offer?",a="Thran teaches novice warriors stances and melee techniques. He prepares them to face troggs and wild beasts in the pass.",al={"what does thran teach","warrior skills thran"},gp=true},{q="Why is he dismissed or curt with certain travelers?",a="Thran has little patience for those who pursue arcane, shadow, or subtle arts. If you are not a warrior, he will tell you plainly that you would not survive a day under his training.",al={"why is thran rude","thran gossip","thran non warrior text"}},{q="Whose side is Thran Khorman on?",a="Thran Khorman stands proudly with Ironforge and the Alliance. Stationed at Anvilmar in Coldridge Valley, he dedicates his strength to drilling fresh dwarven and gnome recruits so Dun Morogh remains defended against any threat.",al={"thran khorman allegiance","thran khorman faction","who does thran serve"},it="side",add="97dd6db6"},{q="What does Thran Khorman want?",a="He wants prospective fighters to take martial discipline seriously and keep their battle skills razor-sharp. Even though the major wars have ceased for the moment, he refuses to let anyone grow soft, demanding rigorous commitment from every aspiring warrior.",al={"thran khorman goal","what does thran khorman care about","thran khorman motivation"},it="wants",add="1baa464c"},{q="Why is Thran Khorman here?",a="Thran is posted at Anvilmar to mold raw adventurers into disciplined warriors. Coldridge Valley serves as the proving ground for Ironforge's newest defenders, and he ensures no one ventures into Dun Morogh without knowing how to hold a blade and bear armor.",al={"why is thran khorman in anvilmar","what brings thran to coldridge valley","thran khorman purpose"},it="why_here",add="d4f40481"}},ang={["class:Warrior"]="As a dwarven or gnomish warrior awakening in Coldridge Pass, Thran is the first master to test your mettle. He gives you your starter runes or orders and teaches you the basics of martial survival.",["race:Dwarf"]="As a dwarf, you can see the stubborn resolve of Ironforge’s defenders in Thran. He keeps them ready even in peacetime, so the kingdom is never caught unprepared."},kw={"anvilmar","coldridge pass","dun morogh","ironforge","thran khorman","warrior trainer"},rel={"subzone:anvilmar","zone:dunmorogh","quest:3106","quest:3112","topic:dwarf"},src={"Thran Khorman"}}
E["npc:tormus-deepforge"] = {t="npc",n="Tormus Deepforge",z="dunmorogh",s="At Ironforge’s Great Forge, Tormus Deepforge keeps weapons flowing to the Alliance. He coordinates iron deliveries and arms defenses across Khaz Modan and beyond.",h="At Ironforge’s Great Forge, Tormus Deepforge keeps weapons flowing to the Alliance.",sec={{t="Master of the Great Forge",b="Beside the Great Forge fires, Tormus Deepforge oversees the Bronzebeard clan’s metalwork. He still hammers steel himself, though he mourns Sturgy Ironband, his mentor. Dark Iron dwarves overran Sturgy’s smithing compound south of Helm’s Bed Lake in eastern Dun Morogh. A load of strange umbral ore had arrived there.",sp=0}},faq={{q="Where can I find Tormus Deepforge?",a="Tormus stands on the circular walkway around the lava pool at the heart of Ironforge.",al={"tormus location","where is tormus","tormus deepforge map"},it="place",gp=true},{q="What role does Tormus play in the Alliance war effort?",a="At the Great Forge, Tormus forges weapons for young warriors who come to him. He asks them to avenge his mentor, Sturgy Ironband, by entering Ironband’s Compound in Dun Morogh and recovering the umbral ore the Dark Iron dwarves killed for. Tormus works the ore into new grey iron weapons.",al={"what does tormus do","tormus purpose","why talk to tormus"},it="purpose"},{q="Who are the other Deepforges?",a="Several dwarves share the Deepforge name, including Bengus, Murgot, and Kaita Deepforge, as well as Tormus’s colleague Thorvald in Loch Modan. Their relationships have never been confirmed.",al={"deepforge clan","deepforge family","is tormus related to murgot"},it="ties"},{q="Who is Tormus Deepforge?",a="Tormus Deepforge is a master dwarven blacksmith working at the Great Forge within Ironforge. Renowned for his skill at shaping iron and steel, he plays a crucial role in crafting equipment and managing shipments of armaments to support allied forces across the Eastern Kingdoms.",al={"who is tormus","tormus deepforge lore","who is deepforge"},it="identity",add="7c43f5fd"},{q="Whose side is Tormus Deepforge on?",a="Tormus is fiercely loyal to King Magni Bronzebeard and the Alliance. Stationed at the very heart of the dwarven capital, he dedicates his craft directly to ensuring Alliance soldiers and distant outposts receive the weapons and supplies they need to stand against their enemies.",al={"tormus deepforge faction","who does tormus serve","is tormus alliance"},it="side",add="43326af9"},{q="What does Tormus Deepforge want?",a="Tormus wants to forge fine weapons and to see his mentor, Sturgy Ironband, avenged. Dark Iron dwarves slaughtered everyone at Ironband's Compound in Dun Morogh after a load of strange umbral ore arrived there, and Tormus asks adventurers to strike back at them and bring him that ore so he can learn its properties.",al={"what does tormus want","tormus goals","tormus deepforge quests"},it="wants",add="6189f272"},{q="Why is Tormus Deepforge in Ironforge?",a="He plies his trade at the Great Forge, the industrial heart of Khaz Modan. There, alongside Ironforge's finest armorers and weaponsmiths, he commands the vast fires and anvils required to forge heavy arms for the kingdom's military efforts.",al={"why is tormus in ironforge","why is tormus here","tormus at the great forge"},it="why_here",add="14a6c7e2"}},ang={["profession:Blacksmithing"]="At the Great Forge, Tormus links raw bar stock to weapons for the front lines.",["race:Dwarf"]="As a dwarf, you see Tormus’s work reflect Ironforge’s readiness to smelt and deliver arms when allies in the Grand Alliance call for aid."},kw={"blacksmith","deepforge","dwarf","great forge","ironforge","lochinver","tormus"},rel={"subzone:great-forge","zone:ironforge","topic:dwarf","quest:1618","quest:1578","subzone:ironband-s-compound","zone:dunmorogh"},src={"Tormus Deepforge"}}
E["npc:veron-amberstill"] = {t="npc",n="Veron Amberstill",z="dunmorogh",s="At Amberstill Ranch in eastern Dun Morogh, Veron Amberstill raises the rams Ironforge riders trust.",h="At Amberstill Ranch in eastern Dun Morogh, Veron Amberstill raises the rams Ironforge riders trust.",sec={{t="Master of the Mounts",b="At Amberstill Ranch in eastern Dun Morogh, Veron Amberstill breeds and trains mountain rams. Their sure feet and thick coats carry them over Khaz Modan’s steep slopes and through its blizzards. Veron raises them for dwarven scouts, mountaineers, and traveling adventurers. He offers standard and swift mounts to fellow dwarves. Riders from other peoples must prove loyalty to Ironforge’s throne before he parts with a ram.",sp=0}},faq={{q="Who is Veron Amberstill?",a="Veron Amberstill breeds mountain rams at Amberstill Ranch in Dun Morogh. He raises sturdy mounts for Ironforge and sells them to qualified riders.",al={"veron amberstill","who is veron","amberstill ram vendor"},it="identity"},{q="Can non-dwarves purchase rams from Veron?",a="Yes. Dwarves can buy Veron’s rams. Riders from other peoples must earn an exalted reputation with Ironforge before he entrusts them with his herd.",al={"can humans buy rams","ram mount non dwarf","ironforge reputation ram"},gp=true},{q="Where is Veron Amberstill located?",a="You can find Veron outside Amberstill Ranch in the hills of eastern Dun Morogh, just north of Gol’Bolar Quarry.",al={"veron location","where is veron","where to find veron amberstill"},it="place",gp=true},{q="Why do dwarves ride rams instead of horses?",a="Mountain rams have thick coats, sturdy frames, and sure footing. Those traits suit Dun Morogh’s freezing winds and sheer rocky ledges better than ordinary horses.",al={"why do dwarves ride rams","dwarven mounts lore","mountain ram mount lore"}},{q="Whose side is Veron Amberstill on?",a="Veron Amberstill is firmly loyal to the dwarven kingdom of Ironforge and the Grand Alliance. He tends to the mountain rams that serve as the prized mounts of the dwarven people, supplying dependable steeds to his kin and trusted Alliance allies who have earned high standing in Ironforge.",al={"veron amberstill faction","is veron amberstill alliance","veron amberstill loyalty"},it="side",add="601a0646"},{q="Why is Veron Amberstill here?",a="Veron Amberstill manages Amberstill Ranch nestled in the windswept hills of Dun Morogh. The cold, rocky terrain provides ideal conditions for raising stout and hardy mountain rams, making the ranch the central hub for breeding and training these iconic dwarven riding beasts.",al={"why is veron amberstill in dun morogh","veron amberstill location reason","amberstill ranch purpose"},it="why_here",add="b4666b3f"},{q="What does Veron Amberstill want?",a="Veron Amberstill wants to protect his livelihood and maintain the ranch's prized stock of mountain rams. He focuses on breeding, rearing, and safeguarding his herds from the dangers prowling the snowy ridges of Dun Morogh, providing sturdy mounts to worthy riders.",al={"veron amberstill goal","what does veron want","veron amberstill purpose"},it="wants",add="8bafbe3f"},{q="Who is Veron Amberstill tied to?",a="Veron is tied to the Amberstill clan and the ranch that carries their family name. Together with his kin at the ranch, he oversees the care and breeding of the mountain rams that have served the dwarves of Dun Morogh for generations.",al={"veron amberstill family","who is veron related to","amberstill family"},it="ties",add="921d6dac"}},ang={["race:Dwarf"]="As a dwarf, you can see your people’s ties to mountain rams in the standard and swift mounts Veron raises for riders across Khaz Modan.",["faction:Alliance"]="As an ally of Ironforge, you must prove your dedication to the dwarven kingdom to earn Veron’s respect and ride a mountain ram."},kw={"amberstill ranch","dun morogh","ironforge","mount vendor","mountain ram","ram vendor","veron amberstill"},rel={"subzone:amberstill-ranch","zone:dunmorogh","zone:ironforge","topic:dwarf"},src={"Veron Amberstill"}}
E["quest:1578"] = {t="quest",n="Supplying the Front",z="dunmorogh",s="In Loch Modan, Mountaineers need fresh arms as trogg attacks threaten their defenses. Tormus Deepforge sends apprentice smiths east to supply them.",h="In Loch Modan, Mountaineers need fresh arms as trogg attacks threaten their defenses.",sec={{t="Arming the Mountaineers",b="Excavations have opened ruins and caverns across the border. Troggs now strike the Mountaineers without warning. Their lines need fresh blades, belts, and fittings to hold against the attacks.",sp=0},{t="The Deepforge Kinship",b="Tormus sends apprentices east while veteran smiths stay at Ironforge’s city forges. His colleague Thorvald Deepforge keeps a field armory in the southern guard tower. There, sturdy copper axes and copper chain belts prove a smith’s reliability and earn advanced smithing techniques.",sp=0}},faq={{q="Who offers this quest and what is required?",a="Tormus Deepforge, a blacksmith in Ironforge’s Great Forge, offers this work to apprentice smiths with a skill of at least thirty. You need to craft six copper axes and six copper chain belts.",al={"who gives supplying the front","quest starter","blacksmith quest requirements"},it="purpose",gp=true},{q="Where is Thorvald Deepforge located?",a="Thorvald Deepforge is inside Loch Modan’s southern guard tower. Follow the main road south past Thelsamar toward the Badlands border. The tower stands beside the mountain pass.",al={"where is thorvald","thorvald location","southern guard tower loch modan"},it="place",gp=true},{q="Why do the Mountaineers need so many copper supplies?",a="The Mountaineers in Loch Modan fight constant skirmishes with violent troggs. Combat quickly chips, dulls, and breaks their equipment, so they need a steady supply of basic weapons and chain armor.",al={"why do they need axes","what is the copper for"},it="motive"},{q="What relation is Thorvald to Tormus?",a="Tormus calls Thorvald his colleague. They share the Deepforge clan name and join Ironforge’s smithing strength to field defenses.",al={"are thorvald and tormus related","tormus colleague"},it="ties"},{q="What kind of reward does Thorvald offer?",a="Thorvald offers plans for new armor in thanks for easing the supply strain at the southern guard tower.",al={"quest reward","what does thorvald teach"},it="for_you",gp=true},{q="Why are the troggs such an issue in Loch Modan right now?",a="Dwarven excavations have opened subterranean vaults and hollows across Khaz Modan. The work accidentally awakened and unearthed swarms of aggressive troggs. They now threaten nearby settlements and watchtowers.",al={"why are troggs attacking","trogg problem loch modan"},it="threat"},{q="Why does Tormus Deepforge need more Copper Axes?",a="The Ironforge Mountaineers fighting in Loch Modan are engaged in nonstop skirmishes against the troggs. Weapons break quickly in constant battle, and Thorvald Deepforge desperately needs fresh armaments to ensure the defenders can maintain their front line.",al={"what are copper axes for","copper axe use supplying front","why copper axes"},it="item",add="0062256f"},{q="Why does Thorvald need Copper Chain Belts?",a="Trogg attacks are brutal and relentless, wearing down the Mountaineers' protective gear as fast as they can repair it. Thorvald relies on steady shipments of durable armor pieces like copper chain belts to keep the dwarven sentries properly protected in the southern passes.",al={"what are copper chain belts for","copper chain belt use","why copper chain belts"},it="item",add="c19cb0c2"},{q="Why does Tormus Deepforge ask an adventurer to help supply the front?",a="Thorvald is swamped trying to keep up with repairs at the front, and Tormus cannot abandon his own anvil in Ironforge. As a budding smith, forging the gear and carrying it east through the tunnels tests your craft while directly relieving the strain on the mountain guard.",al={"why me supplying front","why does tormus need me","why send an adventurer to thorvald"},it="why_me",add="f96d051f"}},ang={["profession:Blacksmithing"]="As a blacksmith, you prove your skill by making reliable copper weapons and armor for military use.",["race:Dwarf"]="As a dwarf, you help defend Loch Modan through your craft, alongside Mountaineers holding rifles.",["faction:Alliance"]="As an Alliance member, you help secure Khaz Modan’s border roads between Ironforge, Stormwind, and Alliance operations in the south."},kw={"blacksmithing","copper axe","copper chain belt","ironforge","loch modan","supplying the front","thelsamar","thorvald deepforge","tormus deepforge","troggs"},rel={"npc:tormus-deepforge","npc:thorvald-deepforge","zone:lochmodan","subzone:thelsamar","topic:trogg","zone:dunmorogh"},m={start="Tormus Deepforge",["end"]="Thorvald Deepforge",faction="Alliance",id=1578,ri={"Copper Axe","Copper Chain Belt"}},src={"Supplying the Front"}}
E["quest:1599"] = {t="quest",n="Beginnings",z="dunmorogh",s="In Dun Morogh, Alamar Grimm tests Alliance warlock novices before teaching them to summon an imp. First, they must take feather charms from Frostmane troll novices.",h="In Dun Morogh, Alamar Grimm tests Alliance warlock novices before teaching them to summon an imp.",sec={{t="A Reluctant Mentor",b="Influential voices have noticed a recruit with promise, and their attention draws Alamar Grimm from his occult research. Though reluctant, the warlock comes to assess the novice.",sp=0},{t="The Spark of Dark Magic",b="Before teaching a novice to enslave lesser demons, Grimm demands proof of endurance and magical affinity. Frostmane troll novices carry feather charms in a cave southwest of Anvilmar. Subtle primal magic runs through the charms, and taking them proves the novice can overcome a magical foe. The curious specimens also serve Grimm's research.",sp=0},{t="Summoning the Imp",b="The charms persuade Grimm that the novice has the will to survive. He teaches the summoning of an imp, a warlock's most basic minion. Its chaotic fire magic can overpower a master who lacks discipline.",sp=0}},faq={{q="Who gives the quest Beginnings?",a="Alamar Grimm gives the trial. He trains warlocks inside Anvilmar in Coldridge Valley, Dun Morogh.",al={"who starts beginnings","beginnings quest giver","alamar grimm location"},it="identity"},{q="What are the feather charms used for?",a="The feather charms prove an aspiring warlock can face and defeat magically adept enemies. These enchanted troll trinkets also give Alamar Grimm curious specimens for his research.",al={"why feather charms","feather charm purpose","frostmane charms"},it="item"},{q="Where are the Frostmane novices located?",a="Frostmane troll novices gather in a cave southwest of Anvilmar in Coldridge Valley. The Frostmane trolls have established a presence there.",al={"where are the troll novices","frostmane cave location","frostmane novice spot"},it="target",gp=true},{q="What reward does a warlock gain upon completing this task?",a="The trial earns Alamar Grimm's approval and teaches a warlock to summon an imp, their first demonic companion.",al={"what does beginnings teach","quest reward beginnings","imp spell quest"},gp=true},{q="Why is Alamar Grimm teaching new warlocks?",a="Influential voices take an interest in the fledgling warlock. Their attention persuades Grimm to pause his private occult studies and test and mentor the recruit.",al={"why does alamar train me","who told alamar to train me"},it="why_me"},{q="Is the imp dangerous for a novice warlock?",a="Yes. Alamar Grimm warns that an imp's small size hides volatile fel fire and cunning. An inexperienced summoner can easily be overpowered.",al={"imp danger","can imps kill you","imp warnings"}},{q="Why does Alamar Grimm want this done?",a="Alamar Grimm was persuaded to pause his own research and train you because notable patrons took an interest in your potential. Before teaching you to summon your first demon, an imp, he requires proof that you have the magical fortitude and physical mettle to survive it. Recovering the feather charms also serves his curiosity, offering curious troll magic for him to study.",al={"alamar grimm motive","why feather charms","why does alamar want feather charms"},it="motive",add="5dfeed0e"},{q="Who are the Frostmane novices you are sent against?",a="The Frostmane novices are young ice trolls practicing rudimentary magic in a cave southwest of Anvilmar. The indigenous Frostmane tribe is locked in conflict with the Ironforge dwarves across Dun Morogh, using nearby caverns to regroup and train their fledgling spellcasters.",al={"frostmane novices dun morogh","who are the frostmane novices","troll novices cave"},it="target",add="f653bf22"}},ang={["class:Warlock"]="As an Alliance warlock in Dun Morogh, you begin your craft by earning Grimm's approval and learning to summon your first demonic servant.",["race:Gnome"]="As a gnome warlock learning your craft in Coldridge Valley, you prove your intellect and command of magic by outsmarting the local Frostmane trolls."},kw={"alamar grimm","anvilmar","beginnings","coldridge valley","dun morogh","feather charm","frostmane novice","imp"},rel={"npc:alamar-grimm","subzone:anvilmar","zone:dunmorogh","topic:troll"},m={start="Alamar Grimm",level="4",faction="Alliance",id=1599,ri={"Feather Charm"}},src={"Beginnings"}}
E["quest:1654"] = {t="quest",n="The Test of Righteousness",z="dunmorogh",s="Jordan Stilwell has a sacred weapon in mind for a paladin worthy of the Light. The Ironforge smith needs rare materials from distant lands, including his lost family hammer.",h="Jordan Stilwell has a sacred weapon in mind for a paladin worthy of the Light.",sec={{t="A Sacred Commission",b="Outside Ironforge's gates, Jordan Stilwell cannot forge the paladin's weapon on his own. You gather the materials his craft demands.",sp=0},{t="Components of Consecration",b="Jordan Stilwell needs four things for the weapon: Whitestone Oak lumber, refined ore from master prospectors, a purified Kor Gem, and his smithing hammer. He left the hammer behind while escaping Shadowfang Keep. Finding all four means facing dangers across the Eastern Kingdoms and beyond.",sp=0},{t="The Smith's Heritage",b="Jordan Stilwell needs his father's hammer for the work. The heirloom is bound to his craft and family line. With the hammer recovered and a rare Kor Gem purified, Jordan can pursue plans he has carried for years and forge an instrument of justice.",sp=1}},faq={{q="What is the purpose of this quest?",a="Jordan Stilwell needs rare materials from across the realm to forge a holy weapon for rising paladins. Gathering them tests their devotion and sacrifice.",al={"what does this quest do","why do test of righteousness","test of righteousness goal"},it="purpose"},{q="Who is Jordan Stilwell?",a="Jordan Stilwell is a human weaponsmith outside Ironforge's gates in Dun Morogh. He plans a sacred weapon for paladins and seeks his father's lost smithing hammer.",al={"jordan stilwell lore","who is the smith outside ironforge","stilwell background"},it="identity"},{q="What materials are needed to forge the weapon?",a="Jordan needs Jordan's Smithing Hammer, Whitestone Oak Lumber, Bailor's Refined Ore Shipment, and a Purified Kor Gem.",al={"what items do i need","materials for jordan stilwell","test of righteousness ingredients"},it="item",gp=true},{q="Why is Jordan's hammer so important to him?",a="Jordan's hammer belonged to his father. Recovering this family heirloom returns it to Jordan's forge and gives him a tool tied to his craft and lineage.",al={"why his father hammer","jordans smithing hammer lore","stilwell hammer history"},it="ties"},{q="What is a Kor Gem?",a="A Kor Gem is a rare, potent stone. Purified of corrupting influences, it can focus the power used to consecrate a holy weapon.",al={"kor gem lore","what is kor gem","purified kor gem"},it="origin"},{q="Where does Jordan Stilwell craft this weapon?",a="Jordan Stilwell works just outside Ironforge's snowy gates in the mountains of Dun Morogh.",al={"jordan stilwell location","where is jordan","where do i turn this in"},it="place",gp=true},{q="Why does Jordan Stilwell want this done?",a="Jordan has harbored designs for a grand weapon of righteousness for a long time, but he lacked both the rare materials and the means to venture across the world to claim them. By entering an alliance with you, he finally has the chance to recover his family's lost hammer and craft his finest masterpiece to date, rewarding a champion of the Light in the process.",al={"jordan stilwell motive","why does jordan want these items","jordan stilwell why"},it="motive",add="c050f299"},{q="What is Jordan's Smithing Hammer for?",a="Jordan's Smithing Hammer is an heirloom passed down to Jordan Stilwell from his father. Jordan needs the trusted, familiar tool in his hands before he can undertake the intricate and exacting labor of forging your holy weapon.",al={"what is jordan's smithing hammer","jordan's smithing hammer purpose","why need jordan's hammer"},it="item",add="4a2d94b4"},{q="What is the Jordan's Refined Ore Shipment for?",a="This refined ore shipment provides the tempered metal needed to forge the head of your weapon. Ordinary iron cannot channel the sacred energies of a paladin, making high-grade refined ore essential to withstand both heavy combat and the Light itself.",al={"jordan's refined ore shipment use","what is the refined ore for","ore shipment jordan"},it="item",add="deb75c2f"},{q="What is the Whitestone Oak Lumber for?",a="Whitestone oak is a dense, exceptionally durable wood prized for crafting resilient hafts. Jordan requires this lumber to carve a sturdy handle capable of supporting the weighty forged head of the hammer without splintering under immense holy power.",al={"whitestone oak lumber use","why whitestone oak","whitestone lumber purpose"},it="item",add="a71ac5b5"},{q="What is the Purified Kor Gem for?",a="A Kor gem possesses an innate affinity for channeling magical and spiritual force. Once cleansed of dark taint and purified, the gem serves as a sacred focal point set into the weapon, allowing you to harness and project the Light through your strikes.",al={"purified kor gem use","what is the kor gem for","why purified kor gem"},it="item",add="ab9031e0"},{q="Why does Jordan Stilwell need you to gather the materials?",a="Jordan is a humble smith bound to his forge outside Ironforge, lacking the combat training and freedom to venture into hazardous lands across Azeroth. The items required are scattered in distant, dangerous places, demanding a skilled paladin of the Light capable of braving peril to recover them.",al={"why me jordan stilwell","why does jordan need help","why can't jordan get the ore"},it="why_me",add="c2f50c47"}},ang={["class:Paladin"]="As a paladin, you face a trial of devotion and sacrifice for a weapon forged to channel the Light.",["profession:Blacksmithing"]="As a blacksmith, you see Jordan Stilwell unite a reclaimed heirloom tool with purified arcane and mineral components to craft a holy relic.",["faction:Alliance"]="As a member of the Alliance, you rely on human craftsmanship and Alliance holdings across Khaz Modan and beyond to arm defenders against rising dark threats."},kw={"bailor's ore","dun morogh","ironforge","jordan stilwell","kor gem","paladin weapon","test of righteousness","whitestone oak"},rel={"npc:jordan-stilwell","quest:1653","quest:1655","quest:1442","zone:dunmorogh","zone:ironforge","topic:light","topic:alliance"},m={start="Jordan Stilwell",level="22",faction="Alliance",id=1654,ri={"Jordan's Refined Ore Shipment","Jordan's Smithing Hammer","Purified Kor Gem","Whitestone Oak Lumber"}},src={"The Test of Righteousness (2)"}}
E["quest:1681"] = {t="quest",n="Ironband's Compound",z="dunmorogh",s="At Ironband's Compound, Tormus Deepforge seeks vengeance for his slain mentor, Sturgy Ironband. Rare umbral ore drew the Dark Iron dwarves to the outpost and brought it down.",h="At Ironband's Compound, Tormus Deepforge seeks vengeance for his slain mentor, Sturgy Ironband.",sec={{t="A Master's Fall",b="South of Helm's Bed Lake, Sturgy Ironband taught smithing at a compound away from the Great Forge's crowded anvils. Promising pupils came there to train under a master revered across Ironforge as an unmatched instructor. Then one student acquired an unfamiliar mineral called umbral ore, and Sturgy chose to experiment with it. He did not know that its presence had marked his school for ruin.",sp=0},{t="The Dark Iron Raid",b="Soon after the umbral ore arrived, Dark Iron dwarves attacked the compound. They killed Sturgy Ironband and every apprentice in his care, then took over the grounds. Tormus Deepforge, one of Ironband's surviving protégés in the capital, refuses to let the massacre go unanswered. He sends Alliance travelers to avenge his teacher and recover the ore that brought destruction to the outpost.",sp=0}},faq={{q="Where is Ironband's Compound located?",a="Ironband's Compound lies in eastern Dun Morogh, south of Helm's Bed Lake.",al={"ironband location","where is compound","find ironband's compound"}},{q="Who was Sturgy Ironband?",a="Sturgy Ironband was a renowned dwarven master blacksmith who taught advanced metalworking at a compound outside Ironforge. Dark Iron dwarves killed him in a raid.",al={"who is ironband","sturgy ironband lore","who was sturgy"}},{q="Why did the Dark Iron dwarves attack the compound?",a="One of Ironband's students brought umbral ore to the compound, drawing the Dark Iron dwarves there. They attacked soon after it arrived, killed everyone present, and took control of the site.",al={"why attack","why dark iron raid","dark iron motive"}},{q="What is umbral ore?",a="Umbral ore is an uncommon, mysterious mineral that caught Master Ironband's interest. Its arrival drew the lethal attention of the Dark Iron clan.",al={"umbral ore lore","what is umbral","strange ore"}},{q="Who is Tormus Deepforge?",a="Tormus Deepforge is an Ironforge blacksmith and former apprentice of Sturgy Ironband. Grieving his teacher's death, he sends travelers to punish the Dark Iron intruders and retrieve the ore.",al={"who gives ironbands compound","tormus deepforge lore","who is deepforge"}},{q="What does Tormus want recovered from the compound?",a="Tormus wants travelers to avenge Ironband by driving out the Dark Iron raiders and recovering the shipment of umbral ore that brought the disaster.",al={"what to get","compound objective","quest turn in"}}},ang={["profession:Blacksmithing"]="Sturgy Ironband's fate shows the danger untested ores can bring to a forge.",["race:Dwarf"]="The attack on Ironband's outpost reflects the bitter hatred between Ironforge's Bronzebeard dwarves and their Dark Iron kin."},kw={"blacksmithing","dark iron","dun morogh","helm's bed lake","ironband's compound","sturgy ironband","tormus deepforge","umbral ore"},rel={"subzone:ironband-s-compound","npc:tormus-deepforge","subzone:helm-s-bed-lake","zone:dunmorogh","zone:ironforge"},m={level="11",id=1681},src={"In-game quest text: Ironband's Compound"},fv=true}
E["quest:170"] = {t="quest",n="A New Threat",z="dunmorogh",s="Balir Frosthammer calls for aid as Rockjaw troggs surge through Coldridge Valley and threaten its settlements and camps.",h="Balir Frosthammer calls for aid as Rockjaw troggs surge through Coldridge Valley and threaten its settlements...",sec={{t="Breaching Coldridge Valley",b="Rockjaw troggs claw up from below in growing numbers. Reports reach Anvilmar of troggs swarming the frozen lake and nearby foothills. They disrupt patrols and cut supply routes through the valley pass. For young dwarven warriors and mountaineers, this valley has long been a place to train. Now the threat reaches it.",sp=0},{t="A Camp Overrun",b="A coordinated trogg attack has overrun a dwarven camp west of the valley. The mountaineers retreated and left their posts. Ironforge cannot spare full battle regiments, so Balir Frosthammer calls on newly recruited adventurers to fight through the Rockjaw ranks. The hills must be secured before the creatures reach Anvilmar.",sp=0}},faq={{q="Who is Balir Frosthammer?",a="Balir Frosthammer is a seasoned dwarven mountaineer stationed outside Anvilmar in Coldridge Valley. He organizes defenses against wild beasts and troggs that threaten local recruits.",al={"balir frosthammer","who gives a new threat","frosthammer anvilmar"},it="identity"},{q="Why are troggs suddenly in Coldridge Valley?",a="Rockjaw troggs are tunneling up from deep fissures across Dun Morogh. Coldridge Valley is among the first populated valleys struck as the creatures break through and overrun surface camps.",al={"where did troggs come from","why troggs attacking","trogg invasion"},it="threat"},{q="What camp was overrun by the troggs?",a="Troggs overwhelmed a dwarven mountaineer camp in the western reaches of Coldridge Valley. The survivors fell back toward Anvilmar.",al={"overrun camp","western camp","where did troggs attack"},it="place"},{q="What kind of troggs are threatening the valley?",a="The attackers belong to the Rockjaw tribe. Standard Rockjaw Troggs and larger, sturdier Burly Rockjaw Troggs lead the advance around the frozen lake and foothills.",al={"rockjaw troggs","which troggs","burly rockjaw troggs"},it="target"},{q="Is King Magni aware of the trogg problem?",a="Local guards hope King Magni Bronzebeard and the Ironforge Senate are preparing a wider response. For now, frontier outposts like Coldridge Valley face the surges on their own.",al={"does magni know","ironforge response to troggs","ironforge senate troggs"},it="in_charge"},{q="What happens after culling these troggs?",a="Thinning the troggs helps steady Anvilmar's immediate surroundings. Balir and other dwarven officers continue to organize counterattacks to reclaim the western camp and drive the troggs underground.",al={"follow up quest","after a new threat","coldridge trogg questline"},it="next_step"},{q="Why does Balir Frosthammer want the troggs culled?",a="Coldridge Valley is under immediate siege. The troggs have not only infested the southern hills and the frozen lake, but just nights ago they violently overran the dwarven camp to the west. Balir needs their numbers thinned before the savage creatures push deeper into the valley and overwhelm Anvilmar entirely.",al={"why kill troggs","balir frosthammer motive","why does balir need troggs dead"},it="motive",add="54af52f4"},{q="Why does Balir Frosthammer need your help instead of the local guards?",a="The defenders at Anvilmar are dangerously shorthanded. The recent surprise attack on their western camp scattered their forces and left the garrison stretched thin trying to hold the settlement's perimeter. With no surplus soldiers to spare for an offensive counterattack, Balir must recruit any able-bodied adventurer who arrives.",al={"why me balir","why not use guards","why does balir need me"},it="why_me",add="3d273126"}},ang={["race:Dwarf"]="As a young Bronzebeard dwarf leaving Anvilmar, you have a personal duty to drive back the troggs and protect Dun Morogh's sacred grounds and tunnels.",["faction:Alliance"]="As an Alliance recruit, you help contain the threat from below in Coldridge Valley. That keeps Ironforge's training grounds viable and the southern mountain gate secure."},kw={"a new threat","anvilmar","balir frosthammer","burly rockjaw","coldridge valley","dun morogh","rockjaw trogg"},rel={"npc:balir-frosthammer","subzone:coldridge-valley","topic:trogg","zone:dunmorogh"},m={start="Balir Frosthammer",level="2",faction="Alliance",id=170},src={"A New Threat (Dun Morogh)"}}
E["quest:179"] = {t="quest",n="Dwarven Outfitters",z="dunmorogh",s="In Coldridge Valley, Sten Stoutarm offers new recruits a bargain. Hunt wolves for their tough meat, and he provides sturdy gloves against Dun Morogh's cold.",h="In Coldridge Valley, Sten Stoutarm offers new recruits a bargain.",sec={{t="A Fair Trade in Coldridge",b="Cold reaches every path through Coldridge Valley. Outside Anvilmar, Sten Stoutarm asks new recruits to hunt wolves in the snowy drifts and bring their tough meat to the outpost. In return, he gives them gloves to guard their hands from the cold.",sp=0},{t="Living Off the Valley",b="Wolves threaten the dwarven scouts and young gnomes training in the valley. Yet they also feed the garrison at Anvilmar. Hunting them makes the paths between local encampments somewhat safer. Stoutarm's bargain tests recruits against local wildlife and adds food for the bitter nights ahead.",sp=0}},faq={{q="Who is Sten Stoutarm?",a="Sten Stoutarm is a dwarf stationed outside Anvilmar in Coldridge Valley. He looks after newly arrived recruits and offers practical gear in return for hunting local game.",al={"sten stoutarm","who gives dwarven outfitters","anvilmar outfitter"},it="identity"},{q="Why does Sten need wolf meat?",a="Anvilmar's outpost relies on local hunting to keep its supplies stocked. Wolf meat feeds the troops and trainers who live in the secluded, snowbound valley.",al={"why wolf meat","tough wolf meat","what is the meat for"},it="motive"},{q="Where do you find the wolves for this task?",a="Wolves roam the snowy clearings throughout Coldridge Valley, especially beyond Anvilmar's main courtyard and along the paths to the outlying camps.",al={"where are wolves","wolf locations coldridge","where to get meat"},it="place",gp=true},{q="What reward does Sten provide?",a="Sten gives recruits a pair of warm gloves to guard their hands from Dun Morogh's bitter winds.",al={"dwarven outfitters reward","what gloves do you get","quest reward"},it="for_you",gp=true},{q="Is wolf meat considered good food among dwarves?",a="Wolf meat is tough, coarse, and chewy, but dwarves in Dun Morogh's harsh mountain climate prize hearty, filling food over fine dining. Stewed or roasted over a campfire, it feeds the garrison.",al={"is wolf meat tasty","dwarf wolf meat","eating wolf"},it="item"},{q="Can gnomes do this quest too?",a="Yes. Gnomes training alongside their dwarven allies in Coldridge Valley face the same biting winds and need warm clothing.",al={"gnome dwarven outfitters","can gnomes get gloves","gnome cold weather"},gp=true},{q="What are the wolves doing in Coldridge Valley?",a="Ragged young wolves and ragged timber wolves roam the frozen crags of Coldridge Valley as native predators. While they are a natural part of Dun Morogh's harsh mountain ecology, their aggressive prowling right outside Anvilmar makes them a constant nuisance to young recruits and a convenient source of fresh provisions for the outpost.",al={"why are there wolves here","coldridge valley wolves","wolf threat dun morogh"},it="target",add="cf6e8786"}},ang={["race:Dwarf"]="As a young Bronzebeard dwarf in Coldridge Valley, you learn to provide for the camp and respect the mountain cold.",["race:Gnome"]="As a gnome taking refuge with your dwarven cousins in Dun Morogh, you need practical mountain clothing to endure the cold at Anvilmar, along with a sharp mind."},kw={"anvilmar","coldridge valley","dun morogh","dwarven outfitters","frostbite","gloves","sten stoutarm","tough wolf meat"},rel={"npc:sten-stoutarm","zone:dunmorogh"},m={start="Sten Stoutarm",level="1",faction="Alliance",id=179,ri={"Tough Wolf Meat"}},src={"Dwarven Outfitters"}}
E["quest:1806"] = {t="quest",n="The Test of Righteousness",z="dunmorogh",s="At Jordan Stilwell’s forge outside Ironforge, you bring the materials for a paladin’s warhammer. Gathered across the Eastern Kingdoms and Kalimdor, they help turn an apprentice into a recognized champion of the Light.",h="At Jordan Stilwell’s forge outside Ironforge, you bring the materials for a paladin’s warhammer.",sec={{t="A Smith's Tribute",b="Jordan Stilwell works at his forge outside Ironforge’s gates. He envies paladins who wander the land, yet takes pride in serving their cause. You bring him rare materials gathered from shadowy crypts, sunken ruins, and dangerous mines. With them, the master smith keeps his promise and forges a weapon worthy of a true defender.",sp=0},{t="The Legacy of Bosch Verigan",b="Jordan Stilwell names the finished warhammer Verigan's Fist, for Bosch Verigan, an honored dwarven paladin and his dear friend. On behalf of himself and his wife, he places the sacred weapon in a young champion's hands. Through it, his fallen friend's memory and valor endure against the darkness threatening Azeroth.",sp=0}},faq={{q="What happens during this step of the quest?",a="Jordan Stilwell works the components you gathered at his anvil, striking hot metal in his forge. When the work is done, he presents you with the finished weapon.",al={"test of righteousness ending","jordan forging weapon","verigan cutscene"},gp=true},{q="Who is Bosch Verigan?",a="Bosch Verigan was an honored dwarven paladin and a close friend of Jordan Stilwell. Jordan named the newly forged two-handed hammer for him, honoring his devotion to the Holy Light.",al={"who is verigan","verigans fist namesake","bosch verigan"},it="people"},{q="Where does this forging take place?",a="Jordan Stilwell forges the hammer just outside Ironforge’s great gates in the snowy peaks of Dun Morogh. His forge and anvil are there.",al={"jordan stilwell location","where is the forge","dun morogh anvil"},it="place",gp=true},{q="Why did Jordan need rare materials from all over the world?",a="Jordan Stilwell needed rare materials from perilous places across the world to forge a weapon of exceptional balance and holy resonance. The ores, wood, and gemstones were needed to make a hammer that could endure a paladin's sacred wrath.",al={"why gathering materials","quest components test of righteousness"},it="why_wanted"},{q="Does Jordan Stilwell ever fight in battle himself?",a="Jordan Stilwell is a blacksmith, not a wandering warrior. He envies those who roam the land, but finds pride and purpose in crafting weapons for defenders of the Light.",al={"is jordan a warrior","jordan stilwell fighter"},it="identity"},{q="What does receiving this hammer signify for a paladin?",a="Receiving the hammer marks the end of a paladin's long trials. It shows the bearer has the courage, persistence, and holy conviction to champion the Light in Azeroth's most dangerous corners.",al={"verigans fist meaning","paladin rite of passage"},it="power"},{q="Why does Jordan Stilwell want to forge this hammer?",a="Jordan Stilwell admits to feeling a pang of envy seeing the daring exploits of champions across Azeroth, as he is a smith rather than an adventurer. By forging Verigan's Fist from the rare components you gathered, he can directly aid a defender of the Light and contribute to keeping the realm safe in his own vital way.",al={"jordan stilwell motive","why forge the weapon","why does jordan forge the hammer"},it="motive",add="49955bc3"}},ang={["class:Paladin"]="As a paladin, your perilous journeys across distant lands earn you Verigan's Fist, a weapon devoted to upholding righteousness.",["profession:Blacksmithing"]="As a blacksmith, you can see how Jordan Stilwell's masterful work gives raw steel and salvaged materials a holy purpose.",["race:Dwarf"]="As a dwarf, you carry a hammer forged to preserve the memory of Bosch Verigan, an honored dwarven paladin who embodied the resilience of Khaz Modan."},kw={"bosch verigan","dun morogh","forge","hammer","ironforge","jordan stilwell","paladin","test of righteousness","verigan"},rel={"npc:jordan-stilwell","topic:light","zone:dunmorogh"},m={start="Jordan Stilwell",level="22",faction="Alliance",id=1806},src={"The Test of Righteousness (3)"}}
E["quest:182"] = {t="quest",n="The Troll Cave",z="dunmorogh",s="In southern Coldridge Valley, Grelin Whitebeard sends you against Frostmane whelps settling in a cave. Their growing camp threatens nearby dwarven homesteads.",h="In southern Coldridge Valley, Grelin Whitebeard sends you against Frostmane whelps settling in a cave.",sec={{t="Eyes in the Cold",b="Grelin watches the frozen valley from a bluff as Ironforge's soldiers fight troggs across the snowfields. He and his brother Senir came on the mountain authorities' orders to learn whether the native ice trolls threatened the heartland. Now Grelin keeps watch alone, tracking their movements along the southern approaches.",sp=0},{t="A Preemptive Strike",b="Grelin found the local Frostmane clan settling in a deep cave along Coldridge Valley's southern ridge. He judges a full mobilization a waste of dwarven manpower, so he hires capable local volunteers to cull the aggressive whelps. Thinning the young fighters could disrupt the camp before the Frostmane launch coordinated raids against nearby dwarven homesteads.",sp=0}},faq={{q="Why doesn't Ironforge send regular soldiers to deal with these trolls?",a="The Ironforge Senate and military are stretched thin by the sudden, devastating trogg invasion across Dun Morogh. Scouts like Grelin Whitebeard hire independent adventurers to handle smaller threats, including troll warbands.",al={"why no dwarven army","where are the guards","why hire adventurers"},it="why_me"},{q="Who are the Frostmane trolls?",a="The Frostmane are an indigenous tribe of ice trolls from Dun Morogh's frigid crags. They have long clashed with Bronzebeard dwarves and mountaineers over hunting grounds, territory, and ancient mountain passes.",al={"frostmane clan","dun morogh trolls","who are the frostmanes"},it="target"},{q="Where is the troll cave located?",a="The cave lies along the southern mountain ridge of Coldridge Valley, south of Grelin Whitebeard's observation camp.",al={"troll cave location","where is the cave","where are the whelps"},it="place",gp=true},{q="Who is Grelin Whitebeard?",a="Grelin Whitebeard is an Ironforge scout stationed in Coldridge Valley. His brother Senir surveys other parts of Dun Morogh, while Grelin tracks hostile troll populations and reports to dwarven leaders.",al={"grelin","quest giver","whitebeard"},it="identity"},{q="Why does Grelin specifically target Frostmane whelps?",a="Grelin targets the Frostmane whelps because their settlement in southern Coldridge Valley is growing, with juvenile warriors among its members. Killing those young fighters may keep the band from growing strong enough to threaten dwarven supply lines.",al={"why whelps","why target young trolls"}},{q="What happens after culling the cave?",a="After you cull the cave, the trolls retaliate at night. They raid Grelin's campsite and steal his personal field journal, which you must recover from deeper in their dens.",al={"what next","troll cave follow up"},sp=1,it="next_step"},{q="Why does Grelin Whitebeard want the trolls dealt with?",a="Grelin and his brother Senir were dispatched across Dun Morogh to evaluate whether the native Frostmane trolls pose a serious threat to the realm. With Ironforge's Senate already overwhelmed by trogg uprisings elsewhere, Grelin hopes to nip this gathering in the bud before it escalates into a crisis that demands regular troops.",al={"why kill the trolls","grelin whitebeard motive","why clear the troll cave"},it="motive",add="9e422164"}},ang={["race:Dwarf"]="As a Bronzebeard dwarf, you face a threat to the frontier and an ancient mountain feud when you take up arms against Frostmane warbands.",["race:Gnome"]="As a gnome taking shelter in Dun Morogh after Gnomeregan's fall, you can lend your wits and weapons to help your dwarven hosts with threats around them.",["class:Hunter"]="As a hunter, you can use the crags around the southern cave as harsh proving grounds, flushing hostile quarry from the mountain heights."},kw={"coldridge valley","dun morogh","frostmane","grelin whitebeard","troggs","trolls","whelp"},rel={"npc:grelin-whitebeard","quest:218","quest:282","subzone:coldridge-valley","zone:dunmorogh","topic:troll","topic:trogg"},m={start="Grelin Whitebeard",level="4",faction="Alliance",id=182},src={"The Troll Cave"}}
E["quest:183"] = {t="quest",n="The Boar Hunter",z="dunmorogh",s="In Coldridge Valley, Talin Keeneye asks young recruits to thin the crag boars threatening the trails. Then seasoned hunters can track in peace.",h="In Coldridge Valley, Talin Keeneye asks young recruits to thin the crag boars threatening the trails.",sec={{t="A Crowded Valley",b="Coldridge Valley gives young mountaineers and Ironforge scholars a quiet, protected place to train. Through the harsh winter, small crag boars have multiplied across the valley. Their attacks now threaten everyone on the snowy trails.",sp=0},{t="Tending the Snows",b="Hunting gives dwarves meat, hide, and practice in the field. When game grows numerous and attacks on sight, culling restores balance. Thin the crag boars across the valley slopes, and young adventurers prove their readiness for combat. Local hunters gain room to track without being overwhelmed.",sp=0}},faq={{q="Who is Talin Keeneye?",a="Talin Keeneye is a dwarven hunter stationed in Coldridge Valley near Anvilmar. He tracks game in the snow and teaches novice adventurers to deal with hostile beasts.",al={"talin keeneye","who gives the boar hunter quest","boar hunter npc"},it="identity"},{q="Why are the crag boars such a problem?",a="Small crag boars have grown unusually numerous in Coldridge Valley, and they attack without provocation. Their numbers make travel and hunting dangerous for locals.",al={"why kill boars","boar problem coldridge","why are boars dangerous"},it="threat"},{q="Where can the crag boars be found?",a="Small crag boars roam the open snowy plains and lightly forested areas around Anvilmar, throughout Coldridge Valley.",al={"where are the boars","crag boar location","small crag boar map"},it="place",gp=true},{q="Does this quest connect to a larger threat in the valley?",a="No. Troggs trouble the dwarven outposts, but the crag boars are a local wildlife problem. Thinning their numbers keeps the footpaths safer and lets Talin hunt in peace.",al={"is there a follow up quest","boar hunter chain","story behind boars"},it="conflict"},{q="What makes crag boars suited to Dun Morogh?",a="Crag boars are tough, thick-hided swine that endure Dun Morogh's freezing temperatures. Their aggression and sharp tusks help them forage through frozen soil and defend themselves from mountain predators.",al={"crag boar lore","dwarf boars","dun morogh wildlife"},it="origin"},{q="Why doesn't Talin Keeneye kill the boars himself?",a="Talin says the aggressive boars have made his hunts unpleasantly dangerous. He asks eager newcomers passing through Anvilmar to thin their numbers so he can return to his usual tracking.",al={"why does talin need help","talin lazy","why can't talin hunt them"},it="why_me"},{q="Why does Talin Keeneye want the small crag boars culled?",a="Talin Keeneye considers boar hunting a fine pastime, but the sheer number of small crag boars infesting Coldridge Valley has ruined his sport. Their aggressive nature and explosive numbers have made his daily routine perilous rather than leisurely. By thinning out a dozen of the beasts, you restore some safety to the valley so he can enjoy his hunting without constantly being swarmed.",al={"why kill boars","talin keeneye motive","why does talin need boars dead"},it="motive",add="aa61ef91"},{q="What are small crag boars and why are they in Coldridge Valley?",a="Small crag boars are the hardy native swine of Dun Morogh, naturally equipped with thick hides and fierce tempers to survive the frigid mountainous terrain. Coldridge Valley provides ample foraging along the snowy foothills, but lately their population has surged so dramatically that they roam everywhere, aggressively charging anyone who draws near.",al={"what are crag boars","why are boars here","small crag boars lore"},it="target",add="cf0c4f7e"}},ang={["race:Dwarf"]="Mountain life means sharing the land with fierce wildlife. As a young dwarf, thinning the aggressive crag boars around Anvilmar is a rite of passage beyond the forge.",["class:Hunter"]="As a hunter, you can follow Talin Keeneye's plain approach to tracking: aim true, respect the beasts, and clear the brush when game turns hostile.",["race:Gnome"]="As a gnome refugee newly arrived from Gnomeregan, facing Dun Morogh's fierce wild boars is a hard introduction to life in rugged dwarf country."},kw={"anvilmar","boar hunter","coldridge valley","crag boar","dun morogh","hunting","talin keeneye"},rel={"subzone:coldridge-valley","zone:dunmorogh"},m={start="Talin Keeneye",level="3",faction="Alliance",id=183},src={"The Boar Hunter"}}
E["quest:1879"] = {t="quest",n="Speak with Bink",z="dunmorogh",s="Magis Sparkmantle sends you to Bink in Ironforge, where her studies need an arcane specialist.",h="Magis Sparkmantle sends you to Bink in Ironforge, where her studies need an arcane specialist.",sec={{t="A Colleague's Summons",b="Bink seeks someone who can wield magic and aid her work. Near Kharanos, Magis Sparkmantle sends apprentices who have outgrown their early exercises to answer Bink's call.",sp=0},{t="The Hall of Mysteries",b="In Ironforge's Mystic Ward, Bink studies in the Hall of Mysteries. Scholars, priests, and arcanists gather there. She watches each arriving apprentice closely, for raw potential without discipline can make a spellcaster dangerous in arcane work.",sp=0}},faq={{q="Who gives this quest?",a="Magis Sparkmantle sends novice Alliance mages from Dun Morogh to Bink once they have advanced beyond their early training.",al={"quest giver","where to start","who starts speak with bink"},it="identity"},{q="Where can I find Bink?",a="Bink is in the Hall of Mysteries, in the Mystic Ward in northern Ironforge.",al={"bink location","where is bink","find bink"},it="place",gp=true},{q="Why does Bink only want a mage?",a="Bink studies arcane energies and sensitive monitoring equipment. She believes non-mages cannot handle the magical details and dangers involved.",al={"why mages only","mage requirement","bink only wants mages"},it="motive"},{q="What happens after meeting Bink?",a="After greeting you and assessing your abilities, Bink asks you to help with her research, which continues with Mage-tastic Gizmonitor.",al={"next quest","bink follow up","what comes after speak with bink"},it="next_step"},{q="Is this quest available to classes other than mages?",a="No. Bink's call is for mages, taking them from local novice training to specialized work in the capital.",al={"can other classes do this","is this mage only","mage specific"},gp=true},{q="What is the Hall of Mysteries?",a="The Hall of Mysteries is Ironforge's center for arcane and holy study. Trainers, scholars, and researchers there represent the magical arts of dwarves and gnomes.",al={"ironforge hall of mysteries","what is hall of mysteries"},it="place"},{q="Why does Magis Sparkmantle send you to Bink?",a="Magis Sparkmantle is a gnome mage trainer stationed in Kharanos who serves as a mentor for rising spellcasters. His colleague in Ironforge, Bink, specifically sent word requesting an adept mage for an important undertaking. Recognizing your growing mastery over the arcane, Magis directs you into the dwarven capital to answer her call and further your magical training.",al={"why magis sends you","magis sparkmantle motive","why talk to bink"},it="motive",add="96ce9827"}},ang={["class:Mage"]="As a mage, you leave introductory valley training for the wider work of Ironforge's arcane scholars.",["race:Gnome"]="As a gnome, you find Bink and Magis Sparkmantle carrying on gnomish arcane tradition in Ironforge's welcoming halls after Gnomeregan's loss.",["faction:Alliance"]="As an Alliance member, you see gnomish intellect and dwarven hospitality joined in study at the Hall of Mysteries."},kw={"bink","dun morogh","hall of mysteries","ironforge","mage","magis sparkmantle","mystic ward"},rel={"npc:bink","npc:magis-sparkmantle","subzone:hall-of-mysteries","subzone:mystic-ward","zone:ironforge","zone:dunmorogh","topic:gnome"},m={start="Magis Sparkmantle",["end"]="Bink",level="10",faction="Alliance",id=1879},src={"Speak with Bink"}}
E["quest:2160"] = {t="quest",n="Supplies to Tannok",z="dunmorogh",s="Hands Springsprocket has inn supplies for Tannok Frosthammer, but troggs have made the pass unsafe. He asks you to carry the crate from Coldridge Valley to the Thunderbrew Distillery in Kharanos.",h="Hands Springsprocket has inn supplies for Tannok Frosthammer, but troggs have made the pass unsafe.",sec={{t="A Blockaded Valley",b="Troggs have overrun Coldridge Pass, making the route out of Coldridge Valley dangerous. Mountaineers are stretched thin guarding settlements and defenses, so supply escorts can be delayed for days. The inn's crate has no safe way through.",sp=0},{t="Hands and the Innkeeper's Assistant",b="Hands Springsprocket is a gnome tinkerer waiting at the pass, but he cannot carry the crate safely himself. You can take the supplies to Tannok Frosthammer, the assistant at the Thunderbrew inn in Kharanos.",sp=0},{t="A Welcoming Hearth in Kharanos",b="Tannok Frosthammer receives the supplies in Kharanos. He says word from Anvilmar has been scarce since troggs disrupted travel. Without the delivery, communication and trade between the two isolated dwarf communities remain fragile.",sp=0}},faq={{q="Who is Hands Springsprocket?",a="Hands Springsprocket is a gnome tinkerer waiting at the mouth of Coldridge Pass in Coldridge Valley. He asks travelers to carry goods to Kharanos because he cannot safely cross the pass alone.",al={"hands springsprocket","quest giver","who gives supplies to tannok"},it="identity"},{q="Who is Tannok Frosthammer?",a="Tannok Frosthammer is the assistant at the Thunderbrew Distillery in Kharanos. He receives provisions sent from places such as Anvilmar.",al={"tannok","tannok frosthammer","kharanos innkeeper assistant"},it="identity"},{q="Why can't Hands deliver the supplies himself?",a="Troggs have overrun the pass between Coldridge Valley and Kharanos, making travel dangerous. Mountaineer escorts are also delayed because they are spread thin guarding settlements and defenses.",al={"why can't hands deliver it","why need adventurer","why is the pass dangerous"},it="why_me"},{q="Where is the inn in Kharanos located?",a="The Thunderbrew Distillery is in the center of Kharanos, along the main road east toward Ironforge. Tannok Frosthammer is inside.",al={"where is tannok","thunderbrew distillery location","kharanos inn location"},it="place",gp=true},{q="What is inside the Crate of Inn Supplies?",a="The crate holds tavern supplies and provisions gathered in Anvilmar for the Thunderbrew inn in Kharanos.",al={"what is in the crate","crate of inn supplies"},it="item"},{q="Why is communication between Anvilmar and Kharanos cut off?",a="Troggs from subterranean tunnels have overrun Coldridge Pass. Their presence has disrupted foot travel and regular dispatches between Coldridge Valley and the rest of Dun Morogh.",al={"why scarce word from anvilmar","trogg problem pass"},it="threat"},{q="Why does Hands Springsprocket want the supplies delivered to Kharanos?",a="Hands Springsprocket promised vital provisions to Tannok Frosthammer, the assistant at the Kharanos inn, but trogg attacks have shut down travel through the pass out of Coldridge Valley. With regular shipments stranded and Mountaineer escorts days away, Tannok is left waiting and worrying with dwindling supplies. Hands wants to honor his delivery and ensure the bustling Thunderbrew Distillery and inn stay stocked for road-weary travelers.",al={"why send supplies to tannok","hands springsprocket motive","why deliver crate of inn supplies"},it="motive",add="6d15a4f4"}},ang={["race:Dwarf"]="As a dwarf, carrying supplies from Anvilmar to Kharanos takes you beyond the sheltered valley and into service to Ironforge.",["race:Gnome"]="As a gnome, helping Hands Springsprocket shows the cooperation between Gnomeregan exiles and their dwarven hosts in Dun Morogh.",["faction:Alliance"]="As an Alliance member, restoring trade between isolated outposts helps keep Ironforge’s inland supply lines moving despite trogg incursions."},kw={"anvilmar","coldridge pass","hands springsprocket","kharanos","supplies to tannok","tannok frosthammer","thunderbrew","troggs"},rel={"npc:hands-springsprocket","npc:tannok-frosthammer","subzone:kharanos","subzone:anvilmar","topic:trogg","zone:dunmorogh"},m={start="Hands Springsprocket",["end"]="Tannok Frosthammer",level="5",faction="Alliance",id=2160},src={"Supplies to Tannok"}}
E["quest:218"] = {t="quest",n="The Stolen Journal",z="dunmorogh",s="Grelin Whitebeard needs his stolen journal to finish judging the troll threat in Coldridge Valley. Grik'nir the Cold, leader of the Frostmane, carried it into the troll cave, leaving Grelin without most of his reconnaissance.",h="Grelin Whitebeard needs his stolen journal to finish judging the troll threat in Coldridge Valley.",sec={{t="A Scholar's Lost Notes",b="The Frostmane trolls have pressed into Coldridge Valley, and Grelin Whitebeard's notes track them. They record the trolls' habits and their sudden aggression. During the unrest, an imposing troll stole Grelin's personal journal and fled into the depths of the den. The journal holds most of his reconnaissance, so Grelin cannot finish his assessment until it is recovered.",sp=0},{t="Confronting Grik'nir the Cold",b="Grik'nir the Cold holds court in the heart of the valley's troll cave. Distinctive paint marks his body and face. Defeating this powerful Frostmane troll breaks the cave trolls' immediate leadership and secures Grelin's journal. With it returned, Grelin can finish his findings, judge the local troll situation manageable, and send his report to his brother Senir.",sp=0}},faq={{q="Who took Grelin Whitebeard's journal?",a="Grik'nir the Cold took Grelin Whitebeard's journal. The large Frostmane troll has strange markings on his skin and face, and lurks deep in the troll cave.",al={"who stole the journal","who has grelin's journal","journal thief"},it="target"},{q="Where can Grik'nir the Cold be found?",a="Grik'nir the Cold is inside the troll cave in the southern reaches of Coldridge Valley.",al={"where is griknir","grik'nir location","how to find grik'nir"},gp=true},{q="Why is the journal important to Grelin?",a="Grelin's journal holds his notes and findings on troll activity in Coldridge Valley. He needs it back to complete a report for his brother Senir.",al={"why does grelin want his journal","what is in grelin's journal"},it="item"},{q="What happens after you return the journal?",a="After you recover the journal, Grelin finishes his report on the troll situation in Coldridge Valley. He asks you to carry his findings to his brother Senir Whitebeard at Kharanos.",al={"what is next after the stolen journal","stolen journal next quest"},sp=1,it="next_step"},{q="Are the Frostmane trolls driven out of Coldridge Valley after this?",a="Grelin believes the troll situation in Coldridge Valley is under control after Grik'nir's defeat. The Frostmane remain a threat across Dun Morogh's broader mountain passes.",al={"are trolls defeated in coldridge","is coldridge safe from trolls"},it="conflict"},{q="Who is Senir Whitebeard?",a="Senir Whitebeard is Grelin's brother, an Alliance scout stationed outside Coldridge Valley near Kharanos. He gathers intelligence on threats facing the kingdom.",al={"who is senir","grelin brother senir"},it="ties"},{q="Why does Grelin Whitebeard want this done?",a="Grelin is compiling an official report on the Frostmane threat in Coldridge Valley for his brother Senir. Without his journal, he cannot complete his notes or assess the safety of the valley, leaving local leaders without crucial intelligence on troll activity.",al={"why does grelin want his journal","grelin whitebeard motive","why recover grelin's journal"},it="motive",add="78f0c4e3"},{q="Why does Grelin need you to retrieve his journal?",a="Grelin is an observer rather than a frontline fighter, and the journal was carried deep into the troll cave of Coldridge Valley by a formidable troll brute. Having already witnessed your success fighting back the trolls in the valley, he turns to you to delve into the cave and handle the danger.",al={"why does grelin need me","why send an adventurer for the journal","why can't grelin get his own journal"},it="why_me",add="beb6a987"}},ang={["race:Dwarf"]="As a dwarf, you help protect young recruits taking their first steps beyond Anvilmar. You break Frostmane leadership in Coldridge Valley.",["race:Gnome"]="As a gnome, you rely on the safety of Coldridge Valley's passes. Gnomish refugees shelter in Anvilmar and regroup in dwarven territory.",["faction:Alliance"]="As an Alliance member, you help keep Dun Morogh's starting valleys secure from disruption. You do so by suppressing the aggressive Frostmane tribe."},kw={"coldridge valley","dun morogh","frostmane hold","frostmane troll","grelin whitebeard","grik'nir the cold","senir whitebeard","stolen journal"},rel={"npc:grelin-whitebeard","quest:182","quest:282","subzone:coldridge-valley","zone:dunmorogh","topic:troll"},m={start="Grelin Whitebeard",level="5",faction="Alliance",id=218,ri={"Grelin Whitebeard's Journal"}},src={"The Stolen Journal"}}
E["quest:233"] = {t="quest",n="Coldridge Valley Mail Delivery",z="dunmorogh",s="At Anvilmar, Sten Stoutarm sends you west with mail for scouts beyond the frozen lake. Snow and nearby troggs can cut off the valley's defenders, leaving important news undelivered.",h="At Anvilmar, Sten Stoutarm sends you west with mail for scouts beyond the frozen lake.",sec={{t="A Courier in the Snow",b="Mail from across Dun Morogh reaches Anvilmar by mountain pass, where winter couriers leave it to gather. Sten Stoutarm tends supplies and security, so recruits carry the bundles down the western road. Without your help, important messages remain in the hall.",sp=0},{t="Frontier Outposts",b="Talin Keeneye watches the frozen lake west of Anvilmar for trogg movements and dangerous wildlife. Even at a cold outpost, news from Ironforge and the surrounding camps matters. Harsh mountain conditions make sorting mail difficult, so letters for different scouts can end up together in one bundle.",sp=0}},faq={{q="Who starts the mail delivery?",a="Sten Stoutarm gives you the delivery outside Anvilmar. Letters have just arrived through the mountain pass, but his duties keep him from carrying them himself.",al={"quest giver","who gives coldridge valley mail delivery","sten stoutarm quest"},gp=true},{q="Where is Talin Keeneye located?",a="Talin Keeneye is camped west of Anvilmar, beside the road near the frozen lake in Coldridge Valley.",al={"where is talin keeneye","talin keeneye location","finding talin keeneye"},gp=true},{q="Are all the letters in the stack actually for Talin?",a="No. Talin finds a letter for Grelin Whitebeard, who is stationed nearby in the valley.",al={"is the mail all for talin","grelin whitebeard letter","misplaced mail"},sp=1},{q="Why does Sten need an adventurer to run the mail?",a="Trogg incursions and local threats keep Sten and the other dwarven defenders busy with supplies and security. Travelers and recruits can carry letters to the outlying posts.",al={"why run mail","why doesnt sten deliver it","mail delivery duty"},it="why_me"},{q="Does this quest lead to other tasks?",a="Yes. After the delivery, Talin asks you to take the misdirected letter to Grelin Whitebeard, continuing the mail deliveries.",al={"next quest","mail chain","follow up to mail delivery"},sp=1,it="next_step",gp=true},{q="Where did the letters originally come from?",a="The letters came through the pass into Coldridge Valley, from the broader lands of Dun Morogh and Ironforge.",al={"where did mail come from","source of letters"},it="origin"},{q="Why does Sten Stoutarm want the letters delivered?",a="A fresh bundle of correspondence just arrived through the mountain pass, but Sten is tied down with his own duties at Anvilmar and cannot step away to run them out himself. Rather than let vital news and dispatches sit collecting dust while mountaineers out in the field wait for word, he relies on a helpful traveler to see them safely carried down the road.",al={"why deliver the letters","sten stoutarm motive","why send mail"},it="motive",add="bf556c8e"}},ang={["race:Dwarf"]="As a dwarf, carrying news between outposts helps keep Ironforge's far-flung valley scouts connected to their clans.",["race:Gnome"]="As a gnome living among allies in Dun Morogh after Gnomeregan's fall, carrying messages helps build trust with local dwarven defenders.",["faction:Alliance"]="As an Alliance member, you help keep Coldridge Valley's outposts connected, which matters for coordinating Dun Morogh's defense."},kw={"anvilmar","coldridge valley","dun morogh","grelin whitebeard","mail delivery","sten stoutarm","talin keeneye"},rel={"npc:sten-stoutarm","npc:grelin-whitebeard","subzone:coldridge-valley","zone:dunmorogh"},m={start="Sten Stoutarm",["end"]="Talin Keeneye",level="3",faction="Alliance",id=233},src={"Coldridge Valley Mail Delivery"}}
E["quest:234"] = {t="quest",n="Coldridge Valley Mail Delivery",z="dunmorogh",s="In Coldridge Valley, a dispatch travels from Talin Keeneye's post to Grelin Whitebeard's camp. You carry it down the southeastern road, keeping the mountaineers in touch with Ironforge.",h="In Coldridge Valley, a dispatch travels from Talin Keeneye's post to Grelin Whitebeard's camp.",sec={{t="A Link to the Mountain",b="Anvilmar is Coldridge Valley's center of rule. From there, field scouts and sentries carry dispatches along the trails between the high passes and Ironforge.",sp=0},{t="Word for Whitebeard",b="Grelin Whitebeard keeps a small camp southeast of Talin Keeneye's post. Veteran mountaineers at these remote watchpoints face freezing drifts and steady trogg harassment. Regular letters keep them abreast of affairs across Dun Morogh and the kingdom beyond.",sp=0}},faq={{q="Who is Grelin Whitebeard?",a="Grelin Whitebeard is a dwarven veteran at an outpost along Coldridge Valley's southeastern road. He watches the roads and guards against troggs and beasts.",al={"grelin","grelin whitebeard info","who is grelin"},it="identity"},{q="Where did this letter originate?",a="The letter came from Ironforge, the dwarven capital. Local runners and sentries carried it through Coldridge Valley and down the mountain passes to its recipient.",al={"where is letter from","ironforge letter","letter sender"},it="origin"},{q="Why is mail delivered by foot here?",a="Foot couriers carry mail through Coldridge Valley because the surrounding peaks cut it off from Dun Morogh's main roads. Trusted travelers and mountaineers bring dispatches by hand to the field camps.",al={"why foot courier","why run mail","no mailboxes in coldridge"},it="purpose"},{q="Where is Grelin Whitebeard's camp located?",a="Grelin Whitebeard's camp lies farther down the southeastern road through Coldridge Valley, past the hunting and scouting grounds of the upper pass.",al={"where is grelin camp","grelin whitebeard location","find grelin"},it="place",gp=true},{q="Who handed off the letter to deliver to Grelin?",a="Talin Keeneye, a hunter and scout stationed along the pass, handed you the letter. It came from the staging grounds near Anvilmar.",al={"who gave the letter","talin keeneye role","who starts quest"}},{q="What happens after Grelin receives his mail?",a="After Grelin receives news from Ironforge, he turns to the dangers in the valley. He often directs recruits against Frostmane trolls and troggs.",al={"what next after mail","grelin next quest","after mail delivery"},it="next_step"},{q="Why does Talin Keeneye want this done?",a="Talin Keeneye is stationed out in the cold along the road and knows Grelin Whitebeard has been waiting out at his camp without news. Having taken the dispatch from Anvilmar, Talin wants to ensure his fellow dwarf finally receives his correspondence from Ironforge rather than leaving him stranded and uninformed in the valley.",al={"why does talin need this delivered","talin keeneye motive","why send the letter to grelin"},it="motive",add="c573251b"},{q="Why does Talin Keeneye ask you to deliver the letter instead of taking it himself?",a="Talin Keeneye is stationed on watch along the road of Coldridge Valley, keeping an eye on the trails and local wildlife. Abandoning his post to hike all the way down to Grelin Whitebeard's camp would leave the pass unguarded, making a passing traveler like you the natural choice to carry the letter the rest of the way.",al={"why does talin need me","why cant talin deliver the letter","why me talin"},it="why_me",add="d47c3713"}},ang={["race:Dwarf"]="As a dwarf, you rely on dispatches from King Magni's seat in Ironforge to coordinate Dun Morogh's defenses.",["faction:Alliance"]="As an Alliance member, you rely on courier routes through snowy passes to carry orders and vital intelligence to remote scouts."},kw={"coldridge valley","courier","dun morogh","grelin whitebeard","ironforge","mail delivery","talin keeneye"},rel={"quest:233","npc:grelin-whitebeard","subzone:coldridge-valley","zone:dunmorogh","zone:ironforge"},m={start="Talin Keeneye",["end"]="Grelin Whitebeard",level="4",faction="Alliance",id=234},src={"Coldridge Valley Mail Delivery (2)"}}
E["quest:282"] = {t="quest",n="Senir's Observations",z="dunmorogh",s="Grelin Whitebeard sends you east to Kharanos with his report for his brother Senir. Troggs have overrun the tunnel from Coldridge Valley, where Mountaineer Thalos guards the way.",h="Grelin Whitebeard sends you east to Kharanos with his report for his brother Senir.",sec={{t="A Courier for the Whitebeards",b="Grelin Whitebeard's report tells of Frostmane troll activity around Coldridge Valley. The trolls stole his journal, and you recovered it. Grelin judged the findings too important for an inexperienced apprentice to carry. So he entrusts the report to you, to deliver directly to his brother Senir in Kharanos.",sp=0},{t="The Blocked Pass to Kharanos",b="Troggs have overrun the eastern tunnel from Coldridge Valley into the rest of Dun Morogh. Mountaineer Thalos guards the entrance to keep civilians from danger. He lets travelers through only when they carry urgent official business.",sp=0}},faq={{q="Who is Grelin sending this report to?",a="Grelin Whitebeard sends his report to his brother Senir Whitebeard in Kharanos, where Senir is assessing regional concerns.",al={"who gets report","senir whitebeard","report recipient"},it="purpose"},{q="Why can't Grelin's apprentice deliver the report?",a="Grelin planned to send his apprentice, but Frostmane trolls stole his journal. The findings were too important to entrust to inexperienced hands.",al={"why not apprentice","grelin apprentice"},it="why_me"},{q="Why is the tunnel out of Coldridge Valley guarded?",a="Troggs have overrun the tunnel from Coldridge Valley into Dun Morogh. Mountaineer Thalos guards the entrance to protect civilians until the way is clear.",al={"why thalos guarding","tunnel blocked","why is tunnel closed"},it="place"},{q="Where is Mountaineer Thalos located?",a="Mountaineer Thalos watches east of Anvilmar, near the tunnel entrance from Coldridge Valley toward Kharanos.",al={"thalos location","where is thalos","find mountaineer thalos"},it="target",gp=true},{q="What allows you to pass through the trogg-infested tunnel?",a="Mountaineer Thalos lets you through because you carry Grelin Whitebeard's urgent dispatch.",al={"pass through tunnel","tunnel permission"},it="item"},{q="What happens after speaking with Mountaineer Thalos?",a="Mountaineer Thalos warns you about the dangerous tunnel and guides you before letting you continue east toward Kharanos.",al={"next step","what after thalos"},it="next_step",gp=true},{q="Why does Grelin Whitebeard want this report delivered?",a="Grelin Whitebeard has been documenting the growing Frostmane troll activity and threats in Coldridge Valley. His brother, Senir Whitebeard, is stationed out in Kharanos gathering intelligence on wider troubles across Dun Morogh. Getting this report safely to Senir is vital for coordinating the defense of the region, especially now that the Frostmane are pushing closer to dwarven settlements.",al={"why send grelin report","grelin whitebeard motive","why deliver senirs observations"},it="motive",add="ba85e128"}},ang={["race:Dwarf"]="As a dwarven mountaineer or recruit, you pass through the eastern tunnel on your first official deployment beyond Coldridge Valley's training grounds.",["race:Gnome"]="As a gnomish refugee among the Bronzebeards, you can carry this dispatch from your first haven toward the troubles gripping Dun Morogh.",["faction:Alliance"]="You help keep passage between dwarven valleys secure, protecting Ironforge and Alliance couriers."},kw={"anvilmar","coldridge valley","grelin whitebeard","grelin's report","kharanos","mountaineer thalos","senir whitebeard","troggs","tunnel"},rel={"quest:218","npc:mountaineer-thalos","npc:grelin-whitebeard","subzone:kharanos","subzone:anvilmar","zone:dunmorogh","topic:trogg","quest:182"},m={start="Grelin Whitebeard",["end"]="Mountaineer Thalos",level="5",faction="Alliance",id=282},src={"Senir's Observations"}}
E["quest:287"] = {t="quest",n="Frostmane Hold",z="dunmorogh",s="Above Iceflow Lake, Frostmane trolls guard a cavern stronghold in the western peaks. Senir Whitebeard, a mountaineer and scout in Kharanos, sends you to scout its depths and bring back intelligence for his reports.",h="Above Iceflow Lake, Frostmane trolls guard a cavern stronghold in the western peaks.",sec={{t="A Scout Behind Schedule",b="Senir tracked the aggressive tribes to their main cavern southwest of Brewnall Village. Armed trolls crowd the entrance. Behind on his official reports, Senir will not enter alone, so he hires you to scout the icy cavern in his place.",sp=0},{t="Breaching the Cavern",b="Above Iceflow Lake, the stronghold is carved into the western peaks and packed with hostile ice trolls. You fight through underground tunnels, kill the Frostmane Headhunters stationed along the ledges, and map the interior. Your findings give Senir the intelligence he needs to complete his report for Ironforge's military commanders.",sp=0}},faq={{q="Where is Frostmane Hold located?",a="Frostmane Hold lies southwest of Brewnall Village, in a cavern on the far western side of Dun Morogh. From Kharanos, follow the road north to the bridge, then take the frozen river west past Iceflow Lake to Brewnall Village and climb southwest into the mountains.",al={"find frostmane hold","where is the cave","frostmane hold location"},it="place",gp=true},{q="Who is Senir Whitebeard?",a="Senir Whitebeard is a dwarven scout stationed outside the Thunderbrew Distillery in Kharanos. He tracks threats across Dun Morogh and writes reports on the aggressive Frostmane trolls.",al={"senir whitebeard","who gives quest","quest giver kharanos"},it="identity"},{q="Why didn't Senir explore the hold himself?",a="Senir scouted the entrance and found the tribe gathered there, but armed trolls filled the cave and he feared entering alone. Worried for his safety and running late on his scouting deadlines, he leaves the dangerous scouting to capable adventurers.",al={"why is senir scared","why didn't senir go"},it="why_me"},{q="Who are the Frostmane trolls?",a="The Frostmane are an ice troll tribe native to the snowy crags of Dun Morogh. Bitter enemies of the Ironforge dwarves and gnomes, they often raid trade routes, camps, and settlements from hidden encampments across the region.",al={"frostmane","trolls dun morogh","dun morogh trolls"},it="threat"},{q="What happens after completing the recon of the hold?",a="When you return with news of the cavern's layout and the headhunters killed, Senir finishes his report. He asks you to deliver the urgent papers to his superiors in Dun Morogh.",al={"next quest","what after frostmane hold","the reports quest"},sp=1,it="next_step",gp=true},{q="How deep into the cave do you have to go?",a="Explore beyond the entrance, scout the interior chambers, and slay five Frostmane Headhunters. Their deaths confirm that the cavern's depths have been thoroughly investigated.",al={"fully explore frostmane hold","cave exploration trigger"},gp=true},{q="Why does Senir Whitebeard want Frostmane Hold explored?",a="Senir Whitebeard is an operative working on intelligence reports regarding Dun Morogh's mounting threats. He fell behind on his scouting duties and needs firsthand information on the Frostmane troll encampment to complete his assessment for Ironforge command before his superiors take note.",al={"why does senir want this done","senir whitebeard motive","why scout frostmane hold"},it="motive",add="889a57f0"},{q="Why are you sent against the Frostmane Headhunters?",a="The Frostmane Headhunters form the militant defense of Frostmane Hold, the deep caverns southwest of Brewnall Village where the displaced trolls have massed in force. Killing them thins their patrols and clears a path to properly scout the cavern's depths.",al={"who are frostmane headhunters","why kill headhunters","frostmane headhunters purpose"},it="target",add="860fac70"}},ang={["race:Dwarf"]="As a dwarf, you know the Frostmane trolls contest Ironforge's hold over Dun Morogh's snowy peaks. Scouting their main cavern stronghold helps defend the realm.",["race:Gnome"]="As a gnome, you know that after Gnomeregan fell, gnomes settled across Dun Morogh and Kharanos. Curbing the Frostmane attacks helps keep refugee supply corridors safe.",["faction:Alliance"]="As an Alliance member, you help secure Dun Morogh and keep the mountain roads linking Ironforge to neighboring kingdoms free from hostile tribal ambushes."},kw={"brewnall village","dun morogh","frostmane headhunter","frostmane hold","ice trolls","iceflow lake","kharanos","senir whitebeard","the reports"},rel={"npc:senir-whitebeard","quest:291","subzone:kharanos","subzone:brewnall-village","subzone:iceflow-lake","zone:dunmorogh","topic:troll"},m={start="Senir Whitebeard",level="9",faction="Alliance",id=287},src={"Frostmane Hold (quest)"}}
E["quest:308"] = {t="quest",n="Distracting Jarven",z="dunmorogh",s="At Thunderbrew Distillery in Kharanos, Jarven Thunderbrew watches the cellar stores. His family forbids him to drink from the barrels while on duty, so he asks you to bring him Thunder Ale from upstairs. He hopes a mug will sharpen his wits.",h="At Thunderbrew Distillery in Kharanos, Jarven Thunderbrew watches the cellar stores.",sec={{t="A Thirsty Guard on Duty",b="Jarven watches the deep stores, with Dun Morogh’s finest stout all around him. His family forbids him to drink from the stock while he is on guard. Yet temptation gets the better of him, and he asks you to fetch a pint of potent Thunder Ale from the taps upstairs.",sp=0},{t="A Dubious Sharpener",b="Jarven says a good drink will sharpen his senses and strengthen his watch. Whether a guard ought to drink on duty is another matter. Still, few hardy dwarves can fault a Thunderbrew for wanting a taste of the ale his own kin make.",sp=0}},faq={{q="Who is Jarven Thunderbrew?",a="Jarven Thunderbrew belongs to the renowned Thunderbrew family. He watches the stored casks in the cellar of Thunderbrew Distillery in Kharanos.",al={"who is jarven","jarven lore","guard in cellar"},it="identity"},{q="Why does Jarven need someone to bring him ale?",a="Jarven's family forbids him to drink from the cellar stock while he is on watch. So he asks an outsider to bring him a fresh mug from upstairs, leaving the sealed casks untouched.",al={"why cant jarven drink","jarven ale quest","why fetch booze"},it="why_me"},{q="Where is Thunder Ale found?",a="The innkeeper and bartenders serve Thunder Ale upstairs in the main taproom of Thunderbrew Distillery in Kharanos.",al={"get thunder ale","where is thunder ale","buy thunder ale"},it="place",gp=true},{q="Where is the Thunderbrew Distillery located?",a="Thunderbrew Distillery is the central inn in Kharanos, in the snowy heart of Dun Morogh. It lies just down the mountain from Ironforge.",al={"kharanos distillery","thunderbrew cellar location","where is jarven"},it="place"},{q="Why is Thunderbrew ale so famous?",a="The Thunderbrew clan's stout and ales are famous across Khaz Modan and beyond. Their strong punch, flavor, and dwarven kick are known far and wide.",al={"thunderbrew reputation","what is thunder ale"},it="fame"},{q="Does getting Jarven drunk cause any trouble?",a="Jarven says the ale sharpens his wits instead of dulling them. But it keeps his attention from anyone poking around the lower storage.",al={"jarven drunk consequences","what happens after distracting jarven"},it="conflict"},{q="Why does Jarven Thunderbrew want a cask of Thunder Ale?",a="Jarven is stationed guarding the cellars surrounded by barrels of dwarven spirits, but strict orders forbid him from tapping into any of the stock in his care. Craving a drink to sharpen his wits and pass the long watch, he needs someone discreet to slip him a taste of Thunderbrew's finest brew so he can indulge without openly breaking discipline.",al={"why does jarven want ale","jarven motive","why jarven drink"},it="motive",add="a200e5d8"},{q="What is the Thunder Ale used for?",a="The cask of Thunder Ale serves as a potent personal refreshment to satisfy Jarven Thunderbrew's thirst. While on guard duty deep in the distillery cellars, he relies on you to fetch it from the taps above so he can drink without abandoning his post or tampering with the stored reserves.",al={"what is thunder ale for","thunder ale use","why get thunder ale"},it="item",add="8c39bfa0"}},ang={["race:Dwarf"]="As a dwarf, you know the agony of standing guard beside casks of legendary ale without a single swallow.",["class:Rogue"]="As a rogue, you know strong liquor can distract a watchman. Jarven asks for that distraction himself."},kw={"cellar","distillery","distracting jarven","dun morogh","jarven thunderbrew","kharanos","thunder ale"},rel={"zone:dunmorogh"},m={start="Jarven Thunderbrew",level="7",faction="Alliance",id=308,ri={"Thunder Ale"}},src={"Distracting Jarven"}}
E["quest:310"] = {t="quest",n="Bitter Rivals",z="dunmorogh",s="Marleth Barleybrew asks you to replace a cask of Thunder Ale at the Thunderbrew Distillery in Kharanos with her family's brew.",h="Marleth Barleybrew asks you to replace a cask of Thunder Ale at the Thunderbrew Distillery in Kharanos with...",sec={{t="A Taste of Competition",b="The Barleybrews have long begrudged the Thunderbrews the fame of their distillery. Marleth respects its ale, but she cannot abide Dun Morogh knowing only Thunderbrew. She means to change local tastes with her family's fiery Barleybrew Scalder.",sp=0},{t="Cellar Subterfuge",b="Beneath the Thunderbrew Distillery in Kharanos, aging casks fill a basement storeroom. A guard watches near the Thunderbrews' prized reserve. Draw him away, then secretly switch the barrels.",sp=0}},faq={{q="Who gives the quest Bitter Rivals?",a="Marleth Barleybrew gives you the work. She wants her family's brewing craft to rival the famed ale of the Thunderbrew Distillery.",al={"who starts bitter rivals","marleth quest starter"},gp=true},{q="Where is the Thunderbrew cellar located?",a="The cellar lies beneath the Thunderbrew Distillery in Kharanos. Its stairs are behind a table in the kitchen.",al={"where is thunderbrew basement","how to get to distillery cellar"},it="place",gp=true},{q="What is Barleybrew Scalder?",a="Barleybrew Scalder is Marleth Barleybrew's potent house ale. She hopes Kharanos patrons will recognize her skill when they taste it in place of Thunder Ale.",al={"barleybrew scalder","what brew do i swap"},it="item"},{q="How do you bypass the guard watching the barrels?",a="The Thunderbrew guard in the basement hints at what might draw his attention. Distract him, then use the chance to switch the barrels.",al={"cellar guard distraction","unguarded thunder ale barrel","guard barrel"},gp=true},{q="Why are the Barleybrews and Thunderbrews feuding?",a="The feud springs from dwarven pride in their craft. The Thunderbrews dominate Kharanos taverns, and the Barleybrews want to prove their recipes are just as good, or better.",al={"brewer feud","why barleybrew hate thunderbrew"},it="conflict"},{q="What quest follows Bitter Rivals?",a="After you place the cask of Barleybrew Scalder, you return to Marleth and report your success.",al={"next quest after bitter rivals","what comes after bitter rivals"},it="next_step",gp=true},{q="Why does Marleth Barleybrew want to switch the ale barrels?",a="Marleth Barleybrew is locked in a fierce, long-standing competition with the Thunderbrew clan over who crafts Dun Morogh's finest ale. While she begrudgingly admits that the Thunderbrews make a decent drink, she cannot stand their boasting and wants to prove that her own Barleybrew Scalder is superior. By slipping her keg into the Thunderbrew Distillery's cellar, she hopes their own loyal patrons will drink it, realize how good it is, and knock the Thunderbrews down a peg.",al={"why swap barrels","marleth motive","why switch the brew"},it="motive",add="6a423fcc"},{q="Why does Marleth Barleybrew need you instead of doing it herself?",a="Marleth is far too recognizable in Kharanos to wander into her rival's basement unnoticed. The Thunderbrew Distillery keeps a close watch on its cellar, and any appearance by a known Barleybrew would instantly raise an alarm. As an unfamiliar traveler, you can slip into the distillery, find a way past the cellar guard, and swap the barrels without immediately blowing the whole scheme.",al={"why cant marleth do it","why me bitter rivals","why hire an outsider"},it="why_me",add="41e8c9ba"}},ang={["race:Dwarf"]="As a dwarf, you know brewing carries prestige to rival blacksmithing. A feud over rival ales suits the snows of Dun Morogh.",["class:Rogue"]="As a rogue, you know how to slip into a guarded cellar, distract a sentry, and switch contraband. Here, the prize is beer instead of gold.",["faction:Alliance"]="As an Alliance traveler, you pass through Kharanos, Dun Morogh's cultural and logistical hub. Local disputes at the inn often draw recruits in."},kw={"barleybrew scalder","bitter rivals","dun morogh","kharanos","marleth barleybrew","thunder ale","thunderbrew distillery"},rel={"quest:311","npc:marleth-barleybrew","subzone:thunderbrew-distillery","subzone:kharanos","quest:117","zone:dunmorogh"},m={start="Marleth Barleybrew",["end"]="Unguarded Thunder Ale Barrel",level="6",faction="Alliance",id=310},src={"Bitter Rivals"}}
E["quest:3106"] = {t="quest",n="Simple Rune",z="dunmorogh",s="At Anvilmar, Sten Stoutarm brings new dwarven warriors a summons from Thran Khorman. The rune calls them from Coldridge Valley's snowy paths to begin training.",h="At Anvilmar, Sten Stoutarm brings new dwarven warriors a summons from Thran Khorman.",sec={{t="A Summons to the Anvil",b="Veteran scouts watch recruits clear pests around Coldridge Valley, seeking promising fighters. Sten brings an inscribed stone from Thran Khorman. Its simple rune calls them from the snowy paths into Anvilmar's warm forge-hall, where they can pledge themselves to the warrior's trade.",sp=0},{t="A Changing Dun Morogh",b="Thran speaks plainly about Dun Morogh's troubles. Gnomes displaced by the explosions that destroyed Gnomeregan seek refuge, while some dwarves take up foreign arcane arts or follow the human faith in the Holy Light. Troggs claw at the mountain borders after being disturbed deep underground. Thran believes firm martial discipline is needed to withstand these threats.",sp=0}},faq={{q="What is the Simple Rune?",a="Sten Stoutarm carries an inscribed slate on Thran Khorman's behalf. It invites new warriors to report indoors for training.",al={"simple rune item","what does the rune do","simple rune lore"}},{q="Who is Thran Khorman?",a="Thran Khorman trains warriors inside Anvilmar in Coldridge Valley. He teaches young dwarven and gnomish warriors melee combat, discipline, and dwarven tenacity.",al={"who is thran","thran khorman lore","warrior trainer coldridge"}},{q="Why are gnomes living in Dun Morogh and Ironforge?",a="Gnomes fled Gnomeregan after setting off catastrophic radiation explosives in a desperate attempt to repel a trogg invasion. The survivors sought refuge with their dwarven allies in Ironforge.",al={"why are gnomes here","gnomes in ironforge","gnomeregan refugees"}},{q="Why does Thran mention troggs?",a="Troggs are primitive, vicious creatures disturbed deep underground. They have recently breached the surface caves in Coldridge Valley and Dun Morogh, threatening settlements and trade routes. Anvilmar's defenders must stay armed and watchful.",al={"trogg threat","why are troggs around","coldridge troggs"}},{q="What does Thran mean about dwarves worshipping the Holy Light?",a="Some dwarves took up the Holy Light through close ties with human kingdoms such as Lordaeron and Stormwind. They now train their own paladins and priests.",al={"dwarves and holy light","dwarf paladins lore","dwarf priests"}},{q="Where do I take the Simple Rune?",a="Take the rune to Thran Khorman at the training grounds inside Anvilmar's great bunker hall, just up the path in Coldridge Valley.",al={"where to turn in simple rune","where is thran khorman","find thran"}}},ang={["class:Warrior"]="As a warrior, the rune marks your formal entrance into martial discipline and sends you to Thran Khorman in Anvilmar.",["race:Dwarf"]="As a dwarf, you can learn traditional grit from Thran Khorman. He teaches recruits to hold fast to their culture of steel and iron as the world changes.",["race:Gnome"]="As a gnome driven from Gnomeregan by troggs and radiation, you learn frontline warfare alongside dwarven mentors in Coldridge Valley to survive exile.",["faction:Alliance"]="As an Alliance member, you train in Coldridge Valley, where mountain forces defend the southern approaches to Khaz Modan."},kw={"anvilmar","coldridge valley","dun morogh","ironforge","simple rune","sten stoutarm","thran khorman","troggs","warrior"},rel={"npc:thran-khorman","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","topic:dwarf","topic:gnome","topic:trogg"},m={start="Sten Stoutarm",["end"]="Thran Khorman",level="1",faction="Alliance",id=3106},src={"Simple Rune (Classic)"}}
E["quest:3107"] = {t="quest",n="Consecrated Rune",z="dunmorogh",s="At Anvilmar, Bromos Grummner calls fledgling dwarven paladins to join the Knights of the Silver Hand. Sten Stoutarm summons them there.",h="At Anvilmar, Bromos Grummner calls fledgling dwarven paladins to join the Knights of the Silver Hand.",sec={{t="A Summons to Anvilmar",b="Your rune marks the start of a formal induction, where raw potential must meet discipline. Around Coldridge Valley, local leaders watch for those gifted in divine martial prowess. Bromos Grummner awaits inside Anvilmar to guide new initiates.",sp=0},{t="Dwarves and the Holy Light",b="The Knights of the Silver Hand began among the humans of Lordaeron, yet Ironforge dwarves embraced the Holy Light with fierce devotion. Bromos welcomes you into the brotherhood and reminds you that dwarven paladins share the solemn duty of protecting Azeroth. The order is grounded in sacrifice, tradition, and martial virtue, and asks recruits to take up hammer and faith in equal measure.",sp=0}},faq={{q="What is the Consecrated Rune?",a="The Consecrated Rune is an inscribed token Sten Stoutarm gives novice dwarven paladins in Coldridge Valley. It directs you to Bromos Grummner inside Anvilmar for formal training.",al={"consecrated rune item","what does the rune do","paladin rune coldridge"}},{q="Who is Bromos Grummner?",a="Bromos Grummner is the paladin trainer inside Anvilmar. He instructs new dwarven members of the Knights of the Silver Hand and prepares them for dangers threatening Dun Morogh.",al={"who is bromos","paladin trainer anvilmar","bromos grummner lore"}},{q="Why are dwarves part of the Knights of the Silver Hand?",a="During the Second War and its aftermath, human priests and paladins brought the teachings of the Holy Light to Ironforge dwarves. Dwarves respect the order's martial discipline and willingness to sacrifice for Azeroth's defense.",al={"dwarf paladin lore","why do dwarves have paladins","silver hand dwarves"}},{q="Who gives you the Consecrated Rune?",a="Sten Stoutarm gives you the rune outside Anvilmar after you help him with local tasks. He says Bromos Grummner asked him to deliver it.",al={"where do i get the rune","who hands you the rune"}},{q="Where is Bromos Grummner located?",a="Bromos Grummner is inside Anvilmar's great hall in Coldridge Valley, alongside the other class mentors.",al={"bromos location","where is bromos","find bromos grummner"}},{q="What happens after presenting the rune to Bromos?",a="After you present the rune, Bromos acknowledges your acceptance into the Silver Hand and offers your first formal combat and holy training. Then he sends you back into Dun Morogh.",al={"what comes next","after consecrated rune"}}},ang={["class:Paladin"]="As a paladin, this rune marks your first formal step into the Knights of the Silver Hand. Your duty is to channel the Light in defense of Ironforge.",["race:Dwarf"]="As a dwarf, you bring traditional dwarven fortitude together with theology taught by humans. Dwarven paladins bring steadfast resolve to the teachings of the Holy Light."},kw={"anvilmar","bromos grummner","coldridge valley","consecrated rune","holy light","paladin trainer","silver hand","sten stoutarm"},rel={"npc:bromos-grummner","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","topic:light","zone:dunmorogh"},m={start="Sten Stoutarm",["end"]="Bromos Grummner",level="1",faction="Alliance",id=3107},src={"Consecrated Rune (Classic)"}}
E["quest:3108"] = {t="quest",n="Etched Rune",z="dunmorogh",s="In Coldridge Valley, novice dwarf hunters receive a carved summons from Sten Stoutarm. It sends them to Thorgas Grimson inside Anvilmar to learn the hunt.",h="In Coldridge Valley, novice dwarf hunters receive a carved summons from Sten Stoutarm.",sec={{t="A Summons in Stone",b="As you help Sten Stoutarm face threats around Coldridge Valley, he gives you the Etched Rune. Dwarven mentors favor carved runes for formal messages, not spoken orders or plain parchment. The stone asks you to take stock of your early work, then report indoors at Anvilmar for deeper instruction in the hunt.",sp=0},{t="Traditions of the Dun Morogh Hunter",b="At Anvilmar, the Etched Rune marks a hunter's entry into formal discipline. Thorgas Grimson teaches that mountaineering and survival in Khaz Modan demand respect for the harsh land. You learn to read tracks in bitter snowdrifts, care for your weapons and ammunition, and understand the wild beasts roaming the crags. The rune marks your first step from a lone wanderer with a gun to an apprentice among Anvilmar's veteran pathfinders.",sp=0}},faq={{q="What is the Etched Rune?",a="The Etched Rune is an inscribed stone tablet that invites novice hunters in Coldridge Valley to seek formal training with Thorgas Grimson inside Anvilmar.",al={"what is etched rune","etched rune item","rune meaning"}},{q="Who sends the Etched Rune?",a="Thorgas Grimson sends the Etched Rune. Sten Stoutarm, a mountaineer, hands it to you after you prove your basic competence outside Anvilmar.",al={"who gave me etched rune","sender etched rune"}},{q="Where do I take the Etched Rune?",a="Bring the Etched Rune to Thorgas Grimson in the great hall inside Anvilmar, in Coldridge Valley.",al={"where do i go","who do i turn it in to","thorgas location"}},{q="Why do dwarves use runes instead of letters?",a="Dwarven culture values stonework, tradition, and enduring craft. Carved runes let messages and sacred instructions endure Dun Morogh's bitter winds and harsh elements better than fragile parchment.",al={"why an etched rune","dwarf runes lore"}},{q="What happens after presenting the rune to Thorgas Grimson?",a="Thorgas welcomes you into the ranks of dwarven trackers. He explains how to survive in the frozen crags, care for your gear, and respect wild beasts before offering training in basic hunter techniques.",al={"what does thorgas teach","turn in etched rune"}},{q="Can any class receive the Etched Rune?",a="Only dwarf hunters beginning their journey in Coldridge Valley receive the Etched Rune. Other classes receive distinct tokens directing them to their own mentors in Anvilmar.",al={"is etched rune hunter only","can warriors get etched rune"}}},ang={["class:Hunter"]="As a hunter, the Etched Rune begins your journey in Dun Morogh and introduces you to Thorgas Grimson and the dwarven traditions of tracking, weapon care, and wilderness survival.",["race:Dwarf"]="As a dwarf, you see the value placed on stonework, tradition, and enduring craft in the carved runes used for formal messages."},kw={"anvilmar","coldridge valley","dun morogh","dwarf","etched rune","hunter","sten stoutarm","thorgas grimson"},rel={"npc:thorgas-grimson","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh"},m={start="Sten Stoutarm",["end"]="Thorgas Grimson",level="1",faction="Alliance",id=3108},src={"Etched Rune (Classic)"}}
E["quest:3109"] = {t="quest",n="Encrypted Rune",z="dunmorogh",s="In Coldridge Valley, Sten Stoutarm gives young rogues a coded rune and calls them into Anvilmar to meet Solm Hargrin.",h="In Coldridge Valley, Sten Stoutarm gives young rogues a coded rune and calls them into Anvilmar to meet Solm...",sec={{t="A Message in Code",b="Sten says someone slipped him the etched stone to deliver. He suspects Solm Hargrin sent it. The rune tests whether a novice can keep a confidence, calling them inside without Solm announcing his need for scouts and scoundrels across the courtyard.",sp=0},{t="Under Anvilmar's Rafters",b="Inside Anvilmar, Solm Hargrin welcomes the new rogues to their craft. He offers to teach the maneuvers, strikes, and subtle arts that keep them alive and earn them coin. He also reminds dwarf rogues to look after their displaced gnomish allies, still recovering from Gnomeregan's catastrophic fall.",sp=0}},faq={{q="Who sends the Encrypted Rune?",a="Solm Hargrin, the rogue trainer in Anvilmar's great hall, writes the rune and has Sten Stoutarm pass it discreetly to promising recruits in the snow.",al={"who wrote the rune","encrypted rune sender","who gave sten the rune"}},{q="Where do I find Solm Hargrin?",a="Solm Hargrin is inside Anvilmar's main hall, the stone bastion at the center of Coldridge Valley in Dun Morogh.",al={"where is solm","solm hargrin location","find solm"}},{q="What is the purpose of this rune?",a="The rune summons novice rogues to decode its message and report to their trainer. He offers to teach them combat techniques and survival maneuvers.",al={"what does the rune do","encrypted rune purpose","why encrypted rune"}},{q="Why does Solm mention the gnomes?",a="Gnomeregan has recently fallen to disaster, and gnomish refugees share Coldridge Valley and Anvilmar with the dwarves. Solm reminds his students to support them as they settle into their temporary home.",al={"why help gnomes","solm gnomeregan comment"}},{q="Who gives the rune to the player?",a="Sten Stoutarm gives the stone to rogue adventurers in Coldridge Valley after they help him with local valley matters.",al={"who starts encrypted rune","quest giver encrypted rune"}},{q="Can other classes receive this rune?",a="No. The rune is for rogue initiates beginning their journeys in Coldridge Valley.",al={"is this quest rogue only","can warriors get encrypted rune"}}},ang={["class:Rogue"]="As a rogue, the rune brings you to Solm Hargrin. He offers to teach you stealth, martial tricks, and survival skills in Dun Morogh.",["race:Dwarf"]="As a dwarf of the Ironforge clan, Solm welcomes you into the shadows. A cold blade and darkness help keep you alive in Dun Morogh.",["race:Gnome"]="As a gnome, you hear Solm urge his students to stand by the gnomes sheltering in Coldridge Valley after the tragic loss of their home in Gnomeregan."},kw={"anvilmar","coldridge valley","dun morogh","encrypted rune","gnomeregan","rogue trainer","solm hargrin","sten stoutarm"},rel={"npc:solm-hargrin","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:gnomeregan","zone:ironforge"},m={start="Sten Stoutarm",["end"]="Solm Hargrin",level="1",faction="Alliance",id=3109},src={"Encrypted Rune (Classic)"}}
E["quest:311"] = {t="quest",n="Return to Marleth",z="dunmorogh",s="Marleth waits in Brewnall Village for the Thunder Ale you bring from Kharanos. The barrel will prove her Scalder reached the Thunderbrew cellar.",h="Marleth waits in Brewnall Village for the Thunder Ale you bring from Kharanos.",sec={{t="The Spoils of Sabotage",b="The barrel comes from the Thunderbrew cellar, taken under the distillers’ noses. It proves the switch worked and gives Marleth a trophy from her rival.",sp=0},{t="A Bitter Brew Settled",b="You carry the heavy keg over snowy ridges to Brewnall Village. Marleth delights in outsmarting Kharanos’s guards and cellar masters. Her caper shows how fiercely dwarven families prize their signature recipes.",sp=0}},faq={{q="What is the purpose of this quest?",a="You bring the stolen barrel of Thunder Ale to Marleth Barleybrew in Brewnall Village. It proves you planted her Scalder in the Kharanos cellar.",al={"what do i do","return to marleth objective","barrel turn in"},it="purpose"},{q="Who is Marleth Barleybrew?",a="Marleth is a dwarven brewer in Brewnall Village. She takes pride in her family's stout recipes and rivals the Thunderbrew distillers in Kharanos.",al={"who is marleth","marleth lore","barleybrew"},it="identity"},{q="Where is the barrel brought from?",a="You take the barrel from the Thunderbrew Distillery cellar in Kharanos after swapping Marleth's Scalder into their stocks.",al={"where did barrel come from","kharanos cellar","thunder ale location"},it="origin"},{q="Where is Brewnall Village?",a="Brewnall Village lies on the frozen banks of Iceflow Lake in western Dun Morogh, northwest of Kharanos.",al={"brewnall location","where is brewnall","how to find marleth"},it="place"},{q="Why is Marleth feuding with Kharanos?",a="Marleth wants to prove her Scalder can best or humiliate the celebrated Thunder Ale made by the Thunderbrews. Dwarven brewmasters compete fiercely over their recipes.",al={"why rivals","marleth vs thunderbrew","brewing feud"},it="conflict"},{q="What does Marleth do with the barrel?",a="The barrel proves the switch succeeded under the noses of the Kharanos guards. Marleth delights in keeping her rival's stock.",al={"why steal thunder ale","what happens to ale"},it="next_step"}},ang={["race:Dwarf"]="As a dwarf, you know brewing can be both an art and a contest of honor. Even cellar espionage can stir local pride.",["class:Rogue"]="As a rogue, you can test your stealth and sleight of hand by slipping into a guarded cellar and switching kegs in the snowy hills."},kw={"brewnall village","dun morogh","kharanos","marleth barleybrew","scalder","thunder ale","thunderbrew"},rel={"quest:310","npc:marleth-barleybrew","subzone:brewnall-village","subzone:kharanos","zone:dunmorogh"},m={start="Unguarded Thunder Ale Barrel",["end"]="Marleth Barleybrew",level="7",faction="Alliance",id=311},src={"Return to Marleth"}}
E["quest:3110"] = {t="quest",n="Hallowed Rune",z="dunmorogh",s="In Coldridge Valley, a young dwarf priest is called to Anvilmar by Sten Stoutarm. He carries Branstock Khalder’s inscribed prayers and guidance to the novice, who is summoned inside to deepen their bond with the Holy Light.",h="In Coldridge Valley, a young dwarf priest is called to Anvilmar by Sten Stoutarm.",sec={{t="A Calling to the Cloth",b="A young priest earns Sten Stoutarm’s notice while helping clear threats outside Anvilmar. Branstock Khalder, the settlement’s spiritual guide, gives Sten a rune inscribed with prayers and guidance for the novice. Then the young priest is called inside Anvilmar’s sturdy halls to begin sacred studies.",sp=0},{t="Defenders of Coldridge",b="Dwarven life prizes martial strength and heavy plate, yet the Holy Light remains central to Ironforge society. In Coldridge Valley, holy casters stand with warriors and hunters to protect the enclave from trogg incursions and dangerous wildlife moving through the snow.",sp=0}},faq={{q="What is the Hallowed Rune?",a="Sten Stoutarm gives the inscribed clerical rune on Branstock Khalder’s behalf. Its prayers introduce young priests to the faith and guide them toward formal training.",al={"what is hallowed rune","rune purpose"}},{q="Who is Branstock Khalder?",a="Branstock Khalder trains dwarven priests inside Anvilmar. His dry humor and steadfast faith guide new acolytes as he teaches the foundational Holy spells used to defend Coldridge Valley.",al={"branstock","priest trainer coldridge"}},{q="Where do I find Branstock Khalder?",a="Branstock Khalder is inside Anvilmar’s main stone lodge, in the central clearing of Coldridge Valley in Dun Morogh.",al={"branstock location","where is branstock"}},{q="Why do dwarves need priests in Coldridge Valley?",a="Troggs have overrun parts of the valley. Guards rely on priests to heal the wounded and wield the Light against their foes as they hold their lines.",al={"why dwarven priests","priests in anvilmar"}},{q="Can any class take this quest?",a="No. Only young dwarf priests beginning their journey in Coldridge Valley receive the Hallowed Rune.",al={"who can get hallowed rune","is this quest priest only"}},{q="Who delivers the rune to the player?",a="Sten Stoutarm delivers the rune. He is an Anvilmar mountaineer who oversees trials outside the lodge and gives it to you after you help defend the early valley.",al={"who starts hallowed rune","sten stoutarm role"}}},ang={["class:Priest"]="As a priest, this rune marks your formal recognition as a servant of the Holy Light in Dun Morogh and sends you to Branstock Khalder for your first spellcraft.",["race:Dwarf"]="As a dwarf, you join devotion to the Light with mountain grit and help hold Coldridge Valley against invading troggs."},kw={"anvilmar","branstock khalder","coldridge valley","dun morogh","dwarf priest","hallowed rune","sten stoutarm"},rel={"npc:branstock-khalder","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","topic:light","topic:trogg","zone:ironforge"},m={start="Sten Stoutarm",["end"]="Branstock Khalder",level="1",faction="Alliance",id=3110},src={"Hallowed Rune (Classic)"}}
E["quest:3112"] = {t="quest",n="Simple Memorandum",z="dunmorogh",s="In Coldridge Valley, gnome warriors receive a call to Anvilmar. Sten Stoutarm carries Thran Khorman’s summons to trained fighters, who are invited to learn the arts of war and prepare to reclaim Gnomeregan.",h="In Coldridge Valley, gnome warriors receive a call to Anvilmar.",sec={{t="A Summons to Anvilmar",b="You help Sten Stoutarm drive off troggs and boars in Coldridge Valley. Thran Khorman, a veteran trainer in Anvilmar, sees promise in the refugee recruit. He calls the recruit to the central hall for martial instruction.",sp=0},{t="A Pledge of Solidarity",b="Dwarven trainers may tease gnome warriors about their size, but Thran Khorman takes their loss seriously. He asks them to imagine how dwarves would feel if Ironforge fell to the Dark Irons. Thran has pledged to help the exiled gnomes. He teaches them the arts of war until they are ready to reclaim their home.",sp=0}},faq={{q="What is the Simple Memorandum?",a="In Coldridge Valley, Sten Stoutarm gives gnome warriors a note directing them to Thran Khorman, the warrior trainer in Anvilmar’s great hall.",al={"simple memorandum","what is this note","memorandum quest"}},{q="Who sends the memorandum?",a="Thran Khorman sends the memorandum through Sten Stoutarm to promising fighters helping the mountaineers.",al={"who wrote memorandum","who sent simple memorandum"}},{q="Why does Thran Khorman train gnome warriors?",a="Thran Khorman pledged to help the exiled gnomes. He respects their resolve and understands their loss. He compares Gnomeregan’s fall to Ironforge being conquered by the Dark Irons.",al={"why thran trains gnomes","gnome warrior lore"}},{q="Where do I find Thran Khorman?",a="You can find Thran Khorman inside Anvilmar’s main hall, in Coldridge Valley, Dun Morogh.",al={"where is thran khorman","thran khorman location"}},{q="Who is Sten Stoutarm?",a="Sten Stoutarm is a dwarven mountaineer outside Anvilmar in Coldridge Valley. He coordinates the defense against aggressive boars and invading troggs.",al={"sten stoutarm","who is sten"}},{q="Why are gnomes starting in Coldridge Valley?",a="After Gnomeregan fell and was irradiated, surviving gnomes fled as refugees into dwarven lands. Anvilmar and Ironforge have opened their doors to shelter them while they rebuild their forces.",al={"why are gnomes here","gnomes in coldridge"}}},ang={["class:Warrior"]="As a gnome warrior, you begin your combat education under the veteran arms masters of Ironforge.",["race:Gnome"]="As a gnome, you carry the memory of exile from Gnomeregan and the resolve to train soldiers who can reclaim your irradiated city.",["race:Dwarf"]="As a dwarf, you see Thran Khorman treat the gnomes’ plight with the same seriousness as dwarven feuds, showing solidarity with displaced allies."},kw={"anvilmar","coldridge valley","dun morogh","gnomeregan","simple memorandum","sten stoutarm","thran khorman","warrior trainer"},rel={"npc:thran-khorman","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:ironforge"},m={start="Sten Stoutarm",["end"]="Thran Khorman",level="1",faction="Alliance",id=3112},src={"Simple Memorandum (quest)"}}
E["quest:3113"] = {t="quest",n="Encrypted Memorandum",z="dunmorogh",s="In Coldridge Valley, Sten Stoutarm gives new gnome rogues a folded note for Solm Hargrin inside Anvilmar.",h="In Coldridge Valley, Sten Stoutarm gives new gnome rogues a folded note for Solm Hargrin inside Anvilmar.",sec={{t="A Discreet Introduction",b="As you help the mountaineers face trogg threats, Sten gives you a parchment entrusted to him. It looks like an official memorandum. The note invites you to meet Solm Hargrin, the rogue trainer stationed inside Anvilmar.",sp=0},{t="Shared Hardships in the Snow",b="Gnome survivors share close quarters with their dwarven hosts after Gnomeregan's sudden fall drove them from their underground home. Solm Hargrin knows rogues draw suspicion when items go missing. So he urges them to stand together quietly and help each other survive.",sp=0}},faq={{q="Who wrote the Encrypted Memorandum?",a="Solm Hargrin, the rogue trainer inside Anvilmar, wrote the note. He disguised it as an official directive from higher-ups so Sten Stoutarm would pass it on without suspicion.",al={"who sent memorandum","who wrote note","solm note"}},{q="Why is the memorandum disguised?",a="Solm Hargrin disguises the note to approach you discreetly in Anvilmar, a dwarven hold. He keeps a low profile to avoid rumors or accusations when gear goes missing, and uses coded greetings to reach fellow scoundrels.",al={"why disguised","why encrypted"}},{q="What does this note reveal about the situation in Dun Morogh?",a="The note describes the strain and solidarity between gnomes and dwarves after Gnomeregan's loss. Sharing space in Ironforge and Dun Morogh strains resources, so Solm urges those in the shadow trade to look out for one another.",al={"gnome dwarven relations","gnomeregan refugees dun morogh"}},{q="Who delivers the memorandum to the player?",a="Sten Stoutarm hands you the memorandum after you help him in Coldridge Valley. He assumes Solm Hargrin sent it for your training.",al={"sten stoutarm delivery","who hands note"}},{q="What role does Solm Hargrin serve?",a="Solm Hargrin trains rogues inside Anvilmar's mountain hall. He teaches new rogues combat techniques and shadowy talents.",al={"solm hargrin role","what does solm do"}},{q="Does this quest relate to Gnomeregan's fall?",a="Yes. Solm speaks of Gnomeregan being overrun and says displaced gnomish rogues can endure through their shared brotherhood, despite losing their mechanical homeland.",al={"gnomeregan fall lore","gnome refugee status"}}},ang={["class:Rogue"]="As a rogue, you receive your first call to meet Solm Hargrin. His message introduces the mutual protection needed to practice your covert trade in dwarven lands.",["race:Gnome"]="As a gnome, you see the hardship facing refugees after Gnomeregan's fall. Its survivors band together as guests among the dwarves.",["race:Dwarf"]="As a dwarf, you see mountaineers like Sten Stoutarm carry messages between Ironforge and the displaced gnomes in Coldridge Valley."},kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","gnomeregan","rogue trainer","solm hargrin","sten stoutarm"},rel={"npc:solm-hargrin","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:gnomeregan","zone:dunmorogh"},m={start="Sten Stoutarm",["end"]="Solm Hargrin",level="1",faction="Alliance",id=3113},src={"Encrypted Memorandum (quest)"}}
E["quest:3114"] = {t="quest",n="Glyphic Memorandum",z="dunmorogh",s="In Anvilmar, Mountaineer Sten Stoutarm gives you a memorandum from mage trainer Marryk Nurribit, who invites you to meet him.",h="In Anvilmar, Mountaineer Sten Stoutarm gives you a memorandum from mage trainer Marryk Nurribit, who invites...",sec={{t="A Missive for Novice Mages",b="The summons is for you, a novice mage Sten assists in Coldridge Valley. Read it, then go inside Anvilmar to meet the gnome who wrote it. Your spellcraft studies begin there.",sp=0},{t="Training with Marryk Nurribit",b="Inside Anvilmar, gnome mage trainer Marryk Nurribit offers plain advice before your lessons. Keep out of serious trouble and save coin for training and tavern drinks. Stay clear of fallen Gnomeregan and its radioactive danger. Marryk is ready to teach you the arcane arts.",sp=0}},faq={{q="Who delivers this memorandum?",a="After you help mountaineer Sten Stoutarm with his early duties in Coldridge Valley, he gives you the memorandum.",al={"who gives glyphic memorandum","sten stoutarm quest"}},{q="Who is Marryk Nurribit?",a="Marryk Nurribit is a gnome mage trainer inside Anvilmar in Coldridge Valley. He teaches new mages their early spells and how to practice the arcane arts safely.",al={"who is marryk","anvilmar mage trainer"}},{q="Where can I find Marryk Nurribit?",a="You can find Marryk Nurribit inside Anvilmar's main hall, at the top of Coldridge Valley in Dun Morogh.",al={"marryk nurribit location","where is the mage trainer in coldridge valley"}},{q="Why does Marryk warn against visiting Gnomeregan?",a="Troggs overran Gnomeregan, and a catastrophic release of radioactive gas contaminated the city. It is perilous for a novice wandering Dun Morogh.",al={"marryk gnomeregan warning","why stay away from gnomeregan"}},{q="What classes receive this task?",a="New mages beginning their studies in Coldridge Valley receive the memorandum to meet their class trainer.",al={"who gets glyphic memorandum","is this quest mage only"}},{q="What does Marryk expect from his students?",a="Marryk advises his students to stay out of trouble, save silver for spell training and an ale for him, and keep away from Gnomeregan.",al={"marryk expectations","what does the trainer want"}}},ang={["class:Mage"]="As a mage, you meet your first arcane trainer in Dun Morogh through this memorandum.",["race:Gnome"]="As a gnome, you can learn from Marryk Nurribit, one of the gnome specialists who took refuge in dwarven lands after Gnomeregan fell.",["faction:Alliance"]="As an Alliance member, you see dwarves and gnomes working together through Sten Stoutarm and Marryk Nurribit in Coldridge Valley."},kw={"anvilmar","coldridge valley","dun morogh","glyphic memorandum","mage trainer","marryk nurribit","sten stoutarm"},rel={"npc:marryk-nurribit","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:gnomeregan"},m={start="Sten Stoutarm",["end"]="Marryk Nurribit",level="1",faction="Alliance",id=3114},src={"Glyphic Memorandum (quest)"}}
E["quest:3115"] = {t="quest",n="Tainted Memorandum",z="dunmorogh",s="In Coldridge Valley, Sten Stoutarm quietly sends you to Alamar Grimm in Anvilmar. Grimm urges you to trust dark power over your dwarven hosts.",h="In Coldridge Valley, Sten Stoutarm quietly sends you to Alamar Grimm in Anvilmar.",sec={{t="A Discreet Summons",b="Warlocks face deep suspicion in Coldridge Valley. As you help Sten Stoutarm with local threats, he reluctantly slips you a note. His warning makes plain how little your kind is trusted here, even under the uneasy truce that allows warlocks to practice in Alliance lands.",sp=0},{t="Gnomish Bitterness in Exile",b="In Anvilmar, Alamar Grimm speaks of the gnomes’ plight. He believes ordinary magic and tinkering failed Gnomeregan, bringing their people near extinction and leaving them as second-class refugees dependent on dwarven goodwill. He urges you to trust neither the Holy Light nor dwarven politics. Instead, summon fiends and master them, for their obedience is unconditional.",sp=0}},faq={{q="What is the Tainted Memorandum?",a="The Tainted Memorandum is a written message Sten Stoutarm gives novice gnome warlocks in Coldridge Valley. It directs them to seek Alamar Grimm, the warlock trainer in Anvilmar.",al={"tainted memo","warlock note dun morogh","what is the memorandum"}},{q="Why are warlocks distrusted in Coldridge Valley?",a="Dwarves and their Alliance allies prize martial honor and the Holy Light. They regard demonology and shadow magic as corrupt and dangerous, so gnome warlocks face deep suspicion.",al={"why don't dwarves like warlocks","warlock prejudice anvilmar"}},{q="Who is Alamar Grimm?",a="Alamar Grimm is a gnome warlock trainer in Anvilmar. Bitter over Gnomeregan’s fall and the gnomes’ dependence on dwarven charity, he teaches young gnomes to bind demonic minions and claim power for themselves.",al={"alamar grimm lore","who is alamar"}},{q="Why does Grimm criticize normal magic and technology?",a="Grimm believes conventional engineering and accepted schools of magic failed the gnomes in the disaster at Gnomeregan. He says this left them dependent on dwarf patrons who put ties with humans ahead of reclaiming the gnome homeland.",al={"grimm gnomeregan view","why dark magic over engineering"}},{q="Can dwarf warlocks receive this quest?",a="No. In Dun Morogh, only gnomes can practice the warlock path, so the summons is for newly arrived gnome practitioners.",al={"dwarf warlock tainted memorandum","can dwarves be warlocks"}},{q="Where does this quest take place?",a="You begin near Sten Stoutarm in Coldridge Valley and finish inside Anvilmar, the central redoubt overlooking the valley in southwestern Dun Morogh.",al={"where is alamar grimm","tainted memorandum turn in"}}},ang={["class:Warlock"]="As a warlock, you receive a missive marking your formal entry into the craft. It presents demonic pacts as a practical choice born of survival, not madness.",["race:Gnome"]="As a gnome, you may share the resentment some exiles feel over losing their home and depending on Ironforge.",["race:Dwarf"]="As a dwarf, you see your people tolerate these dark practitioners under their roof with obvious distaste and sharp wariness."},kw={"alamar grimm","anvilmar","coldridge valley","dun morogh","gnome warlock","gnomeregan exile","sten stoutarm","tainted memorandum"},rel={"npc:alamar-grimm","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","topic:light","topic:human","quest:1599"},m={start="Sten Stoutarm",["end"]="Alamar Grimm",level="1",faction="Alliance",id=3115},src={"Tainted Memorandum (quest)"}}
E["quest:312"] = {t="quest",n="Tundra MacGrann's Stolen Stash",z="dunmorogh",s="Tundra MacGrann needs his winter stores back from Old Icebeard. The yeti carried off the thorium-reinforced meat locker, and MacGrann's injured leg keeps him from reaching the cave.",h="Tundra MacGrann needs his winter stores back from Old Icebeard.",sec={{t="Winter Stores and Stolen Lockers",b="For the cold season, MacGrann had salted away a month's worth of dried meat. He sealed it in a thorium-reinforced locker to keep hungry bears out. Old Icebeard carried off the whole chest instead of trying to open it.",sp=0},{t="Old Icebeard's Den",b="While MacGrann was away hunting deer, Old Icebeard dragged the chest to a cave in the jagged hills. MacGrann believes the yeti cannot break through solid thorium, but his injured leg keeps him from retrieving the stores. You can face the beast or slip inside while it prowls the snowdrifts.",sp=0}},faq={{q="Who is Tundra MacGrann?",a="Tundra MacGrann is a dwarven hunter who lives in the snowy reaches of Dun Morogh. His injured leg leaves him reliant on his stored provisions for winter.",al={"tundra macgrann","macgrann","who is macgrann"},it="identity"},{q="Who stole MacGrann's meat locker?",a="Old Icebeard, a local yeti, stole MacGrann's meat locker while the hunter was away hunting deer. The beast dragged it into its mountain cave.",al={"who stole the stash","who took the meats","stolen stash thief"},it="target"},{q="Why can't MacGrann get his meats back himself?",a="MacGrann's injured leg keeps him from moving quickly or quietly enough to enter Old Icebeard's cave and escape safely.",al={"why cant macgrann get it","macgranns leg","bum leg"},it="why_me"},{q="Did the yeti eat the food?",a="No. The dried meat remains locked inside a solid thorium chest. Old Icebeard carried it away but cannot break through the metal.",al={"is the food eaten","can icebeard open the chest"}},{q="Do you have to fight Old Icebeard to get the meat locker?",a="You can slip into the cave while Old Icebeard is out prowling and retrieve the locker without fighting him.",al={"can you sneak past icebeard","do i have to kill icebeard"},gp=true},{q="Where is the stolen stash located?",a="The stolen meat locker is deep inside Old Icebeard's mountain cave, in the hills near MacGrann's camp in Dun Morogh.",al={"where is the cave","icebeard cave location"},it="place",gp=true},{q="Why does Tundra MacGrann need his meat locker recovered?",a="MacGrann spent long days hunting and salting an entire month's worth of rations to survive the harsh Dun Morogh cold season. Without those preserved meats, he faces starvation in his remote mountain camp once the winter flurries roll in, as his injured leg prevents him from hunting enough game to replenish his winter stores in time.",al={"why help tundra macgrann","macgrann motive","why retrieve the meat locker"},it="motive",add="ceb049bb"},{q="What is MacGrann's Dried Meats?",a="It is a heavy reserve of salted venison and game that Tundra MacGrann cured specifically to outlast the mountain winter. He locked the meat inside a reinforced thorium locker to keep scavenging bears from sniffing it out, which luckily proved durable enough to keep Old Icebeard from tearing into it as well.",al={"macgranns dried meats","what is macgrann's dried meats","macgrann meat locker contents"},it="item",add="9ce729b1"}},ang={["class:Hunter"]="As a hunter, you know how much work it takes to preserve meat. MacGrann lost his stores to a beast while he was out tracking deer.",["race:Dwarf"]="As a dwarf, you know how harsh a mountain winter can be. Without preserved meat or shelter, even a seasoned mountaineer may not withstand the cold.",["class:Rogue"]="As a rogue, you can slip into Old Icebeard's cave while he is away and take the locker without drawing a blade."},kw={"dried meats","dun morogh","meat locker","old icebeard","stolen stash","thorium","tundra macgrann","yeti"},rel={"zone:dunmorogh"},m={start="Tundra MacGrann",level="12",faction="Alliance",id=312,ri={"MacGrann's Dried Meats"}},src={"Tundra MacGrann's Stolen Stash"}}
E["quest:313"] = {t="quest",n="The Grizzled Den",z="dunmorogh",s="At Steelgrill's Depot near Kharanos, Pilot Stonegear sends you west to hunt wendigos in the Grizzled Den. Their thick pelts will warm his siege engine, Trollplow.",h="At Steelgrill's Depot near Kharanos, Pilot Stonegear sends you west to hunt wendigos in the Grizzled Den.",sec={{t="A Test of Grit",b="Stonegear tests newcomers before he trusts them with the work. A massive siege tank is hard to operate in freezing mountain air. It takes nerves of iron and a steady constitution. Face the native beasts in the frozen hills to prove you have both.",sp=0},{t="Creature Comforts in Trollplow",b="Dun Morogh's bitter cold bites through Trollplow's cramped, iron-plated cabin. Stonegear wants thick wendigo manes for a warm, durable rug on the engine's deck. The hunt also helps keep the local beasts in check.",sp=0}},faq={{q="Who is Pilot Stonegear?",a="Pilot Stonegear is a dwarven siege engine driver stationed outside Kharanos in Dun Morogh. He pilots Trollplow, an armored war machine, and takes pride in his iron nerves and mechanical trade.",al={"pilot stonegear","who gives quest","who is stonegear"},it="identity"},{q="Where is the Grizzled Den located?",a="The Grizzled Den lies in the snow-covered mountains directly west of Kharanos. Its caves shelter Dun Morogh's vicious wendigos.",al={"grizzled den location","where is wendigo cave","how to find grizzled den"},it="place",gp=true},{q="Why does Stonegear want wendigo manes?",a="Stonegear wants wendigo fur for a warm rug on Trollplow's interior deck. Gathering the pelts also tests an adventurer's bravery.",al={"why wendigo manes","purpose of manes","what are manes for"},it="motive"},{q="What is Trollplow?",a="Trollplow is Pilot Stonegear's personal dwarven siege engine. Its name reflects the conflict between Ironforge dwarves and the hostile Frostmane trolls in the surrounding crags.",al={"trollplow","stonegear tank","what is trollplow"},it="identity"},{q="What kind of creatures inhabit the Grizzled Den?",a="Savage wendigos inhabit the Grizzled Den. These feral, ape-like beasts are native to Dun Morogh's snowy heights and fiercely defend their territory.",al={"monsters in grizzled den","what lives in grizzled den"},it="residents"},{q="Are the wendigos dangerous to Kharanos?",a="Wendigos rarely organize attacks like the Frostmane trolls. Yet their violent ferocity and nearness to the main roads put travelers and local tradesfolk at risk.",al={"are wendigos a threat","wendigo danger"},it="threat"},{q="What are the Wendigo Manes used for?",a="Pilot Stonegear wants the thick, shaggy manes of the Grizzled Den's wendigos for a very practical dwarf luxury: interior decorating. Operating a massive siege engine like Trollplow in Dun Morogh's biting chill leaves the metal deck freezing underfoot. Stonegear plans to stitch the harvested manes together into a warm, heavy rug to make Trollplow's cabin much cozier during long patrols.",al={"wendigo mane use","what is wendigo mane for","why wendigo manes"},it="item",add="9edb896b"},{q="Why does Pilot Stonegear send you instead of getting the manes himself?",a="Stonegear is a siege engine pilot, and keeping an iron machine like Trollplow maintained and ready for defense in Kharanos demands his full attention. Hunting agile, ferocious wendigos inside tight, frozen cavern passages isn't work suited for a massive war machine. Stonegear also treats the task as an open challenge to see if you have the grit, mettle, and nerve required of Dun Morogh's defenders.",al={"why me stonegear","why does stonegear need help","why not get manes himself"},it="why_me",add="72b90979"}},ang={["race:Dwarf"]="As a young Mountaineer or Ironforge adventurer, facing the wendigos of the Grizzled Den is a local rite of passage.",["profession:Engineering"]="If you appreciate dwarven siege craft, you know heavy machinery needs clever ways to stay warm in sub-zero weather.",["race:Gnome"]="Living beside the dwarves around Kharanos means you can help equip Ironforge's heavy armored engines."},kw={"dun morogh","grizzled den","kharanos","pilot stonegear","trollplow","wendigo","wendigo mane"},rel={"subzone:grizzled-den","npc:pilot-stonegear","subzone:kharanos","zone:dunmorogh"},m={start="Pilot Stonegear",level="7",faction="Alliance",id=313,ri={"Wendigo Mane"}},src={"The Grizzled Den (quest)"}}
E["quest:314"] = {t="quest",n="Protecting the Herd",z="dunmorogh",s="At Amberstill Ranch, Rudra Amberstill fears Vagash will take more prized mountain rams. He asks passing fighters to protect the herd and bring proof of the predator’s death.",h="At Amberstill Ranch, Rudra Amberstill fears Vagash will take more prized mountain rams.",sec={{t="A Threat to the Ranch",b="Vagash has taken two prized mountain rams from Amberstill Ranch. The ranch supplies the Bronzebeard dwarves with riding and working beasts, and the herd supports Dun Morogh’s rustic economy. Vagash hunts local livestock in the crags above the ranch.",sp=0},{t="Strained Defenses",b="Ironforge’s forces are spread thin across the realm, supporting the Alliance on distant frontiers. With no military patrol on the ridgelines, Rudra Amberstill asks independent fighters to hunt Vagash. He wants one of the beast’s deadly fangs as proof.",sp=0}},faq={{q="Who is Vagash?",a="Vagash is a dangerous predator that stalks the snowy ridges above Amberstill Ranch. His strength and vicious appetite threaten the ranch’s prized rams and travelers in eastern Dun Morogh.",al={"what is vagash","vagash monster","vagash lore"},it="target"},{q="Where can Vagash be found?",a="Vagash makes his den in a snow-covered cave high in the crags above Amberstill Ranch. Climb the snowy hill beyond the pine trees behind the homestead to reach its mouth.",al={"vagash location","where is vagash","find vagash"},it="place",gp=true},{q="Why are the Ironforge guards not handling this?",a="Ironforge’s forces are spread thin across distant garrisons and Alliance campaigns. Amberstill Ranch has no nearby military help, so its breeders must defend the homestead or seek capable fighters.",al={"why no guards","where is ironforge army","why help amberstill"},it="why_me"},{q="Who is Veron mentioned by Rudra?",a="Veron Amberstill breeds, trains, and tends the Bronzebeards’ riding rams at the ranch. Rudra says Veron will be relieved when the predator stalking their prized animals is gone.",al={"who is veron","veron amberstill","veron"},it="people"},{q="Why is proof of the kill required?",a="Rudra wants Vagash’s fang as proof that the monster terrorizing the herd is dead, not some common prowler from the mountain slopes.",al={"why vagash fang","fang of vagash","what is the proof"},it="why_wanted"},{q="What importance do the rams have to Dun Morogh?",a="Mountain rams are hardy and sure-footed across Khaz Modan’s freezing, rocky ground. They provide the dwarves with draft power, wool, and cavalry mounts.",al={"why are rams important","amberstill ram purpose","dwarf rams lore"},it="ties"},{q="Why does Rudra Amberstill want this done?",a="Rudra Amberstill is defending her family's livelihood. The Amberstill ranch breeds and tends the sturdy mountain rams prized throughout Dun Morogh and Ironforge. Vagash has begun prowling close to the homestead, creeping in under cover of darkness to slaughter the livestock. With two prized rams already dragged away in a single night, the ranch cannot survive ongoing raids from such a vicious predator.",al={"why does Rudra want Vagash dead","rudra amberstill motive","why kill vagash"},it="motive",add="81b569d0"},{q="What is the Fang of Vagash for?",a="The fang serves as undeniable physical proof that the feared beast has truly been slain. Vagash is infamous around the ranch for his size and ferocity, and Rudra Amberstill needs absolute certainty that the predator stalking the crags above is dead before she and her family can rest easy about their surviving herd.",al={"why need fang of vagash","fang of vagash purpose","vagash tooth"},it="item",add="34abe682"}},ang={["race:Dwarf"]="As a dwarf, you can help defend the mountain rams that carry your kin into battle across Khaz Modan.",["class:Hunter"]="As a hunter, tracking Vagash to his mountain den tests your skill in Dun Morogh’s snowdrifts.",["faction:Alliance"]="As an Alliance fighter, you can aid rural homesteads while High Seat regiments support Alliance commitments across the Eastern Kingdoms."},kw={"amberstill ranch","dun morogh","ironforge","mountain rams","protecting the herd","rudra amberstill","vagash","veron amberstill"},rel={"zone:dunmorogh","zone:ironforge","topic:alliance"},m={start="Rudra Amberstill",faction="Alliance",id=314,ri={"Fang of Vagash"}},src={"Protecting the Herd"}}
E["quest:315"] = {t="quest",n="The Perfect Stout",z="dunmorogh",s="In Brewnall Village, Rejold Barleybrew still pursues The Perfect Stout. He draws on family brewing tradition and exotic local ingredients, and now seeks shimmerweed, a pungent plant cultivated only by the hostile Frostmane trolls atop Shimmer Ridge. He sends daring travelers into their encampment to take the herb from tribal baskets.",h="In Brewnall Village, Rejold Barleybrew still pursues The Perfect Stout.",sec={{t="A Brewer's Ambition",b="Brewing is a way of life in Brewnall Village, especially for the Barleybrew family. Rejold Barleybrew believes greatness runs in his blood, but the perfect stout calls for new ideas. He looks beyond hops, malt and mountain spring water to Dun Morogh's untamed plants, hoping they will give his ale an unmistakable bite.",sp=0},{t="The Troll Herb of Shimmer Ridge",b="East of Brewnall Village, the Frostmane trolls cultivate shimmerweed on Shimmer Ridge. They gather it for tribal and mystic rituals, while dwarves know it for its sharp, distinct flavor. The herb is kept in baskets in the troll village, where Rejold's latest and boldest brewing experiment awaits it.",sp=0}},faq={{q="What is shimmerweed?",a="Shimmerweed is a distinct plant grown and harvested by the Frostmane trolls on Shimmer Ridge. They use it mainly in tribal ceremonies and rituals, while Rejold Barleybrew hopes its sharp flavor will bring something new to dwarven brewing.",al={"shimmerweed lore","what does shimmerweed do","frostmane plant"},it="item"},{q="Where is Shimmer Ridge located?",a="Shimmer Ridge rises in northern Dun Morogh, east of Brewnall Village. It is a fortified camp for the indigenous Frostmane trolls, so gathering herbs there means entering hostile territory.",al={"shimmer ridge location","where is shimmer ridge","how to find shimmer ridge"},it="place",gp=true},{q="Why does Rejold want to steal from the Frostmane trolls?",a="The Frostmane trolls alone cultivate shimmerweed in Dun Morogh, and tensions between dwarves and trolls make peaceful trade impossible. Rejold's only option is to sneak into their encampment or fight through it to seize the harvested plants from their tribal baskets.",al={"why steal from trolls","why troll baskets","rejold troll plan"},it="motive"},{q="Who is Rejold Barleybrew?",a="Rejold Barleybrew is an ambitious dwarf brewer who lives in Brewnall Village. He experiments with new flavors and potent wild ingredients in pursuit of the perfect stout.",al={"who is rejold","rejold barleybrew","barleybrew family"},it="identity"},{q="Is shimmerweed considered an alchemy herb?",a="No. Shimmerweed is not an alchemical reagent gathered from wild nodes. It is the sought-after item stored in wicker baskets and caches throughout the Frostmane settlements atop Shimmer Ridge.",al={"can herbalists pick shimmerweed","is shimmerweed herbalism","shimmerweed gather"},gp=true},{q="What becomes of the shimmerweed once turned in?",a="When the shimmerweed reaches him in Brewnall Village, Rejold throws it into an active fermentation batch. He hopes its unique flavor will finally unlock the flawless recipe he seeks.",al={"does the stout work","rejold brew result","shimmerweed beer"},it="next_step"},{q="Who are the Frostmane trolls?",a="The Frostmane are an indigenous tribe of ice trolls native to the snowy crags of Dun Morogh. Driven out of their historic hunting grounds by the expanding Ironforge dwarves, they harbor deep hostility toward their dwarven neighbors. From settlements like the one on Shimmer Ridge, they cultivate shimmerweed for their tribal rituals and fiercely defend their camps against any intruders.",al={"frostmane trolls","who are the trolls on shimmer ridge","frostmane tribe"},it="target",add="3780a202"}},ang={["race:Dwarf"]="As a dwarf, you know brewing is nearly sacred to the Bronzebeard clan. Finding an exotic herb to outdo rival taverns is a noble pursuit.",["profession:Herbalism"]="As a herbalist, you may find shimmerweed an intriguing novelty. Its unusual botanical traits let it endure the frozen crags of Dun Morogh."},kw={"brewnall village","dun morogh","dwarf brew","frostmane","perfect stout","rejold barleybrew","shimmer ridge","shimmerweed"},rel={"npc:rejold-barleybrew","subzone:brewnall-village","subzone:shimmer-ridge","zone:dunmorogh","topic:troll"},m={start="Rejold Barleybrew",faction="Alliance",id=315,ri={"Shimmerweed"}},src={"The Perfect Stout"}}
E["quest:317"] = {t="quest",n="Stocking Jetsteam",z="dunmorogh",s="At Steelgrill's Depot, Pilot Bellowfiz prepares Jetsteam for a long deployment with the Ironforge Siege Brigade. Its crew needs boar meat and bear pelts for the journey.",h="At Steelgrill's Depot, Pilot Bellowfiz prepares Jetsteam for a long deployment with the Ironforge Siege...",sec={{t="Provisioning the Engine",b="Master engineer Beldin Steelgrill tunes the siege tank at Steelgrill's Depot, just outside Kharanos. Jetsteam is being readied for an operation on behalf of the Siege Brigade. The crew needs a month's provisions to endure Dun Morogh's sub-zero temperatures.",sp=0},{t="Hunting the Snow Fields",b="Beldin Steelgrill works beneath Jetsteam's hood, so Bellowfiz cannot leave the vehicle to gather food and insulation. The snowy plains south of the Grizzled Den hold boars for meat and bears whose pelts can line the tank's bedding and keep it warm.",sp=0}},faq={{q="What is Jetsteam?",a="Jetsteam is the siege tank operated by Pilot Bellowfiz, a dwarf. At Steelgrill's Depot, it is being tuned and provisioned for a long deployment with the Ironforge Siege Brigade.",al={"jetsteam","who is jetsteam","what is jetstream","bellowfiz tank"},it="identity"},{q="Who is Pilot Bellowfiz?",a="Pilot Bellowfiz, nicknamed Fizzer, is a dwarven siege engine pilot with the Ironforge Siege Brigade. While his vehicle is adjusted at Steelgrill's Depot, he coordinates supplies for an upcoming mission.",al={"pilot bellowfiz","bellowfiz","who is pilot bellowfiz"},it="people"},{q="Where can the required supplies be gathered?",a="The snowy plains south of the Grizzled Den hold the boars and bears whose meat and pelts provide food and bedding.",al={"where are the boars","where are bears","hunting location","boar meat dun morogh"},it="place",gp=true},{q="What is the Siege Brigade?",a="The Siege Brigade is Ironforge's corps of siege engine pilots. Its heavily armored machines, including Jetsteam and Trollplow, support dwarven defense and Alliance campaigns.",al={"siege brigade"},it="allies"},{q="Where does this mission lead next?",a="Once Jetsteam is restocked with meat and furs, Pilot Bellowfiz sends travelers west to Brewnall Village for Evershine. He uses the potent brew to keep warm and as emergency fuel for the tank's furnace.",al={"next quest","what comes after stocking jetsteam","stocking jetsteam follow up"},sp=1,it="next_step"},{q="Why does a siege engine require animal furs?",a="Dwarven and gnomish steam tanks grow frigid and drafty during long operations in the mountain snows. Thick bear pelts keep the crew's bedding warm during prolonged stays away from camp.",al={"why fur","thick bear fur use","bedding"},it="item"},{q="Why does Pilot Bellowfiz want this done?",a="Pilot Bellowfiz is gearing up for an extended deployment with the Siege Brigade. The mission ahead will keep him out in the field for at least a month, and operating deep in Dun Morogh's frigid wilderness requires careful preparation. He needs substantial provisions stowed aboard Jetsteam before heading out into active duty.",al={"pilot bellowfiz motive","why stock jetsteam","why does bellowfiz need supplies"},it="motive",add="bd6a237a"},{q="What is the Chunk of Boar Meat for?",a="The boar meat serves as vital rations for Pilot Bellowfiz's upcoming month-long deployment. Operating a heavy siege engine in the freezing cold burns serious energy, and durable meat gathered from the local crag boars provides the sustenance he needs while deployed far from friendly outposts.",al={"chunk of boar meat use","why boar meat","boar meat jetsteam"},it="item",add="f0e85f28"},{q="Why does Pilot Bellowfiz need you to do the hunting?",a="Bellowfiz cannot spare the time to hunt because he is overseeing the maintenance of Jetsteam. Master mechanic Beldin Steelgrill is actively tuning and repairing the tank at Steelgrill's Depot, requiring the pilot to stay close by and ensure the machine is properly prepped for departure.",al={"why cant bellowfiz hunt","why me bellowfiz","why do i have to hunt for bellowfiz"},it="why_me",add="779906a6"}},ang={["race:Gnome"]="As a gnome, your help keeps the dwarven Siege Brigade supplied for its long campaigns. The Brigade is an ally to the exiled gnomes.",["race:Dwarf"]="As a dwarf, you help feed and rest the Siege Brigade's crews as they work from Khaz Modan's machine yards.",["profession:Cooking"]="As a cook, you can use the boar meat that sustains Dun Morogh's mountain garrisons.",["faction:Alliance"]="As an Alliance member, you help link dwarven repair yards with the Siege Brigade's armored crews and keep Alliance siege technology working."},kw={"bear furs","boar meat","dun morogh","grizzled den","jetsteam","pilot bellowfiz","siege brigade","steelgrill's depot"},rel={"npc:pilot-bellowfiz","subzone:steelgrill-s-depot","quest:318","quest:319","subzone:grizzled-den","quest:313","zone:dunmorogh"},m={start="Pilot Bellowfiz",level="6",faction="Alliance",id=317,ri={"Chunk of Boar Meat","Thick Bear Fur"}},src={"Stocking Jetsteam"}}
E["quest:318"] = {t="quest",n="Evershine",z="dunmorogh",s="At Steelgrill's Depot near Kharanos, Pilot Bellowfiz needs Evershine from Rejold Barleybrew in Brewnall Village. The strong brew warms him and can fuel his siege engine, Jetsteam.",h="At Steelgrill's Depot near Kharanos, Pilot Bellowfiz needs Evershine from Rejold Barleybrew in Brewnall...",sec={{t="A Potent Concoction",b="Rejold Barleybrew's brewing experiments go beyond ordinary dwarven ales. Evershine can knock all but the hardiest dwarves flat, yet its heat is prized in Dun Morogh's bitter cold.",sp=0},{t="Fuel for Pilot Bellowfiz",b="At Steelgrill's Depot outside Kharanos, Pilot Bellowfiz takes a warming sip of Evershine against the freezing winds. The volatile brew can also feed Jetsteam's furnace. When Bellowfiz is in a tight spot, it gives his siege engine an explosive burst of emergency power.",sp=0}},faq={{q="What is Evershine?",a="Evershine is an exceptionally strong experimental brew made by the dwarven brewer Rejold Barleybrew in Brewnall Village. Its fiery strength can fell even hardy dwarven drinkers.",al={"what is evershine","evershine brew","what kind of drink is evershine"},it="item"},{q="Why does Pilot Bellowfiz want Evershine?",a="Pilot Bellowfiz drinks Evershine to warm himself against Dun Morogh's chill and uses it as emergency fuel. In Jetsteam's furnace, the volatile spirit gives the siege engine an immediate burst of power.",al={"why bellowsfiz wants brew","pilot bellowfiz evershine","why does bellowfiz need it"},it="motive"},{q="Where is Brewnall Village?",a="Brewnall Village lies in western Dun Morogh, along the road west of Kharanos. Brewers such as Rejold Barleybrew live there near the snowy hills.",al={"where is brewnall","brewnall village location","find brewnall"},it="place",gp=true},{q="Who is Rejold Barleybrew?",a="Rejold Barleybrew is an experimental dwarven brewer in Brewnall Village. He makes many drinks, from pleasant ales to fierce brews potent enough to ignite machine furnaces.",al={"who is rejold","rejold barleybrew info","barleybrew brewer"},it="people"},{q="What comes next after reaching Rejold Barleybrew?",a="Rejold needs help before he will hand over his liquor. At Brewnall Village, you find A Favor for Evershine, where you help the brewer before he gives you a cask for Pilot Bellowfiz.",al={"next quest after evershine","what after evershine","rejold quest followup"},sp=1,it="next_step"},{q="Is Evershine truly safe to drink?",a="Pilot Bellowfiz says Evershine will flatten almost any dwarf who tries it. The strongest mountain folk can drink it, but its extreme flammability also makes it useful in an engine furnace.",al={"can you drink evershine","is evershine poison","evershine dangerous"},it="item"}},ang={["race:Gnome"]="As a gnome, you may appreciate how Pilot Bellowfiz turns ordinary things, even dwarven brew, into improvised fuel.",["race:Dwarf"]="As a dwarf, you know the fiery extremes of dwarven brewing, and Rejold Barleybrew's spirit brings them to Dun Morogh's cold peaks.",["profession:Engineering"]="As an engineer, you can see how volatile spirits give pilots like Bellowfiz another way to keep siege engines running in harsh conditions."},kw={"brewnall village","dun morogh","evershine","jetsteam","kharanos","pilot bellowfiz","rejold barleybrew"},rel={"npc:pilot-bellowfiz","npc:rejold-barleybrew","quest:319","quest:317","subzone:brewnall-village","subzone:kharanos","zone:dunmorogh","topic:dwarf"},m={start="Pilot Bellowfiz",["end"]="Rejold Barleybrew",level="7",faction="Alliance",id=318},src={"Evershine"}}
E["quest:319"] = {t="quest",n="A Favor for Evershine",z="dunmorogh",s="At Steelgrill's Depot, Pilot Bellowfiz needs Evershine for his siege engine, Jetsteam. Rejold Barleybrew will give up a cask only after you drive the predators away from Brewnall Village.",h="At Steelgrill's Depot, Pilot Bellowfiz needs Evershine for his siege engine, Jetsteam.",sec={{t="A Brewer's Bargain",b="Rejold offers his brew if you thin the wild beasts of western Dun Morogh. Ice Claw Bears, Elder Crag Boars, and Snow Leopards roam near Brewnall Village. Their presence endangers the locals and keeps Rejold from freely giving up the cask.",sp=0},{t="Peace for the Craftsmen",b="Rejold says no self-respecting dwarf cowers before wild animals. Yet watching for predators around the village takes the craftsmen valuable hours. Once the beasts are driven off, villagers can focus on distilling and smithing without keeping watch on the tree line.",sp=0}},faq={{q="Why does Rejold want these animals killed?",a="Ice Claw Bears, Elder Crag Boars, and Snow Leopards prowl near Brewnall Village. The dwarves do not fear them, but driving the beasts off takes hours from brewing and crafting.",al={"why kill bears","why cull animals brewnall","rejold task reason"},it="motive"},{q="What is Evershine?",a="Evershine is a potent, celebrated liquor brewed only in Brewnall Village by Rejold Barleybrew. Siege engine pilots like Pilot Bellowfiz prize it as a drink and a volatile fuel additive.",al={"what is evershine","evershine brew","rejold liquor"},it="item"},{q="Who originally asked for the Evershine?",a="Pilot Bellowfiz at Steelgrill's Depot sent you for Evershine to keep him warm on the road and feed into the furnace of his siege engine, Jetsteam, for a burst of power.",al={"who sent me for evershine","who wants evershine","quest chain start"},it="origin"},{q="Where can the animals be found?",a="The animals roam the frozen fields and crags around Brewnall Village and Iceflow Lake in western Dun Morogh.",al={"where are ice claw bears","snow leopard location","elder crag boar location"},it="target",gp=true},{q="What happens after completing the favor?",a="Once the beasts are thinned, Rejold gives you a cask of Evershine to take back to Pilot Bellowfiz at Steelgrill's Depot.",al={"next quest","what after favor for evershine"},it="next_step"},{q="Are the villagers in actual danger from the predators?",a="Rejold says no self-respecting dwarf fears a beast in the snow. Yet predators near the doorstep disrupt daily work and pose a danger.",al={"is brewnall in danger","are dwarves scared"},it="danger"},{q="What animals is Rejold Barleybrew sending you to hunt?",a="Rejold sends you to cull the wild predators and beasts roaming the snowy drifts around Brewnall Village: Ice Claw Bears, Elder Crag Boars, and Snow Leopards. These native beasts wander dangerously close to the settlement's perimeter, growling and snorting outside while the villagers try to tend to their vats and workshops.",al={"rejold targets","which beasts","animals to kill evershine","what animals brewnall"},it="target",add="02738ac5"},{q="Why does Rejold ask you instead of having Brewnall's villagers handle the beasts?",a="The dwarves of Brewnall Village are hardly afraid of local wildlife—no self-respecting dwarf would cower before a boar or snow leopard. However, hunting down packs of prowling predators takes valuable time away from their true passions: brewing ale, crafting, and tending their vats. Since you are an able-bodied traveler already looking for a cask of Evershine, Rejold strikes a trade so his folk can keep working in peace.",al={"why can't villagers kill them","why me rejold","why does rejold need help","brewnall village hunters"},it="why_me",add="fe0fe64f"}},ang={["race:Dwarf"]="As a dwarf, you know wild predators must be kept from an honest still.",["race:Gnome"]="As a gnome, you know the siege pilots and tinkerers at Steelgrill's Depot await the cask. They rely on adventurers to appease the stubborn brewer so Jetsteam's preparations can continue.",["class:Hunter"]="As a hunter, you test your marksmanship against the hardiest winter beasts in the crags of western Dun Morogh."},kw={"bellowfiz","brewnall village","dun morogh","elder crag boar","evershine","ice claw bear","rejold barleybrew","snow leopard"},rel={"npc:rejold-barleybrew","quest:318","subzone:brewnall-village","quest:317","zone:dunmorogh","topic:dwarf"},m={start="Rejold Barleybrew",level="8",faction="Alliance",id=319},src={"A Favor for Evershine"}}
E["quest:3361"] = {t="quest",n="A Refugee's Quandary",z="dunmorogh",s="Gnomeregan's displaced gnomes flee into Dun Morogh after troggs and radiation drive them from their home. Near Anvilmar, engineer Felix Whindlebolt has lost his tools and belongings to Frostmane scavengers.",h="Gnomeregan's displaced gnomes flee into Dun Morogh after troggs and radiation drive them from their home.",sec={{t="The Flight from Gnomeregan",b="Troggs overran Gnomeregan, the high-tech city beneath the earth. High Tinker Gelbin Mekkatorque and his advisors released radioactive gas to kill the invaders. The gas brought disaster instead. Thousands of innocents died, survivors became mindless leper gnomes, and the rest fled across Dun Morogh.",sp=0},{t="Scavengers in the Snow",b="Gnome engineers and tinkerers carried away the tools and blueprints they could save. Frostmane trolls prowl the icy mountain passes between Gnomeregan and Coldridge Valley. As Felix Whindlebolt hurried toward shelter at Anvilmar, Frostmane raiders took his tool chest, lockbox, and bucket of bolts. They carried his belongings to camps southwest of town.",sp=0}},faq={{q="Who is Felix Whindlebolt?",a="Felix Whindlebolt is a gnome engineer who escaped Gnomeregan's radioactive destruction. He shelters near Anvilmar and cannot fight off Dun Morogh's dangers, so he tries to recover his stolen equipment.",al={"felix whindlebolt","who is felix","felix anvilmar"},it="identity"},{q="Why is Gnomeregan irradiated?",a="Gnome authorities released radioactive gas during a trogg invasion, hoping to wipe out the invaders. Instead, the gas contaminated Gnomeregan's ventilation systems. It killed or mutated most residents and made the city uninhabitable.",al={"what happened to gnomeregan","gnomeregan radiation","fall of gnomeregan"},it="history"},{q="Who stole Felix's belongings?",a="Frostmane trolls took Felix's chest, box, and bucket of bolts. They ambush travelers on Dun Morogh's mountain trails, then carry stolen scrap and gear to their encampments southwest of Anvilmar.",al={"who stole the bolts","who has felix's stuff","frostmane trolls"},it="threat"},{q="Where did the displaced gnomes seek refuge?",a="Many displaced gnomes fled across Dun Morogh to Ironforge. Others found temporary shelter in settlements such as Anvilmar and Kharanos.",al={"where are gnomes living","gnome refugees","gnome settlement"},it="place"},{q="Why does a bucket of bolts matter so much?",a="For an exiled gnome tinkerer, tools, specialized screws, and machined bolts are a livelihood. Without proper equipment, refugee engineers cannot ply their trade, fashion defenses, or rebuild their lives in exile.",al={"why bolts","felix bucket of bolts"},it="item"},{q="What threat do the Frostmane trolls pose to Coldridge Valley?",a="The Frostmane tribe has long lived in Dun Morogh's harsh peaks. With trogg outbreaks and Gnomeregan's evacuation bringing chaos, the trolls have grown bolder. They raid supply lines and ambush travelers.",al={"trolls in dun morogh","frostmane threat","frostmane camp"},it="danger"},{q="Why does Felix Whindlebolt want his belongings back?",a="Having fled the radiation poisoning Gnomeregan with barely the clothes on his back, Felix lost the last remnants of his livelihood and trade. Without his personal chest, box, and tools, he is completely stranded in Anvilmar with no means to rebuild his life or ply his craft as a refugee.",al={"felix motive","why does felix need this","felix whindlebolt belongings"},it="motive",add="0b2d3aab"},{q="Why can't Felix retrieve his belongings himself?",a="Felix is an ordinary tinkerer and displaced refugee, not an adventurer or soldier. Terrified by the hostile wilderness and outmatched by the Frostmane trolls who carried off his gear, he cannot risk venturing into their encampments alone.",al={"why doesn't felix get his stuff","why does felix need me","felix why me"},it="why_me",add="48f90e68"},{q="What is inside Felix's Box and Chest?",a="Felix's chest and box contain the personal belongings and specialized tools he managed to pack when fleeing the disaster in Gnomeregan. To a displaced craftsman far from home, these containers hold everything required to make a fresh start.",al={"felix's box","felix's chest","what is in felix's chest"},it="item",add="6a13a14f"}},ang={["race:Gnome"]="As a gnome, you know the bitter tragedy of losing your wondrous home to poison and betrayal. Now everyday tinkerers must ask strangers to recover basic tools from the trolls.",["race:Dwarf"]="As a dwarf, you know the Coldridge mountains have sheltered your kin for centuries. Helping gnome refugees secure a foothold in Anvilmar honors the ancient alliance between Ironforge and Gnomeregan.",["profession:Engineering"]="As an engineer, you know a craftsman cannot stand by while scavengers take precision bolts, calipers, and toolboxes assembled over a lifetime."},kw={"anvilmar","bucket of bolts","coldridge","felix whindlebolt","frostmane","gnomeregan","radiation"},rel={"npc:felix-whindlebolt","zone:gnomeregan","subzone:anvilmar","zone:dunmorogh","topic:gnome","topic:troll","topic:trogg"},m={start="Felix Whindlebolt",level="3",faction="Alliance",id=3361,ri={"Felix's Box","Felix's Bucket of Bolts","Felix's Chest"}},src={"A Refugee's Quandary (Classic)"}}
E["quest:3364"] = {t="quest",n="Scalding Mornbrew Delivery",z="dunmorogh",s="Nori Pridedrift sends you across Coldridge Valley with hot mornbrew for Durnan Furcutter in Anvilmar. The mountain cold can steal its heat before it arrives.",h="Nori Pridedrift sends you across Coldridge Valley with hot mornbrew for Durnan Furcutter in Anvilmar.",sec={{t="A Race Against the Frost",b="After you deliver to Grelin Whitebeard, Nori has another cup to send. He cannot carry it himself before the mornbrew freezes into slush. So he asks you to brave the snow and keep his customer from waiting.",sp=0},{t="The Price of a Warm Mug",b="Durnan Furcutter waits inside Anvilmar's warm mountain hall and is particular about his refreshments. He will not take chilled mornbrew. A hot cup gives the weary dwarf a needed break from his duties. Nori expects his favorite mug back in one piece.",sp=0}},faq={{q="Who is Durnan Furcutter?",a="Durnan Furcutter is a dwarf in Anvilmar's underground hall in Coldridge Valley. Nori Pridedrift brings him hot mornbrew.",al={"durnan furcutter","who is durnan","furcutter"},it="identity"},{q="Why does the delivery need to be so fast?",a="The cold in Coldridge Valley cools hot drinks quickly. Durnan ordered scalding mornbrew, and dwarves consider cold ale or tea ruined.",al={"why timed","mornbrew timer","why hurry"}},{q="Who is Nori Pridedrift?",a="Nori Pridedrift is a dwarf stationed along Coldridge Valley's snowy paths. He carries deliveries between local encampments, including drinks for Grelin Whitebeard and workers in Anvilmar.",al={"nori pridedrift","nori","who is nori"},it="identity"},{q="What is mornbrew?",a="Mornbrew is a warm, invigorating dwarven morning brew. It cuts through the chill of the Dun Morogh peaks and sustains hardy mountain workers.",al={"what is mornbrew","mornbrew lore"},it="item"},{q="Where is Anvilmar located?",a="Anvilmar lies northeast of Nori's post, carved into the mountain rock of Coldridge Valley. It shelters young mountaineers and craftsmen from the blizzards.",al={"where is anvilmar","anvilmar location","find anvilmar"},it="place",gp=true},{q="Does Nori want the mug back?",a="Yes. When Durnan finishes his hot brew, he returns the empty mug for Nori in Coldridge Valley.",al={"mug return","bring back the mug","nori's mug"},it="next_step"},{q="Why does Nori Pridedrift want the mornbrew delivered?",a="Nori was supposed to deliver fresh, piping-hot mornbrew to Durnan Furcutter, but a prior delivery to Grelin Whitebeard held him up. Durnan specifically expects his brew piping hot, not lukewarm or chilly, so Nori is scrambling to get the drink to Anvilmar before it completely cools off.",al={"why deliver mornbrew","nori motive","why does nori need this delivered"},it="motive",add="77d8ea01"},{q="Why does Nori ask you to deliver it instead of taking it himself?",a="Nori has already fallen behind schedule after stopping to serve Grelin Whitebeard. Knowing the brew only stays scalding hot for a few short minutes, he realizes he cannot sprint up the mountain path quickly enough on his own. Spotting you, he relies on your fresh legs to dash to Anvilmar before the drink turns cold.",al={"why does nori need me","why cant nori deliver it","why me nori delivery"},it="why_me",add="4fdc3467"}},ang={["race:Dwarf"]="As a dwarf, you know cold brew in mountain air is a sorrow worth crossing the valley to prevent.",["profession:Cooking"]="As a cook, you know serving a drink at the proper temperature shows respect, especially in Dun Morogh's bitter cold."},kw={"anvilmar","coldridge valley","dun morogh","durnan furcutter","mornbrew","nori pridedrift"},rel={"npc:nori-pridedrift","npc:durnan-furcutter","subzone:anvilmar","quest:3365","zone:dunmorogh"},m={start="Nori Pridedrift",["end"]="Durnan Furcutter",level="5",faction="Alliance",id=3364},src={"Scalding Mornbrew Delivery"}}
E["quest:3365"] = {t="quest",n="Bring Back the Mug",z="dunmorogh",s="Durnan Furcutter sends you back across Coldridge Valley with Nori Pridedrift's empty mug. Its return closes the Mornbrew delivery.",h="Durnan Furcutter sends you back across Coldridge Valley with Nori Pridedrift's empty mug.",sec={{t="A Matter of Tavern Etiquette",b="After warming himself with the Mornbrew, Durnan leaves the tankard in your care. Cold bites hard in Dun Morogh, where hospitality depends on mutual respect. Good dishware should make it back too.",sp=0},{t="Mugs Don't Grow on Trees",b="Nori Pridedrift values sturdy drinkware. Mugs do not grow on trees, especially among the subzero crags of the dwarven homeland. Bring his mug back in one piece, and you show the local community that you can be trusted.",sp=0}},faq={{q="Who starts this errand?",a="After you deliver the freshly brewed Mornbrew to Durnan Furcutter in Dun Morogh, he sends you back with the empty tankard.",al={"quest giver","who gives bring back the mug","durnan furcutter quest"},gp=true},{q="Who do I return the mug to?",a="Return the empty mug to Nori Pridedrift, who wanders Coldridge Valley in Dun Morogh selling his mornbrew.",al={"where do i take the mug","who gets the mug","nori location"},gp=true},{q="Is there a time limit to return the mug?",a="There is no time limit. The first delivery of the Scalding Mornbrew had a strict timer to keep it piping hot, but you can return the empty mug at your own pace.",al={"is this quest timed","mug timer","do i have to hurry back"},gp=true},{q="Why does Nori care so much about an empty mug?",a="Quality mugs and steins are valuable barware in Dun Morogh. Nori points out that mugs do not grow on trees, and taverns cannot afford to lose drinkware to passing couriers.",al={"why does nori want the mug back","importance of the mug"},it="why_wanted"},{q="What quest leads directly into this one?",a="This follows directly after Scalding Mornbrew Delivery, when Durnan drinks the beverage you brought him.",al={"prerequisite quest","what comes before bring back the mug"},gp=true},{q="Where can Durnan Furcutter be found?",a="Find Durnan Furcutter inside Anvilmar, the settlement dug into the mountain in Coldridge Valley. He sells cloth and leather armor.",al={"durnan location","where is durnan"},it="place",gp=true},{q="Why does Durnan Furcutter want this done?",a="Durnan Furcutter just finished enjoying the piping hot scalding mornbrew delivered by Nori in Coldridge Valley to keep the chill away. Returning the empty mug is basic courtesy to Nori Pridedrift, who expects his glassware back rather than letting couriers leave it scattered out in the freezing snow of Dun Morogh.",al={"why return mug","durnan return mug","why send back the mug"},it="motive",add="aa771bb6"}},ang={["race:Dwarf"]="As a dwarf, you know that keeping a tavernkeeper's tankard can lead to a brawl. Returning Nori's mug is basic dwarven manners.",["profession:Cooking"]="As a cook or brewer, you know good service ends only when the dishware is accounted for and returned to the kitchen."},kw={"bring back the mug","dun morogh","durnan furcutter","kharanos","mornbrew","nori pridedrift","tankard"},rel={"quest:3364","npc:nori-pridedrift","npc:durnan-furcutter","zone:dunmorogh"},m={start="Durnan Furcutter",["end"]="Nori Pridedrift",level="5",faction="Alliance",id=3365},src={"Bring Back the Mug"}}
E["quest:384"] = {t="quest",n="Beer Basted Boar Ribs",z="dunmorogh",s="At the Thunderbrew Distillery in Kharanos, patrons hunger for Ragnar Thunderbrew's famed ribs. His regular supplier has joined the King's Army, so Ragnar needs fresh crag boar ribs and Rhapsody Malt to keep them on the menu.",h="At the Thunderbrew Distillery in Kharanos, patrons hunger for Ragnar Thunderbrew's famed ribs.",sec={{t="A Tavern in Need",b="Tavern keeper Ragnar Thunderbrew has eager customers, but his pantry is bare. The local hunter who supplied fresh meat enlisted in the King's Army to reinforce the Alliance front. Now Ragnar has no fresh ribs for the patrons who favor them.",sp=0},{t="The Secret Ingredient",b="Crag boars roam the snowy foothills around Kharanos, and their meat is tough. Ragnar's recipe also calls for fresh Rhapsody Malt, drawn straight from the distillery's taps. The malt softens the game meat and makes a savory feast fit for a dwarf's praise.",sp=0}},faq={{q="Why is Ragnar Thunderbrew short on meat?",a="Ragnar's regular meat supplier was a local mountain trapper who left Kharanos to enlist in the King's Army. The trapper went to support Alliance operations abroad, leaving the tavern without a steady supply of game.",al={"why ragnar need boar ribs","what happened to ragnar meat supplier","who supplies the ribs"},it="motive"},{q="Where does Rhapsody Malt come from?",a="Rhapsody Malt is brewed and served at the Thunderbrew Distillery in Kharanos. Ragnar draws it straight from the tavern bar.",al={"where get rhapsody malt","how to get malt for ragnar","who sells rhapsody malt"},it="item",gp=true},{q="What kind of boars provide the ribs?",a="Crag boars roaming the hills, snowdrifts, and frozen valleys around Kharanos in Dun Morogh provide the ribs.",al={"which boars drop ribs","where find boar ribs dun morogh","crag boars dun morogh"},it="target",gp=true},{q="What is the secret to Ragnar's rib recipe?",a="Ragnar bastes tough boar ribs in Rhapsody Malt. The malt tenderizes the cold-weather game and gives it the rich flavor of dwarven brewing.",al={"secret to beer basted ribs","beer basted boar ribs secret"},it="item"},{q="Who is fighting on the front lines for the King's Army?",a="Dwarven recruits join the King's Army in its ongoing conflicts against troggs, dark iron incursions, and other military fronts across the Eastern Kingdoms.",al={"why did the trapper enlist","what war is the kings army fighting","alliance front lines 25 adp"}},{q="Where is the Thunderbrew Distillery located?",a="The Thunderbrew Distillery is Kharanos's primary tavern and inn, along the main road through central Dun Morogh.",al={"where is thunderbrew distillery","where is ragnar thunderbrew","kharanos inn location"},it="place"},{q="What are the Crag Boar Ribs for?",a="Ragnar needs these ribs to prepare his tavern's signature dish, Beer Basted Boar Ribs. The local patrons crave them, but his regular meat supplier enlisted in the King's Army to fight on the front lines, leaving the Thunderbrew Distillery completely out of fresh stock.",al={"crag boar ribs use","why ribs","what are boar ribs for"},it="item",add="44c418cd"},{q="Why does Ragnar need an adventurer to gather the ingredients?",a="Ragnar is busy running the Thunderbrew Distillery and serving thirsty tavern patrons in Kharanos. With his usual supplier off fighting in the King's Army, he must rely on passing travelers like you to hunt the local crag boars and fetch ingredients from the innkeeper inside.",al={"why me ragnar","why can't ragnar get ribs","why ask me ragnar"},it="why_me",add="ba894b88"}},ang={["profession:Cooking"]="As someone who enjoys cooking over a hearth, you can learn to blend malt liquor with wild game from one of Dun Morogh's famed brewmasters.",["race:Dwarf"]="As a dwarf, you know hearty ale and roasted boar are at the heart of mountain hospitality. Keeping the distillery stocked is a matter of local pride.",["faction:Alliance"]="As an Alliance member, you can see the war effort reach even Kharanos's taverns. Local mountain folk leave their trades to answer the call to arms."},kw={"beer basted boar ribs","crag boar","dun morogh","kharanos","ragnar thunderbrew","rhapsody malt","thunderbrew distillery"},rel={"npc:ragnar-thunderbrew","subzone:thunderbrew-distillery","subzone:kharanos","quest:117","zone:dunmorogh","topic:alliance"},m={start="Ragnar Thunderbrew",["end"]="Ragnar Thunderbrew",faction="Alliance",id=384,ri={"Rhapsody Malt","Tender Boar Ribs"}},src={"Beer Basted Boar Ribs (quest)"}}
E["quest:400"] = {t="quest",n="Tools for Steelgrill",z="dunmorogh",s="At Kharanos, Tharek Blackstone sends you northeast with tools for Beldin Steelgrill at the depot. The road leads from town to the mechanics and war machines gathered there.",h="At Kharanos, Tharek Blackstone sends you northeast with tools for Beldin Steelgrill at the depot.",sec={{t="A Master Rough on His Gear",b="Across Dun Morogh, Beldin Steelgrill is known as the sharpest siege engine mechanic in the mountains. His rough work breaks arclight spanners and other tools faster than Kharanos suppliers can replace them. Tharek Blackstone has a fresh batch of durable gear ready, so a traveler bound northeast carries the heavy crate to the depot.",sp=0},{t="Keeping the Engines Running",b="Steelgrill's Depot is crowded with idle war machines and military repairs. Beldin's backlog includes urgent work on Pilot Stonegear's siege engine. He broke his last fang-ratchet only hours before you arrive. The crate is needed to keep Ironforge's tracked armor fleet running.",sp=0}},faq={{q="Where do I take the tools?",a="Take the tools northeast from Kharanos along the road toward Ironforge. Beldin Steelgrill works at Steelgrill's Depot among parked siege engines and tanks.",al={"where is steelgrill","where to deliver tools","beldin steelgrill location"},it="place",gp=true},{q="Who is Beldin Steelgrill?",a="Beldin Steelgrill is a renowned dwarven mechanic who specializes in siege engines and runs Steelgrill's Depot in Dun Morogh. He oversees repairs, modifications, and maintenance for veteran pilots serving Ironforge's armored forces.",al={"who is beldin","beldin lore","siege engine tech"},it="identity"},{q="Why does Beldin break so many tools?",a="Siege engines are massive war machines with heavy plating and oversized iron fittings. Their reinforced hulls demand leverage and force, often snapping arclight spanners and fang-ratchets during urgent repairs.",al={"why broken tools","arclight spanners breaking","steelgrill tools"}},{q="Whose siege engine is Beldin fixing?",a="Beldin is repairing the siege engine belonging to Pilot Stonegear, a veteran dwarven pilot stationed at the depot.",al={"pilot stonegear tank","what engine is broken","stonegear siege engine"}},{q="What is Steelgrill's Depot?",a="Steelgrill's Depot is an open-air workshop and staging ground northeast of Kharanos. Veteran siege engine pilots and tank crews gather there to test, tune, and repair their armored treads.",al={"what is the depot","depot purpose","steelgrill workshop"},it="place"},{q="Why does Tharek Blackstone ask an adventurer to carry them?",a="Tharek Blackstone has filled Steelgrill's latest tool order and needs a traveler heading northeast to carry the heavy crate. He offers modest coin and an introduction to the veteran pilots up the road.",al={"why ask me","tharek delivery reason"},it="why_me"},{q="Why does Tharek Blackstone want these tools delivered?",a="Tharek runs Kharanos's supply trade and has just assembled Beldin Steelgrill's latest order of equipment. Beldin is the finest siege engine technician in Dun Morogh, but his rough hands chew through delicate gear like arclight spanners at an alarming rate. Keeping Beldin supplied ensures the dwarven siege engines keeping the roads and mountains secure remain fully operational.",al={"tharek blackstone motive","why deliver tools for steelgrill","why send steelgrill tools"},it="motive",add="fd264fde"}},ang={["profession:Engineering"]="Beldin relies on precision tools such as arclight spanners and fang-ratchets. Their strain shows how mechanical warfare taxes crafted instruments.",["race:Dwarf"]="As a dwarf, you know Ironforge's armored forces rely on field repair stations like Steelgrill's Depot to keep siege engines moving across the frozen passes.",["race:Gnome"]="As a gnome, you recognize the arclight spanners and intricate ratchets Beldin uses as precision instruments shaped by gnomish engineering and adapted for dwarven plate."},kw={"arclight spanner","beldin steelgrill","dun morogh","fang-ratchet","kharanos","pilot stonegear","siege engine","steelgrill's depot","tharek blackstone"},rel={"subzone:steelgrill-s-depot","npc:beldin-steelgrill","npc:tharek-blackstone","npc:pilot-stonegear","subzone:kharanos","zone:dunmorogh"},m={start="Tharek Blackstone",["end"]="Beldin Steelgrill",level="5",faction="Alliance",id=400},src={"Tools for Steelgrill"}}
E["quest:403"] = {t="quest",n="Guarded Thunderbrew Barrel",z="dunmorogh",s="In Kharanos, the Thunderbrew family’s ale waits under guard in the distillery cellar. Jarven watches over the stock.",h="In Kharanos, the Thunderbrew family’s ale waits under guard in the distillery cellar.",sec={{t="A Cellar Under Watch",b="Jarven Thunderbrew keeps watch over the aging casks beneath the Thunderbrew Distillery in Kharanos. Sentries stand beside the barrels, guarding the brew from tampering or theft.",sp=0},{t="Family Pride and Rivalries",b="The Thunderbrews keep their recipes close, especially the potent Thunder Ale. Dwarves give brewing the care they give smithing and mining. Troggs creep nearby, and brewing rivals compete across the Alliance. So Jarven watches until the family’s ale is ready to be tapped.",sp=0}},faq={{q="Why can't I open this barrel?",a="Jarven Thunderbrew is keeping watch in the basement. While he guards the barrels, no one may disturb the Thunderbrew family’s stock.",al={"cannot open barrel","why cant i touch the ale","jarven guarding barrel"},it="purpose",gp=true},{q="Who is Jarven Thunderbrew?",a="Jarven Thunderbrew belongs to the Thunderbrew clan and is stationed in the Kharanos distillery cellar. He watches the family’s finest ales and keeps thieves and troublemakers from tampering with them.",al={"who is jarven","jarven lore","dwarf in cellar"},it="identity"},{q="Where is this barrel located?",a="The barrel rests in the cellar beneath the Thunderbrew Distillery in Kharanos, Dun Morogh.",al={"where is the guarded barrel","cellar location","thunderbrew basement"},it="place",gp=true},{q="Why do the Thunderbrews guard their ale so closely?",a="The Thunderbrews guard their ale because brewing is a revered craft and a family legacy to dwarves. Rival brewers, thieves, troggs, and leper gnomes threaten rare vintage barrels of Thunder Ale.",al={"why guard ale","importance of thunderbrew ale"},it="motive"},{q="Is this part of another quest?",a="Yes. You help Marleth Barleybrew with Bitter Rivals by slipping a barrel of Barleybrew Scalder among the Thunderbrews’ barrels of Thunder Ale.",al={"thunderbrew questline","what quest is this for"},it="ties",gp=true},{q="Can you distract or move Jarven?",a="Yes. Jarven has orders not to touch the stock, though he admits he would love a taste of Thunder Ale. Bring him one, and his attention turns from the barrels.",al={"how to get past jarven","distract jarven"},gp=true}},ang={["race:Dwarf"]="As a dwarf, you know a family’s secret brew is worth defending with your life and limb. Jarven’s stubborn watch in the cellar comes naturally.",["class:Rogue"]="As a rogue, you know a quiet cellar heist grows harder with a vigilant dwarf watching the keg."},kw={"dun morogh","dwarven brew","guarded thunderbrew barrel","jarven thunderbrew","kharanos","thunder ale","thunderbrew distillery"},rel={"zone:dunmorogh","quest:117"},m={start="Guarded Thunder Ale Barrel",level="1",faction="Alliance",id=403},src={"Guarded Thunderbrew Barrel"}}
E["quest:412"] = {t="quest",n="Operation Recombobulation",z="dunmorogh",s="In Kharanos, Razzle Sprysprocket and Ozzie Togglevolt search for a cure for their kin. Their experimental Recombobulator needs parts taken from hostile leper gnomes outside Gnomeregan.",h="In Kharanos, Razzle Sprysprocket and Ozzie Togglevolt search for a cure for their kin.",sec={{t="A Remedy for a Calamity",b="Razzle and Ozzie are building a machine to restore their afflicted kin to health and sanity. Radiation changed most of Gnomeregan's gnomes into sickly, deranged leper gnomes. The inventors hope their Recombobulator can reverse that change.",sp=0},{t="Scavenging from the Afflicted",b="Razzle needs Restabilization Cogs and Gyromechanic Gears for the delicate prototype. The parts must come from hostile leper gnomes outside Gnomeregan's sealed gates. Debris from their altered kin may help undo the tragedy they share.",sp=0}},faq={{q="What is the Recombobulator supposed to do?",a="Razzle Sprysprocket and Ozzie Togglevolt designed the Recombobulator to reverse the effects of Gnomeregan's radiation and cure leper gnomes.",al={"what is recombobulator","purpose of recombobulator","recombobulate meaning"},it="purpose"},{q="Who are Razzle Sprysprocket and Ozzie?",a="Razzle Sprysprocket and Ozzie Togglevolt are gnomish inventors working in Kharanos, in Dun Morogh. Since Gnomeregan fell, they have devoted their skills to finding ways to save their displaced, irradiated people.",al={"who is razzle","who is ozzie togglevolt","razzle sprysprocket lore"},it="people"},{q="Why are there leper gnomes outside Gnomeregan?",a="Radiation released during the trogg invasion failed to kill the troggs. Instead, it drove many surviving gnomes mad and changed them into hostile leper gnomes.",al={"why are gnomes lepers","how did leper gnomes happen","gnomeregan radiation"},it="threat"},{q="Where do the parts for the Recombobulator come from?",a="The parts come from leper gnomes outside Gnomeregan's entrance in western Dun Morogh. The afflicted gnomes still carry salvaged mechanical hardware on their bodies.",al={"where to get cogs and gears","restabilization cogs source","gyromechanic gears"},it="origin"},{q="Does the Recombobulator actually work?",a="Razzle says the right parts, hydrolubricant, and adjustments to the electrogum gel will restore the gnomes to normal. Gnomish engineering can be volatile, and it remains uncertain whether the machine can undo toxic irradiation.",al={"did recombobulator cure them","can leper gnomes be cured","recombobulator success"},it="history"},{q="Why does Razzle Sprysprocket want this done?",a="The fall of Gnomeregan did not just leave the city overrun by troggs; the radiation released during the catastrophe twisted the vast majority of the gnomish population into mindless, hostile leper gnomes. Razzle Sprysprocket and his partner Ozzie refuse to accept that their people are lost forever. They believe their invention, the Recombobulator, can reverse the terrible afflictions of the fallout and restore the gnomish race to its former self.",al={"why does razzle want this","razzle motive","why build the recombobulator"},it="motive",add="8df716ac"},{q="What are the Restabilization Cogs and Gyromechanic Gears for?",a="These precision components are essential mechanical parts needed to finish building the Recombobulation Device according to Ozzie's intricate schematics. Once assembled into the apparatus alongside hydrolubricant, crank-o-ratchets, and electrogum gel, the gears and cogs will balance and regulate the machinery designed to undo the radiation that corrupted the leper gnomes.",al={"what are restabilization cogs","gyromechanic gears use","what are the parts for"},it="item",add="ed729e1a"},{q="Who are you sent against at Gnomeregan?",a="You are dispatched to hunt down the leper gnomes prowling outside the entrance gates of Gnomeregan. Formerly ordinary citizens, their minds and bodies were warped by the toxic radiation deployed to purge the trogg invasion. Driven mad, they now carry the scavenged machinery, gears, and cogs from the ruined city while violently attacking anyone who approaches.",al={"who am i fighting","operation recombobulation enemies","gnomeregan target"},it="target",add="c92cc687"}},ang={["race:Gnome"]="For gnomes, this work offers a desperate hope of saving family and friends changed into violent shells during the fall of their capital.",["profession:Engineering"]="As an engineer, you can appreciate Razzle's unorthodox work with Restabilization Cogs, crank-o-ratchets, and viscous electrogum gel to manipulate biophysical radiation."},kw={"dun morogh","gnomeregan","gyromechanic gear","kharanos","leper gnome","ozzie togglevolt","razzle sprysprocket","recombobulator","restabilization cog"},rel={"npc:razzle-sprysprocket","zone:gnomeregan","topic:leper-gnome","subzone:kharanos","topic:gnome","topic:trogg","zone:dunmorogh"},m={start="Razzle Sprysprocket",level="10",faction="Alliance",id=412,ri={"Gyromechanic Gear","Restabilization Cog"}},src={"Operation Recombobulation (Classic)"}}
E["quest:413"] = {t="quest",n="Shimmer Stout",z="dunmorogh",s="At Brewnall Village, Rejold Barleybrew is sending Shimmer Stout to his brother Wellart. The guard watches the pass toward Loch Modan, where a cold post makes a strong drink welcome.",h="At Brewnall Village, Rejold Barleybrew is sending Shimmer Stout to his brother Wellart.",sec={{t="A Family Recipe on the Frontier",b="Rejold Barleybrew perfected Shimmer Stout with shimmering fronds gathered from Dun Morogh’s icy crags. His family tends the vats and kegs at Brewnall Village, while his brother Wellart chose life as a Mountaineer. Knowing how lonely frontier guard duty can be, Rejold sends a fresh barrel with passing travelers. It is a kindness between brothers and a chance to test the brew.",sp=0},{t="The South Gate Guard Tower",b="Wellart Barleybrew guards the South Gate Pass into Loch Modan from the southern tower. High in the pass, Mountaineers face bitter winds and occasional beast attacks as they watch over travelers on the mountain road. Wellart is running low on drink and restless for excitement. Shimmer Stout packs quite a punch, he finds, and seems to brighten his vision in the dim mountain night.",sp=0}},faq={{q="Who is Mountaineer Barleybrew?",a="Mountaineer Wellart Barleybrew is Rejold Barleybrew’s brother. While his kin brew ale in Brewnall Village, Wellart serves with the Dun Morogh Mountaineers and watches the high pass between Dun Morogh and Loch Modan.",al={"who is wellart barleybrew","wellart barleybrew","mountaineer barleybrew lore"},it="identity"},{q="Where is the southern guard tower located?",a="The southern tower sits along Dun Morogh’s eastern border, guarding the South Gate Pass through the mountains toward Loch Modan.",al={"where is southern guard tower","mountaineer barleybrew location","where is wellart"},it="place",gp=true},{q="What makes Shimmer Stout special?",a="Shimmer Stout is brewed with special shimmering fronds gathered in the snowy wilderness. Wellart says it brightens his eyes and makes him feel as though he can see through the dark.",al={"what does shimmer stout do","shimmer stout effect"},it="item"},{q="What happens after Wellart drinks the stout?",a="Wellart enjoys the brew and asks travelers to carry another keg into Loch Modan for Mountaineer Kadrell, who patrols the road through Thelsamar.",al={"what is next after shimmer stout","next quest after shimmer stout"},sp=1,it="next_step"},{q="Why does Rejold Barleybrew want this done?",a="Rejold is eager to share the fruits of his craft with his brother, Mountaineer Wellart Barleybrew. Having just perfected his new recipe for Shimmer Stout at the family distillery, Rejold knows that while Wellart walked away from the brewing trade to patrol the borders, he remains a true dwarf at heart who loves a hearty drink. Delivering a fresh barrel is both a gesture of brotherly pride and a way to get an honest verdict on his latest concoction from a thirsty soldier in the field.",al={"why send shimmer stout","rejold barleybrew motive","why deliver the stout"},it="motive",add="cd95a50e"}},ang={["race:Dwarf"]="As a dwarf, you know sharing ale with family matters as much as guarding the mountain passes. This delivery is part of frontier life in Ironforge.",["faction:Alliance"]="As an Alliance traveler, you help keep the Mountaineers supplied as they guard the highway between Dun Morogh and Loch Modan."},kw={"dun morogh","kharanos","mountaineer barleybrew","rejold barleybrew","shimmer stout","south gate pass","wellart"},rel={"npc:rejold-barleybrew","npc:mountaineer-barleybrew","quest:415","quest:414","zone:dunmorogh","zone:lochmodan"},m={start="Rejold Barleybrew",["end"]="Mountaineer Barleybrew",level="10",faction="Alliance",id=413},src={"Shimmer Stout (quest)"}}
E["quest:414"] = {t="quest",n="Stout to Kadrell",z="dunmorogh",s="A cask of Rejold Barleybrew’s new Shimmer Stout is headed east to Mountaineer Kadrell in Loch Modan. You carry it from Dun Morogh’s frozen heights to the warmer valley.",h="A cask of Rejold Barleybrew’s new Shimmer Stout is headed east to Mountaineer Kadrell in Loch Modan.",sec={{t="A Taste Beyond the Mountains",b="From Dun Morogh’s eastern border post, Mountaineer Barleybrew watches the mountain passes and the kin guarding neighboring lands. The Mountaineers’ patrols can be cold and grueling, and a stout heart calls for stout drink. Rejold’s new Shimmer Stout is too good to keep in Dun Morogh. Barleybrew wants an honest opinion from a fellow patrolman, so he sends a cask east with travelers bound for Loch Modan.",sp=0},{t="The Road to Thelsamar",b="For young dwarven and gnomish adventurers, the road to Loch Modan is a rite of passage after their early days in Dun Morogh’s snowbound crags. You pass southeast through the South Gate Outpost, then follow long tunnels cut through the mountain bedrock. Beyond them lies Loch Modan’s warmer, wooded basin. Mountaineer Kadrell patrols the road through Thelsamar. He pauses to tap the cask and finds that Barleybrew’s new recipe has an astonishing kick.",sp=0}},faq={{q="Who is Mountaineer Kadrell?",a="Mountaineer Kadrell is a dwarven defender in Loch Modan. He patrols the central road through Thelsamar.",al={"kadrell","who is kadrell","mountaineer kadrell location"},it="identity"},{q="What is Shimmer Stout?",a="Shimmer Stout is a potent ale brewed by Rejold Barleybrew at the Brewnall Village distillery in western Dun Morogh. Its strength brings a head-spinning kick and invigorating warmth.",al={"what is shimmer stout","shimmer stout","rejold brew"},it="item"},{q="How do I reach Loch Modan from Dun Morogh?",a="From Dun Morogh’s eastern guard posts, head southeast through the mountain tunnels past the South Gate. In Loch Modan, follow the road as it forks northeast toward Thelsamar by the lake.",al={"how to get to loch modan","road to thelsamar","dun morogh to loch modan"},gp=true},{q="Why does Barleybrew want Kadrell to try the beer?",a="Mountaineer Barleybrew and Mountaineer Kadrell are fellow members of the dwarven Mountaineers. Impressed by his brother’s new recipe, Barleybrew wants his comrade in the neighboring valley to try it.",al={"why send stout to kadrell","barleybrew kadrell connection"},it="motive"},{q="What does Kadrell think of the brew?",a="Kadrell is astonished by the stout’s strength. He swears by Magni’s beard that it spins his head and lightens his limbs until he feels he can fly.",al={"kadrell reaction","is shimmer stout good"}},{q="Does this quest lead to further tasks?",a="Delivering the cask concludes the Shimmer Stout chain begun in Dun Morogh. It brings travelers to Thelsamar, where many duties await across Loch Modan.",al={"stout to kadrell follow up","what comes next"},it="next_step",gp=true},{q="Why does Mountaineer Barleybrew need you to deliver the cask?",a="Barleybrew is on active watch at the South Gate Outpost, tasked with guarding Dun Morogh's eastern borders and monitoring travelers. As a Mountaineer on duty, he cannot abandon his post simply to share a drink, leaving him dependent on passing adventurers traveling southeast toward Loch Modan to carry the cask to Kadrell.",al={"why cant barleybrew deliver the stout","why does barleybrew need me","why send an adventurer to thelsamar"},it="why_me",add="46258ba9"}},ang={["race:Dwarf"]="As a dwarf, you carry mountain ale across territorial lines, connecting Brewnall Village’s brewers with the patrols guarding Khaz Modan.",["faction:Alliance"]="As an Alliance traveler, you follow the road from Dun Morogh’s snowy reaches into Loch Modan’s broader frontier."},kw={"ale","barleybrew","cask","dun morogh","kadrell","loch modan","rejold","shimmer stout","thelsamar"},rel={"quest:413","quest:415","npc:mountaineer-kadrell","npc:mountaineer-barleybrew","subzone:thelsamar","zone:lochmodan","zone:dunmorogh"},m={start="Mountaineer Barleybrew",["end"]="Mountaineer Kadrell",level="10",faction="Alliance",id=414},src={"Stout to Kadrell"}}
E["quest:415"] = {t="quest",n="Rejold's New Brew",z="dunmorogh",s="Back at Brewnall Village, Rejold Barleybrew has perfected his new recipe. He wants you, the trusted friend who secured the Shimmerweed, to taste it.",h="Back at Brewnall Village, Rejold Barleybrew has perfected his new recipe.",sec={{t="A Summons to Brewnall",b="Tharek Blackstone and Pilot Bellowfiz send you back to Brewnall Village. Rejold has finished fermenting his experimental batches and is ready to share them with you. You secured Shimmerweed from the bitter slopes, and now he can offer you the fruits of that effort.",sp=0},{t="Tasting the Fruit of Labor",b="Rejold Barleybrew has blended local herbs into his mash to make Shimmer Stout. Before he ships barrels to neighboring outposts and thirsty patrons in Loch Modan, he gives you the honor of the first sip. You risked life and limb for the herbs, and the first taste is yours.",sp=0}},faq={{q="Who sends me back to Rejold Barleybrew?",a="Your allies in Dun Morogh, including Tharek Blackstone and Pilot Bellowfiz, tell you Rejold wants you back at Brewnall Village.",al={"who starts rejolds new brew","quest giver","where to get quest"},it="identity"},{q="Where is Brewnall Village?",a="Brewnall Village lies in western Dun Morogh, along the shores of frozen Iceflow Lake.",al={"where is brewnall","brewnall village location","rejold barleybrew location"},it="place",gp=true},{q="What is Rejold's new drink made of?",a="Rejold made his new drink by adding Shimmerweed, a wild plant from Dun Morogh’s chilly crags, to his traditional ale recipe.",al={"what is in the brew","what did rejold make","shimmerweed recipe"},it="origin"},{q="What happens after I speak to Rejold?",a="Rejold offers you a sample of his new creation, then asks you to bring a barrel of Shimmer Stout to his brother Wellart, a Mountaineer stationed in the southern guard tower on the border with Loch Modan.",al={"next quest","what comes next","rejold chain"},sp=1,it="next_step"},{q="Why does Rejold want me specifically to try it?",a="You helped Rejold obtain the rare Shimmerweed for his experimental recipe, so he considers it proper dwarven courtesy to let you sample the result first.",al={"why does rejold want me","who tested the beer"},it="why_me"},{q="What is the name of the final beverage?",a="The experimental blend is called Shimmer Stout, after the key ingredient that gives it its distinct kick.",al={"what drink did he make","drink name","rejold's beer"},it="name"},{q="Why does the quest giver send you to Rejold Barleybrew?",a="Rejold Barleybrew has been actively asking around for you specifically. Word reached outposts like Steelgrill's Depot, and whether it was Tharek Blackstone or Pilot Bellowfiz who caught wind of it, they are simply passing the message along. Rejold needs your help testing a promising new recipe, and as far as your informants are concerned, answering his call might just earn you a taste of free booze.",al={"why does tharek send me to rejold","why does pilot bellowfiz send me to brewnall","why return to rejold"},it="motive",add="4916bbae"}},ang={["race:Dwarf"]="As a dwarf, you know few honors rank higher than a respected brewmaster summoning you to take the first pull from a fresh cask.",["faction:Alliance"]="As an Alliance adventurer, you know hearty dwarven ales keep garrisons throughout the Eastern Kingdoms in good spirits, even at harsh frontier outposts like Dun Morogh."},kw={"ale","brew","brewnall village","dun morogh","pilot bellowfiz","rejold barleybrew","shimmer stout","shimmerweed","tharek blackstone"},rel={"npc:rejold-barleybrew","subzone:brewnall-village","quest:413","quest:414","zone:dunmorogh"},m={start="Tharek BlackstonePilot Bellowfiz",["end"]="Rejold Barleybrew",level="10",faction="Alliance",id=415},src={"Rejold's New Brew"}}
E["quest:417"] = {t="quest",n="A Pilot's Revenge",z="dunmorogh",s="Hildelve’s search ends in the crags of Dun Morogh, where Pilot Hammerfoot’s searchers find him frozen beside his journal. His last words call for vengeance.",h="Hildelve’s search ends in the crags of Dun Morogh, where Pilot Hammerfoot’s searchers find him frozen beside...",sec={{t="A Final Entry",b="Hildelve’s journal tells of his savage fight with Mangeclaw, the huge Ice Claw bear. He drove the beast away at first, but his wounds were grave. Mangeclaw returned and killed him.",sp=0},{t="A Pilot's Dying Wish",b="Hildelve’s final plea calls for vengeance against Mangeclaw. Bring his journal and a claw torn from the beast to Pilot Hammerfoot. The grim news gives the Ironforge Siege Brigade closure and honors its lost comrade.",sp=0}},faq={{q="Who was Hildelve?",a="Pilot Hildelve was a dwarven siege engine pilot in the Ironforge Siege Brigade. When his engine broke down, he set out on foot into the mountains of Dun Morogh. His friend Pilot Hammerfoot sent searchers, who found Hildelve’s remains in the snow.",al={"hildelve","who is the dead dwarf","lost pilot"},it="identity"},{q="What is Mangeclaw?",a="Mangeclaw is an exceptionally large and ferocious Ice Claw bear roaming the slopes of Dun Morogh. The bear ambushed Pilot Hildelve and wounded him mortally. Then Mangeclaw returned and killed him.",al={"mangeclaw","ice claw bear","who killed hildelve"},it="target"},{q="Who is Pilot Hammerfoot?",a="Pilot Hammerfoot is a seasoned siege engine pilot stationed in Dun Morogh and a member of the Ironforge Siege Brigade. Concerned for his missing friend Hildelve, he sends you into the wilds to learn what happened.",al={"hammerfoot","pilot hammerfoot"},it="people"},{q="Why does Hildelve's death matter to Ironforge?",a="The Ironforge Siege Brigade relies on trained pilots and machinery to scout and defend the mountainous territory around the capital. Hildelve’s death is a harsh blow to its ranks.",al={"why care about hildelve","siege brigade importance"},it="ties"},{q="Where does this quest chain begin?",a="Pilot Hammerfoot begins the journey by asking you to find his missing friend in “The Lost Pilot.” Finding Hildelve’s corpse begins “A Pilot’s Revenge.”",al={"how to start a pilot's revenge","lost pilot quest chain"},gp=true},{q="What proof do you need to bring to Hammerfoot?",a="Bring Hildelve’s Journal from the pilot’s corpse and a Mangy Claw taken from Mangeclaw’s carcass. Together, they prove the beast was slain.",al={"mangeclaw proof","what items needed"},it="item"},{q="Why does the dwarven corpse give you this task?",a="The corpse is that of Pilot Hildelve, who recorded his final moments in his recovered journal. Although he initially fended off the massive ice claw bear Mangeclaw, the beast returned to finish him off. His journal makes his dying wish clear: he wanted vengeance against the beast that ended his life in the frozen crags.",al={"why dwarven corpse quest","hildelve motive","why revenge on mangeclaw"},it="motive",add="5ec072c3"},{q="Why can't Ironforge handle Mangeclaw themselves?",a="Pilot Hammerfoot is stationed at the remote camp awaiting word of his missing comrade, unaware of Hildelve's fate until you discover the body. With Hildelve lying dead in the snow and no patrol nearby to stumble upon his journal, you are the only one on the scene capable of carrying out his final wish.",al={"why do i have to kill mangeclaw","why me a pilots revenge","why doesn't hammerfoot kill mangeclaw"},it="why_me",add="b9e5721c"}},ang={["race:Dwarf"]="As a dwarf, you honor Hildelve’s memory by avenging your fallen Ironforge Siege Brigade comrade and punishing his killer.",["faction:Alliance"]="As an Alliance member, you know the Ironforge pilots are vital to dwarven and Alliance defenses. Recovering lost pilots is an essential duty.",["class:Hunter"]="As a hunter, you test your mountain survival skills by tracking an unusually vicious alpha beast like Mangeclaw through Dun Morogh’s freezing winds."},kw={"dun morogh","hammerfoot","hildelve","ice claw bear","ironforge siege brigade","mangeclaw","revenge"},rel={"quest:419","npc:pilot-hammerfoot","zone:dunmorogh","zone:ironforge"},m={start="A Dwarven Corpse",["end"]="Pilot Hammerfoot",level="11",faction="Alliance",id=417,ri={"Mangy Claw"}},src={"A Pilot's Revenge (Classic)"}}
E["quest:419"] = {t="quest",n="The Lost Pilot",z="dunmorogh",s="At the wreck, Pilot Hammerfoot fears for Mori Hildelve in Dun Morogh's crags. Hildelve went on foot to seek rare ore for potent blastpowder, but days have passed and roars echo through the peaks.",h="At the wreck, Pilot Hammerfoot fears for Mori Hildelve in Dun Morogh's crags.",sec={{t="A Search Cut Short",b="Pilot Mori Hildelve drove his siege engine up Dun Morogh's steep ridges in search of rare ore for high-grade blastpowder. The machine broke on the slope. He left Pilot Hammerfoot at the camp to guard the wreck, then climbed higher into the frozen wilderness on foot.",sp=0},{t="Echoes in the Snow",b="Days passed, and Hildelve did not return to camp. At night, vicious growls echoed from the rocky crags. Hammerfoot's impatience gave way to dread. Hildelve was tough, but the frigid heights offered little shelter from prowling predators without his engine or heavy support.",sp=0},{t="A Grim Discovery",b="Mori Hildelve's trail ends in the crags. His remains lie exposed to the elements, mauled and stripped by mountain scavengers. Roughly scribbled notes are clutched in his lifeless hand. A Brigadier's Vest still drapes his ruined frame, marking the violent end of the siege engineer.",sp=1}},faq={{q="Why was Pilot Hildelve out in the wilderness alone?",a="Hildelve went into the wilderness to seek rare ore for high-grade dwarven blastpowder. When his siege engine broke on a steep slope, he continued into the crags on foot rather than abandon the search.",al={"why hildelve left","what was hildelve doing","pilot hildelve mission"},it="purpose"},{q="Who sends you to look for Hildelve?",a="Pilot Hammerfoot, Hildelve's friend and fellow siege engine operator, asks you to investigate. Hildelve left Hammerfoot behind to guard their damaged machinery while he scouted ahead.",al={"who gives quest","lost pilot quest giver"},it="identity"},{q="What happened to Hildelve's siege engine?",a="Hildelve damaged the siege engine's mechanics while driving it up a steep, icy hillside in search of ore. The machine was left stranded in the snow.",al={"broken siege engine","why engine broke"},it="history"},{q="What killed Pilot Hildelve?",a="Hammerfoot has heard beastly growls in the hills and fears for Hildelve. Following the pilot's trail reveals his fate.",al={"hildelve killer","how did pilot die","who killed hildelve"},sp=1,it="threat"},{q="What proof is found at Hildelve's remains?",a="Roughly scribbled notes are clutched in Hildelve's hand, and a Brigadier's Vest in fine condition remains around his frame.",al={"hildelve evidence","hildelve corpse items","proof of death"},sp=1,it="item"},{q="What happens after Hildelve's body is discovered?",a="Finding Hildelve reveals what happened during his search. The evidence found there carries the investigation onward.",al={"what next lost pilot","revenge quest"},sp=1,it="next_step"},{q="Why does Pilot Hammerfoot want you to find Hildelve?",a="Pilot Hammerfoot and Mori Hildelve are close friends and fellow Siege Engine pilots who journeyed into the hills together searching for rare ore. Mori set off on foot days ago after wrecking his engine, leaving Hammerfoot behind. Having heard ferocious growls echoing through the mountains every night since, Hammerfoot is deeply worried for his comrade's survival and desperate to learn his fate.",al={"why does hammerfoot want hildelve","pilot hammerfoot motive","why search for hildelve"},it="motive",add="da1c7c00"},{q="Why doesn't Pilot Hammerfoot look for Hildelve himself?",a="Before venturing into the snow-covered peaks alone, Hildelve explicitly charged Hammerfoot with guarding their valuable siege engines. With one machine damaged and both stranded out in the rugged wilds of Dun Morogh, Hammerfoot cannot abandon his post to launch a solitary search without leaving Ironforge's heavy machinery completely defenseless to wandering beasts and scavengers.",al={"why cant hammerfoot search","why does hammerfoot need me","why send an adventurer"},it="why_me",add="120a5684"}},ang={["race:Dwarf"]="As a dwarf, the loss of a skilled siege engine driver to wild beasts strikes close to home. Even Khaz Modan's familiar hills hold lethal dangers.",["profession:Engineering"]="As an engineer, you know the dwarves keep searching for volatile minerals to refine into potent explosives and blastpowder."},kw={"blastpowder","brigadier vest","dun morogh","lost pilot","mori hildelve","pilot hammerfoot","siege engine"},rel={"npc:pilot-hammerfoot","quest:417","zone:dunmorogh","topic:dwarf"},m={start="Pilot Hammerfoot",["end"]="Mori Hildelve",level="10",faction="Alliance",id=419},src={"The Lost Pilot (Classic)"}}
E["quest:420"] = {t="quest",n="Senir's Observations",z="dunmorogh",s="Grelin Whitebeard's report reaches his brother Senir in Kharanos, carrying news from Coldridge Valley. Its arrival sends Senir back to watching hostile forces across the snowfields.",h="Grelin Whitebeard's report reaches his brother Senir in Kharanos, carrying news from Coldridge Valley.",sec={{t="Through the Tunnel to Kharanos",b="Mountaineer Thalos guards the gate out of Coldridge Valley. He entrusts passing travelers with Grelin's dispatch. Beyond the gate, violent troggs ambush those crossing the tunnel and make the passage to Kharanos dangerous. Past the tunnel, the main road runs through central Dun Morogh to town.",sp=0},{t="A Grumpy Welcome and Senate Politics",b="At the Thunderbrew Distillery, Senir Whitebeard warms himself over drinks when Grelin's report arrives. He chuckles at his brother's forceful words. Grelin invokes King Magni Bronzebeard to press for urgent action, Senir says, and that will agitate the stubborn Ironforge Senate.\n\nThe bitter cold has kept Senir from filing his own observations. Grelin's dispatch sends him back to watching hostile forces across the snowfields.",sp=0}},faq={{q="Why is Mountaineer Thalos having a traveler deliver the report?",a="Mountaineer Thalos guards the Coldridge Valley tunnel against aggressive troggs and cannot leave his post. When a traveler passes through, he entrusts them with Grelin's dispatch for Kharanos.",al={"why thalos asks you","thalos courier","who gives this quest"},it="why_me"},{q="Who is Senir Whitebeard?",a="Senir Whitebeard is a dwarven scout and Grelin Whitebeard's brother. He is stationed in Kharanos, gathering field reports on local threats for Ironforge's high command.",al={"who is senir","senir whitebeard kharanos","senir background"},it="identity"},{q="What is in Grelin's report?",a="Grelin's report records his findings on Frostmane troll activity and incursions in Coldridge Valley. He invokes King Magni Bronzebeard's authority to press the authorities for reinforcements and attention.",al={"what does the report say","grelin report contents","grelins report lore"},it="item"},{q="Why does Senir say Grelin's report will ruffle feathers in the Senate?",a="Grelin invokes King Magni's name forcefully to demand action. That can challenge the Ironforge Senate's authority and pride, irritating members who favor formal deliberation.",al={"senate feathers ruffled","senir ironforge senate","why is the senate mad"},it="conflict"},{q="Why is the tunnel between Coldridge Valley and Kharanos dangerous?",a="Rockjaw troggs have emerged from deep subterranean cracks and seized the mountain tunnel. They attack dwarven travelers, merchants and messengers who try to pass.",al={"coldridge tunnel dangerous","trogg tunnel dun morogh","why are troggs in the tunnel"},it="danger"},{q="Where does the road lead after delivering this message?",a="Kharanos brings travelers into Dun Morogh's wider defense. Senir Whitebeard seeks help investigating Frostmane and trogg threats, while town leaders direct aid toward Brewnall Village, Ironforge and the outlying farms.",al={"what next after senir","next quest after senirs observations","where does kharanos lead"},it="next_step",gp=true},{q="Why does Mountaineer Thalos want this report delivered?",a="Mountaineer Thalos is stationed to guard the dangerous pass out of Coldridge Valley and cannot abandon his post. Grelin Whitebeard's reconnaissance on the trogg and troll threats is vital intelligence meant for his brother Senir, who coordinates broader defensive reports for Ironforge. Ensuring the report reaches Senir in Kharanos is crucial for warning the rest of Dun Morogh about the brewing dangers.",al={"why send grelins report","thalos motive","why deliver the report to senir"},it="motive",add="bc98cde7"}},ang={["race:Dwarf"]="As a dwarf, you leave the sheltered training valley for Kharanos and take a first step into Khaz Modan's defense. There, field scouts' concerns meet the Ironforge Senate's caution.",["race:Gnome"]="As a gnome, you travel through the pass to Kharanos and draw closer to Dun Morogh's main hubs and efforts to support your dwarven hosts.",["faction:Alliance"]="Coordinated scouting helps keep Dun Morogh secure while Stormwind is caught up in domestic strife and cannot spare aid for its northern allies."},kw={"coldridge valley","dun morogh","grelin whitebeard","grelin's report","ironforge senate","kharanos","mountaineer thalos","senir whitebeard","troggs"},rel={"quest:282","quest:218","quest:182","npc:senir-whitebeard","npc:mountaineer-thalos","subzone:kharanos","zone:dunmorogh","zone:ironforge"},m={start="Mountaineer Thalos",["end"]="Senir Whitebeard",level="5",faction="Alliance",id=420},src={"Senir's Observations (2)"}}
E["quest:432"] = {t="quest",n="Those Blasted Troggs!",z="dunmorogh",s="In Gol'Bolar Quarry, troggs wreck the workings while Foreman Stonebrow calls for help. They have broken his equipment and powder barrels. His fading aim keeps him from fighting them himself, so he asks willing fighters to thin the Skullthumpers.",h="In Gol'Bolar Quarry, troggs wreck the workings while Foreman Stonebrow calls for help.",sec={{t="Chaos in the Quarry",b="Troggs have overrun the lower terraces of Gol'Bolar Quarry in eastern Dun Morogh. They broke through the bedrock and flooded the tunnels, ending the dwarven excavation's productive days. Now they smash scaffolding and blow apart powder barrels, leaving the quarry in ruin.",sp=0},{t="Stonebrow's Boiling Rage",b="From the ridge, Foreman Stonebrow watches his life's work crumble. Age has weakened his hands and spoiled his aim, so he relies on passing wanderers and Alliance recruits to fight in his place. He wants the burly Rockjaw Skullthumpers thinned. Only their complete destruction would satisfy his anger.",sp=0}},faq={{q="Where is Gol'Bolar Quarry?",a="Gol'Bolar Quarry lies in eastern Dun Morogh, south of the main road east toward the gates of Loch Modan. Foreman Stonebrow stands on the rim above the excavation pits.",al={"gol'bolar location","where is the quarry","stonebrow location"},it="place",gp=true},{q="Why are the troggs attacking the quarry?",a="Troggs dwell deep beneath the earth across Khaz Modan. Dwarven excavations often break into the caverns where troggs nest, and they surge to the surface to overwhelm active mines.",al={"why troggs here","trogg invasion reason"},it="threat"},{q="Who is Foreman Stonebrow?",a="Foreman Stonebrow supervises Gol'Bolar Quarry. Bitter and hot-tempered, he sends willing fighters to clear out the troggs because his combat skills are fading.",al={"stonebrow","who gives quest"},it="identity"},{q="What is a Rockjaw Skullthumper?",a="Rockjaw Skullthumpers are brutish frontline enforcers of the trogg tribe in Gol'Bolar Quarry. They use raw strength and primitive clubs to bludgeon intruders.",al={"skullthumper","skullthumpers"},it="target"},{q="Why can't Stonebrow clear the quarry himself?",a="Stonebrow says his eyesight and aim have faded since his youth. Age leaves him at risk of being overwhelmed in the quarry pits, so he hires adventurers to fight there.",al={"why doesn't stonebrow fight"},it="why_me"},{q="What are the troggs destroying in the quarry?",a="Troggs are wrecking heavy equipment and disrupting mining at the quarry. They are also detonating supplies, including barrels of dwarven blasting powder.",al={"trogg destruction","what are troggs breaking"},it="conflict"},{q="Why does Foreman Stonebrow want the troggs killed?",a="Foreman Stonebrow is beside himself with fury watching his life's work get torn apart. The invading troggs have overrun the Gol'Bolar Quarry, smashing equipment and detonating his precious blasting powder. Left with nothing but stress and boiling anger, Stonebrow wants sheer vengeance: he wants to see every single trogg down there wiped out so his blood pressure can settle and order can eventually return to the site.",al={"stonebrow motive","why kill troggs","stonebrow quarry revenge"},it="motive",add="dd6a776f"}},ang={["race:Dwarf"]="As a dwarf, the troggs' invasion of Khaz Modan strikes close to home. The stonecutters have been driven from Gol'Bolar, making vengeance in the pit personal.",["profession:Mining"]="As a miner, you know Gol'Bolar for its stonecutting and mineral extraction. Clearing the invaders is the first step toward getting the picks swinging again."},kw={"dun morogh","gol'bolar","powder","quarry","rockjaw","skullthumper","stonebrow","troggs"},rel={"npc:foreman-stonebrow","subzone:gol-bolar-quarry","topic:trogg","zone:dunmorogh","topic:light"},m={start="Foreman Stonebrow",level="9",faction="Alliance",id=432},src={"Those Blasted Troggs! (Classic)"}}
E["quest:433"] = {t="quest",n="The Public Servant",z="dunmorogh",s="At Gol'Bolar Quarry, Senator Mehr Stonehallow calls for aid against troggs that have halted mining in Dun Morogh. He wants the Rockjaw Bonesnappers driven out so miners can return to work.",h="At Gol'Bolar Quarry, Senator Mehr Stonehallow calls for aid against troggs that have halted mining in Dun...",sec={{t="A Senator in the Field",b="Mehr Stonehallow serves in Ironforge's Senate and belongs to the Explorers' League. He has come to Gol'Bolar Quarry to direct the response himself. There, he hires travelers and mercenaries to drive the invaders from the mine.",sp=0},{t="The Disaster at Gol'Bolar",b="Deep digging at Gol'Bolar Quarry broke into sealed hollows underground. Rockjaw troggs poured into the pits, smashed mining equipment, and drove out the workers. Stonehallow wants the Rockjaw Bonesnappers cleared away so Mountaineers can secure the quarry and mining can resume.",sp=0}},faq={{q="Who is Senator Mehr Stonehallow?",a="Mehr Stonehallow serves in Ironforge's Senate and belongs to the Explorers' League. He has come to Gol'Bolar Quarry to direct the response to the trogg threat.",al={"stonehallow","senator stonehallow","who is the senator"},it="identity"},{q="Why is Gol'Bolar Quarry overrun with troggs?",a="Miners dug too deeply beneath Gol'Bolar Quarry and broke into caverns inhabited by Rockjaw troggs. The creatures surged into the pits, smashed equipment, and drove the workers away.",al={"why are troggs at gol bolar","quarry troggs","what happened to the quarry"},it="conflict"},{q="What are Rockjaw Bonesnappers?",a="Rockjaw Bonesnappers are fierce fighters among the Rockjaw troggs. They use crude weapons and brute force against dwarven miners and defenders.",al={"rockjaw bonesnapper","bonesnappers","bonesnapper troggs"},it="target"},{q="What is the plan after clearing out the troggs?",a="Once the troggs are driven out, Senator Stonehallow plans to bring in Ironforge Mountaineers. They will secure the quarry, rebuild its damaged equipment, and resume mining.",al={"stonehallow plan","what happens next gol bolar"},it="next_step"},{q="Why is the Explorers' League involved here?",a="Senator Stonehallow belongs to the Explorers' League. Its members investigate ancient excavations, underground ruins, and trogg incursions across the Khaz Modan mountains.",al={"explorers league mining","why league here"},it="allies"},{q="Where is Gol'Bolar Quarry located?",a="Gol'Bolar Quarry lies in southeastern Dun Morogh, in the snowy hills south of the road between Kharanos and the South Gate toward Loch Modan.",al={"gol bolar location","where is quarry"},it="place",gp=true},{q="Why does Senator Mehr Stonehallow want the troggs killed?",a="Senator Stonehallow views clearing Gol'Bolar Quarry as his civic duty as both an Explorers' League scholar and a member of Ironforge's Senate. The sudden trogg uprising wrecked vital mining machinery and drove out dwarven workers. Exterminating the pests is the essential first step toward reclaiming the site, repairing infrastructure, and getting the miners back underground.",al={"why kill troggs","mehr stonehallow motive","why clear gol'bolar"},it="motive",add="78fbc7a2"},{q="Why does Senator Stonehallow need an adventurer instead of the Mountaineers?",a="Ironforge's military forces are stretched thin across Dun Morogh dealing with trogg invasions and Frostmane troll raids. Senator Stonehallow has taken personal charge of the situation at Gol'Bolar Quarry, but the Mountaineers cannot safely establish a perimeter until the initial frontline of violent Rockjaw troggs is thinned out by willing travelers.",al={"why does mehr need me","why no mountaineers","why send an adventurer"},it="why_me",add="b5671d80"}},ang={["race:Dwarf"]="As a dwarf, you see the trogg breach at Gol'Bolar threaten your homeland's industry. Deep digging can bring danger from beneath the earth.",["profession:Mining"]="As a miner, you know what Gol'Bolar's closure costs. Troggs now hold the quarry's stone and ore veins.",["faction:Alliance"]="As an Alliance member, you depend on Ironforge's resources. Keeping Dun Morogh's quarries safe matters to the Alliance's supply."},kw={"bonesnapper","dun morogh","gol'bolar","quarry","rockjaw","senate","stonehallow","trogg"},rel={"subzone:gol-bolar-quarry","npc:senator-mehr-stonehallow","topic:trogg","zone:dunmorogh","topic:explorers-league"},m={start="Senator Mehr Stonehallow",level="11",faction="Alliance",id=433},src={"The Public Servant (Classic)"}}
E["quest:466"] = {t="quest",n="Search for Incendicite",z="dunmorogh",s="At Steelgrill's Depot, Pilot Stonegear seeks samples of volatile incendicite ore from the Wetlands. He believes its explosive force could change dwarven artillery, and needs you to reach a secluded cave and bring back the dangerous mineral.",h="At Steelgrill's Depot, Pilot Stonegear seeks samples of volatile incendicite ore from the Wetlands.",sec={{t="A Volatile Discovery",b="Siege engine pilots and mechanics at Steelgrill's Depot have heard of rare, unstable ore. Rich veins are rumored in a cavern northwest of Algaz Gate, in the Wetlands. Careless miners there risk having the reactive mineral detonate in their faces.",sp=0},{t="Munitions of Tomorrow",b="Pilot Stonegear sees military promise in the ore. Refined correctly, it could power dwarven artillery or serve as its payload. Cannon shells might gain enough force to break fortified defenses. He wants raw samples so researchers can test smelting methods without blowing up the depot.",sp=0}},faq={{q="What is incendicite ore used for?",a="Incendicite is an intensely volatile, explosive mineral. Pilot Stonegear wants to test smelting methods that could make it powerful artillery ammunition for cannon shells.",al={"incendicite uses","what does incendicite do"},it="why_wanted"},{q="Where is incendicite found?",a="The ore lies in a cave system northwest of Algaz Gate, in the southern mountains of the Wetlands.",al={"incendicite location","where to get incendicite"},it="place",gp=true},{q="Who is Pilot Stonegear?",a="Pilot Stonegear is a dwarven siege engine pilot with the Ironforge Siege Brigade. He is stationed at Steelgrill's Depot in Dun Morogh, where he works with mechanics and siege engineers to improve dwarven war machines.",al={"pilot stonegear","who gives this quest"},it="identity"},{q="Why does harvesting this ore require a pickaxe?",a="Incendicite lies in raw mineral veins, not loose on the surface. Miners need a practiced hand with a pick to chip the brittle, explosive ore from rock without setting it off.",al={"do i need mining","mining skill needed"},gp=true},{q="Is incendicite safe to handle?",a="No. Incendicite is notoriously unstable and may detonate during excavation, transport, or smelting.",al={"is incendicite dangerous","does incendicite explode"},it="danger"},{q="How does this connect to Stonegear's Search?",a="Pilot Longbeard or Mountaineer Kadrell sends you to Steelgrill's Depot after Pilot Stonegear hears rumors of rare ore and wants someone to find it. This follows 'Stonegear's Search'.",al={"stonegear search followup","quest chain"},it="ties"},{q="Why does Pilot Stonegear want incendicite ore?",a="Pilot Stonegear believes the volatile mineral holds untapped military potential. Incendicite is notoriously unstable and dangerous to handle, but he is convinced that properly smelted ore could be used to manufacture devastating cannon shells. Stationed at Steelgrill's Depot, Stonegear hopes to gather samples so Ironforge technicians can experiment with the explosive material and bolster their weaponry.",al={"why does stonegear want incendicite","stonegear incendicite motive","pilot stonegear goal"},it="motive",add="1b52d5e2"}},ang={["profession:Mining"]="As a miner, you need practiced hands to extract incendicite with a pick. Its volatility makes careful work essential.",["race:Dwarf"]="As a dwarf, you come from a people known for advancing gunpowder and artillery. Incendicite shells fit Khaz Modan's siege traditions.",["profession:Engineering"]="As an engineer, you know the risk of explosive compounds comes with seeking the next great blast."},kw={"algaz gate","artillery","cannon shells","dun morogh","incendicite","mining","ore","pilot stonegear","steelgrill's depot","wetlands"},rel={"npc:pilot-stonegear","subzone:steelgrill-s-depot","quest:467","zone:dunmorogh","zone:wetlands"},m={start="Pilot Stonegear",level="22",faction="Alliance",id=466},src={"Search for Incendicite"}}
E["quest:5541"] = {t="quest",n="Ammo for Rumbleshot",z="dunmorogh",s="Outside Anvilmar, Hegnar Rumbleshot needs ammunition for the riflemen at practice. A courier fled wendigo near the Grizzled Den and left a crate behind.",h="Outside Anvilmar, Hegnar Rumbleshot needs ammunition for the riflemen at practice.",sec={{t="A Courier's Flight",b="Loslor Rudge at Steelgrill's Depot supplies tradesmen across Dun Morogh, though wildlife often disrupts his shipments. His courier had camped near the Grizzled Den cave system when local wendigo crossed his path. He fled for his life and left the heavy wooden crate in the snow.",sp=0},{t="Powder and Shot",b="Hegnar Rumbleshot runs a gun shop beside the main road leading away from Anvilmar. Ironforge riflemen, mountaineers, and dwarven mortar squads gather in the clearing outside his forge to sight their weapons and practice with live fire. Without regular deliveries of powder and lead from suppliers like Loslor, the riflemen's marksmanship practice soon comes to a halt.",sp=0}},faq={{q="Where was the ammo crate lost?",a="The courier abandoned Loslor Rudge's shipment while camping just outside the Grizzled Den, a wendigo-infested cave in the snowy hills southwest of Kharanos.",al={"ammo location","where is rumbleshot ammo","crate location"},it="place",gp=true},{q="Who is Hegnar Rumbleshot?",a="Hegnar Rumbleshot is a dwarven gunsmith with a weapon shop along the road near Anvilmar. He supplies powder, bullets, and firearms to mountaineers, hunters, and siege teams drilling nearby.",al={"who is hegnar","rumbleshot","hegnar rumbleshot"},it="identity"},{q="Why was the courier chased off?",a="The courier camped near the Grizzled Den, home to savage, territorial wendigo that roam the hills southwest of Kharanos.",al={"why courier ran","wendigo attack","courier story"},it="threat"},{q="Why is Hegnar Rumbleshot out of ammunition?",a="Dwarven riflemen and mortar teams use up powder and lead as they practice target drills near Hegnar's shop, keeping demand for his ammunition high.",al={"why low on ammo","rumbleshot out of ammo"},it="purpose"},{q="Who is Loslor Rudge?",a="Loslor Rudge is a dwarven engineering supplier at Steelgrill's Depot who ships ammunition to Hegnar Rumbleshot.",al={"loslor rudge","who is loslor"},it="identity"},{q="Does recovered ammunition spoil in the snow?",a="Dwarven munitions are traditionally packed in heavy, weather-sealed wooden crates to keep black powder dry and ready to burn, even in Dun Morogh's sub-zero blizzards.",al={"ammo ruined by snow","wet powder"}},{q="Why does Loslor Rudge need this ammo delivered?",a="Loslor Rudge operates out of Steelgrill's Depot and supplies vendors across Dun Morogh. Hegnar Rumbleshot is waiting on an overdue shipment to keep local riflemen and mortar teams supplied with practice rounds. A courier panicked and abandoned the crate when wendigo attacked their camp, leaving Loslor's business commitment unfulfilled and a valued customer empty-handed until you recover it.",al={"why does loslor care","loslor rudge motive","why send the ammo"},it="motive",add="76205b16"},{q="What is Rumbleshot's Ammo used for?",a="The crate contains fresh ammunition meant for Hegnar Rumbleshot's shop along the road to Anvilmar. Dwarven riflemen and mortar teams frequently train nearby and burn through supplies quickly, relying on Hegnar to keep their powder horns and shot pouches filled.",al={"what is rumbleshot ammo","rumbleshot crate use","why is ammo needed"},it="item",add="c1dcb566"}},ang={["class:Hunter"]="As a hunter in Coldridge, you know Hegnar's shop well. His fresh powder and shot help keep your rifle ready for the wilderness.",["race:Dwarf"]="As a dwarf, you know your craftsmanship depends on a steady supply line between Anvilmar's smithies and frontline gunsmiths like Rumbleshot.",["profession:Engineering"]="As an engineer, you know dwarven firearms and mortars need finely milled powder and uniform shot. Rumbleshot's stock matters to local tinkerers and gunners."},kw={"ammo","anvilmar","coldridge","grizzled den","hegnar","loslor rudge","rumbleshot","wendigo"},rel={"npc:hegnar-rumbleshot","npc:loslor-rudge","subzone:grizzled-den","quest:313","subzone:anvilmar","zone:dunmorogh"},m={start="Loslor Rudge",["end"]="Hegnar Rumbleshot",level="6",faction="Alliance",id=5541,ri={"Rumbleshot's Ammo"}},src={"Ammo for Rumbleshot"}}
E["quest:5625"] = {t="quest",n="Garments of the Light",z="dunmorogh",s="At Maxan Anvol’s urging, you go south of Kharanos to help a wounded mountaineer before you receive the Garments of the Light.",h="At Maxan Anvol’s urging, you go south of Kharanos to help a wounded mountaineer before you receive the...",sec={{t="An Urgent Trial",b="Maxan Anvol, the priest trainer, asks for practical aid before ceremony. Acolytes usually face formal trials to prove they deserve church vestments. But Mountaineer Dolf is wounded, and he needs help now.",sp=0},{t="Aiding the Mountaineers",b="South of Kharanos, you find Mountaineer Dolf wounded in the line of duty. Restorative prayers mend his injuries. Power Word: Fortitude strengthens him and helps keep an Ironforge defender alive.",sp=0},{t="Robes of the Church",b="Once Dolf has received aid, Maxan Anvol presents you with formal garments. The robes give warmth against Dun Morogh’s chill and mark you as a servant of the Light. You are ready to aid wounded wanderers and local guards.",sp=0}},faq={{q="What is the purpose of this quest?",a="Maxan Anvol tests whether a novice priest can use early spells to help someone in need. You find the injured Mountaineer Dolf south of Kharanos, heal his wounds, and strengthen him with Power Word: Fortitude.",al={"what do i do","garments of the light goal"},it="purpose"},{q="Who is Maxan Anvol?",a="Maxan Anvol is the dwarven priest trainer in Kharanos. He mentors young priests arriving from Coldridge Valley and favors the Light’s direct work of saving lives over strict formal liturgy.",al={"who is maxan anvol","kharanos priest trainer"},it="identity"},{q="Who is Mountaineer Dolf?",a="Dolf is an Ironforge mountaineer stationed near Kharanos, injured on patrol. He waits south of the settlement, where initiates are sent to mend his wounds and grant him Fortitude.",al={"dolf location","who is dolf"},it="identity"},{q="Why does a priest receive specific garments for this task?",a="Vestments and robes show a practitioner’s devotion and rank within the Holy Light. Soldiers and other community members can recognize a robed priest who can tend life-threatening injuries and offer spiritual guidance.",al={"why do priests wear robes","priest garments lore"},it="item"},{q="Why do dwarves worship the Holy Light?",a="The dwarves of Ironforge adopted the Holy Light through centuries of close cultural exchange and alliance with the humans of Lordaeron and Stormwind. Dwarven priests join traditional highland grit with reverence for compassion, tenacity, and protection.",al={"dwarf light lore","do dwarves believe in the light"},it="history"},{q="What happens after completing this trial?",a="After the trial, Maxan Anvol encourages the newly vested acolyte to venture out, practice combat and support spells, and test their limits alongside other travelers. Harder trials within the church await as the priest grows in experience and power.",al={"what comes after garments of the light","next priest trial"},it="next_step"},{q="Why does Maxan Anvol want you to heal Dolf?",a="Priests of your standing are normally put through formal trials to prove they are worthy of wearing church vestments. However, Maxan Anvol has more pressing matters on his mind and received word that Mountaineer Dolf lies injured just south of Kharanos. Rather than conducting an idle test, Maxan uses this real emergency to see if you can put your faith into practice by mending and bolstering an ally on the field.",al={"why does maxan send you","maxan anvol motive","why help mountaineer dolf"},it="motive",add="21e41a20"},{q="Why does Maxan Anvol send you instead of tending to Dolf himself?",a="Maxan is tied down with broader duties tending to the parish and church matters in Kharanos, and you happen to be standing before him in need of your trial. Sending you out into the snow solves two problems at once: it provides immediate aid to the wounded mountaineer and simultaneously proves whether your training in the Light has prepared you for the harsh realities of Dun Morogh.",al={"why can't maxan heal dolf","why does maxan need me","why send an initiate"},it="why_me",add="574078e1"}},ang={["class:Priest"]="As a priest, you move from novice to recognized minister of the Holy Light, trusted to keep companions alive on the front lines.",["race:Dwarf"]="As a dwarf, you know Ironforge mountaineers guard Dun Morogh’s dangerous passes. Tending wounded scouts like Dolf strengthens the bond between dwarven faith and military defense.",["faction:Alliance"]="As an Alliance member, you look to the Holy Light for comfort and battlefield healing while soldiers hold the line against troggs, beasts, and worse."},kw={"dun morogh","fortitude","garments of the light","holy light","ironforge","kharanos","lesser heal","maxan anvol","mountaineer dolf","priest"},rel={"quest:5623","npc:maxan-anvol","subzone:kharanos","zone:dunmorogh","topic:light"},m={start="Maxan Anvol",level="4",faction="Alliance",id=5625},src={"Garments of the Light (Dun Morogh)"}}
E["quest:5626"] = {t="quest",n="In Favor of the Light",z="dunmorogh",s="Branstock Khalder sends a young priest from Coldridge Valley through the mountain pass to Kharanos for further study. There, Priest Trainer Maxan Anvol prepares the novice for greater duties and a chance to earn their first formal vestments.",h="Branstock Khalder sends a young priest from Coldridge Valley through the mountain pass to Kharanos for...",sec={{t="Leaving the Anvil",b="You leave Anvilmar after showing dedication and understanding of Holy magic. Branstock Khalder sends promising novices beyond the mountains, where priests meet Dun Morogh’s needs and help defend its people.",sp=0},{t="A Step Toward Kharanos",b="The Coldridge Pass tunnel opens into central Dun Morogh, where Priest Trainer Maxan Anvol guides you beyond basic prayers. He teaches that service to the Holy Light calls for moral character, physical hardiness, and an unyielding will. Prove your resolve under his guidance, and you may receive your first formal garments of office.",sp=0}},faq={{q="Who sends you on this journey?",a="Branstock Khalder, the priest trainer at Anvilmar in Coldridge Valley, sends you to Kharanos for further study after you show aptitude with the Holy Light.",al={"who gives quest","quest giver","branstock khalder"},it="identity"},{q="Who is Maxan Anvol?",a="Maxan Anvol is the priest trainer in the mountain village of Kharanos. He guides developing priests and teaches them to unite devotion with physical endurance and mental fortitude.",al={"maxan anvol lore","who is maxan anvol","kharanos priest trainer"},it="identity"},{q="What happens after reaching Maxan Anvol?",a="Maxan Anvol asks you to prove your worth by helping injured locals in Garments of the Light. Afterward, he awards you your first official priest robes.",al={"next quest","what follows in favor of the light","garments of the light"},it="next_step"},{q="Why must priests leave Coldridge Valley so early?",a="Coldridge Valley teaches the basics of combat and spellcraft. In Kharanos, priests meet the needs and dangers of a wider community and learn to serve its people.",al={"why leave coldridge","leaving anvilmar","why go to kharanos"},it="why_here"},{q="Do human priests receive this same quest?",a="Human priests in Elwynn Forest undertake the same rite under the same name. Priestess Anetta in Northshire sends them to Priestess Josetta in Goldshire.",al={"human in favor of the light","northshire version"}},{q="How does the dwarven view of the Light differ here?",a="Dwarves value physical strength, will, and practical endurance alongside piety. Maxan Anvol teaches that serving the Light in freezing mountain peaks calls for strength of body as well as faith.",al={"dwarf light beliefs","dwarves and the light"},it="origin"},{q="Why does Branstock Khalder send you to Kharanos?",a="Branstock recognizes that you have advanced past the basic teachings in Coldridge Valley. To continue your spiritual journey and earn the vestments appropriate for an ordained servant of the Holy Light, he sends you to Maxan Anvol, a senior priest in Kharanos who can test your worthiness and guide your next steps.",al={"why send me to kharanos","branstock khalder motive","why visit maxan anvol"},it="motive",add="7dcff5c0"}},ang={["class:Priest"]="As a priest, you leave basic training for active service and receive your first vestments.",["race:Dwarf"]="As a dwarf, you join spiritual devotion with practical resilience as you leave Coldridge for Dun Morogh’s freezing winds."},kw={"branstock khalder","coldridge valley","dun morogh","in favor of the light","kharanos","light","maxan anvol","priest","vestments"},rel={"quest:5624","npc:maxan-anvol","npc:branstock-khalder","subzone:kharanos","zone:dunmorogh","topic:light","quest:5623"},m={start="Branstock Khalder",["end"]="Maxan Anvol",level="4",faction="Alliance",id=5626},src={"In Favor of the Light (Dun Morogh)"}}
E["quest:6064"] = {t="quest",n="Taming the Beast",z="dunmorogh",s="In Dun Morogh, Taming the Beast sets a hunter on the first trial toward mastering companion beasts. In Kharanos, Grif Wildheart guides young trackers as they calm a Large Crag Boar with an enchanted taming rod.",h="In Dun Morogh, Taming the Beast sets a hunter on the first trial toward mastering companion beasts.",sec={{t="A Hunter's Companion",b="Dwarven mountaineers and trackers depend on guns, traps, and their wits in the wild. Yet a hunter's calling is to make a lifelong bond with a wild beast. Outside the Thunderbrew Distillery in Kharanos, Grif Wildheart oversees this rite. He tests novices against several species native to Dun Morogh before asking them to bind any beast for good.",sp=0},{t="The Crag Boar",b="A Large Crag Boar is the first test for a young tracker. These thick-hided swine roam Dun Morogh's snowy foothills, where their bristling fur and tough flesh make them stubborn and fierce. Grif provides an enchanted Taming Rod. The hunter faces the boar's charge and tries to calm its fury until it submits to command.",sp=0}},faq={{q="Who offers this trial?",a="Grif Wildheart offers the trial outside the Thunderbrew Distillery in Kharanos, where he trains dwarven hunters.",al={"quest giver","who starts taming the beast","grif wildheart location"},it="identity"},{q="Why do I tame a Large Crag Boar first?",a="Large Crag Boars are sturdy and stubborn, yet plentiful across Dun Morogh's snowy ridges. Taming one gives you a first chance to command an aggressive, thick-skinned beast calmly.",al={"why crag boar","what beast do i tame","boar taming"},it="target"},{q="Do I get to keep this boar forever?",a="No. The bond formed with the Taming Rod is temporary. You can command the boar, then return the rod and try other species.",al={"is this boar permanent","keep crag boar","can i keep the pet"},gp=true},{q="Where can I find Large Crag Boars?",a="Large Crag Boars roam the open snowfields and pine groves around Kharanos, as well as Dun Morogh's frozen slopes.",al={"boar locations","where are large crag boars","large crag boar spawn"},it="place",gp=true},{q="What comes after taming the crag boar?",a="When you return to Grif Wildheart, the first lesson is complete and the second trial begins: taming a Snow Leopard.",al={"next trial","what is after this quest","hunter chain next"},it="next_step"},{q="How does the Taming Rod work?",a="Hunter trainers provide an enchanted Taming Rod to help novices channel their will and calm wild instincts. No advanced magical training or lifelong experience with beast-whispering is needed.",al={"taming rod lore","what is the rod","how do i tame"},it="item"},{q="Why does Grif Wildheart want you to tame a beast?",a="Grif Wildheart is training you in the fundamentals of being a true dwarven hunter. In his eyes, knowing how to bond with and command a beast companion is just as crucial as maintaining your weapon. Rather than handing you a pet, he believes the only proper way to learn is through hands-on experience in the wild, testing your patience and mastery against different kinds of local creatures before you choose a permanent companion.",al={"grif wildheart motive","why tame a beast","grif wildheart training reason"},it="motive",add="49cdd252"}},ang={["class:Hunter"]="As a Hunter, you cross from novice marksman to beast master and begin the trials that unlock permanent animal companions.",["race:Dwarf"]="As a Dwarf, you follow Ironforge mountaineers, who revere beasts able to endure Dun Morogh's biting cold. Beginning with the rugged crag boar reflects dwarven respect for grit and resilience."},kw={"beast","boar","crag boar","dun morogh","grif wildheart","hunter","kharanos","taming","taming rod"},rel={"npc:grif-wildheart","subzone:kharanos","zone:dunmorogh","quest:6065","quest:6081","quest:6061","topic:dwarf"},m={start="Grif Wildheart",["end"]="Grif Wildheart",level="10",faction="Alliance",id=6064},src={"Taming the Beast (Dwarf 1)"}}
E["quest:6074"] = {t="quest",n="The Hunter's Path",z="dunmorogh",s="In Dun Morogh, the trainers send ready hunters to Kharanos to begin learning how to tame wild beasts. Grif Wildheart oversees the trials there.",h="In Dun Morogh, the trainers send ready hunters to Kharanos to begin learning how to tame wild beasts.",sec={{t="A Hunter's True Calling",b="Novice hunters cross Dun Morogh’s snowy crags alone until they learn to bond with beasts. Olmin Burningbeard and Tristane Shadowstone watch their pupils closely. They wait until a hunter can face a savage creature calmly and spare its life. Then the trainers send the disciplined novice down the mountain roads toward Kharanos.",sp=0},{t="Reporting to Grif Wildheart",b="In Kharanos, Grif Wildheart oversees the final trials of dwarven huntsmanship. Taming a beast takes more than bringing it down for meat or pelt. A hunter needs patience, physical endurance, and an instinctive bond with the wild predators of the mountains. Wildheart prepares each hunter to test their will against Dun Morogh’s fiercest wildlife.",sp=0}},faq={{q="What is the purpose of this quest?",a="Ready hunters travel to Kharanos to begin taming trials under Grif Wildheart.",al={"why do this quest","what is hunter's path","hunter pet quest start"},it="purpose"},{q="Who sends me on this path?",a="Hunter trainers direct their pupils along this path. They include Olmin Burningbeard in Ironforge's Hall of Arms, Tristane Shadowstone, and Einris Brightspear.",al={"quest giver","who gives hunters path","where to pick up"},it="identity"},{q="Where can I find Grif Wildheart?",a="Grif Wildheart waits outside the Thunderbrew Distillery in Kharanos, in Dun Morogh's snowy valley.",al={"grif wildheart location","where is grif","kharanos hunter trainer"},it="place",gp=true},{q="Why do hunters need a trainer to tame beasts?",a="Hunters use special techniques and a taming rod to commune with wild beasts without provoking a fight to the death. Grif Wildheart teaches these traditions.",al={"why need taming training","lore behind pet taming","why cant i tame yet"},it="history"},{q="What happens after reporting to Grif Wildheart?",a="After you report to Grif Wildheart, he tests your mettle. He sends you into the wilderness with a taming rod to subdue several distinct beasts native to Dun Morogh.",al={"next quest","what follows hunters path","chain after this"},it="next_step"},{q="Can any hunter take this specific quest?",a="This summons directs dwarven hunters in Dun Morogh to the local trainer in Kharanos.",al={"is this dwarf only","can night elves do this","race restriction"},gp=true},{q="Why do the hunter trainers send you to Grif Wildheart?",a="Your trainers recognize that you have developed the basic prowess necessary to commune with and manage wild beasts. Rather than continuing standard martial instruction, they direct you to Grif Wildheart in Kharanos so you can undergo specialized training. In their eyes, mastering the art of beast companionship is the essential next milestone in your growth as a true hunter.",al={"why send me to grif","hunter trainers motive","why see grif wildheart"},it="motive",add="5e8bda0f"}},ang={["class:Hunter"]="As a hunter, you begin to leave solitary tracking behind and learn to command wild predators.",["race:Dwarf"]="As a dwarf, you know mountaineers have long kept bears and boars as trusted scouting companions across Dun Morogh's snowy peaks."},kw={"dun morogh","grif wildheart","hunter","kharanos","olmin burningbeard","pet quest","taming","tristane shadowstone"},rel={"npc:grif-wildheart","quest:6061","quest:6081","subzone:kharanos","zone:dunmorogh","topic:dwarf"},m={start="Olmin Burningbeard, Tristane Shadowstone, Einris Brightspear",["end"]="Grif Wildheart",level="10",faction="Alliance",id=6074},src={"The Hunter's Path (Dwarf)"}}
E["quest:6084"] = {t="quest",n="Taming the Beast",z="dunmorogh",s="Grif Wildheart sends you to face a snow leopard in the second taming trial. The test reaches beyond the crag boar.",h="Grif Wildheart sends you to face a snow leopard in the second taming trial.",sec={{t="A Lesson in Finesse",b="Snow leopards prowl southeast of Kharanos. The crag boar tested your strength against hard blows. Now Grif expects you to face a swift, graceful predator on its own terms. Beneath its white coat lies dangerous strength, ready to strike.",sp=0},{t="Mastering the Taming Rod",b="With an enchanted taming rod, you face a wild snow leopard and seek to turn its hunting instincts toward partnership. Its speed, agility, and sharp reflexes test you in ways the crag boar did not. Learn to work alongside a predator that strikes swiftly from the snowy crags, and you draw closer to mastering the beasts of the wild.",sp=0}},faq={{q="What is the purpose of this quest?",a="This is the second trial in the dwarf hunter rite of passage. Grif Wildheart tests your skill against different beasts before teaching you to form lasting bonds with animal companions.",al={"why do this quest","snow leopard quest dwarf","taming the beast 2"},it="purpose"},{q="Where do I find the snow leopards?",a="Snow leopards prowl the rocky crags and snowy slopes south and east of Kharanos in Dun Morogh.",al={"snow leopard location","where are snow leopards dun morogh","leopard location"},it="place",gp=true},{q="Why does Grif Wildheart want me to tame a leopard?",a="Grif Wildheart wants you to learn both strength and finesse. The crag boar relies on resilience, while the snow leopard teaches you to fight alongside a swift, agile, deadly companion.",al={"why snow leopard","grif wildheart leopard reasoning"},it="motive"},{q="Do I get to keep this snow leopard permanently?",a="No. The beasts you tame in these first trials are temporary partners, bound by the taming rod's magic. When Grif considers your training complete, you can permanently tame any wild beast you choose.",al={"can i keep the snow leopard","is the leopard permanent"},gp=true},{q="Who assigns this trial?",a="Grif Wildheart, the dwarf hunter trainer outside the inn in Kharanos, Dun Morogh, assigns this trial.",al={"who gives quest","quest giver","grif wildheart role"},it="identity"},{q="What comes next in the chain?",a="After you master the snow leopard, Grif sends you to face an Ice Claw Bear in the third and final taming trial. Then he teaches you to tame and train wild beasts on your own.",al={"next quest","what after snow leopard"},sp=1,it="next_step"},{q="What kind of beast is the snow leopard?",a="Snow leopards are swift, agile predators native to the snowy ridges of Dun Morogh. Unlike the sturdy and stubborn crag boars of your first trial, these large white cats rely on finesse, speed, and lethal strikes. Grif Wildheart directs you to them so you can learn how to handle a delicate, aggressive hunting partner that fights very differently from a brute beast.",al={"snow leopard lore","why tame snow leopard","snow leopards dun morogh"},it="target",add="baf34ad8"},{q="Why does Grif Wildheart have me tame the snow leopard myself?",a="This is your rite of passage as a young hunter, not a chore Grif needs handled for the town. Taming requires establishing personal dominance and empathy with wild beasts. Grif already knows the craft; you are the one who must learn how to channel the taming rod's magic and withstand a charging predator to prove you are ready to command a lifelong companion.",al={"why do i have to tame it","why me taming rod","why grif wildheart sends me"},it="why_me",add="4533de88"}},ang={["class:Hunter"]="As a hunter, you learn how boars endure punishment while cats strike with speed and aggression.",["race:Dwarf"]="As a dwarf, you share Dun Morogh's frozen peaks with snow leopards, whose stealth and hunting skill command respect."},kw={"dun morogh","grif wildheart","hunter quest","kharanos","snow leopard","taming rod","taming the beast"},rel={"npc:grif-wildheart","quest:6061","quest:6081","quest:6065","subzone:kharanos","zone:dunmorogh","topic:dwarf"},m={start="Grif Wildheart",level="10",faction="Alliance",id=6084},src={"Taming the Beast (Dwarf 2)"}}
E["quest:6085"] = {t="quest",n="Taming the Beast",z="dunmorogh",s="In Dun Morogh, Grif Wildheart tests your control of an Ice Claw Bear east of Kharanos. With an enchanted rod, you subdue the bear and learn to understand it. Then you earn the power to tame, call, and dismiss a lasting wild companion.",h="In Dun Morogh, Grif Wildheart tests your control of an Ice Claw Bear east of Kharanos.",sec={{t="The Strength of the Wild",b="Dun Morogh’s mountaineers and scouts depend on hardy beasts in its freezing crags. You have practiced on swift, cunning predators. Now Grif Wildheart sends you to capture an Ice Claw Bear in the snowdrifts east of Kharanos. Its strength and endurance test the control every dwarven huntsman must learn.",sp=0},{t="Earning a Companion",b="The Taming Rod keeps the bear docile while you learn how wild instincts answer to will and calm intent. Your bond lasts only for the trial, which teaches discipline. Return the rod to Grif and the trials are complete. He then teaches you to pacify a compatible wild creature and call it throughout your life of adventure.",sp=0}},faq={{q="What animal do I need to tame for this quest?",a="You need to tame an Ice Claw Bear in the frozen foothills east of Kharanos in Dun Morogh. The Taming Rod subdues it while you learn to handle its brute force.",al={"which bear","target animal","taming target"},it="target",gp=true},{q="Do I keep the Ice Claw Bear after turning in the quest?",a="No. The Ice Claw Bear subdued by the Taming Rod is only a temporary test of discipline and skill. When you return the rod to Grif Wildheart, the bear departs, and you gain the abilities to tame any wild beast you choose.",al={"do i keep the bear","keep pet","is bear permanent"},gp=true},{q="Where is Grif Wildheart located?",a="Grif Wildheart is outside the Thunderbrew Distillery in Kharanos, Dun Morogh. He trains fledgling hunters in marksmanship and beast mastery.",al={"grif location","where is grif","hunter trainer kharanos"},it="place",gp=true},{q="What abilities do I learn upon finishing this trial?",a="You learn Tame Beast, Call Pet, and Dismiss Pet. These abilities let you venture into the world with a permanent companion.",al={"quest rewards","hunter skills learned","tame beast reward"},gp=true},{q="What is the next step after completing this quest?",a="Grif sends you on to Training the Beast. There, you learn to feed, nurture, and instruct your new companion so it stays loyal in combat.",al={"next quest","what comes next","training the beast"},it="next_step",gp=true},{q="Why does Grif have hunters test multiple types of beasts?",a="The three trials introduce different fighting styles: agility, cunning, and brute power. These temperaments help a mountaineer choose a companion suited to their hunting style.",al={"why three beasts","purpose of trials","three animals"},it="motive"},{q="What are Ice Claw Bears and why are they around Kharanos?",a="Ice Claw Bears are sturdy, thick-furred predators native to the snowy crags of Dun Morogh, commonly prowling the wilderness east of Kharanos. Grif Wildheart considers them an ideal companion for a developing hunter because of their raw fortitude and brute strength. Facing one forces you to prove you can stand your ground against immense physical power and dominate a truly hardy mountain beast before claiming full mastery over wild creatures.",al={"ice claw bear lore","why tame ice claw bear","ice claw bears dun morogh"},it="target",rc="Dwarf",add="d0a90924"}},ang={["class:Hunter"]="As a hunter, you begin as an isolated archer and become a true beast-tamer. You gain the essential abilities to tame and summon beasts.",["race:Dwarf"]="As a dwarf, you know bears as favored companions of Dun Morogh’s mountaineers. They are renowned for matching their masters’ stubborn resilience."},kw={"dun morogh","grif wildheart","hunter quest","ice claw bear","kharanos","pet taming","taming rod","taming the beast"},rel={"npc:grif-wildheart","subzone:kharanos","quest:6081","quest:6065","zone:dunmorogh","topic:dwarf"},m={start="Grif Wildheart",level="10",faction="Alliance",id=6085},src={"Taming the Beast (Dwarf 3)"}}
E["quest:6086"] = {t="quest",n="Training the Beast",z="dunmorogh",s="In Dun Morogh, Grif Wildheart sends young dwarven hunters to Ironforge to learn care for a lasting animal companion. After taming the mountain’s wild predators, they learn to feed and train their beasts.",h="In Dun Morogh, Grif Wildheart sends young dwarven hunters to Ironforge to learn care for a lasting animal...",sec={{t="From the Wild to the Forge",b="Young hunters finish their trial near Kharanos under Grif Wildheart’s watch. They have tamed large crag boars, snow leopards, and sturdy ice claw bears with a taming rod. Then Grif sends them up the mountain pass to Ironforge. They seek the Hall of Arms in the military district.",sp=0},{t="Belia Thundergranite's Teachings",b="Belia Thundergranite teaches animal care in Ironforge’s Hall of Arms. Revered among the dwarven kingdom’s master animal trainers, she shows young hunters how to nourish their pets and teach them new battlefield skills. She also teaches them to call their spirits back if they fall defending their master. Her lessons turn a frightened wild beast into a loyal partner.",sp=0},{t="The Dwarven Hunter's Bond",b="Dwarven tradition asks for respect between hunter and beast, never subjugation. Belia reminds young hunters that an animal companion reflects the care it receives. Fed well, respected, and properly trained, a beast will fight loyally against troggs, frost trolls, and any threat to Khaz Modan.",sp=0}},faq={{q="What is the purpose of this quest?",a="Training the Beast completes a dwarf hunter’s foundational training. You learn to care for a lasting animal companion, feed and train it, call it to your side, and bring it back if it dies.",al={"why do this quest","training the beast purpose","hunter pet quest reward"},it="purpose"},{q="Who is Belia Thundergranite?",a="Belia Thundergranite is a revered master animal trainer and senior instructor in Ironforge’s Hall of Arms. She teaches dwarf hunters care, discipline, and commands that turn tamed beasts into lifelong allies.",al={"who is belia","belia thundergranite lore","hunter trainer ironforge"},it="identity"},{q="Where do I find Belia Thundergranite?",a="Belia Thundergranite is in Ironforge’s Hall of Arms, the city’s military wing. Dwarf and gnome warriors, hunters, and paladins gather and train there.",al={"belia location","where is belia thundergranite","where is hall of arms ironforge"},it="place",gp=true},{q="What beasts do dwarven hunters tame before receiving this training?",a="Before this training, young hunters use a taming rod to soothe a large crag boar, a snow leopard, and an ice claw bear in Dun Morogh. Grif Wildheart oversees these trials.",al={"what beasts do you tame","dwarf pet trial beasts","prior quests beasts"},it="history"},{q="Why must dwarven hunters feed their pets?",a="Dwarven beast lore treats animal companions as partners, not tools. A hungry pet grows sullen and less willing to fight. Keep it well-fed to earn its fierce loyalty and help it fight at its best.",al={"why feed pet","pet happiness lore","beast loyalty dwarf"},it="purpose"},{q="Who gives this quest?",a="Grif Wildheart is a veteran hunter trainer beside the road east of Kharanos in Dun Morogh. He gives this training after you complete your third taming trial.",al={"who starts training the beast","grif wildheart role","quest giver"},it="people"},{q="Why does Grif Wildheart send you to Ironforge?",a="Grif Wildheart has guided your basic trials across the crags of Dun Morogh, teaching you to tame wild beasts. However, mastering the care, feeding, and discipline of a beast companion requires advanced expertise. Grif sends you to Ironforge so that Belia Thundergranite, one of the dwarves' most respected master trainers in the Hall of Arms, can complete your education and ensure your pet becomes a steadfast ally.",al={"why does grif send you","grif wildheart motive","why go to ironforge hunter"},it="motive",add="5ee43731"}},ang={["class:Hunter"]="As a hunter, you learn to feed, command, and revive a lasting animal companion.",["race:Dwarf"]="As a dwarf, you inherit Khaz Modan’s tradition of treating bears, boars, and mountain cats as partners in exploring and defending the mountainous wilderness.",["faction:Alliance"]="As an Alliance member, you rely on Ironforge’s beastmasters. Their loyal companions contribute heavily to Alliance scouting forces and patrol the frigid mountain passes."},kw={"belia thundergranite","dun morogh","dwarf hunter","grif wildheart","hall of arms","ironforge","pet training","training the beast"},rel={"npc:grif-wildheart","quest:6061","quest:6065","zone:ironforge","zone:dunmorogh","topic:dwarf"},m={start="Grif Wildheart",["end"]="Belia Thundergranite",level="10",faction="Alliance",id=6086},src={"Training the Beast (Dwarf)"}}
E["quest:637"] = {t="quest",n="Sully Balloo's Letter",z="dunmorogh",s="At the Thandol Span, Sully Balloo's Letter carries a dwarf's last words to his wife in Ironforge. Found beneath the bridge, it tells where he died.",h="At the Thandol Span, Sully Balloo's Letter carries a dwarf's last words to his wife in Ironforge.",sec={{t="A Voice from the Riverbed",b="Beneath the stone pilings of the Thandol Span, the land bridge between the Wetlands and the Arathi Highlands, a drowned skeleton still clutches an envelope. Its water-damaged pages begin, “My dear Sara,” and preserve the tenderness of Sully Balloo's careful writing.",sp=0},{t="The Price of the Span",b="Alliance forces and their enemies have fought fiercely for the Thandol Span. Dark Iron saboteurs and warbands contesting the borderlands have threatened the crossing. Sully Balloo was among the dwarven soldiers sent north to defend it. His family in the mountains knew nothing of his fate until a diver brought his farewell letter up from beneath the waves.",sp=0},{t="A Widow in Ironforge",b="In Ironforge, Sully's widow Sara Balloo receives the letter and learns where her husband died. Grief and lingering hope had left her unsure whether he was missing or lost forever. His handwritten words force her at last to face the bitter truth of his death.",sp=1}},faq={{q="Where is Sully Balloo's letter found?",a="Sully Balloo's Letter was found in a drowned skeleton's hand beneath the stone pillars of the Thandol Span, between the Wetlands and the Arathi Highlands.",al={"letter location","where is sully balloo","thandol span skeleton"}},{q="Who was Sully Balloo?",a="Sully Balloo was an Alliance dwarven soldier who fell defending the Thandol Span. Before taking watch over the span, he wrote a farewell letter to his wife Sara. His remains and the letter were found beneath the icy waters.",al={"who is sully","sully balloo lore","who was sully balloo"}},{q="Who is Sara Balloo?",a="Sara Balloo is Sully's widow, living in Ironforge. She has spent months waiting for news of her husband's fate on the northern frontier.",al={"where is sara balloo","who is sara","sara balloo location"}},{q="What happens after you deliver the letter?",a="After Sara learns of Sully's death, sorrow overtakes her. She asks that he be memorialized, bringing a further request in Ironforge.",al={"what next","sully quest chain","after delivering letter"},sp=1},{q="Why was the letter still intact underwater?",a="The envelope clutched in the soldier's remains protected the letter. By the time it was retrieved, the pages were waterlogged and partly dissolved. Enough of Sully's careful writing remained legible to read.",al={"why is letter readable","how did envelope survive"}},{q="What real-world inspiration is behind this quest?",a="The story honors Major Sullivan Ballou of the 2nd Rhode Island Infantry. Shortly before his death at the First Battle of Bull Run during the American Civil War, he wrote an iconic, poetic farewell letter to his wife.",al={"sully balloo trivia","sullivan ballou","civil war reference"}}},ang={["race:Dwarf"]="As a dwarf of Ironforge, you honor Sully's final words and a brother-in-arms who died defending the great works of dwarven stonework against northern threats.",["faction:Alliance"]="As an Alliance soldier, you remember the sacrifices frontline fighters make to protect the fragile overland links between the southern and northern Alliance territories."},kw={"arathi","dwarf soldier","ironforge","sara balloo","skeleton","sully balloo","thandol span","waterlogged envelope","wetlands"},rel={"npc:sara-balloo","subzone:thandol-span","quest:631","zone:ironforge","zone:dunmorogh"},m={start="Waterlogged Envelope",["end"]="Sara Balloo",level="30",faction="Alliance",id=637},src={"Sully Balloo's Letter (quest)"}}
E["quest:683"] = {t="quest",n="Sara Balloo's Plea",z="dunmorogh",s="In Ironforge, Sara Balloo grieves for Sully and asks you to carry her plea to King Magni Bronzebeard.",h="In Ironforge, Sara Balloo grieves for Sully and asks you to carry her plea to King Magni Bronzebeard.",sec={{t="A Widow's Request",b="Sara has received Sully’s final letter, recovered from the waters of the Thandol Span. She wants the king to remember his sacrifice, so she writes him a plea. Grief keeps her from appearing before the throne herself. She entrusts the sealed letter to you, a champion of the Alliance, to carry to King Magni Bronzebeard.",sp=0},{t="Audience with the King",b="At the High Seat in Ironforge, King Magni Bronzebeard sets aside the affairs of state to read Sara’s private plea. He takes note of Khaz Modan’s brave defenders. His attention shows his bond with the common dwarves who built and defend his mountain kingdom.",sp=1}},faq={{q="Who is Sara Balloo?",a="Sara Balloo is a dwarf who lives in Ironforge. Her husband, the soldier Sully Balloo, died in the Thandol Span tragedy, and she holds his memory dear.",al={"sara balloo","who is sara"},it="identity"},{q="Why does Sara want me to see the King instead of going herself?",a="Sara is overcome by grief after learning what happened to Sully. She feels unable to keep the composure expected when petitioning King Magni Bronzebeard at the High Seat.",al={"why cant sara go","sara grief"},it="why_me"},{q="Who was Sully Balloo?",a="Sully Balloo was a dwarf soldier who defended the Thandol Span. He died fighting along the bridge, leaving a waterlogged letter for his wife.",al={"sully balloo","saras husband"},it="history"},{q="Where do I deliver Sara Balloo's Plea?",a="You deliver Sara’s plea to King Magni Bronzebeard at the High Seat in the center of Ironforge.",al={"where is magni","king magni location","turn in location"},it="next_step",gp=true},{q="What happens after King Magni reads the plea?",a="After reading Sara’s plea, King Magni honors Sully Balloo, leading to A King's Tribute and the making of a lasting monument.",al={"quest continuation","next quest"},sp=1,it="next_step"},{q="What faction can undertake this task?",a="Only members of the Alliance can carry Sara’s plea, which concerns dwarven affairs and an audience with King Magni Bronzebeard.",al={"can horde do this","faction requirement"},it="side",gp=true},{q="Why does Sara Balloo want her plea delivered to King Magni?",a="Sara Balloo is grieving the loss of her husband, Sully Balloo, who fell defending the Thandol Span. Having finally received his last letter, recovered from beneath the span, she wants King Magni Bronzebeard to formally recognize Sully's sacrifice and honor his memory. Delivering this plea is her way of ensuring her late husband's devotion to the Alliance is remembered in Ironforge.",al={"why does sara balloo want this done","sara balloo motive","why send plea to magni"},it="motive",add="ca82ce02"}},ang={["race:Dwarf"]="As a dwarf, carrying a grieving widow’s plea to your King touches on the importance your people place on stonework, lineage, and honoring ancestral sacrifice.",["faction:Alliance"]="As a member of the Alliance, you carry word between grieving citizens and Alliance leaders. You bear witness to the personal cost of preserving the realm."},kw={"a king's tribute","dun morogh","ironforge","magni bronzebeard","sara balloo","sully balloo","thandol span"},rel={"npc:sara-balloo","npc:magni-bronzebeard","quest:686","zone:ironforge","zone:dunmorogh","topic:alliance"},m={start="Sara Balloo",["end"]="King Magni Bronzebeard",level="30",faction="Alliance",id=683},src={"Sara Balloo's Plea (quest)"}}
E["quest:689"] = {t="quest",n="A King's Tribute",z="dunmorogh",s="King Magni Bronzebeard has ordered a memorial for Sully Balloo, who died defending the Thandol Span. Grand Mason Marblesten sends you north to Hillsbrad for stone worthy of the fallen soldier.",h="King Magni Bronzebeard has ordered a memorial for Sully Balloo, who died defending the Thandol Span.",sec={{t="A Royal Commission",b="Grand Mason Marblesten carries King Magni Bronzebeard’s commission to honor Sully Balloo. Sully died in the disaster at the Thandol Span. Dark Iron saboteurs have attacked the span, a vital artery between the dwarven lands and the northern kingdoms. Marblesten will shape a sculpture to withstand time and war, so the Great Forge remembers the dwarven sacrifice.",sp=0},{t="Stone of the North",b="For Sully Balloo’s likeness, Marblesten requires Alterac Granite. Its dense, resilient stone and clean texture make it prized by masons. The finest deposits lie around Darrow Hill in Hillsbrad’s contested foothills. The journey into the troubled north is dangerous, but Marblesten seeks stone worthy of the heroism it will honor.",sp=0}},faq={{q="Who is Sully Balloo?",a="Sully Balloo was an Alliance soldier who died defending the Thandol Span during its catastrophic sabotage. After his widow, Sara Balloo, sent a grieving letter, King Magni Bronzebeard ordered a permanent statue in his honor.",al={"sully balloo","who was sully balloo","sully balloo lore"},it="people"},{q="Who is Grand Mason Marblesten?",a="Grand Mason Marblesten is Ironforge's master sculptor and stoneworker. He works from the city's Commons, handles royal commissions, and takes pride in using the finest regional stones.",al={"grand mason marblesten","marblesten ironforge","who is marblesten"},it="identity"},{q="Why is Alterac Granite needed?",a="Alterac Granite is prized across the Eastern Kingdoms for its density, fine grain, and resistance to erosion. Marblesten believes only stone of this quality can make a royal tribute endure through the ages.",al={"why alterac granite","alterac granite purpose","what is alterac granite"},it="item"},{q="Where is Darrow Hill?",a="Darrow Hill lies in northern Hillsbrad Foothills, just below the Headland and near the border of Alterac. Caves there hold Alterac Granite.",al={"where is darrow hill","darrow hill location","find darrow hill"},it="place",gp=true},{q="What happened at the Thandol Span?",a="The Thandol Span is a massive bridge over the chasm between the Wetlands and the Arathi Highlands. Dark Iron saboteurs planted explosives to cut Alliance supply routes, killing many defenders.",al={"thandol span tragedy","thandol span catastrophe","what happened to thandol span"},it="history"},{q="What happens after bringing the granite to Marblesten?",a="When you bring Marblesten the Alterac Granite, he completes the memorial and asks you to report its completion to King Magni.",al={"after turning in granite","marblesten statue progress"},it="next_step"},{q="Why does Grand Mason Marblesten want this done?",a="King Magni Bronzebeard personally commissioned a memorial to honor the fallen soldier Sully Balloo. For Grand Mason Marblesten, royal commissions carry the highest priority and demand his absolute best work. Though he laments the endless bloodshed across Azeroth, he insists on using only the finest stone to craft a truly epic, lasting tribute worthy of the king's request.",al={"why does marblesten care","marblesten motive","why build sully balloo monument"},it="motive",add="1680ec58"}},ang={["race:Dwarf"]="As a dwarf, you know stonework, martial sacrifice, and loyalty to King Bronzebeard are bound closely together. Honoring Sully Balloo speaks to all three.",["profession:Mining"]="As a miner, you know Alterac Granite's hard, unyielding veins take seasoned hands to extract cleanly without fracturing.",["faction:Alliance"]="As an Alliance member, you help secure materials from Hillsbrad and strengthen the Alliance presence in the fractured north. The memorial honors an ordinary soldier who died for the common cause."},kw={"alterac granite","darrow hill","ironforge","magni bronzebeard","marblesten","stonemason","sully balloo","thandol span"},rel={"npc:grand-mason-marblesten","quest:686","subzone:thandol-span","subzone:darrow-hill","zone:ironforge","topic:alterac-kingdom","quest:631","zone:dunmorogh"},m={start="Grand Mason Marblesten",level="31",faction="Alliance",id=689,ri={"Alterac Granite"}},src={"A King's Tribute (2)"}}
E["quest:8653"] = {t="quest",n="Goldwell the Elder",z="dunmorogh",s="During the Lunar Festival, Elder Goldwell welcomes travelers in Kharanos and invites them to honor the ancestors. Your visit keeps their memory alive across the snowy dwarven lands.",h="During the Lunar Festival, Elder Goldwell welcomes travelers in Kharanos and invites them to honor the...",sec={{t="A Mountain Greeting",b="Beside the Thunderbrew Distillery, Elder Goldwell greets those who follow the trade path to Ironforge's gates. Weary travelers, adventurers, and locals all pass before him. He remembers the ancient days when the first mortals walked beneath Azeroth's stars.",sp=0},{t="Honoring the Ancestors",b="Goldwell is glad that mortals still remember the ancient races and their deeds. He thanks you for pausing to honor them. Then he gives you a Coin of Ancestry as a sign of his blessing.",sp=0}},faq={{q="Where can I find Elder Goldwell?",a="Elder Goldwell waits outside the Thunderbrew Distillery inn in Kharanos. The town lies along Dun Morogh's snowy road, just southwest of Ironforge's gates.",al={"elder goldwell location","where is elder goldwell","goldwell spot"}},{q="What is the purpose of seeking out Elder Goldwell?",a="During the Lunar Festival, travelers seek Elder Goldwell to honor the world's ancient spirits. Their respect shows that mortal races still remember the sacrifices and wisdom of antiquity.",al={"why visit elder goldwell","what does elder goldwell do","goldwell quest"}},{q="What reward does Elder Goldwell provide?",a="Elder Goldwell gives travelers a Coin of Ancestry, a blessed token from the festival elders. It can be presented to the Cenarion Circle in Moonglade for festival goods.",al={"elder goldwell reward","what do i get from elder goldwell","coin of ancestry goldwell"}},{q="Is this quest available to Horde travelers?",a="Yes. Goldwell and the other festival elders are neutral ancestral spirits who welcome adventurers of any faction. Horde travelers must avoid the dwarven mountaineers patrolling Kharanos.",al={"can horde talk to elder goldwell","horde elder goldwell","is elder goldwell friendly to horde"}},{q="Why does Elder Goldwell reside in Dun Morogh?",a="The Lunar Festival elders appear across Azeroth wherever mortal civilizations have built enduring communities. Goldwell chose Kharanos to bless those living near the heart of the dwarven kingdom.",al={"why is goldwell in kharanos","why dun morogh","goldwell dwarven land"}},{q="Can you complete this quest more than once?",a="No. Each festival season, an adventurer may honor Elder Goldwell once and receive a single blessing and coin.",al={"is elder goldwell repeatable","elder goldwell daily","goldwell reset"}}},ang={["race:Dwarf"]="As a dwarf returning from Ironforge, you meet an elder of ancient lineage outside Kharanos's premier tavern, the Thunderbrew Distillery. The visit joins timeless reverence with hometown pride.",["faction:Alliance"]="In Alliance territory, Goldwell is one of the easiest elders for young Alliance heroes to visit on the road between Coldridge Valley and Ironforge.",["faction:Horde"]="To reach Goldwell, you must sneak deep into Dun Morogh, past dwarven guards and the bitter cold outside Ironforge's high gates."},kw={"ancestor","coin of ancestry","dun morogh","elder goldwell","goldwell","ironforge","kharanos","lunar festival","thunderbrew"},rel={"npc:elder-goldwell","subzone:kharanos","zone:dunmorogh","zone:ironforge"},m={start="Elder Goldwell",id=8653},src={"Goldwell the Elder"}}
E["quest:95041"] = {t="quest",n="Data Hoarders",z="dunmorogh",s="Outside Gnomeregan, Jemma Quikswitch searches the snow for lost punch cards. The exiled gnome lives in Ironforge, and the cards hold her family's archives, from submarine designs to family recipes. Without them, the records she still has remain unreadable.",h="Outside Gnomeregan, Jemma Quikswitch searches the snow for lost punch cards.",sec={{t="A Scramble in the Snow",b="When troggs invaded Gnomeregan and radiation struck, thousands of gnomes fled with what they could carry. A damaged satchel spilled several of Jemma's cards into the snow around the fallen city. Without them, her surviving records read as gibberish, and her family's knowledge risks being lost.",sp=0},{t="Equations and Chili",b="The Quikswitch archives hold arcanotechnical field equations and submarine hull blueprints from the Second War. They also preserve Grandma Quikswitch's secret chili recipe. For refugees in Ironforge, the comforts of home matter as much as engineering marvels.",sp=0}},faq={{q="Who is Jemma Quikswitch?",a="Jemma Quikswitch is a gnomish refugee who escaped Gnomeregan's fall and now lives in Ironforge.",al={"jemma quikswitch","who gives data hoarders","quest giver data hoarders"}},{q="What data is stored on the lost cards?",a="The punch cards hold the Quikswitch family's archives, including arcanotechnical equations, submarine hull schematics from the Second War, and Grandma Quikswitch's chili recipe.",al={"what are the punch cards","what was on the cards","quikswitch archives"}},{q="Where did the data cards get lost?",a="The cards slipped from Jemma's pack as she fled Gnomeregan. They lie in the snow just outside the city's gates in Dun Morogh.",al={"where are cards","data card location","where did she drop them"}},{q="Why can't Jemma read the surviving cards without the missing ones?",a="Jemma says the data is too scrambled to recover without the missing punch cards. The records do not explain how the cards encode or organize that information.",al={"why need all cards","scrambled data","punch card data"}},{q="What role did gnomes play in the Second War regarding submarines?",a="During the Second War, gnomes aided the Alliance with advanced engineering. They designed and piloted submersible vessels to counter the Horde's naval forces.",al={"gnome submarines second war","submarine hull designs"}},{q="Why are gnomish refugees living in Ironforge?",a="After trogg invaders brought down Gnomeregan and radiation struck, surviving gnomes fled their underground home. King Magni Bronzebeard offered them sanctuary in Ironforge.",al={"why are gnomes in ironforge","gnomes living with dwarves"}}},ang={["race:Gnome"]="As a gnome, you can help preserve inventions and family memories from your homeland by recovering the punch cards.",["profession:Engineering"]="As an engineer, you can see the value of the Second War submarine blueprints and arcanotechnical equations on these cards.",["profession:Cooking"]="As a cook, you can appreciate Grandma Quikswitch's chili recipe among the engineering records.",["faction:Alliance"]="As an Alliance member, you can help displaced gnomes preserve wartime engineering records and the Alliance knowledge they hold."},kw={"data hoarders","dun morogh","gnomeregan","ironforge","jemma quikswitch","punch cards","second war","submarine hull"},rel={"zone:gnomeregan","zone:ironforge","zone:dunmorogh","topic:second-war"},m={level="10",id=95041},src={"In-game quest text: Data Hoarders"},fv=true}
E["quest:96047"] = {t="quest",n="Camping 101: First Aid",z="dunmorogh",s="In Kharanos, Thamner Pol teaches you to prepare First Aid Kits for camps in Dun Morogh. With these supplies, travelers can stay alive in the field.",h="In Kharanos, Thamner Pol teaches you to prepare First Aid Kits for camps in Dun Morogh.",sec={{t="Tending Wounds in the Wild",b="You can build on your basic bandaging skills by learning to prepare supplies for a resting site. Thamner Pol shows you how raw medical supplies become complete kits, ready for use at camp when travelers need care far from shelter.",sp=0},{t="The Lessons of Kharanos",b="Thamner Pol teaches you practical ways to outfit expedition sites with emergency supplies. A proper field kit lets a group bind wounds and regain strength together by the hearth before heading back into the cold.",sp=0}},faq={{q="What is the purpose of this task?",a="Newly trained medics go to Thamner Pol in Kharanos to learn how to make First Aid Kits for adventurer campsites.",al={"why do camping 101 first aid","what does this quest do","camping 101 goal"}},{q="Who is Thamner Pol?",a="Thamner Pol trains people in Kharanos, Dun Morogh, to make gear for wilderness camps.",al={"who is thamner pol","thamner pol location","where is thamner pol"}},{q="Where does this training take place?",a="The training takes place in Kharanos, the main settlement in central Dun Morogh, south of Ironforge.",al={"where do i go","camping 101 location","kharanos first aid"}},{q="Why is a camp first aid kit important?",a="A camp First Aid Kit gives injured travelers supplies to bind their wounds and recover safely between battles.",al={"what does first aid kit do","why make a first aid kit","camping first aid utility"}},{q="Do you need prior medical training before seeking Thamner Pol?",a="Yes. Adventurers should know the basics of First Aid and show some skill before Thamner Pol teaches them advanced camping recipes.",al={"requirements for camping 101","first aid skill required","do i need first aid first"}},{q="Is this pursuit open to any adventurer?",a="Any adventurer can learn First Aid, whatever their calling, making it a useful skill for travelers in Dun Morogh.",al={"can anyone do this","class requirements","who can learn camp first aid"}}},ang={["race:Dwarf"]="As a dwarf, you rely on sturdy, practical gear while patrolling Dun Morogh's high snowy passes. A camp First Aid Kit is a useful part of your supplies.",["race:Gnome"]="As a gnome refugee or wanderer in Kharanos, you can rely on field medicine while surviving beyond Gnomeregan's lost halls.",["faction:Alliance"]="As an Alliance recruit training in Khaz Modan's frozen heart, you learn that self-sufficiency and field medicine matter to military and exploratory groups."},kw={"bandages","camping 101","dun morogh","first aid","first aid kit","kharanos","survival","thamner pol"},rel={"subzone:kharanos","zone:dunmorogh"},m={level="6",id=96047},src={"In-game quest text: Camping 101: First Aid"},fv=true}
E["quest:96390"] = {t="quest",n="Nip 'Em in the Bud",z="dunmorogh",s="Dark Iron spies move through Dun Morogh, and Earthseer Farsen calls for help. Near Ironband's Compound, their presence threatens the Bronzebeard homeland.",h="Dark Iron spies move through Dun Morogh, and Earthseer Farsen calls for help.",sec={{t="Eyes in the Cold",b="Dark Iron spies have crossed Dun Morogh's high passes and snowy crags. They hide near settlements and excavations, where even a few watchers may signal a strike. Earthseer Farsen sees the danger and calls on Alliance defenders to find them before their plans advance.",sp=0},{t="Threat Near Ironband's Compound",b="The spies gather near Ironband's Compound in eastern Dun Morogh. Earthseer Farsen does not know their purpose at first. Searching the scouts reveals an Underground Map, proof that they prepare for more than watching the area. Their plans reach toward ancient secrets below ground, including the Hall of Thanes.",sp=1}},faq={{q="Who offers the quest Nip 'Em in the Bud?",a="After you complete Farsen's Watch, Earthseer Farsen calls for aid against intruders in Dun Morogh.",al={"quest giver nip em in the bud","who starts nip em in the bud","farsen quest"},it="identity"},{q="Why are Dark Iron spies in Dun Morogh?",a="The Dark Iron clan schemes against its Bronzebeard cousins. Its spies watch settlements in eastern Dun Morogh and may excavate or scout buried passages near Ironband's Compound.",al={"why dark iron spies here","what are dark irons doing in dun morogh","ironband dark iron spies"},it="target"},{q="Where are the Dark Iron spies located?",a="The spies gather near Ironband's Compound in eastern Dun Morogh, watching from the snowy perimeter.",al={"spy location","where are dark iron spies","where to find spies"},it="place",gp=true},{q="What leads into this task?",a="You come here after reporting for Farsen's Watch. The defenses shift from watching for intruders to hunting them.",al={"prerequisite quest","what comes before nip em in the bud","nip em in the bud prequest"},it="origin"},{q="What is uncovered while hunting these spies?",a="The fallen spies carry a Dark Iron Map. It begins with the words “Underground Map” and points toward secrets tied to the Hall of Thanes.",al={"what drops from spies","dark iron map drop","next quest after nip em in the bud"},sp=1,it="next_step"},{q="Who is Earthseer Farsen?",a="Earthseer Farsen is a dwarf in Dun Morogh who watches for unusual seismic activity and hostile clan movements in the mountains.",al={"who is farsen","earthseer farsen lore"},it="leader"},{q="Why does Earthseer Farsen want the Dark Iron spies dealt with?",a="Earthseer Farsen knows that any Dark Iron foothold in Dun Morogh spells danger for Ironforge and the surrounding lands. Though their precise motives remain unclear to him, allowing infiltrators to operate unchecked invites greater sabotage or open assault. He wants to crush their presence immediately before whatever scheme they are preparing takes root.",al={"why does farsen want spies dead","earthseer farsen motive","nip em in the bud why"},it="motive",add="bdd12e65"}},ang={["race:Dwarf"]="As a Bronzebeard dwarf, driving Dark Iron spies from your ancestral mountains means defending your home and answering old clan grudges.",["faction:Alliance"]="As an Alliance member, stopping enemy scouts in Dun Morogh helps keep Ironforge's supply lines and nearby outposts safe from sabotage."},kw={"dark iron map","dark iron spy","dun morogh","earthseer farsen","hall of thanes","ironband's compound","nip 'em in the bud","underground map"},rel={"quest:96392","quest:96391","subzone:ironband-s-compound","zone:dunmorogh","zone:hallofthanes"},m={start="Earthseer Farsen",level="13",id=96390},src={"Nip 'Em in the Bud"},fv=true}
E["quest:96391"] = {t="quest",n="Underground Map",z="dunmorogh",s="Near Ironband's Compound, the Underground Map points toward chambers beneath Ironforge. Recovered from Dark Iron spies, its runes trace a hidden route piercing toward ancient halls beneath the mountain. You bring it to Earthseer Farsen to begin learning what lies below.",h="Near Ironband's Compound, the Underground Map points toward chambers beneath Ironforge.",sec={{t="A Blueprint of Infiltration",b="You find the parchment near Ironband's Compound after dealing with Dark Iron spies. Its diagrams lay out an intricate maze of roads beneath the earth. Harsh, jagged runes mark passages that run deep underground and converge beneath Ironforge. Their course suggests a possible threat beneath the Bronzebeard capital, though the Dark Iron notes remain uncertain.",sp=0},{t="Whispers on the Wind",b="As you study the crude map, an unnatural gust carries the faint murmur of a dwarf's voice. It urges swift action and points you to Earthseer Farsen. You take this warning to him, where it may expose early movements toward ancient halls sealed deep below the city and threaten the mountain kingdom's sanctuary.",sp=1}},faq={{q="Where did this underground map come from?",a="Dark Iron spies carried the map while surveying the perimeter of Ironband's Compound in Dun Morogh. You find it among their scouts in the foothills.",al={"map drop","where find map","how to get underground map"},it="origin"},{q="What does the map show?",a="The map shows a complex network of underground highways and tunnels snaking through the earth. They converge beneath Ironforge.",al={"what is on the map","map details","dark iron map purpose"},it="purpose"},{q="Who is Earthseer Farsen?",a="Earthseer Farsen is a dwarven earthseer from Aerie Peak, attuned to the deep rocks and mountain spirits. He senses unnatural movements below ground and needs the map to assess the breach beneath Ironforge.",al={"where is farsen","who is farsen","earthseer"},it="identity"},{q="Why are the Dark Irons tunneling under Ironforge?",a="The map suggests a possible route beneath Ironforge, but its Dark Iron notes remain undeciphered. Earthseer Farsen must examine it before their plan can be established.",al={"why dark iron tunneling","dark iron plot dun morogh"},it="conflict"},{q="What does this quest lead to?",a="Bringing the map to Earthseer Farsen begins an effort to investigate the depths beneath the city. It leads into the Old Ironforge Incursion and opens a way toward the Hall of Thanes.",al={"underground map follow up","next quest after underground map"},sp=1,it="next_step"},{q="What language are the map's runes written in?",a="The map bears the jagged runic script of the Dark Iron dwarves. Whoever finds it cannot be sure what the notes say.",al={"map runes","dark iron language"}},{q="Why must the Dark Iron Map be brought to Earthseer Farsen?",a="The map details an alarming network of subterranean tunnels and highways all converging directly beneath Ironforge. Its jagged Dark Iron runes require translation, and the eerie dwarven voice carried on the wind makes it clear that Earthseer Farsen must inspect the possible subterranean threat immediately to warn the mountain kingdom of the subterranean threat.",al={"why bring map to farsen","dark iron map motive","why deliver map"},it="motive",add="1c73103d"}},ang={["race:Dwarf"]="As a Bronzebeard dwarf, you know Dark Iron tunnels running straight toward Ironforge's foundation are a grave breach of the capital's borders.",["class:Shaman"]="As a shaman, you may hear the gust guiding you to Earthseer Farsen as a warning from elemental spirits. They sense unnatural digging beneath Dun Morogh.",["faction:Alliance"]="As an Alliance member, you know this underground route must be stopped to keep Ironforge and the Alliance's northern anchor secure."},kw={"dark iron map","dun morogh","earthseer farsen","hall of thanes","ironband's compound","ironforge","underground map"},rel={"quest:96390","quest:96393","zone:hallofthanes","subzone:ironband-s-compound","zone:ironforge","zone:dunmorogh"},m={start="Dark Iron Map",["end"]="Earthseer Farsen",level="15",id=96391},src={"Underground Map"},fv=true}
E["quest:96392"] = {t="quest",n="Farsen's Watch",z="dunmorogh",s="Near Gol'Bolar Quarry, Earthseer Farsen watches for Dark Iron movement close to Ironforge. The Wildhammer shaman lends you his farsight, revealing a threat that calls for swift action.",h="Near Gol'Bolar Quarry, Earthseer Farsen watches for Dark Iron movement close to Ironforge.",sec={{t="Eyes Across the Ridge",b="From his post above Gol'Bolar Quarry, Farsen watches the lower reaches of Dun Morogh. He came south from the crags of Aerie Peak, bringing a Wildhammer's spiritual awareness with him. His clan's old arts let him sense tremors underground and watch for sudden movement along the hillsides.",sp=0},{t="A Borrowed Vision",b="Farsen lends you his farsight, a shamanic gift that carries sight across great distances. Through it, you see danger beyond troggs and wild beasts. Dark Iron dwarves have drawn close to Ironforge's industrial center and are digging in. Their foothold must be confronted before it takes root.",sp=0}},faq={{q="Who is Earthseer Farsen?",a="Earthseer Farsen is a Wildhammer dwarf visiting Dun Morogh from Aerie Peak in the Hinterlands. His shamanic gift lets him sense disturbances in the land and watch threats from afar.",al={"earthseer farsen","who is farsen","farsen wildhammer"},it="identity"},{q="Where is this watch taking place?",a="Farsen watches from above Gol'Bolar Quarry, a Bronzebeard mining excavation in eastern Dun Morogh.",al={"farsen location","where is farsen","quarry overlook"},it="place"},{q="What threat does Farsen reveal?",a="Farsen's farsight reveals a nearby foothold of hostile Dark Iron dwarves, an active danger to the region.",al={"what does farsight show","dark iron threat","farsen vision"},it="threat"},{q="How does this connect to the Hall of Thanes?",a="Investigating the Dark Iron presence seen during Farsen's watch begins the chain of tasks for those seeking entry to the Hall of Thanes.",al={"hall of thanes attunement","hall of thanes questline"},it="ties"},{q="Why is a Wildhammer dwarf involved in Dun Morogh's defense?",a="Wildhammers call the Hinterlands home, but kinship and their shared enmity toward the Dark Irons sometimes bring travelers like Farsen to the ancestral Bronzebeard lands of Dun Morogh.",al={"why is wildhammer here","aerie peak dwarf dun morogh"},it="why_here"},{q="What comes directly after completing Farsen's Watch?",a="After you witness the Dark Iron infiltration through Farsen's vision, he urges you to suppress the encroaching enemy with 'Nip 'Em in the Bud'.",al={"next quest","what comes after farsen's watch","nip em in the bud"},it="next_step"},{q="Why does Earthseer Farsen want this done?",a="While traveling through Dun Morogh from Aerie Peak, Earthseer Farsen spotted signs of Dark Iron dwarf aggression encroaching near Gol'Bolar Quarry. Before acting or raising alarms, the shaman wants you to witness the brewing danger firsthand through his far-seeing magic, ensuring Ironforge's defenders grasp the true scope of the hostile infiltration before it spirals out of control.",al={"why farsens watch","farsen motive","why does farsen want me to look"},it="motive",add="73fc96dc"}},ang={["race:Dwarf"]="As a Bronzebeard defender, you hear a warning from an Aerie Peak cousin. It shows how brazen the Dark Iron presence in your homeland has become.",["class:Shaman"]="As a shaman, you witness the earthen and spiritual vision of the Wildhammer tradition, rooted in the crags of Aerie Peak.",["faction:Alliance"]="As an Alliance traveler, you help uncover Dark Iron plots in Dun Morogh and protect Ironforge and the surrounding mountain passes."},kw={"aerie peak","dark iron","dun morogh","earthseer","farsen","farsight","gol'bolar","hall of thanes","wildhammer"},rel={"zone:dunmorogh","subzone:gol-bolar-quarry","quest:96408","quest:96390","zone:hallofthanes","topic:dark-iron-dwarf","topic:dwarf"},m={start="Earthseer Farsen",level="13",id=96392},src={"Farsen's Watch"},fv=true}
E["quest:96393"] = {t="quest",n="Old Ironforge Incursion",z="dunmorogh",s="Beneath Ironforge, Earthseer Farsen sends you to the Hall of Thanes for the last part of the investigation. There, you face the Dark Iron threat and report to King Magni Bronzebeard.",h="Beneath Ironforge, Earthseer Farsen sends you to the Hall of Thanes for the last part of the investigation.",sec={{t="Breaching the Vaults",b="The underground map reveals Dark Iron movements, and Earthseer Farsen identifies the mastermind behind the intrusion. The entrance to the Hall of Thanes lies deep within Old Ironforge's ancient stone halls. While the upper city tends to matters on the surface, Dark Iron forces slip into caverns that lie dormant beneath the kingdom.",sp=0},{t="Durgen Dirgehammer",b="Earthseer Farsen translates captured Dark Iron documents and names the commander: Durgen Dirgehammer. Deep in the lower vaults, Durgen threatens the heart of the Bronzebeard mountain kingdom. Reach him, strike him down, and carry his severed head to King Magni Bronzebeard above.",sp=1},{t="Audience with the King",b="Durgen Dirgehammer's head confirms to King Magni Bronzebeard the Dark Iron threat beneath the city's ancient roots. You bring proof of victory and a personal greeting from Farsen, Magni's old friend. The investigation ends with Magni aware of what lurks below.",sp=1}},faq={{q="What is Old Ironforge Incursion?",a="Earthseer Farsen sends you into the Hall of Thanes beneath Old Ironforge to face the Dark Iron commander, Durgen Dirgehammer. It is the last stage of an investigation into Dark Iron activity beneath Dun Morogh.",al={"old ironforge incursion quest","durgen dirgehammer quest"},it="purpose"},{q="Where does this quest take place?",a="You enter the Hall of Thanes, an ancient chamber deep in the bedrock beneath Old Ironforge and the mountain capital.",al={"where is hall of thanes","hall of thanes location"},it="place"},{q="Who is Durgen Dirgehammer?",a="Durgen Dirgehammer commands the Dark Iron incursion into the Hall of Thanes beneath Old Ironforge. Earthseer Farsen learned his name from recovered Dark Iron documents.",al={"who is dirgehammer","durgen dirgehammer"},it="target"},{q="Who gives the quest, and who receives it?",a="After you recover the Underground Map, Earthseer Farsen sends you to King Magni Bronzebeard in Ironforge.",al={"quest giver old ironforge incursion","who turns in old ironforge incursion"},it="people"},{q="How do I start the quest chain that leads to this?",a="Begin with A Visitor to Dun Morogh, offered by Beldin Steelgrill outside Kharanos in Dun Morogh.",al={"how to start hall of thanes quest","visitor to dun morogh start"},gp=true},{q="What is the connection between Earthseer Farsen and King Magni?",a="Earthseer Farsen considers himself an old friend of King Magni Bronzebeard. He asks you to send his personal regards when you present Durgen Dirgehammer's head in the throne room.",al={"farsen and magni","earthseer farsen lore"},it="ties"},{q="Why does Earthseer Farsen want Durgen Dirgehammer killed?",a="Farsen uncovered enemy movements beneath the mountain and deciphered orders pointing to Durgen Dirgehammer as the commander leading the incursion into Old Ironforge. The Dark Iron presence in the ancient Hall of Thanes directly threatens the dwarven capital from below. By sending you to cut down their leader, Farsen aims to shatter the assault before the Dark Irons can entrench themselves, while sending undeniable proof of the threat directly to King Magni Bronzebeard.",al={"farsen motive","why kill durgen dirgehammer","why does farsen send you"},it="motive",add="bdae81a8"},{q="What is Durgen Dirgehammer's Head for?",a="You need Durgen Dirgehammer's Head as absolute proof for King Magni Bronzebeard that the commander of the subterranean assault has been dealt with. Delivering the gruesome trophy directly to the throne room confirms that the hostile Dark Iron strike force in the Hall of Thanes has lost its leader and carries Earthseer Farsen's personal warning to the king.",al={"durgen dirgehammer head use","why take durgen's head","head of durgen dirgehammer"},it="item",add="664606f0"}},ang={["race:Dwarf"]="As a dwarf, you know Dark Iron infiltrators have violated your ancestral fortress in the forgotten vaults beneath the High Seat.",["faction:Alliance"]="As an Alliance member, you help stop an incursion that threatens a devastating surprise attack on your faction's primary stronghold in the Eastern Kingdoms."},kw={"dark iron","dirgehammer","farsen","incursion","ironforge","kharanos","magni","thanes"},rel={"zone:hallofthanes","subzone:old-ironforge","quest:96391","npc:magni-bronzebeard","npc:beldin-steelgrill","quest:96408","zone:ironforge","zone:dunmorogh"},m={start="Earthseer Farsen",["end"]="King Magni Bronzebeard",level="16",id=96393,ri={"Durgen Dirgehammer's Head"}},src={"Old Ironforge Incursion"},fv=true}
E["quest:96408"] = {t="quest",n="A Visitor to Dun Morogh",z="dunmorogh",s="Beldin Steelgrill sends you to learn who has lit a fire above Gol'Bolar Quarry. The camp overlooks the excavation, and the dwarves fear its visitor may mean them harm.",h="Beldin Steelgrill sends you to learn who has lit a fire above Gol'Bolar Quarry.",sec={{t="A Smoke Plume on the Heights",b="High on the snowy ridges east of Kharanos, a stranger's campfire burns above the quarry. The unfamiliar fire has worried the folk of Kharanos. There, the Mountaineers watch the heights for danger.",sp=0},{t="Meeting the Earthseer",b="Earthseer Farsen has camped on the heights above Gol'Bolar Quarry. He is a mystic bound deeply to the earth, not a marauding trogg or hostile spy. His watch draws him into disturbances beneath Khaz Modan and the mystery of the Hall of Thanes.",sp=1}},faq={{q="Who sends you to investigate the visitor?",a="Beldin Steelgrill, outside Kharanos, asks you to investigate after mountaineers report an unfamiliar fire in the hills.",al={"who gives this quest","quest starter","beldin steelgrill quest"},gp=true},{q="Where is the mysterious campsite located?",a="The campfire burns high on the snowy ridges east of Kharanos, above Gol'Bolar Quarry.",al={"camp location","where is the visitor","visitor spot"},gp=true},{q="Who is the visitor overlooking the quarry?",a="Earthseer Farsen is the visitor camped on the heights above the quarry, watching over it.",al={"who is farsen","who is the visitor","earthseer farsen"},sp=1,it="target"},{q="Why were the dwarves suspicious of the campfire?",a="The dwarves distrust the unknown camp because it overlooks Gol'Bolar Quarry, a critical operation already under pressure from local troggs. They fear scouts or hostile forces may be watching their movements.",al={"why suspicious","why investigate","why send me"},it="motive"},{q="What does this quest lead into?",a="Speaking with Earthseer Farsen leads to Farsen's Watch and begins the Hall of Thanes attunement chain.",al={"what comes next","followup quest","hall of thanes intro"},sp=1,it="next_step"},{q="Do you need to fight the stranger at the camp?",a="No. Beldin Steelgrill warns you to be ready for violence, but Earthseer Farsen is a peaceful observer who is willing to speak with you.",al={"is the visitor hostile","do i kill the visitor","visitor fight"},sp=1,gp=true},{q="Why does Beldin Steelgrill ask an adventurer instead of the Mountaineers?",a="The local Mountaineers spotted the hillside campfire from afar, but their ranks are stretched thin guarding the roads, settlements, and quarry operations from troggs and wild beasts. Since the fire is likely harmless, Beldin relies on a capable traveler passing through Kharanos to quickly scout the ridge rather than pulling guards from active duty.",al={"why send me","why not send guards","beldin steelgrill why me"},it="why_me",add="3b0d76fb"}},ang={["race:Dwarf"]="As a Bronzebeard dwarf, you know why the Mountaineers watch strangers above major mining sites like Gol'Bolar. They guard Khaz Modan's borders.",["class:Shaman"]="As a shaman, you meet Earthseer Farsen, whose communion with the mountain stones is rare in Dun Morogh's snowy highlands.",["faction:Alliance"]="As an Alliance member, you help the Mountaineers outside Kharanos protect the supply lines and quarry workers from unforeseen threats."},kw={"beldin steelgrill","dun morogh","earthseer farsen","farsen's watch","gol'bolar quarry","hall of thanes","kharanos","visitor"},rel={"npc:beldin-steelgrill","subzone:gol-bolar-quarry","subzone:kharanos","zone:dunmorogh","quest:96392","zone:hallofthanes"},m={start="Beldin Steelgrill",["end"]="Earthseer Farsen",level="13",faction="Alliance",id=96408},src={"A Visitor to Dun Morogh"},fv=true}
E["quest:96628"] = {t="quest",n="The Adventurer",z="dunmorogh",s="At Dun Morogh’s southern gate, The Adventurer carries supplies toward Kharanos. Mountaineer Thalos asks travelers to bring provisions to Eric Brighthammer, a newcomer camped just outside the village.",h="At Dun Morogh’s southern gate, The Adventurer carries supplies toward Kharanos.",sec={{t="A Favor for the Mountaineers",b="Mountaineer Thalos keeps watch at Dun Morogh’s southern gate, where the trail leaves Coldridge Valley. Guarding the high passes and tunnels keeps the Mountaineers busy. Thalos also watches for dangers and travelers on the road. When a lone adventurer arrives near Kharanos, he asks trusted passersby to carry supplies onward. The bundle is meant to help newcomers venturing into the frozen crags.",sp=0},{t="Supplies for Kharanos",b="The road from the southern pass winds down to Kharanos, a center of dwarven craft and travel in central Dun Morogh. Eric Brighthammer has recently made camp just outside the village. Carrying the Mountaineers’ provisions to him links the sentries on the ridge with those walking the wilderness.",sp=0}},faq={{q="Who starts the quest The Adventurer?",a="Mountaineer Thalos asks travelers for help from his post at the mountain pass gate, where the Coldridge Valley trail enters Dun Morogh.",al={"quest giver","who gives the adventurer","thalos quest"},gp=true},{q="Who is Eric Brighthammer?",a="Eric Brighthammer is an adventurer who recently arrived outside Kharanos. Mountaineer Thalos asks travelers to bring him a bundle of supplies.",al={"where is eric brighthammer","who is the adventurer","brighthammer"},it="identity"},{q="Where does this delivery take place?",a="The delivery goes to Eric Brighthammer’s camp just outside Kharanos in Dun Morogh. It lies north of the Coldridge Pass tunnel, where Mountaineer Thalos is posted.",al={"where to deliver supplies","eric brighthammer location","supply bundle drop"},it="place"},{q="Why is Mountaineer Thalos sending supplies?",a="The Mountaineers keep watch over travelers across Dun Morogh. When Thalos hears that an adventurer has camped near Kharanos, he arranges provisions to support him in the cold.",al={"why send supplies","thalos purpose","reason for bundle"},it="motive"},{q="What item are you carrying?",a="You carry a Supply Bundle from Mountaineer Thalos to Eric Brighthammer.",al={"what supplies","supply bundle item"},it="item"},{q="Is this quest available to Horde players?",a="No. Mountaineer Thalos is a dwarven guard aligned with the Alliance, so the work is for Alliance travelers.",al={"can horde do this","is it alliance only","horde adventurer quest"},gp=true},{q="Why does Mountaineer Thalos ask you to deliver the supplies?",a="Mountaineer Thalos and his patrol are stationed at the pass, tasked with watching the road and securing the tunnel against local perils. Because you are already travelling onward through the pass toward Kharanos, he asks you to take the delivery along your route rather than pulling his mountaineers away from their guard posts.",al={"why me the adventurer","why does thalos need me","why send player to eric brighthammer"},it="why_me",add="95095969"}},ang={["race:Dwarf"]="As a dwarf leaving Coldridge Valley, you carry provisions to Eric Brighthammer and help the Mountaineers in Dun Morogh.",["faction:Alliance"]="As an Alliance traveler, you carry supplies along the icy roads to allies camped outside Kharanos."},kw={"coldridge pass","dun morogh","eric brighthammer","kharanos","mountaineer thalos","supply bundle","the adventurer"},rel={"npc:mountaineer-thalos","subzone:kharanos","zone:dunmorogh"},m={start="Mountaineer Thalos",["end"]="Eric Brighthammer",level="6",faction="Alliance",id=96628},src={"The Adventurer (Dun Morogh)"},fv=true}
E["subzone:amberstill-ranch"] = {t="subzone",n="Amberstill Ranch",z="dunmorogh",s="North of Gol'Bolar Quarry, Amberstill Ranch stands along the snowy road to Loch Modan. The Amberstill family tends its mountain rams and guards them from hungry predators.",h="North of Gol'Bolar Quarry, Amberstill Ranch stands along the snowy road to Loch Modan.",sec={{t="Home of the Mountain Rams",b="Across Khaz Modan, Amberstill Ranch is known for its strong mountain rams. The Amberstill family tends the stables and paddocks, training the sure-footed beasts for snowy passes and steep cliffs. The ranch supplies riding mounts and livestock. Wendigos drawn to the flock threaten the herd, and the family must fend them off.",sp=0}},faq={{q="What is Amberstill Ranch known for?",a="Amberstill Ranch breeds Barak Tor'ol mountain rams for the Alliance. Dwarves and honored Alliance champions come to learn ram riding and buy mounts from the stable masters.",al={"amberstill purpose","why visit amberstill","amberstill rams"},it="purpose"},{q="Can non-dwarves purchase mounts here?",a="Rams are traditionally for dwarven riders who know their stubborn nature. Riders of other Alliance races can learn to ride and buy one only after earning Ironforge's utmost trust and exalted standing.",al={"buy rams non dwarf","human buy ram","ram mount requirements"},gp=true},{q="What threats does the ranch face?",a="Wendigos descend from the frozen bluffs and threaten the herd. Vagash, a massive wendigo, is the most notorious predator on the surrounding heights and regularly targets the livestock.",al={"amberstill danger","wendigo threat","vagash quest"},it="threat"},{q="Can you obtain anything else at the ranch?",a="Young Yarlyn Amberstill keeps domestic snowshoe rabbits and sells them in crates to travelers seeking a companion for the road.",al={"amberstill rabbit","snowshoe rabbit pet","yarlyn amberstill"},gp=true},{q="What is Amberstill Ranch?",a="Amberstill Ranch is a dwarven homestead and breeding ground tucked into the hills of eastern Dun Morogh, north of the Gol'Bolar Quarry. It serves as the primary stables for raising the hardy mountain rams prized by the Ironforge dwarves as trustworthy mounts in Khaz Modan's rugged terrain.",al={"what is amberstill ranch","amberstill ranch purpose","what is this place amberstill"},it="place",add="0dde8a5d"},{q="Who lives at Amberstill Ranch?",a="The ranch is home to the Amberstill family, who breed, tend, and train Dun Morogh's famous mountain rams. Members of the family manage the stables, sell local pets like snowshoe rabbits, and offer riding instruction to those who have earned the deep trust of Ironforge.",al={"who runs amberstill ranch","amberstill ranch residents","who lives here"},it="residents",add="f9ed26f9"},{q="Is Amberstill Ranch dangerous?",a="The ranch itself is a safe Alliance haven, but its outskirts are perilous. Fierce wild beasts roam the snowy bluffs nearby, none more feared by the local breeders than the monstrous wendigo Vagash, who preys upon their livestock.",al={"amberstill ranch danger","is amberstill safe","dangers at amberstill ranch"},it="danger",add="1facab92"}},ang={["race:Dwarf"]="As a dwarf, you can acquire your first Barak Tor'ol ram mount at Amberstill Ranch.",["faction:Alliance"]="For the Alliance, the Amberstill family's sturdy rams provide dependable cold-weather cavalry for rugged mountain terrain."},kw={"amberstill","mount vendor","rams","ranch","riding trainer","snowshoe rabbit","vagash","yarlyn"},rel={"zone:dunmorogh","zone:lochmodan","zone:ironforge","subzone:gol-bolar-quarry","quest:314","topic:alliance"},src={"Amberstill Ranch"}}
E["subzone:anvilmar"] = {t="subzone",n="Anvilmar",z="dunmorogh",s="In Coldridge Valley, Anvilmar gathers young Bronzebeard dwarves and displaced gnomes to train for the road ahead. Snowy Dun Morogh surrounds the fortified outpost and its great stone forge.",h="In Coldridge Valley, Anvilmar gathers young Bronzebeard dwarves and displaced gnomes to train for the road...",sec={{t="The Hearth of Coldridge",b="A great forge burns inside Anvilmar's sturdy stone walls in the northern crags of Coldridge Valley. Class mentors and supply vendors serve the outpost, while veteran mountain mountaineers drill recruits before they set out across the kingdom. Snowdrifts shelter the walls, but Frostmane trolls and wild beasts prowl the frozen valley, keeping the defenders alert.",sp=0},{t="A Legacy of Iron and Trolls",b="Anvilmar may take its name from High King Modimus Anvilmar. He ruled the dwarven clans before the War of the Three Hammers. Today, the garrison keeps watch and tends the forge fires as trolls and beasts roam the valley.",sp=0}},faq={{q="What is Anvilmar?",a="Anvilmar is a dwarven outpost in northern Coldridge Valley, in Dun Morogh. Newly recruited dwarves and gnomes gather there to train for the road ahead.",al={"what is anvilmar","anvilmar location","anvilmar overview"},it="place"},{q="Why is it named Anvilmar?",a="Anvilmar may take its name from High King Modimus Anvilmar or his bloodline. He ruled the dwarven clans before the War of the Three Hammers, but the name's origin is unconfirmed.",al={"who was anvilmar","anvilmar name origin","name meaning"},it="name"},{q="What threats does Anvilmar face?",a="Frostmane trolls and dangerous wildlife threaten Anvilmar. Wolves and wendigos roam the crags of Coldridge Valley.",al={"anvilmar enemies","who attacks anvilmar","threats to anvilmar"},it="threat"},{q="Can you learn professions here?",a="Anvilmar has a forge, but no professional tradeskill trainers. Young recruits travel farther into Dun Morogh to learn a craft, at places such as Kharanos or Ironforge.",al={"professions in anvilmar","anvilmar forge","blacksmithing anvilmar"},gp=true},{q="Is Anvilmar dangerous?",a="The settlement itself is safe and protected, serving as a haven with a grand forge, hearth, trainers, and guards. However, just beyond its immediate perimeter, danger lurks in every direction. Aggressive wolves, hungry bears, and raiding parties of hostile Frostmane trolls roam the snowy drifts of Coldridge Valley, posing constant hazards to unwary travelers and new recruits.",al={"is anvilmar safe","danger anvilmar","threats in anvilmar"},it="danger",add="449334a9"}},ang={["race:Dwarf"]="As a dwarf, you begin your journey at Anvilmar. Its name may honor the ancient High King who once ruled the dwarven clans.",["race:Gnome"]="As a gnome taking shelter at Anvilmar, you find dwarven allies, warm hearths, and instructors who help you adapt to the frozen wilderness."},kw={"anvilmar","coldridge valley","dun morogh","forge","frostmane","modimus anvilmar","starting zone"},rel={"subzone:coldridge-valley","zone:dunmorogh","subzone:coldridge-pass","topic:troll"},src={"Anvilmar"}}
E["subzone:brewnall-village"] = {t="subzone",n="Brewnall Village",z="dunmorogh",s="In Chill Breeze Valley, the Barleybrew family works on new brews and guards against wild beasts. Their camp lies near the entrance to Gnomeregan.",h="In Chill Breeze Valley, the Barleybrew family works on new brews and guards against wild beasts.",sec={{t="A Bitter Brew in the Valley",b="The Barleybrew clan brews in Chill Breeze Valley, among the gnomish reaches of western Dun Morogh. They work to perfect old recipes and make the finest stout. Tents and brewing gear fill the camp, with no permanent stone buildings. As the Barleybrews test new ales, wolves and bears threaten the valley. Wandering mountaineers gather rare ingredients and help keep the area safe.",sp=0}},faq={{q="What is Brewnall Village?",a="Brewnall Village is a dwarven camp in Chill Breeze Valley, in western Dun Morogh, just east of Gnomeregan. The Barleybrew clan experiments with beer recipes there and contends with local wildlife.",al={"where is brewnall","what is brewnall village","brewnall info"},it="place"},{q="Why is it called a village if there are no buildings?",a="Brewnall Village is an open-air camp of tents and supply kegs, rather than stone houses. The Barleybrews brew in the cold valley without building permanent homes.",al={"why is it a camp","where are the houses","brewnall buildings"},it="name"},{q="Why is a dwarven settlement located in gnomish territory?",a="The Barleybrews settled in Chill Breeze Valley, where gnomes live near Gnomeregan. Ironforge and the gnomes are close allies, and the dwarves pursue their brewing craft here undisturbed.",al={"dwarves near gnomeregan","why are dwarves here","gnome territory dwarf camp"}},{q="What problems do the residents face?",a="Aggressive wildlife threatens the camp, including crag boars, bears, and frost wolves. The Barleybrews also seek rare ingredients for new and better brews.",al={"brewnall quests","what do the barleybrews need","village problems"},it="danger"},{q="Who lives in Brewnall Village?",a="Brewnall Village serves as the home and testing ground for the Barleybrew family. These dwarven brewers have set up camp here in Chill Breeze Valley to dedicate themselves entirely to their craft, endlessly experimenting to refine and perfect the art of dwarven ale brewing.",al={"who runs brewnall","brewnall village residents","who lives at brewnall village"},it="residents",add="c4fa2ce1"}},ang={["race:Dwarf"]="As a dwarf, you can see the Barleybrews' pursuit of the finest recipe as an honorable craft rooted in Ironforge tradition.",["race:Gnome"]="Near Gnomeregan, you find a dwarven camp deep in the gnomish valleys of western Dun Morogh."},kw={"barleybrew","beer","brewnall","chill breeze valley","dun morogh","gnomeregan","stout"},rel={"subzone:chill-breeze-valley","quest:315","quest:319","zone:dunmorogh","zone:gnomeregan","zone:ironforge"},src={"Brewnall Village"}}
E["subzone:chill-breeze-valley"] = {t="subzone",n="Chill Breeze Valley",z="dunmorogh",s="In western Dun Morogh, travelers cross Chill Breeze Valley between Kharanos and Gnomeregan. Refugees and young travelers follow the main trail, while dangerous beasts haunt the secluded reaches.",h="In western Dun Morogh, travelers cross Chill Breeze Valley between Kharanos and Gnomeregan.",sec={{t="A Crossroads of Snow and Claws",b="A T-shaped trench cuts through the mountains, its main trail running east to west. Young dwarves and gnomes travel between Kharanos and the outskirts of Gnomeregan. The north-south branch leads into dangerous ground. Blood stains the snow, and mangled carcasses lie nearby.\n\nSavage wendigos make dens in deep ice caves. They prey on anyone who wanders into their hunting grounds.",sp=0}},faq={{q="Where is Chill Breeze Valley located?",a="Chill Breeze Valley lies in western Dun Morogh, between Kharanos to the east and Gnomeregan to the west.",al={"chill breeze valley location","where is chill breeze valley","chill breeze valley map"},it="place",gp=true},{q="Why is the valley so dangerous to travel through?",a="The main trail between Kharanos and Gnomeregan sees heavy foot traffic and is relatively safe. Predatory beasts hunt in the northern and southern branches, where blood stains the snow and torn carcasses mark the caves where wendigos dwell.",al={"chill breeze valley monsters","dangers in chill breeze valley","why are there bones here"},it="danger"},{q="What kinds of beasts make their dens here?",a="Ferocious wendigos make dens in the valley’s deeper recesses. One especially large and powerful wendigo has claimed a cave as its lair.",al={"wendigo in chill breeze valley","what lives in chill breeze valley"},it="residents"},{q="What is Chill Breeze Valley?",a="Chill Breeze Valley is a rugged, T-shaped pass nestled in western Dun Morogh, linking the ruins of Gnomeregan to the west with the town of Kharanos to the east. Its central path serves as a vital transit corridor for traveling dwarves and gnome refugees, while its deeper reaches remain treacherous snowy wilderness.",al={"chill breeze valley","what is this valley","about chill breeze valley"},it="place",add="746bfe00"}},ang={["race:Gnome"]="As a gnome fleeing Gnomeregan for the safety of Kharanos or Ironforge, you must pass the predators around Chill Breeze Valley.",["race:Dwarf"]="As a dwarf, you can test your mettle against the ferocious wendigos threatening the vital passage between central Dun Morogh and the western highlands."},kw={"caves","chill breeze valley","dun morogh","gnomeregan","kharanos","t-shaped","wendigo"},rel={"zone:dunmorogh","subzone:kharanos","zone:gnomeregan","topic:gnome"},src={"Chill Breeze Valley"}}
E["subzone:coldridge-pass"] = {t="subzone",n="Coldridge Pass",z="dunmorogh",s="Troggs now bar the road through Coldridge Pass, the way out of Coldridge Valley.",h="Troggs now bar the road through Coldridge Pass, the way out of Coldridge Valley.",sec={{t="The Gateway Out of the Valley",b="Recruits leave Coldridge Valley through Coldridge Pass and travel toward Kharanos. The tunnel cuts through Dun Morogh’s southern mountain ridge, carrying them from sheltered training grounds into the wider kingdom. Troggs have overrun the passage, threatening anyone who crosses between the valley and the rest of Dun Morogh.",sp=0}},faq={{q="Where does Coldridge Pass lead?",a="Coldridge Pass leads from Coldridge Valley in the southwest to the rest of Dun Morogh. It opens among snowy hills just west of Kharanos.",al={"where does coldridge pass go","coldridge pass destination","how to leave coldridge valley"},it="place"},{q="Why are there troggs in Coldridge Pass?",a="Troggs have surged from deep cracks beneath Dun Morogh and seized caves and tunnels across the region. Coldridge Pass shelters them and gives them a place to ambush travelers.",al={"why are troggs here","coldridge pass monsters","trogg infestation"},it="threat"},{q="Is Coldridge Pass safe to travel through?",a="No. Hostile troggs crowd the tunnel, so recruits and travelers must fight through or sprint in darkness to reach the far end.",al={"is coldridge pass dangerous","can i walk through coldridge pass"},it="danger"},{q="Who guards or maintains the pass?",a="Mountaineers watch the valley and road exits, but the tunnel remains contested and uncleared. Travelers must defend themselves as they cross.",al={"dwarf guards at coldridge pass","who controls the pass"},it="in_charge"},{q="What is the history of Coldridge Pass?",a="Carved through the mountains of Dun Morogh, Coldridge Pass was established as the primary lifeline connecting the isolated training grounds of Coldridge Valley to the wider realm and the frontier town of Kharanos. For generations, dwarven recruits and mountaineers used this corridor to travel freely between the valley and the rest of the kingdom. However, the recent emergence of hostile troggs inside the tunnel disrupted that peace, forcing travelers to fight their way through what was once a secure transit route.",al={"coldridge pass history","what happened at coldridge pass","coldridge pass background"},it="history",add="7f71f8e0"}},ang={["race:Dwarf"]="As a dwarf, you leave novice training at Anvilmar through Coldridge Pass to serve across Ironforge’s lands.",["race:Gnome"]="As a gnome, you must cross the trogg-held pass to reach Kharanos and the higher road toward Ironforge. There, you can aid the Alliance."},kw={"anvilmar","coldridge pass","coldridge valley","dun morogh","kharanos","mountain pass","trogg","tunnel"},rel={"subzone:coldridge-valley","subzone:kharanos","zone:dunmorogh","topic:trogg"},src={"Coldridge Pass"}}
E["subzone:coldridge-valley"] = {t="subzone",n="Coldridge Valley",z="dunmorogh",s="Coldridge Valley is where young dwarves and gnome refugees train to serve Ironforge. Snow lies deep over this sheltered vale, high in the southwest of Dun Morogh. Sheer cliffs close it in. Only one road leads out to the wider mountains, and that is Coldridge Pass.",h="Coldridge Valley is where young dwarves and gnome refugees train to serve Ironforge.",sec={{t="A Secluded Proving Ground",b="The recruits gather at Anvilmar, the valley's training hall. There they learn to fight, to move unseen and to wield sorcery. Veteran dwarves teach them, side by side with gnome scholars who have lost their home. Out on the snowy valley floor roam boars and hungry winter wolves. They test whether a novice can survive the frontier.",sp=0},{t="Encroaching Foes",b="But this valley is not at peace. Frostmane trolls camp here, at Frostmane Hovel and beyond. They say the land was theirs by ancestral right, and they skirmish with the mountaineers over it. And Rockjaw troggs have overrun Coldridge Pass. It is the tunnel to Kharanos, and while it is blocked, nothing moves freely to Ironforge.",sp=0}},faq={{q="How do you leave Coldridge Valley?",a="Coldridge Pass is the only overland route out of the valley. The snowy tunnel cuts northeast through the mountain ridge, then the road runs east toward Kharanos and onward to Ironforge's great gates.",al={"exit coldridge","how to get out","path to kharanos"},it="next_step",gp=true},{q="Why are gnomes starting here alongside dwarves?",a="Surviving gnomes fled to Dun Morogh after troggs and radioactive fallout brought the tragic fall of Gnomeregan. King Magni Bronzebeard welcomed High Tinker Mekkatorque's people, and many exiled gnomish apprentices now train beside young dwarves in Anvilmar.",al={"gnomes in coldridge","why are gnomes here","gnome starting area"},it="arrival"},{q="What threats are troubling the valley?",a="Frostmane trolls resent dwarven settlements on their mountain territory, while Rockjaw troggs have clawed up from the deep earth and blocked Coldridge Pass. Wolves and boars also harass unwary travelers. The blocked pass prevents free movement between the valley and the mountain realm.",al={"coldridge enemies","valley threats","who is attacking"},it="threat"},{q="What is Anvilmar?",a="Anvilmar is the central fortress-lodge and settlement in Coldridge Valley. It houses class trainers, forge-masters, and local mountaineer officers, who coordinate the valley's defense and prepare newly forged adventurers for the wider world.",al={"anvilmar town","what is the town here"},it="place"},{q="What is Coldridge Valley?",a="Coldridge Valley is a sheltered, snow-covered basin tucked into the southwestern corner of Dun Morogh. Ringed by jagged mountain peaks, it serves as the secluded training ground and staging camp for young dwarves and gnome refugees before they venture out into the wider kingdom.",al={"coldridge valley overview","where is coldridge valley","coldridge info"},it="place",add="80e4cacf",nx={6}},{q="Is Coldridge Valley part of Dun Morogh?",a="Yes, it sits in the southwestern heights of Dun Morogh. It remains physically separated from the rest of the snowbound region by a ring of mountains, linked to the mainland only through the narrow tunnel of Coldridge Pass to the northeast.",al={"is coldridge in dun morogh","dun morogh coldridge valley"},it="place",add="73aec6cd"},{q="Is Coldridge Valley dangerous?",a="While intended as a quiet, sheltered training ground, trouble has recently spilled into the valley. Hostile Frostmane trolls lurk in nearby camps, aggressive wildlife prowls the snowdrifts, and vicious troggs have overrun the only mountain pass leading out to the rest of Dun Morogh.",al={"coldridge danger","is it safe here","coldridge threats"},it="danger",add="0ba4a80e"},{q="Who rules the dwarves?",a="The dwarves of Ironforge are ruled by King Magni Bronzebeard. A steadfast leader and veteran of the Great Wars, King Magni governs the Kingdom of Ironforge from his mighty mountain throne room and stands as one of the Alliance's most resolute champions.",al={"who is the dwarf king","king of ironforge","dwarf leader"},it="leader",add="7fc500c6"},{q="What's in Kharanos and why does everyone keep mentioning it?",a="Kharanos is the lively frontier town located just beyond Coldridge Pass along the main road to Ironforge. It serves as the primary outpost for young recruits to report for active duty, boast craft training, and sample world-famous ale at the Thunderbrew Distillery.",al={"what is kharanos","why go to kharanos","kharanos town"},it="next_step",add="ff57e405",nx={10}},{q="Who is Senir Whitebeard?",a="Senir Whitebeard is a prominent dwarven leader stationed in the nearby frontier town of Kharanos. He coordinates defense efforts in the region, actively working to eradicate the dangerous foothold that the Frostmane ice trolls have carved out across Dun Morogh's peaks.",al={"senir whitebeard","senir kharanos"},it="people",add="966deec9"},{q="How did I end up in Coldridge Valley?",a="You arrived in Coldridge Valley because it serves as the sheltered training ground for new recruits in Dun Morogh. Tucked away in the southwestern mountains, the valley offers aspiring defenders a secluded place to learn their craft, gather gear, and prove their mettle before braving the wider, harsher realm beyond.",al={"how did i get here","why am i here","how did i end up here","what brought me here"},it="arrival",add="a3c72edd"},{q="What am I supposed to be doing in Coldridge Valley?",a="Your task is to undergo basic training, hone your combat skills, and aid the local authorities stationed at Anvilmar. You are expected to cull unruly local wildlife, push back encroaching Frostmane trolls and troggs, and eventually clear a path through Coldridge Pass to report for service in Kharanos.",al={"what do i do here","what is my mission","what should i do in coldridge","what am i doing here"},it="purpose",add="8bdf0a70"},{q="Why does a new Dwarf start here, in Coldridge Valley?",a="As a young dwarven adventurer, you have come to Anvilmar to master your martial and magical traditions under veteran trainers. Ironforge needs stalwart champions to protect its realm, and this mountain cradle offers the ideal proving ground to forge fresh recruits into seasoned defenders of Khaz Modan.",al={"why do dwarves start here","why am i here dwarf","dwarf starting area","why coldridge valley dwarf"},it="arrival",rc="Dwarf",add="2eeaa2be"},{q="Why does a new Gnome start here, in Coldridge Valley?",a="With Gnomeregan recently fallen to the trogg invasion, surviving gnomes have fled their home and found shelter among their dwarven allies. As an exiled gnome eager to aid the Alliance and rebuild your people's future, you begin your training alongside dwarven recruits in the safety of Coldridge Valley.",al={"why do gnomes start here","why am i here gnome","gnome starting area","why coldridge valley gnome"},it="arrival",rc="Gnome",add="ef9153cd"}},ang={["race:Dwarf"]="As a dwarf, you take your first steps beyond the hearth in the traditional training ground of Bronzebeard mountaineers and clerics, preparing to serve the High Seat.",["race:Gnome"]="As a gnome exiled from Gnomeregan, you find a safe haven in Coldridge Valley's snows, where you can master spells and machinery alongside your dwarven hosts."},kw={"anvilmar","coldridge pass","coldridge valley","dun morogh","frostmane","ironforge","starting area","troggs"},rel={"subzone:anvilmar","zone:dunmorogh","subzone:coldridge-pass","subzone:frostmane-hovel","subzone:kharanos","topic:dwarf","topic:gnome","topic:trogg"},src={"Coldridge Valley"}}
E["subzone:frostmane-hold"] = {t="subzone",n="Frostmane Hold",z="dunmorogh",s="Frostmane trolls raid from the cliffs south of Gnomeregan in western Dun Morogh. The Ironforge Guard watches their camp and caverns as the raiders press into dwarven lands.",h="Frostmane trolls raid from the cliffs south of Gnomeregan in western Dun Morogh.",sec={{t="A Troll Bastion in the Snows",b="In western Dun Morogh, Frostmane Hold cuts into cold cliffs. Rough structures stand outside its winding caves, where hideskinners and headhunters guard the tribe’s stronghold. From here, Frostmane raiders strike the valleys, threaten travelers on mountain passes, and test the defenses around Kharanos.",sp=0},{t="A Thorn in Kharanos' Side",b="Dwarven commanders in Kharanos fear the growing Frostmane force. Young mountaineers and adventurers scout the caverns and map their defenses. They thin the warbands before the tribe can gather for an organized assault on dwarven outposts.",sp=0}},faq={{q="Who lives in Frostmane Hold?",a="Frostmane ice trolls live in the hold, including hunters, hideskinners, headhunters, chieftains, and raiders.",al={"who is in frostmane hold","frostmane hold mobs","trolls in frostmane hold"},it="residents"},{q="Where is Frostmane Hold located?",a="Frostmane Hold lies in western Dun Morogh, south of Gnomeregan’s industrial ruins and west of Kharanos.",al={"frostmane hold location","where is frostmane hold","find frostmane hold"},gp=true},{q="Why are the dwarves interested in this cave?",a="Dwarven leaders in Kharanos fear the Frostmane are gathering strength to raid settlements. They send scouts to map the caves and thin the trolls’ ranks.",al={"why scout frostmane hold","kharanos troll quest"},it="purpose"},{q="Are there troggs in Frostmane Hold?",a="No. Frostmane ice trolls occupy the hold. Troggs in Dun Morogh remain mainly in their own dens and the ruins of Gnomeregan.",al={"troggs frostmane hold","rockjaw frostmane"},it="threat"},{q="What is Frostmane Hold?",a="Frostmane Hold is a sprawling cave system and base camp nestled into the frigid mountains in western Dun Morogh, just south of Gnomeregan. Composed of rustic structures and deep caverns, it serves as a central stronghold for the indigenous Frostmane ice trolls.",al={"what is frostmane hold","frostmane hold dun morogh","about frostmane hold"},it="place",add="81bf3a2c"},{q="Is Frostmane Hold dangerous?",a="It is extremely hazardous for any Alliance traveler. The hold is fiercely defended by Frostmane headhunters and hideskinners who show no mercy to outsiders wandering into their territory.",al={"is frostmane hold dangerous","frostmane hold danger","how safe is frostmane hold"},it="danger",add="406236bf"},{q="Why is it called Frostmane Hold?",a="The stronghold takes its name directly from the Frostmane tribe of ice trolls who carved out the caves and claim these frozen mountains as their ancestral homeland.",al={"why is it called frostmane hold","frostmane hold name meaning","where did the name frostmane hold come from"},it="name",add="0c447a8f"}},ang={["race:Dwarf"]="The Frostmane have contested Dun Morogh for centuries. As a mountaineer, you help clear Frostmane Hold and protect Ironforge’s snowy heartland.",["race:Gnome"]="South of Gnomeregan, Frostmane Hold is another dangerous front beside the embattled former gnome capital."},kw={"dun morogh","frostmane","frostmane hold","headhunter","hideskinner","ice troll","kharanos","vejrek"},rel={"quest:287","zone:dunmorogh","subzone:kharanos","zone:gnomeregan","topic:troll"},src={"Frostmane Hold"}}
E["subzone:frostmane-hovel"] = {t="subzone",n="Frostmane Hovel",z="dunmorogh",s="In southern Coldridge Valley, Frostmane trolls press toward the dwarven training grounds.",h="In southern Coldridge Valley, Frostmane trolls press toward the dwarven training grounds.",sec={{t="A Troll Den in the Valley",b="Frostmane trolls shelter in caverns cut into the mountains south of Coldridge Valley. They refuse to yield the high snows to Ironforge and raid nearby dwarven camps. Their attacks disrupt the supply lines into the valley.",sp=0}},faq={{q="What is the Frostmane Hovel?",a="Frostmane trolls take shelter from foul weather in a natural cavern in southern Coldridge Valley, encroaching on dwarven territory.",al={"frostmane hovel","what is this cave","coldridge troll cave"},it="place"},{q="Why are there trolls in Coldridge Valley?",a="The Frostmane tribe has lived in Dun Morogh's snowy peaks for generations. Bitter rivals of the Bronzebeard dwarves, they descend from the high ridges to raid supply paths and challenge dwarven settlements.",al={"why trolls here","dun morogh trolls","frostmane presence"},it="why_here"},{q="Who controls this cave?",a="Raiding Frostmane trolls occupy the cave and use its sheltered crevice to stage incursions across the valley's southern shelf.",al={"who leads the cave","who lives in frostmane hovel"},it="in_charge"}},ang={["race:Dwarf"]="As a young Bronzebeard recruit training in Coldridge Valley, you must help secure the perimeter against the hostile Frostmane tribe in caves like this.",["faction:Alliance"]="As an Alliance traveler, you can see the Frostmane presence just outside Anvilmar. Even Ironforge's heartland must defend itself against nearby foes."},kw={"anvilmar","coldridge valley","dun morogh","frostmane","hovel","trolls"},rel={"subzone:coldridge-valley","zone:dunmorogh","topic:troll"},src={"Frostmane Hovel"}}
E["subzone:gnomeregan"] = {t="subzone",n="Gnomeregan",z="dunmorogh",s="Troggs and leper gnomes roam Gnomeregan’s poisoned halls among the broken defenses. The city was once the gnomes’ underground capital, until a desperate defense ended in catastrophe.",h="Troggs and leper gnomes roam Gnomeregan’s poisoned halls among the broken defenses.",sec={{t="A Wonder of Engineering",b="Gnomeregan’s halls once rang with the work of gnomish engineers. Ironforge dwarves helped build the city centuries ago, carving it into the snowy crags of western Dun Morogh. Steam-driven gears, copper pipes, and vast assembly halls made it the heart of gnomish industry and invention. During the Second War, its designs, flying machines, and complex weapons supplied the Alliance. Even Orgrim Doomhammer’s Horde could not break the city during its siege.",sp=0},{t="The Fall and the Poisoned Halls",b="During the Third War, troggs surged up from deep underground and broke into Gnomeregan’s lowest chambers. High Tinker Gelbin Mekkatorque chose to face the invasion alone, unwilling to draw Alliance armies away from the slaughter in Lordaeron.\n\nOn the advice of chief engineer Mekgineer Thermaplugg, he ordered radioactive gas released through the lower chambers to wipe out the troggs. Instead, the gas empowered many troggs and killed nearly eighty percent of the gnomish people. Survivors exposed to it became twisted leper gnomes, and Thermaplugg took control of the poisoned ruins.",sp=0}},faq={{q="Why is Gnomeregan full of radiation?",a="High Tinker Mekkatorque released radioactive gas into Gnomeregan’s lower vents as troggs overran the city, following Mekgineer Thermaplugg’s advice. The gas was meant to kill the troggs, but it slaughtered thousands of gnomes, changed survivors into leper gnomes, and left the city permanently irradiated.",al={"why is it radioactive","gnomeregan toxic gas","what poisoned gnomeregan"},it="ruin"},{q="Where are all the surviving gnomes now?",a="Surviving gnomes fled to Ironforge, where King Magni Bronzebeard gave them refuge in the Tinkers’ Court. High Tinker Gelbin Mekkatorque works there to aid his scattered people and plan their return home.",al={"where do gnomes live","gnome refugees","where is mekkatorque"},it="people"},{q="Who controls Gnomeregan now?",a="Mekgineer Thermaplugg controls Gnomeregan and has declared himself its king. Once Mekkatorque’s chief advisor, he commands rogue defense automatons, irradiated leper gnomes, and mutant troggs from deep within the city’s core.",al={"who is the boss of gnomeregan","gnomeregan leader","thermaplugg"},it="in_charge"},{q="Why didn't the Alliance help save Gnomeregan during the invasion?",a="Mekkatorque chose not to ask the Alliance for help. As the Scourge ravaged humanity during the Third War, the gnomes kept their struggle underground secret rather than draw vital defenders away from Lordaeron.",al={"why alliance no help","why didn't humans help gnomes","gnomes in third war"},it="history"},{q="What is Gnomeregan?",a="Gnomeregan is the subterranean capital city of the gnomes, built beneath the snowy peaks of Dun Morogh. A marvel of wrought-iron engineering, clockwork machinery, and steam-driven technology, it stood for generations as the bustling heart of gnomish culture, ingenuity, and political power alongside their dwarven allies.",al={"what is gnomeregan","gnomeregan city","gnome capital"},it="place",add="927c35f4"},{q="Is Gnomeregan dangerous?",a="Extremely dangerous. The lower depths are awash in lingering, lethal radiation capable of warping the body and mind. The halls swarm with savage troggs, deranged leper gnomes, malfunctioning combat automatons, and the lethal traps of the self-proclaimed King Thermaplugg. Entering without proper preparation or a stout group invites a horrific death.",al={"is gnomeregan dangerous","dangers of gnomeregan","how dangerous is gnomeregan"},it="danger",add="702e95d4"}},ang={["race:Gnome"]="For gnomes, Gnomeregan’s loss remains a deep wound. Entering its irradiated halls is a solemn pilgrimage to destroy Thermaplugg and recover lost mechanical heirlooms.",["profession:Engineering"]="Though radioactive poison chokes Gnomeregan, it holds the Eastern Kingdoms’ greatest concentration of schematics, advanced spare parts, and working industrial machinery."},kw={"dun morogh","gnomeregan","leper gnome","mekkatorque","thermaplugg","tinkers court","trogg"},rel={"zone:dunmorogh","npc:gelbin-mekkatorque","npc:sicco-thermaplugg","topic:leper-gnome","topic:trogg","subzone:tinkers-court","quest:412"},src={"Gnomeregan"}}
E["subzone:gol-bolar-quarry"] = {t="subzone",n="Gol'Bolar Quarry",z="dunmorogh",s="At Gol'Bolar Quarry, troggs have driven the miners from the snowy hills of southeastern Dun Morogh. The Ironforge dwarves came for stone and ore, but now the dig lies quiet.",h="At Gol'Bolar Quarry, troggs have driven the miners from the snowy hills of southeastern Dun Morogh.",sec={{t="A Quarry Under Siege",b="Ironforge dwarves opened Gol'Bolar Quarry southeast of Kharanos to draw stone and mineral wealth from the mountains. Their digging broke into underground warrens and brought a horde of hostile troggs into the open. The creatures soon drove out the miners.\n\nThe upper camp is now an embattled staging ground. Overseers, tradesfolk, and Prospector Gehn gather dwarven and gnomish recruits there to drive the troggs back and reclaim the pit.",sp=0}},faq={{q="What is Gol'Bolar Quarry?",a="Gol'Bolar Quarry is an open-pit mine in southeastern Dun Morogh. Ironforge dwarves keep it as a dig site and a small outpost with supplies and work for local adventurers.",al={"gol bolar","what is this place","quarry info"},it="place"},{q="Why are there so many troggs here?",a="Dwarven miners dug too deeply and broke into tunnels inhabited by troggs. The creatures swarmed into the open pits and nearby mine shafts, forcing the miners back to the quarry's upper rim.",al={"why are troggs here","trogg infestation","who attacked the quarry"},it="threat"},{q="Who is Prospector Gehn?",a="Prospector Gehn is a dwarven supervisor at the quarry camp. He oversees efforts to secure the dig site and offers bounties and tasks to adventurers willing to cull the troggs.",al={"who is gehn","prospector gehn"},it="identity"},{q="What happened at Gol'Bolar Quarry?",a="Gol'Bolar began as an active dwarven excavation site and mining camp in southeastern Dun Morogh, dedicated to carving stone and unearthing valuable minerals. However, standard operations ground to a sudden halt when subterranean troggs broke through into the lower dig and the nearby mine. The vicious creatures quickly overwhelmed the miners, forcing the dwarves to pull back and establish a fortified camp on the quarry's upper ridges to recruit help in reclaiming it.",al={"gol'bolar quarry history","what happened at golbolar","gol'bolar background"},it="history",add="e8696793"},{q="Who lives in or runs Gol'Bolar Quarry?",a="A resilient group of dwarven miners, overseers, and support staff hold the camp overlooking the pit. Overseen by Prospector Gehn and fellow excavators, the outpost includes weapon vendors, provisioners, and profession trainers who support young mountaineers and explorers working to drive back the trogg menace.",al={"who runs gol'bolar quarry","gol'bolar quarry camp","who lives at gol'bolar"},it="residents",add="3a8dc0a0"},{q="Is Gol'Bolar Quarry dangerous?",a="Yes. While the upper rim and small camp remain protected by local dwarves, the open pit and the quarry mine below swarm with hostile troggs. Any traveler descending into the excavation without caution risks being swarmed by aggressive tunnelers claiming the dig site as their own.",al={"is gol'bolar dangerous","danger in gol'bolar quarry","threats in gol'bolar"},it="danger",add="becb3bb6"}},ang={["profession:Mining"]="Exposed rock tiers and nearby tunnels hold plentiful mineral veins. Entrenched troggs stand between you and the ore.",["race:Dwarf"]="As a dwarf, clearing Gol'Bolar Quarry protects Ironforge's mountain resources and upholds clan pride. The dwarves cannot afford to let the troggs seize them."},kw={"dun morogh","gol'bolar","mine","prospector gehn","quarry","trogg"},rel={"subzone:gol-bolar-quarry-mine","zone:dunmorogh","topic:trogg","topic:gnome"},src={"Gol'Bolar Quarry"}}
E["subzone:gol-bolar-quarry-mine"] = {t="subzone",n="Gol'Bolar Quarry Mine",z="dunmorogh",s="Troggs hold Gol'Bolar Quarry Mine beneath the quarry in eastern Dun Morogh. Dwarves of Ironforge mined its tunnels for stone and rich ore until their picks broke into trogg caverns. Now Hammerspine leads the warband in the deepest shafts.",h="Troggs hold Gol'Bolar Quarry Mine beneath the quarry in eastern Dun Morogh.",sec={{t="A Breach in the Deep",b="The dwarves' pickaxes broke through a wall into caverns where troggs dwelled. Their mining ended there. Troggs poured from the darkness, overwhelmed the crews, and drove them from the mine. The abandoned shafts remain in trogg hands.",sp=0},{t="Lair of Hammerspine",b="Younger troggs roam the quarry's sunlit terraces, but the mine shelters the warband's fiercest fighters. Deep in its cramped tunnels lurks Hammerspine, their vicious chieftain. Local mountaineers still need to reclaim the valuable quarry. To do so, they must reach the mine's deepest shafts and cut off the troggs at their source.",sp=0}},faq={{q="Why is the mine full of troggs?",a="Dwarven miners broke into a hidden cavern as they dug. Troggs swarmed through the breach, slaughtered some miners and drove the rest out, then claimed the shafts.",al={"why are troggs in gol bolar","how did troggs get here","who took over the mine"},it="ruin"},{q="Who leads the troggs inside Gol'Bolar Quarry Mine?",a="Hammerspine leads the troggs in Gol'Bolar Quarry Mine. The hulking brute commands the warband's strongest fighters deep in the shafts.",al={"mine boss","trogg leader gol bolar","who is hammerspine"},it="residents"},{q="Is the mine different from the rest of the quarry?",a="Yes. Weaker troggs roam the outer quarry pit, while the deep, cramped tunnels hold the toughest fighters and their chieftain.",al={"quarry vs mine","are the mine troggs harder"},it="place"},{q="Can miners still work here?",a="No. Mining has stopped. Dwarven mountaineers and adventurers now fight to drive out the troggs instead of gathering stone.",al={"is the mine active","are dwarves still mining"}},{q="What happened at Gol'Bolar Quarry Mine?",a="The mine was actively excavated by dwarven prospectors until their digging broke directly into an underground cavern system inhabited by troggs. Surprised and overwhelmed by the feral onslaught, the dwarves were violently driven from the depths, losing both the inner tunnels and the surrounding quarry to the invaders.",al={"gol bolar quarry mine history","what happened at the mine","gol bolar mine backstory"},it="history",add="58d8a204"},{q="Is Gol'Bolar Quarry Mine dangerous?",a="It is considerably more perilous than the quarry outside. While weaker scavengers wander the open pits, the deepest and strongest troggs lurk in these cramped tunnels under the command of their brutal leader, Hammerspine. Anyone entering unprepared faces a lethal subterranean ambush.",al={"is gol bolar mine dangerous","how dangerous is gol bolar mine","gol bolar mine trogg danger"},it="danger",add="2d64c093"}},ang={["race:Dwarf"]="Each swing of a pick into the mountain risks waking what lies beneath. Reclaiming Gol'Bolar Mine would restore its value and dwarven pride.",["profession:Mining"]="Hostile troggs still block the mine. Its deepest tunnels must be cleared before miners can return."},kw={"dun morogh","gol'bolar","gol'bolar quarry mine","hammerspine","mine","quarry","troggs"},rel={"subzone:gol-bolar-quarry","topic:trogg","zone:dunmorogh"},src={"Gol'Bolar Quarry Mine"}}
E["subzone:grizzled-den"] = {t="subzone",n="Grizzled Den",z="dunmorogh",s="In Dun Morogh, wendigo packs make their lair in Grizzled Den, southwest of Kharanos.",h="In Dun Morogh, wendigo packs make their lair in Grizzled Den, southwest of Kharanos.",sec={{t="A Frost-Chilled Lair",b="Southwest of Kharanos, Grizzled Den cuts into Dun Morogh’s crags. Wendigo packs make their home in its hollows. These aggressive, ape-like beasts breathe frost at intruders and band together to defend their lair. Hunters brave the cavern for thick wendigo manes, used by craftsmen to line cold chairs and carriage seats with insulating fur.",sp=0},{t="Hidden Treasures",b="Prospectors work copper veins in Grizzled Den’s frozen stone walls. Scouts search its darker corners for discarded footlockers. Deeper in the tunnels, the den’s largest and most vicious predators wait in the shadows.",sp=0}},faq={{q="Where is the Grizzled Den located?",a="Grizzled Den lies among Dun Morogh’s snow-covered mountain ridges, southwest of Kharanos.",al={"grizzled den location","where is grizzled den","how to get to grizzled den"},it="place",gp=true},{q="What creatures live in the Grizzled Den?",a="Ferocious wendigo packs live in Grizzled Den. The white-furred beasts breathe freezing frost and swarm intruders.",al={"what is in grizzled den","grizzled den mobs","creatures inside grizzled den"},it="residents"},{q="Why do people venture into the Grizzled Den?",a="Hunters seek wendigo manes for warm seat covers, while others enter the tunnels to mine copper from the walls.",al={"why go to grizzled den","grizzled den quests","wendigo manes"},it="purpose"},{q="What is the Grizzled Den?",a="The Grizzled Den is an expansive cave system tucked into the snowy hills southwest of Kharanos in Dun Morogh. It serves as a natural lair carved into the mountains, notorious across the region for its frosty interior and the wild beasts sheltering within its rocky depths.",al={"what is grizzled den","grizzled den overview","about grizzled den"},it="place",add="4377d186"},{q="Is the Grizzled Den dangerous?",a="Yes, it poses a genuine peril to lone travelers and novice adventurers. The cave is infested with aggressive wendigos capable of breathing frost spells. Worse still, these beasts tend to flock together to overwhelm invaders, and an exceptionally ferocious specimen lurks deep within the caverns.",al={"how dangerous is grizzled den","grizzled den danger","is grizzled den safe"},it="danger",add="44a06046"}},ang={["profession:Mining"]="Copper deposits run through Grizzled Den’s outer and inner tunnels, though wendigos make mining there dangerous.",["race:Dwarf"]="For young dwarven mountaineers training around Kharanos, clearing Grizzled Den is a rite of passage."},kw={"cave","dun morogh","frost","grizzled den","kharanos","wendigo"},rel={"quest:313","subzone:kharanos","zone:dunmorogh"},src={"Grizzled Den"}}
E["subzone:helm-s-bed-lake"] = {t="subzone",n="Helm's Bed Lake",z="dunmorogh",s="In southeastern Dun Morogh, dwarves keep a hole open in Helm's Bed Lake for fresh water. But beasts, troggs, and hostile Dark Iron dwarves make the shore dangerous.",h="In southeastern Dun Morogh, dwarves keep a hole open in Helm's Bed Lake for fresh water.",sec={{t="A Treacherous Shoreline",b="The ice is firm enough to cross, but the banks are dangerous. Displaced troggs scavenge along the ridges, and wild beasts prowl the edges. South of the water, hostile Dark Iron dwarves have taken an abandoned lodge. They ambush travelers who pass nearby.",sp=0}},faq={{q="Why is there an open hole in the middle of the frozen lake?",a="Local dwarves keep a hole open in the thick ice to reach fresh water through Dun Morogh's freezing cold.",al={"ice hole","water access","why is the ice broken"},it="purpose"},{q="What dangers lurk around Helm's Bed Lake?",a="The solid ice is safe to cross, but wild beasts and displaced troggs prowl the shore. Hostile Dark Iron dwarves occupy an old building south of the water and drive away anyone who comes near.",al={"threats at helms bed lake","who is attacking here","enemies nearby"},it="threat"},{q="Who is Narm Faulk?",a="Narm Faulk is a dwarf whose body lies along Helm's Bed Lake's shore. He fell amid the sudden rise of threats and Dark Iron infiltrators in the area.",al={"narm faulk corpse","dead dwarf near lake","dead body at helms bed lake"},it="identity"},{q="Are the Dark Iron dwarves officially occupying the lake?",a="The Dark Iron dwarves have not seized the lake, but an armed squad has taken an abandoned structure just south of it. They use it as a forward position for skirmishes into central Dun Morogh.",al={"dark irons at the lake","dark iron dwarf lodge"},it="conflict"},{q="What is Helm's Bed Lake?",a="Helm's Bed Lake is a small, mostly frozen lake nestled in southeastern Dun Morogh. A hole in the thick ice is kept open to allow access to fresh drinking water. While the frozen surface itself offers steady footing, the wilderness surrounding the lake is far less welcoming, teeming with predators, roaming troggs, and hostile Dark Iron infiltrators.",al={"helms bed lake","where is helms bed lake","what is this lake"},it="place",add="ba815d26"}},ang={["race:Dwarf"]="As a dwarf of Ironforge, you know Helm's Bed Lake as a vital source of fresh water, and its shores have grown less secure. Dark Iron saboteurs and troggs are pushing deeper into Dun Morogh's heartland.",["faction:Alliance"]="As an Alliance traveler heading east toward Loch Modan, stay alert. The trail south passes close to Dark Iron ambushes."},kw={"dark iron","dun morogh","helm's bed lake","ice hole","narm faulk","trogg"},rel={"zone:dunmorogh","topic:trogg"},src={"Helm's Bed Lake"}}
E["subzone:iceflow-lake"] = {t="subzone",n="Iceflow Lake",z="dunmorogh",s="In western Dun Morogh, dwarves keep fishing holes open at Iceflow Lake, just north of Brewnall Village. Snow-covered islands rise from its center, where winter wolves prowl under their alpha, Timber.",h="In western Dun Morogh, dwarves keep fishing holes open at Iceflow Lake, just north of Brewnall Village.",sec={{t="Frozen Depths and Island Predators",b="Paxton Ganter and other local dwarves clear thick ice from the lake for drinking water and fish. Bitter cold sweeps the shore, yet it still sustains them.\n\nThe islands are dangerous ground. A fierce pack of wild wolves prowls the icy mounds, led by Timber, a savage gray worg.",sp=0}},faq={{q="Why is there an open hole in the frozen lake?",a="Dwarves from nearby Brewnall Village keep part of Iceflow Lake clear because the cold freezes it solid. The open water gives them drinking water and a place to fish.",al={"ice hole","why is the ice broken","brewnall fishing hole"},it="purpose"},{q="Who is Paxton Ganter?",a="Paxton Ganter is a dwarven fisherman and fishing trainer beside Iceflow Lake. He teaches travelers to fish in Dun Morogh.",al={"paxton ganter","dwarf at iceflow lake","lake dwarf"},it="people"},{q="What threats live on the lake's islands?",a="Hungry winter wolves prowl the central islands under Timber, a ferocious worg. Travelers crossing the ice may be ambushed by the pack.",al={"timber","wolves in the lake","island wolves dun morogh"},it="threat"},{q="What is Iceflow Lake?",a="Iceflow Lake is a medium-sized, frozen body of water located in western Dun Morogh, just outside Brewnall Village. The bitter mountain altitude keeps its waters locked beneath thick ice year-round, save for a designated hole maintained by local dwarves for fishing and fresh water. Dominated by central islands overrun with aggressive predators, it serves as both a vital local resource and a treacherous crossing for travelers traversing the snowy crags.",al={"what is iceflow lake","iceflow lake dun morogh","where is iceflow lake"},it="place",add="26667757"},{q="Is Iceflow Lake dangerous?",a="Yes, traversing Iceflow Lake carries significant risk. While the ice itself is thick enough to walk upon, the large islands rising from the center of the lake are inhabited by a vicious pack of ravenous winter wolves led by the fearsome worg Timber. Anyone wandering onto the ice without watching their surroundings risks drawing the attention of these hungry predators.",al={"is iceflow lake dangerous","dangers at iceflow lake","iceflow lake threats"},it="danger",add="d98fd8f9"}},ang={["race:Dwarf"]="As a dwarf, you rely on Iceflow Lake for fresh water, though danger crosses its ice. Predatory wolves may roam there, so stay alert.",["class:Hunter"]="As a hunter, you can track hardy winter beasts along the snowy shores and central islands, including Timber, the fearsome worg alpha."},kw={"brewnall village","dun morogh","frozen lake","ice fishing","iceflow lake","paxton ganter","timber"},rel={"zone:dunmorogh","subzone:brewnall-village"},src={"Iceflow Lake"}}
E["subzone:ironband-s-compound"] = {t="subzone",n="Ironband's Compound",z="dunmorogh",s="Dark Iron dwarves now hold Ironband's Compound south of Helm's Bed Lake in eastern Dun Morogh. Sturgy Ironband once used the camp, but its fall has brought danger to travelers and nearby settlements.",h="Dark Iron dwarves now hold Ironband's Compound south of Helm's Bed Lake in eastern Dun Morogh.",sec={{t="A Fall to the Dark Irons",b="Sturgy Ironband raised the camp as a staging post in Dun Morogh's snowy wilderness. Dark Iron infiltrators then pushed deep into Bronzebeard territory and seized it. Their forces now stand close to Ironforge, and the outpost threatens the city's edge.",sp=0},{t="A Threat to Ironforge",b="Within Dun Morogh, the Dark Iron camp is a grave provocation to Ironforge. The city keeps watch and sends seasoned warriors to recover fallen scouts. They also seek vital intelligence on the Dark Iron threat in the mountain kingdom.",sp=0}},faq={{q="Who originally built Ironband's Compound?",a="Sturgy Ironband once inhabited and used the outpost. Hostile forces drove him out and seized it.",al={"who made this camp","sturgy ironband","who owns ironbands compound"},it="origin"},{q="Who controls Ironband's Compound now?",a="Dark Iron dwarves now control the camp. They attack wanderers and Ironforge patrols that come near.",al={"who is here","what enemies are here","dark irons dun morogh"},it="residents"},{q="Where is Ironband's Compound located?",a="The compound lies in eastern Dun Morogh's snowy hills, south of Helm's Bed Lake.",al={"where is ironbands compound","how to find ironband compound","ironband location"},it="place",gp=true},{q="Why is this camp important to the leaders of Ironforge?",a="An enemy clan has fortified a base in Dun Morogh, raising alarm over Ironforge's security. The city's authorities send fighters to gather evidence of Dark Iron infiltration.",al={"why care about this camp","ironforge response","dark iron threat"},it="threat"},{q="What is Ironband's Compound?",a="Ironband's Compound is a fortified campsite situated south of Helm's Bed Lake in eastern Dun Morogh. Originally an outpost inhabited by the dwarf Sturgy Ironband, the compound has recently been overrun and occupied by a hostile contingent of Dark Iron dwarves.",al={"what is ironbands compound","ironbands compound dun morogh","tell me about ironband compound"},it="place",add="18d4f4e7"},{q="What happened at Ironband's Compound?",a="Once held peacefully by Sturgy Ironband, this remote outpost was violently ambushed and seized by infiltrating Dark Iron dwarves. The invaders drove out its rightful occupants and established an entrenched staging ground directly within Dun Morogh's borders, alarming the authorities in Ironforge.",al={"ironbands compound history","what happened here ironband","how was ironbands compound lost"},it="history",add="ea846983"},{q="Why is Ironband's Compound abandoned?",a="The outpost was not simply abandoned—it was violently captured. Sturgy Ironband and his allies were forced out when Dark Iron infiltrators launched a surprise assault, turning the dwarven camp into a heavily guarded enemy encampment.",al={"why is ironbands compound abandoned","is ironbands compound ruined","what happened to sturgy ironband"},it="ruin",add="be9cbc3a"},{q="Is Ironband's Compound dangerous?",a="It is extremely hazardous for lone travelers. The Dark Iron dwarves stationed here are openly hostile, heavily armed, and will assault anyone venturing near the compound to protect their foothold in Dun Morogh.",al={"is ironbands compound dangerous","ironbands compound threats","can i go to ironbands compound"},it="danger",add="c49e4d1f"},{q="Why is it called Ironband's Compound?",a="The encampment bears the name of Sturgy Ironband, the dwarf who originally established and inhabited the site before hostile Dark Iron forces seized it.",al={"why called ironbands compound","who is ironband","ironbands compound name origin"},it="name",add="8089f1d9"}},ang={["race:Dwarf"]="As a Bronzebeard, you see the Dark Irons' hold within Dun Morogh as an insult and a continuing danger to your homeland.",["class:Warrior"]="As a warrior, Ironforge's veteran trainers send you here to aid fallen comrades and gather proof of the Dark Iron presence."},kw={"dark iron","dun morogh","dwarf","helm's bed lake","ironband's compound","ironforge","sturgy ironband"},rel={"zone:dunmorogh","subzone:helm-s-bed-lake","zone:ironforge","topic:dwarf"},src={"Ironband's Compound"}}
E["subzone:ironforge"] = {t="subzone",n="Ironforge",z="dunmorogh",s="Beneath Dun Morogh, Ironforge’s Great Forge still burns at the heart of dwarven rule and Alliance trade. Deep within Ironforge Mountain, the city anchors Khaz Modan and guards the Alliance.",h="Beneath Dun Morogh, Ironforge’s Great Forge still burns at the heart of dwarven rule and Alliance trade.",sec={{t="The Mountain Fortress",b="Ironforge fills the deep halls of Ironforge Mountain, with stone rings circling the Great Forge. Dwarves founded the city millennia ago, after awakening and migrating from Uldaman. It has endured ages of history, including the War of the Three Hammers, which left the Bronzebeard clan in sole control.\n\nNatural magma pours through the mountain and powers the city. Massive stone gates guard its halls. Dwarven craftsmen and warriors share them with many exiled gnomes, who arrived after Gnomeregan fell recently.",sp=0},{t="Heart of Alliance Trade",b="Ironforge is one of the Alliance’s busiest centers of commerce and industry. From the High Seat, King Magni Bronzebeard rules Khaz Modan. Dwarven prospectors, miners, and engineers work beside gnome refugees in Tinker Town.\n\nBeneath the mountains, the Deeprun Tram runs to Stormwind City. It carries trade and troops at high speed, keeping the capitals linked in mutual defense.",sp=0}},faq={{q="Who rules Ironforge right now?",a="King Magni Bronzebeard rules Ironforge from the High Seat. The city is Khaz Modan’s seat, under the sole leadership of the Bronzebeard clan.",al={"who is the king of ironforge","ironforge leader","who leads ironforge"},it="in_charge"},{q="Why are there so many gnomes living in Ironforge?",a="After Gnomeregan fell, the surviving gnomes fled to Ironforge. The Bronzebeards welcomed their longtime allies and gave them sanctuary in Tinker Town.",al={"why are gnomes in ironforge","gnomes tinker town","where did gnomes come from"},it="people"},{q="How does Ironforge connect to Stormwind City?",a="The Deeprun Tram connects Ironforge directly to Stormwind. Built by gnomes, it runs underground from Tinker Town to Stormwind’s Dwarven District.",al={"tram to stormwind","how to get to stormwind","subway to stormwind"}},{q="What is the Great Forge in the center of the city?",a="The Great Forge is an immense furnace fueled by natural rivers of magma channeled through the heart of the mountain. It is Khaz Modan’s main center for smithing and smelting.",al={"giant forge in ironforge","what is the great forge","lava in ironforge center"},it="origin"},{q="What is Ironforge?",a="Ironforge is the underground capital city of the dwarves and the seat of the Kingdom of Khaz Modan. Carved entirely out of stone beneath the tallest mountain in Dun Morogh, it stands as an impregnable subterranean fortress and an industrial heartland for the Alliance. Its districts radiate out in concentric rings around the massive Great Forge, packed with smelters, smithies, lively taverns, and military halls.",al={"what is ironforge","ironforge lore","about ironforge"},it="place",add="492ad021"},{q="What happened at Ironforge?",a="Ironforge was founded millennia ago when ancient dwarves wandered from Uldaman and built the Great Forge to honor the titan Khaz'goroth. Centuries later, civil strife tore through the mountain during the War of the Three Hammers. Following the death of High King Modimus Anvilmar, the Bronzebeard, Wildhammer, and Dark Iron clans fought violently for control until the Bronzebeards ousted their rivals, claiming sole dominion over the mountain fortress.",al={"ironforge history","what happened here","ironforge past"},it="history",add="f6c71775"},{q="Is Ironforge dangerous?",a="Within its massive stone gates, Ironforge is one of the safest sanctuaries in the Eastern Kingdoms. Guarded heavily by dwarven mountaineers and royal sentries, its thick mountain walls keep surface perils at bay. So long as you do not fall into the molten rivers of the Great Forge or belong to the Horde, you face little peril walking its bustling, cozy streets.",al={"is ironforge safe","dangers in ironforge","threats in ironforge"},it="danger",add="9692900f"},{q="Why is the city called Ironforge?",a="The city takes its name from the Great Forge that sits at the center of the cavern, as well as the towering mountain it was carved beneath. When the early dwarves first carved into the peak and constructed their grand smelting works, the entire underground metropolis grew outward around that monumental forge.",al={"why is it called ironforge","how ironforge got its name","ironforge name origin"},it="name",add="ea3b645e"}},ang={["race:Dwarf"]="As a dwarf, Ironforge is your ancestral capital and the heart of the Bronzebeard clan. Dwarven craft, valor, and history are carved into the living mountain stone.",["race:Gnome"]="As a gnome, you have lost Gnomeregan to troggs and radiation. Your people have made Tinker Town a temporary refuge and a staging ground for reclaiming your home."},kw={"bronzebeard","deeprun tram","dun morogh","great forge","high seat","ironforge","khaz modan","magni","tinker town"},rel={"zone:dunmorogh","subzone:great-forge","subzone:high-seat","subzone:tinker-town","subzone:deeprun-tram","topic:bronzebeard-clan","zone:gnomeregan","zone:stormwind"},src={"Ironforge"}}
E["subzone:ironforge-airfield"] = {t="subzone",n="Ironforge Airfield",z="dunmorogh",s="Gnome flying machines and dwarven mountaineers keep watch at Ironforge Airfield, high above Dun Morogh. Its plateau overlooks jagged crags and the steep descent toward the Wetlands.",h="Gnome flying machines and dwarven mountaineers keep watch at Ironforge Airfield, high above Dun Morogh.",sec={{t="A Hidden Redoubt in the Crags",b="Above Dun Morogh's trails, gnome flying machines line open strips among the peaks. Dwarven stonework holds the ridgelines, where mountaineers watch the perimeter. Nearby, engineers tend the machines and inspect their engines in the cold.",sp=0},{t="Frontier Skirmishes and Frozen Valleys",b="Frostmane trolls dwell in caves near the airfield and harass the dwarven sentries. Across the frozen waters beneath the peaks, dwarven defenders and Stormpike patrols clash with troll raiders. So the outpost remains on guard.",sp=0}},faq={{q="How do you get up to the airfield?",a="No roads, flights, or maintained tunnels link the valley to Ironforge or lower Dun Morogh. You must climb steep mountainsides on foot, following difficult ridgeline paths from Loch Modan or near Dun Morogh's passes.",al={"get to airfield","how to climb to airfield","airfield location","airfield path"},it="arrival",gp=true},{q="What is the purpose of this place?",a="The airfield tests and maintains flying machines and scouts the mountain borderlands between Dun Morogh, Loch Modan, and the Wetlands. Dwarven mountaineers and gnome engineers work there.",al={"why is there an airstrip","what is ironforge airfield for"},it="purpose"},{q="Who is attacking the dwarven guards here?",a="Frostmane trolls from nearby caves attack the dwarven guards. The mountaineers clash with them over the frozen lake below the runway.",al={"who attacks airfield","who is fighting on the lake"},it="threat"},{q="Is the airfield tied to any official quests?",a="No standard assignment sends travelers to the airstrip. The remote plateau lies apart from the dwarven kingdom's main routes.",al={"any quests here","airfield quests"},gp=true},{q="What is Ironforge Airfield?",a="Ironforge Airfield, also called the Dun Morogh Airstrip, is a high mountain base nestled in the peaks northeast above Ironforge. Constructed with landing strips, dwarven battlements, and mechanical hangars, it serves as a staging ground and testing site for gnomish flying machines and dwarven aerial operations high above the snowy crags.",al={"ironforge airfield","what is the dun morogh airstrip","what is this airfield"},it="place",add="d601e954"},{q="Who lives in or runs Ironforge Airfield?",a="The airfield is manned by Ironforge Mountaineers and dwarven guards protecting the mountain perimeter, alongside gnomish engineers and pilots tinkering with flying machines along the runways. Scouts affiliated with the Stormpike Guard also maintain a presence in the surrounding snowy passes.",al={"who controls ironforge airfield","who runs the airfield","who is at the airstrip"},it="residents",add="ef0ab7f8"},{q="Is Ironforge Airfield dangerous?",a="While the airfield itself is secured by dwarven sentries and gnomish aviators, the surrounding valley holds real danger. Hostile Frostmane trolls inhabit caves bordering the southern frozen lake and frequently clash with dwarven patrols, while wild bears roam the icy ridges nearby.",al={"is ironforge airfield dangerous","airfield threats","danger at the airstrip"},it="danger",add="74586b0d"}},ang={["profession:Engineering"]="As a tinker, you see gnomish flying machines assembled and kept in extreme cold.",["race:Dwarf"]="As a dwarf, you know Ironforge's Mountaineers keep watch even in Khaz Modan's most inaccessible heights."},kw={"airfield","airstrip","dun morogh","flying machine","frostmane","ironforge","mountaineers"},rel={"zone:dunmorogh","zone:ironforge","zone:lochmodan","subzone:north-gate-pass","subzone:gol-bolar-quarry","topic:gnome","topic:troll"},src={"Ironforge Airfield"}}
E["subzone:kharanos"] = {t="subzone",n="Kharanos",z="dunmorogh",s="Travelers leaving Coldridge Valley make Kharanos their primary stop, just down the road from Ironforge. The town has a forge, gnomish workshops, and the famous Thunderbrew Distillery.",h="Travelers leaving Coldridge Valley make Kharanos their primary stop, just down the road from Ironforge.",sec={{t="A Hearty Frontier Haven",b="Along Dun Morogh's central road, Kharanos is the first true town for recruits arriving from Anvilmar. The cold and wind bite hard, but dwarven grit and gnomish ingenuity keep the settlement thriving. Its heart is a roaring public forge and the Thunderbrew Distillery, whose ale is counted among the finest in Khaz Modan and renowned across the eastern mountains.\n\nCrafters work among weary travelers seeking warmth. Together, they make Kharanos an essential place for business in the lower peaks.",sp=0},{t="Guarding the Lowlands",b="Behind Kharanos's cozy hearths, a military outpost guards the mountain passes. Fierce indigenous wendigo prowl the frozen caverns directly to the west, while aggressive Frostmane trolls hold Shimmer Ridge to the northwest.\n\nIronforge's regular forces are stretched thin across the realm. So Kharanos relies heavily on visiting adventurers and local watchmen to drive back raiding parties, cull dangerous predators, and keep the trade routes open.",sp=0}},faq={{q="What is Kharanos?",a="In central Dun Morogh, Kharanos is the main settlement for dwarves and gnomes. It is a crossroads linking Coldridge Valley, Ironforge, and the outer wilderness, with trade, training services, and an inn.",al={"kharanos overview","where is kharanos","kharanos town"},it="place"},{q="What services and facilities are in Kharanos?",a="The famous Thunderbrew Distillery is the town's inn and taproom. Kharanos also has a large public forge and class and profession trainers. Nearby, Steelgrill's Depot and other workshops provide mechanized engineering supplies.",al={"kharanos trainers","what is in kharanos","kharanos inn"},gp=true},{q="What threats endanger the town?",a="Aggressive Frostmane troll tribes hold Shimmer Ridge to the northwest, while predatory wendigo roam the icy caves directly to the west.",al={"kharanos enemies","frostmane trolls kharanos","wendigo kharanos"},it="threat"},{q="Who lives in Kharanos?",a="Kharanos is a bustling settlement inhabited primarily by Bronzebeard dwarves alongside gnomish refugees and engineers. Craftspeople, smiths, distillers, and military recruits mingle here, patronizing the local forge, gnomish workshops, and the famous Thunderbrew Distillery. While no single lord governs it openly, it operates as a vital local hub and garrison for Ironforge's forces in Dun Morogh.",al={"who lives here kharanos","who runs kharanos","kharanos residents"},it="residents",add="2ba82cf7"},{q="Is Kharanos dangerous?",a="The town itself is heavily guarded and safe behind dwarf patrols, but the surrounding wilderness poses constant danger. Savage wendigo prowl caverns directly to the west, while hostile Frostmane trolls hold fortified positions atop Shimmer Ridge to the northwest. The town stays on high alert, regularly dispatching recruits to keep Dun Morogh's predators and encroaching trolls at bay.",al={"is kharanos safe","kharanos danger","threats in kharanos"},it="danger",add="d56d3e20"}},ang={["race:Dwarf"]="For dwarves leaving Coldridge Valley's sheltered crags, Kharanos is their first taste of the wider kingdom. Its forges steam, and the Thunderbrew clan's stout is legendary.",["race:Gnome"]="Refugees and tinkerers from Gnomeregan often make their homes in and around Kharanos. They work with local smiths and out of nearby depots."},kw={"distillery","dun morogh","frostmane","kharanos","shimmer ridge","thunderbrew"},rel={"zone:dunmorogh","subzone:thunderbrew-distillery","zone:ironforge","subzone:anvilmar","subzone:shimmer-ridge","subzone:steelgrill-s-depot","subzone:gol-bolar-quarry","topic:dwarf"},src={"Kharanos"}}
E["subzone:misty-pine-refuge"] = {t="subzone",n="Misty Pine Refuge",z="dunmorogh",s="In central Dun Morogh, the Argent Dawn keeps a small outpost at Misty Pine Refuge.",h="In central Dun Morogh, the Argent Dawn keeps a small outpost at Misty Pine Refuge.",sec={{t="Shelter in the Snow",b="Misty Pine Refuge is an unassuming Argent Dawn outpost among Dun Morogh's windswept hills. Ironforge mountaineers patrol the crags nearby. Father Gavin, the order's lone agent here, keeps a quiet hearth amid bitter cold and danger on the mountain roads.",sp=0}},faq={{q="What is Misty Pine Refuge?",a="The Argent Dawn keeps a small outpost at Misty Pine Refuge in central Dun Morogh. Father Gavin is the order's only agent there.",al={"what is this place","misty pine","misty pine refuge overview"},it="place"},{q="Why is the Argent Dawn here in Dun Morogh?",a="The Argent Dawn chiefly watches the undead menace in the north. Agents such as Father Gavin also keep watch in quieter corners of Alliance lands.",al={"why argent dawn here","father gavin argent dawn","argent dawn dwarf lands"},it="purpose"},{q="Who stays at the refuge?",a="Father Gavin, an Argent Dawn agent, is the order's only member stationed at Misty Pine Refuge.",al={"who is at misty pine","misty pine npcs"},it="residents"},{q="Is Misty Pine Refuge dangerous?",a="No, the refuge itself is a safe haven amidst the cold wilderness of Dun Morogh. It is an outpost of the Argent Dawn under the watchful eye of Father Gavin, though the snowy wilds surrounding it still carry the usual perils of prowling beasts and troggs.",al={"is misty pine refuge safe","misty pine refuge danger","threats at misty pine refuge"},it="danger",add="f4fbb46a"}},ang={["class:Priest"]="As a priest, you can see Father Gavin's humble post as an example of the Light's service through quiet vigilance, far from the battlefields."},kw={"argent dawn","dun morogh","father gavin","misty pine refuge"},rel={"zone:dunmorogh","topic:argent-dawn","topic:dwarf"},src={"Misty Pine Refuge"}}
E["subzone:north-gate-outpost"] = {t="subzone",n="North Gate Outpost",z="dunmorogh",s="At North Gate Outpost, mountaineers guard the road where Dun Morogh meets Loch Modan. Their patrols shield travelers from beasts in the crags.",h="At North Gate Outpost, mountaineers guard the road where Dun Morogh meets Loch Modan.",sec={{t="Guards of the Pass",b="Dwarven mountaineers watch North Gate Pass from the outpost. They guard travelers heading through the mountain tunnels into Loch Modan. The pass marks Dun Morogh’s northeastern edge, where harsh weather and steep ravines make patrols perilous. When patrols go missing or predators threaten the road, the garrison calls on travelers to scout the ridges.",sp=0}},faq={{q="What is North Gate Outpost used for?",a="North Gate Outpost gives the mountaineers a post from which to guard North Gate Pass, the northern road between Dun Morogh and Loch Modan. They drive back wild beasts to keep the route open to trade and travel.",al={"north gate outpost purpose","why is north gate outpost here"},it="purpose"},{q="Where does the road through the pass lead?",a="The road runs east through mountain tunnels into Loch Modan, or west toward Kharanos and Ironforge.",al={"where does north gate pass go","road past north gate outpost"}},{q="Why do the mountaineers need help from travelers?",a="Territorial beasts prowl the snowy cliffs, and mountaineers have gone missing in the crags while hunting them. The garrison needs scouts to search for the missing mountaineers and learn their fates.",al={"north gate outpost quests","missing mountaineers"},it="threat"},{q="What is North Gate Outpost?",a="North Gate Outpost is the northeasternmost dwarven settlement in Dun Morogh. Nestled high in North Gate Pass, it sits along the vital mountain roadway that connects Dun Morogh in the west to the valley of Loch Modan to the east, serving as a fortified checkpoint for travelers and supply caravans.",al={"what is north gate outpost","north gate outpost lore","tell me about north gate outpost"},it="place",add="c46f381d"},{q="Who lives in or runs North Gate Outpost?",a="The outpost is manned by dwarven mountaineers tasked with patrolling the high pass and safeguarding travel between Dun Morogh and Loch Modan. They maintain a watchful eye over the icy road, though harsh weather and aggressive beasts keep their small garrison stretched thin.",al={"who is at north gate outpost","who runs north gate outpost","north gate outpost residents"},it="residents",add="650c30dc"},{q="Is North Gate Outpost dangerous?",a="While the outpost itself offers shelter, the surrounding pass is perilous. Encroaching mountain predators frequently threaten the perimeter, and several mountaineers have recently gone missing in the snows while tracking down particularly ferocious beasts that stalk the crags.",al={"is north gate pass dangerous","dangers near north gate outpost","threats north gate outpost"},it="danger",add="5e6548b7"},{q="Why is it called North Gate Outpost?",a="The outpost takes its name from North Gate Pass, the northern mountain corridor it guards. Positioned directly in the middle of this transit route, it serves as the northern gateway connecting Dun Morogh to Loch Modan.",al={"why north gate outpost","north gate outpost name","how did north gate outpost get its name"},it="name",add="aaf153dc"}},ang={["race:Dwarf"]="As a dwarf, you know the mountaineers’ duty: keeping the highland passes open through freezing weather and prowling predators.",["race:Gnome"]="As a gnome, you can use your wits and marksmanship to help the dwarven garrison track down lost patrols."},kw={"dun morogh","ironforge","loch modan","mountaineers","north gate outpost","north gate pass"},rel={"subzone:north-gate-pass","zone:dunmorogh","zone:lochmodan","topic:gnome"},src={"North Gate Outpost"}}
E["subzone:shimmer-ridge"] = {t="subzone",n="Shimmer Ridge",z="dunmorogh",s="In northern Dun Morogh, Shimmer Ridge lies west of the Gates of Ironforge, where Frostmane trolls hold two camps across a chasm. Shimmerweed grows nowhere else.",h="In northern Dun Morogh, Shimmer Ridge lies west of the Gates of Ironforge, where Frostmane trolls hold two...",sec={{t="A Frostmane Stronghold",b="Frostmane trolls hold camps on both sides of a chasm, joined by a rickety wooden bridge. Troll scavengers and tamed mountain boars guard the rocky heights. The ridge lies near the main road and the dwarven capital, giving the trolls a place to raid travelers and mountain patrols.",sp=0},{t="The Price of Shimmerweed",b="Frostmane trolls grow shimmerweed on the ridge. Dwarven brewmasters prize the plant for the potent, flavorful highland ales it makes. Since it is hard to gather elsewhere, mountaineers and young recruits brave troll ambushes and tusked beasts to harvest it from the trolls' plots.",sp=0}},faq={{q="Where is Shimmer Ridge located?",a="Shimmer Ridge lies in northern Dun Morogh, west of the Gates of Ironforge, which lead into the dwarven capital.",al={"shimmer ridge location","where is shimmer ridge","find shimmer ridge"},it="place",gp=true},{q="Who controls Shimmer Ridge?",a="Frostmane trolls control Shimmer Ridge. They guard two camps joined by a bridge, with tamed mountain boars.",al={"who lives at shimmer ridge","shimmer ridge enemies","trolls at shimmer ridge"},it="residents"},{q="What is shimmerweed and why is it sought after?",a="Shimmerweed is a mountain herb that grows on Shimmer Ridge. Local dwarven brewers value it for flavorful highland ale.",al={"shimmerweed use","what is shimmerweed","shimmer weed purpose"},it="item"},{q="Why don't the dwarves clear out the trolls completely?",a="Ironforge's military is occupied with broader defense and external matters. Regional mountaineers and wandering recruits handle local threats like the Frostmane camps in Dun Morogh.",al={"why ironforge ignores shimmer ridge","ironforge vs frostmane","dwarf response shimmer ridge"},it="conflict"},{q="What is Shimmer Ridge?",a="Shimmer Ridge is a rugged highland nestled in northern Dun Morogh, situated just west of the massive Gates of Ironforge. It is a hostile territory dominated by Frostmane trolls, who have carved out two distinct encampments across the heights, connected by a wooden bridge. In addition to harboring troll warbands and their tamed boars, the ridge is famous for producing shimmerweed, a potent local plant prized by nearby dwarven brewers.",al={"what is shimmer ridge","shimmer ridge overview","tell me about shimmer ridge"},it="place",add="92b9c418"},{q="Is Shimmer Ridge dangerous?",a="Yes, it is quite hazardous for unseasoned travelers. The Frostmane trolls living across the ridge are intensely hostile to outsiders and vigorously guard their camps and shimmerweed patches. Between aggressive troll defenders and the wild boars they keep and tame, anyone venturing up the heights without caution risks being quickly overwhelmed by local warbands.",al={"is shimmer ridge safe","shimmer ridge dangers","how dangerous is shimmer ridge"},it="danger",add="aaffe09f"},{q="Why is it called Shimmer Ridge?",a="The origin of the name is unknown. The ridge is known for shimmerweed, which the Frostmane trolls grow and dwarven brewers seek for ale.",al={"shimmer ridge name origin","why is it named shimmer ridge","where does the name shimmer ridge come from"},it="name",add="e59eca35"}},ang={["race:Dwarf"]="As a dwarf, you can see the Frostmane threat from Ironforge's gates. Shimmer Ridge is a dangerous source of shimmerweed for dwarven stout.",["profession:Herbalism"]="As an herbalist, you can gather shimmerweed on Shimmer Ridge, where Frostmane trolls tend it among their camps."},kw={"dun morogh","frostmane","ironforge","mountaineers","shimmer ridge","shimmerweed","trolls"},rel={"zone:dunmorogh","subzone:gates-of-ironforge","zone:ironforge","topic:troll"},src={"Shimmer Ridge"}}
E["subzone:south-gate-outpost"] = {t="subzone",n="South Gate Outpost",z="dunmorogh",s="At South Gate Outpost, mountaineers guard the pass between Dun Morogh and Loch Modan. Their fortified post watches the southern road from Ironforge's frigid heights to the Loch's temperate valley.",h="At South Gate Outpost, mountaineers guard the pass between Dun Morogh and Loch Modan.",sec={{t="Watchers of the Southern Road",b="At South Gate Outpost, snowy slopes give way to Loch Modan's basin. Ironforge mountaineers patrol the rocky switchbacks and keep dangerous wildlife off the main highway. Their kin at North Gate Outpost face a harder fight, but the southern road is largely secure. Travelers, pilgrims, and trade wagons can reach Thelsamar in relative safety.",sp=0}},faq={{q="What is the purpose of South Gate Outpost?",a="Mountaineers hold South Gate Outpost as a fortified border checkpoint and garrison along South Gate Pass. They keep the snowy road clear of mountain beasts and hostile interlopers traveling between Dun Morogh and Loch Modan.",al={"why is south gate outpost here","south gate outpost purpose","what is south gate outpost"},it="purpose"},{q="Why is it so much calmer here than at North Gate Outpost?",a="South Gate's garrison has culled aggressive wildlife beside the road. North Gate Outpost faces heavier incursions and wilder mountain terrain, leaving the southern pass comparatively calm.",al={"difference between north gate and south gate","is south gate safe","south gate vs north gate"}},{q="Where does the road through South Gate Outpost lead?",a="Westward, the road climbs through the pass into Dun Morogh's snowy highlands toward Ironforge. Eastward, it descends into Loch Modan's temperate valley, then winds toward Thelsamar.",al={"where does this road go","south gate road destination","south gate pass path"}},{q="What is South Gate Outpost?",a="South Gate Outpost is a fortified dwarven mountain waystation nestled along South Gate Pass in eastern Dun Morogh. It sits directly on the snowy high pass connecting Dun Morogh to the wider valley, welcoming travelers and couriers journeying east toward Thelsamar.",al={"what is south gate outpost","south gate outpost info","south gate pass outpost"},it="place",add="3c6e6693"},{q="Who lives in or runs South Gate Outpost?",a="Ironforge mountaineers man this remote border station. They keep watch over travelers traversing the pass, manage supplies, and coordinate closely with local patrolmen to ensure secure transit through the mountain corridors between Dun Morogh and Loch Modan.",al={"who controls south gate outpost","who runs south gate outpost","who lives at south gate outpost"},it="residents",add="790564b9"},{q="Is South Gate Outpost dangerous?",a="The outpost itself is quite safe. The stationed mountaineers have diligently cleared out most of the encroaching mountain wildlife along the pass, sparing this station from the violent creature attacks and harsh pressures facing North Gate Outpost.",al={"is south gate safe","is south gate outpost dangerous","danger south gate outpost"},it="danger",add="94f233ba"},{q="Why is it called South Gate Outpost?",a="It takes its name from South Gate Pass, the southern mountain gap carved through the crags between Dun Morogh and Loch Modan, as opposed to the northern crossing defended by North Gate Outpost.",al={"why is it called south gate outpost","south gate outpost name origin","why south gate"},it="name",add="09ad7c8c"}},ang={["race:Dwarf"]="For dwarves leaving Coldridge Valley and Dun Morogh for the first time, South Gate Outpost is the last chilly landmark before the descent into Loch Modan's vibrant, sunlit lands.",["faction:Alliance"]="For the Alliance, South Gate Outpost offers dependable military shelter along one of Khaz Modan's primary domestic supply lines. It keeps the passage between the capital and eastern settlements open."},kw={"dun morogh","dwarf","ironforge road","loch modan","mountaineers","south gate outpost","south gate pass","thelsamar"},rel={"subzone:south-gate-pass","zone:lochmodan","zone:dunmorogh","subzone:thelsamar","subzone:north-gate-outpost","subzone:the-loch"},src={"South Gate Outpost"}}
E["subzone:steelgrill-s-depot"] = {t="subzone",n="Steelgrill's Depot",z="dunmorogh",s="East of Kharanos, Steelgrill's Depot keeps Alliance vehicles and machinery working. Beldin Steelgrill and his crew repair them, supply tinkerers, and salvage what they can.",h="East of Kharanos, Steelgrill's Depot keeps Alliance vehicles and machinery working.",sec={{t="A Bastion of Steam and Steel",b="Just off the snowy road, dwarven miners and eccentric gnome engineers gather among heavy machinery, mechanized walking frames, and raw ore from nearby quarries. Metal clanks, steam vents hiss, and experimental engines churn. Trogg disruptions and shortages of mechanical supplies trouble Dun Morogh. In the bitter cold, travelers come for spare parts or technical guidance.",sp=0}},faq={{q="What is Steelgrill's Depot?",a="Steelgrill's Depot sits just down the road east of Kharanos. It is a workshop and outpost in Dun Morogh, where miners, tinkerers, and field technicians tend heavy machinery.",al={"steelgrill depot","what is this place","steelgrills"},it="place"},{q="Who runs the depot?",a="Beldin Steelgrill manages the depot with his fellow dwarven and gnomish crafters. Together, they maintain the surrounding machinery and oversee mining operations.",al={"who leads steelgrills","who runs steelgrill depot","belbi steelgrill"},it="residents"},{q="What services are available here?",a="The depot has trade suppliers, repair services, and trainers who help craftsmen hone their engineering and gathering skills in the field.",al={"trainers at steelgrills","what can i do here","steelgrills depot services"},gp=true},{q="Is Steelgrill's Depot dangerous?",a="Not directly. Steelgrill's Depot is a secure dwarven work camp and trade stop nestled safely along the snowy road east of Kharanos. While the surrounding crags and hills crawl with wild beasts, roaming troggs, and pesky leper gnomes fleeing the fall of Gnomeregan, the depot itself remains firmly in Alliance hands, guarded by hearty miners, craftworkers, and nearby mountaineers.",al={"is steelgrills depot dangerous","steelgrills depot danger","is it safe at steelgrills depot"},it="danger",add="01d49f70"},{q="Why is it called Steelgrill's Depot?",a="The outpost takes its name from Beldin Steelgrill, the master engineer and entrepreneur overseeing operations here. Beldin and his fellow artisans established this wayside camp to service, assemble, and test dwarven and gnomish mechanical marvels, siege machinery, and mining gear just outside the busy settlement of Kharanos.",al={"why steelgrills depot","who is steelgrill","steelgrill name origin"},it="name",add="14c76990"}},ang={["profession:Engineering"]="As an aspiring engineer traveling through Dun Morogh, you can rest at this open-air laboratory, surrounded by steam machinery and tinkering supplies.",["race:Gnome"]="As a gnome, you may work with your dwarven hosts at the depot. Exiled gnomish tinkers often use its forge fires and spare components to keep their salvaged contraptions running."},kw={"belbi steelgrill","dun morogh","engineering","kharanos","steelgrill","steelgrill's depot","workshop"},rel={"subzone:kharanos","zone:dunmorogh","zone:gnomeregan"},src={"Steelgrill's Depot"}}
E["subzone:thunderbrew-distillery"] = {t="subzone",n="Thunderbrew Distillery",z="dunmorogh",s="In Kharanos, Thunderbrew Distillery offers travelers ale and shelter. Its brewhouse and tavern draw mountain travelers, while mentors and tradesfolk share their skills within.",h="In Kharanos, Thunderbrew Distillery offers travelers ale and shelter.",sec={{t="The Warm Hearth of Kharanos",b="The Thunderbrew Distillery anchors Kharanos in southern Dun Morogh. Arkilus Thunderbrew founded its brewhouse, and his kin have kept it in the family. Its strong ales are known across Khaz Modan for warming those who face the mountain cold. Innkeeper Belm manages the inn, where weary mountaineers find a fire, hearty food, and beds beyond the blizzards outside.",sp=0},{t="A Crossroads of Knowledge and Craft",b="Kharanos is the first major settlement travelers reach after leaving Coldridge Valley. Beneath the distillery’s timber rafters, instructors teach martial arts, holy rites, arcane studies, and roguecraft. Teachers also offer cooking and first aid. The hall pours its well-known stouts and gives travelers a place to prepare for the road ahead.",sp=0}},faq={{q="Who owns and operates the Thunderbrew Distillery?",a="The Thunderbrew family owns the distillery, founded by Arkilus Thunderbrew. His son Ragnar Thunderbrew tends the family brewing traditions, while Innkeeper Belm looks after guests and their rooms in Kharanos.",al={"distillery owner","who runs thunderbrew","thunderbrew family"},it="residents"},{q="What services are available inside the distillery?",a="The distillery is Kharanos’s main inn. Innkeeper Belm can bind your hearthstone, vendors sell drinks and supplies, and trainers teach warriors, paladins, priests, mages, rogues, cooking, and first aid.",al={"what is in thunderbrew distillery","distillery trainers","kharanos inn services"},gp=true},{q="Why is the distillery so famous?",a="The distillery is famed across the Eastern Kingdoms for potent dwarven ales, especially Thunderbrew Ale. Travelers know its brews for fortifying them against the freezing cold of the Dun Morogh peaks.",al={"why is thunderbrew ale famous","thunderbrew ale reputation"},it="fame"},{q="What is the Thunderbrew Distillery?",a="The Thunderbrew Distillery is a bustling dwarven tavern and inn standing at the heart of Kharanos. Beyond offering warm beds, hearthstones, and hearty drinks, it serves as the community's primary gathering place where mountaineers, craftsmen, class mentors, and travelers rest and share news from across Dun Morogh.",al={"what is thunderbrew distillery","thunderbrew tavern","distillery in kharanos"},it="place",add="1fa2ba89"},{q="What is the history of the Thunderbrew Distillery?",a="Founded by the dwarven brewer Arkilus Thunderbrew, the distillery has stood for generations as one of Dun Morogh's finest breweries. Today, it remains family-run under his son Ragnar and continues crafting its famed ales.",al={"distillery history","history of thunderbrew distillery","who founded thunderbrew distillery"},it="history",add="6c9338b8"},{q="Is the Thunderbrew Distillery dangerous?",a="Not at all. The distillery is a safe haven for travelers and Alliance defenders, well protected by mountaineers and town guards from the troggs, frost trolls, and hungry beasts wandering the snowy hills outside Kharanos.",al={"is thunderbrew distillery dangerous","distillery safe","is it safe here"},it="danger",add="ec3a2fd6"},{q="Why is it called the Thunderbrew Distillery?",a="The distillery takes its name from the Thunderbrew family, who founded and maintained the business across generations, as well as the potent dwarven ales they brew inside its cellars.",al={"why is it named thunderbrew distillery","origin of thunderbrew name","thunderbrew distillery name"},it="name",add="1194a384"}},ang={["race:Dwarf"]="As a dwarf leaving Coldridge Valley, you find familiar stout, a seat by the hearth, and trusted mentors in iron and faith at the distillery.",["profession:Cooking"]="The distillery kitchen offers cooking instruction and supplies. Stop here to learn to prepare hearty mountain provisions."},kw={"dun morogh","dwarven ale","innkeeper belm","kharanos","ragnar thunderbrew","thunderbrew distillery"},rel={"subzone:kharanos","npc:ragnar-thunderbrew","zone:dunmorogh","npc:marleth-barleybrew","quest:117"},src={"Thunderbrew Distillery"}}
E["subzone:tundrid-hills"] = {t="subzone",n="Tundrid Hills",z="dunmorogh",s="In south-central Dun Morogh, the Tundrid Hills offer a perilous crossing west of Gol'Bolar Quarry. Snowbound ridges and dangerous wildlife make every step off the rocky passes a risk.",h="In south-central Dun Morogh, the Tundrid Hills offer a perilous crossing west of Gol'Bolar Quarry.",sec={{t="A Treacherous Wilderness",b="From Coldridge Valley, the Tundrid Hills give you a rough way into eastern Dun Morogh, away from the main roads through Kharanos. Jagged slopes hold the snow, and the crossing is dangerous. Ferocious predators prowl the hills, so keep a weapon ready if you leave the beaten path.",sp=0}},faq={{q="Where are the Tundrid Hills located?",a="The Tundrid Hills cross south-central Dun Morogh, west of Gol'Bolar Quarry. They rise south of the main road from Kharanos to the eastern lands.",al={"tundrid hills location","where is tundrid hills","tundrid hills map"},it="place"},{q="Why would anyone travel through the Tundrid Hills?",a="You can cross overland from Coldridge Valley to eastern Dun Morogh through the Tundrid Hills. The route bypasses established settlement routes, but is far more hazardous than the patrolled roads.",al={"why go to tundrid hills","tundrid hills shortcut"},it="purpose"},{q="What threats can be found in the Tundrid Hills?",a="Fierce wildlife adapted to the freezing heights lives in the Tundrid Hills. Few travelers venture there without a weapon at hand.",al={"what lives here","tundrid hills enemies","monsters in tundrid hills"},it="threat"},{q="Is traveling through the Tundrid Hills dangerous?",a="Yes, traversing these snowy hills is considerably more hazardous than sticking to the patrolled roads. The heights are populated by fierce, predatory wildlife and offer no organized dwarven guard patrols or shelter. While it provides a direct shortcut between Coldridge Valley and eastern Dun Morogh, few travelers venture off the beaten path without a ready weapon and a watchful eye.",al={"are the tundrid hills dangerous","tundrid hills danger","is it safe in tundrid hills"},it="danger",add="6d54f98b"}},ang={["race:Dwarf"]="As a dwarf of Ironforge, you know these heights remind you how wilderness and hostile Frostmane trolls press close to Dun Morogh's heartland.",["class:Hunter"]="As a hunter, you can track hardy beasts adapted to Dun Morogh's punishing mountain chill across these wind-battered crags."},kw={"coldridge valley","dun morogh","frostmane","gol'bolar quarry","ironforge","kharanos","tundrid hills"},rel={"zone:dunmorogh","subzone:gol-bolar-quarry","subzone:coldridge-valley","subzone:kharanos","topic:troll"},src={"Tundrid Hills"}}
E["topic:frostmane-tribe"] = {t="topic",n="Frostmane tribe",z="dunmorogh",s="Across Dun Morogh, the Frostmane tribe fights to reclaim the mountain home dwarves took from them. Driven into caves and remote ridges centuries ago, the ice trolls now wage war against the dwarves.",h="Across Dun Morogh, the Frostmane tribe fights to reclaim the mountain home dwarves took from them.",sec={{t="Exiles of the High Crags",b="Long before the Bronzebeard clan united under Ironforge, the Frostmane trolls ruled Dun Morogh’s snowy reaches. As the dwarven kingdom spread, it crushed their realm. The survivors fled into caves and across frozen ridges and crags.\n\nDefeat left the Frostmane with a hatred passed down through generations. They see every mountaineer, traveler, and homestead as an invader to drive out or slaughter.",sp=0},{t="A Seized Opportunity",b="For decades, the Ironforge Senate treated the Frostmane as little more than a nuisance in the hills. Then the trogg menace emerged beneath Dun Morogh, and dwarven defenses fell into disarray. The mountaineers were overwhelmed while dwarven forces fought Alliance wars abroad.\n\nThe Frostmane seized their chance. From strongholds such as Frostmane Hold and Shimmer Ridge, they renewed their violent raids to reclaim their ancient lands.",sp=0},{t="Raiders of the Valleys",b="The Senate of Ironforge came to recognize the growing danger. It sent Grelin Whitebeard and his brother Senir to confront the Frostmane. From the caves of Frostmane Hold and the heights of Shimmer Ridge, the trolls strike at dwarves.\n\nIn Coldridge Valley, war leaders such as Grik'nir the Cold direct aggressive incursions against the mountaineers.",sp=1}},faq={{q="Who are the Frostmane trolls?",a="The Frostmane are ice trolls native to Dun Morogh’s snowy crags. They ruled the region until dwarven armies defeated them centuries ago and drove them into the high ridges.",al={"frostmane lore","what are frostmane","dun morogh trolls"},it="identity"},{q="Why are the Frostmane attacking the dwarves now?",a="Trogg invasions have strained the dwarven mountaineers while their forces fight Alliance wars abroad. The Frostmane see a chance to reclaim their ancestral hunting grounds and take revenge on Ironforge.",al={"why do frostmane attack","frostmane uprising","troll attacks dun morogh"},it="hostile"},{q="Who leads the Frostmane tribe?",a="The Frostmane raid from Frostmane Hold and Shimmer Ridge. In Coldridge Valley, war leaders such as Grik'nir the Cold lead bands that harry the dwarves.",al={"frostmane leader","chief of frostmane","who runs the frostmane"},it="leader"},{q="What happened to Frostmane Hold?",a="Frostmane Hold remains a troll stronghold in the hills of Dun Morogh, and the Frostmane launch raids from its caves. The Senate of Ironforge sent Grelin Whitebeard and his brother Senir to face the threat.",al={"frostmane hold troggs","what happened to troll cave","why did trolls leave hold"},it="place"},{q="What is Shimmerweed, and why do the trolls gather it?",a="Shimmerweed is a hardy plant that grows in Shimmer Ridge’s bitter winds. The Frostmane cultivate and harvest it for sacred tribal rituals, while dwarven brewers prize it for potent stout.",al={"shimmerweed","frostmane shimmerweed","what is shimmerweed used for"},it="item"},{q="Are the Frostmane aligned with the Horde?",a="No. The Frostmane are independent ice trolls who hate outsiders and attack travelers and explorers regardless of faction.",al={"are frostmane horde","frostmane faction","frostmane friendly to horde"},it="allies"},{q="Why are the Frostmane trolls in Dun Morogh?",a="The Frostmane view the snowy peaks of Dun Morogh as their ancestral homeland. Long before Ironforge rose to power, their forebears ruled these mountains until dwarven armies broke their empire and forced them into the frigid hills. Today, scattered camps like Frostmane Hovel and Shimmer Ridge serve as bases for their ongoing guerrilla war to reclaim their lost territory from the dwarves.",al={"why are frostmane in dun morogh","why are trolls in dun morogh","frostmane dun morogh why"},it="why_here",add="a2fffb42"},{q="What is the history of the Frostmane tribe?",a="The Frostmane once held dominion over the snowy crags of Dun Morogh, only to see their realm broken by the rise of the dwarves, who drove them into the high ridges. Reduced to remote caves and camps, they have waged a persistent war against Ironforge ever since.",al={"frostmane history","where did frostmane trolls come from","frostmane origins","frostmane lore"},it="history",add="4f875446"}},ang={["race:Dwarf"]="For dwarves, the Frostmane recall ancestral blood feuds. The mountaineers’ defense of Dun Morogh is deeply personal.",["race:Troll"]="As a Darkspear troll, you share the broad heritage of trollkind. The isolated Frostmane are savage ice trolls with little interest in kinship, and they treat Horde visitors as intruders on their sacred peaks.",["profession:Cooking"]="Crag boars and other beasts kept around Frostmane encampments provide rough game meat for hearthside rations in Dun Morogh’s biting snows."},kw={"battok","coldridge valley","dun morogh","frostmane","frostmane hold","grik'nir","ice troll","shimmer ridge"},rel={"zone:dunmorogh","subzone:coldridge-valley","quest:182","quest:287","subzone:shimmer-ridge","subzone:frostmane-hovel","topic:trogg","npc:grelin-whitebeard"},src={"Frostmane tribe"}}
E["zone:dunmorogh"] = {t="zone",n="Dun Morogh",z="dunmorogh",s="Dun Morogh is high snow country, the mountain home of the dwarves. The gnomes shelter here too, for they have lost their own home. But the snows are not safe. Troggs and Frostmane trolls prowl them, and so do the leper gnomes.",h="Dun Morogh is high snow country, the mountain home of the dwarves.",sec={{t="A Mountain Stronghold",b="The mountains rise between Searing Gorge in the south and the Wetlands in the north. Their snowmelt feeds the rivers of Khaz Modan, and copper and iron run in veins through the rock. Dwarven Mountaineers watch the narrow roads at the north and south gates. And beneath the tallest mountain lies Ironforge, the seat of King Magni Bronzebeard.",sp=0},{t="A Refuge Divided",b="Centuries ago, the dwarves drove the native Frostmane ice trolls up into the crags. So they made room for themselves, beside their gnome allies. The two peoples thrived in neighboring mountain halls, until the Third War. Then Gnomeregan fell.\n\nTroggs invaded the gnomes' city, and radioactive gas ruined it. Its own defenders were twisted into leper gnomes. High Tinker Gelbin Mekkatorque led the survivors into exile, and now they live as guests in Ironforge. But the leper gnomes and the troggs spill out into Chill Breeze Valley.",sp=0},{t="Trouble in the Drifts",b="The Frostmane have grown bolder, with armed camps from Shimmer Ridge to Coldridge Valley. Troggs have clawed up from old fissures into Gol'Bolar Quarry, and the mines are in danger. Wendigos and wild boars roam the drifts, and the Dark Iron dwarves send in their spies. Toxic fallout spreads from the ruins of Gnomeregan. The Mountaineers struggle to keep order, from Kharanos to the border gates.",sp=0}},faq={{q="What races start in Dun Morogh?",a="Dwarves and gnomes begin their journeys in Coldridge Valley, in the southwest of Dun Morogh. As a dwarf, you come from this ancestral homeland. From Anvilmar’s hearthfires to the Great Forge’s blazing core, you defend these peaks from trolls and troggs in service to King Magni Bronzebeard.",al={"dun morogh starting race","who starts here","dwarf start zone","gnome start zone"},it="residents",gp=true},{q="What happened to Gnomeregan?",a="During the Third War, troggs swarmed Gnomeregan from below. High Tinker Gelbin Mekkatorque released radioactive gas into the lower levels to purge them, but the plan failed. Thousands died, many gnomes became crazed leper gnomes, and the healthy survivors fled to Ironforge.",al={"why is gnomeregan ruined","what happened to the gnomes","why are leper gnomes here"},it="ruin"},{q="How do you leave Dun Morogh on foot?",a="High mountain ridges surround Dun Morogh. To reach Loch Modan on foot, follow the roads to North Gate Pass or South Gate Pass in the northeastern mountains. From Ironforge, the Deeprun Tram carries travelers directly to Stormwind City.",al={"exit dun morogh","dun morogh to loch modan","leave dun morogh"},gp=true},{q="Where is the flight master in Dun Morogh?",a="The zone’s only functional Alliance flight master is inside Ironforge’s Great Forge. The flight routes connect travelers with places across Khaz Modan, Stormwind, and the northern Alliance outposts.",al={"dun morogh flight master","dun morogh flight path","where to fly dun morogh"},it="place",gp=true},{q="Who are the Frostmane trolls?",a="The Frostmane are ice trolls who ruled Dun Morogh long before the dwarves emerged from Uldaman. Dwarves defeated them and drove them into the crags generations ago, but they remain bitter enemies of Ironforge and raid farms and roads from retreats such as Frostmane Hold.",al={"why are there trolls in dun morogh","dun morogh trolls","frostmane tribe"},it="threat"},{q="What is Kharanos?",a="Kharanos is the main dwarven settlement in central Dun Morogh. It has the Thunderbrew Distillery, trainers, and supplies, and Mountaineers and young adventurers use it as a base against local trolls and wildlife.",al={"town in dun morogh","kharanos hub","what is the main town"},it="place"},{q="What is Dun Morogh?",a="Dun Morogh is a high, snowy mountain region in western Khaz Modan. Ringed on all sides by towering peaks, it forms the ancestral heartland of the Ironforge dwarves and the refuge of the gnomes. The realm is known for its bitter cold, dense pine forests, frozen lakes, and vast mineral wealth. It houses the magnificent mountain citadel of Ironforge along its northern ridges, as well as the besieged techno-city of Gnomeregan tucked away in the western hills.",al={"what is this place","where are we","dun morogh zone"},it="place",add="ee70a2d7",nx={8}},{q="What happened in Dun Morogh's past?",a="Dun Morogh was originally held by the Frostmane ice trolls. The dwarves and gnomes later settled these snowy peaks and forged a lasting kinship, building Ironforge and Gnomeregan while pushing the Frostmane back into the remote crags. During the Second War, dwarven and gnomish defenders successfully held their mountain fortresses against the orcish Horde. Today, the peaceful lands face unrest following the fall of Gnomeregan and rising trogg incursions.",al={"dun morogh history","history of dun morogh","what happened here"},it="history",add="8c7c9511"},{q="Who lives in and rules Dun Morogh?",a="Dun Morogh is governed primarily by King Magni Bronzebeard from his throne in the mountain fortress of Ironforge. The Bronzebeard dwarves maintain mountain garrisons, outposts, and watchtowers across the passes. Dun Morogh is also home to the gnomes, whose leader High Tinker Gelbin Mekkatorque and surviving populace currently shelter alongside their dwarven allies following the tragic loss of Gnomeregan. Beyond the settlements, Frostmane trolls and primitive troggs contest dwarven authority in the wild crags and quarries.",al={"who rules dun morogh","who controls dun morogh","who lives here"},it="in_charge",add="4399d516"},{q="Is Dun Morogh dangerous?",a="While the highways and towns are guarded by dwarven mountaineers, the wilderness presents serious peril. Savage wildlife like grizzly bears, mountain boars, starving wolves, and ferocious wendigos roam the snowbanks. Hostile Frostmane ice trolls mount raids from mountain ridges like Shimmer Ridge and Frostmane Hold. Meanwhile, subterranean troggs have overrun Gol'Bolar Quarry and Coldridge Pass, and radioactive leper gnomes prowl the contaminated outskirts of Gnomeregan.",al={"is dun morogh safe","dun morogh threats","dangers in dun morogh"},it="danger",add="1f8f2322"},{q="Why does everyone want me killing troggs at Gol'Bolar Quarry?",a="Gol'Bolar Quarry in southeastern Dun Morogh is a vital dwarven excavation and mining camp. While digging for stone and precious ore, the miners broke into subterranean tunnels and unearthed hordes of savage troggs. The creatures swarmed into the open pit and the quarry mine, driving back workers and shutting down operations. The mountaineers and overseers rely on able-bodied recruits to wipe out the infesting troggs so the kingdom can reclaim its quarry.",al={"gol bolar troggs","why kill troggs quarry","gol bolar quarry problem"},it="threat",add="6bfc0e90"},{q="Where should I head after Dun Morogh?",a="Once you have completed your tasks in Dun Morogh and reached sufficient experience, your journey naturally leads eastward into Loch Modan. You can pass on foot through either the North Gate Pass or South Gate Pass tunnels, or catch a gryphon ride from the great flight master's roost inside Ironforge directly to the lakeside village of Thelsamar.",al={"where do i go after dun morogh","dun morogh next zone","after dun morogh"},it="next_step",add="bf67ca5d"},{q="How did I end up in Dun Morogh?",a="If you are a dwarf or gnome beginning your journey, you started in the sheltered training grounds of Coldridge Valley before venturing out through the pass into Dun Morogh proper. Dwarves hail from these rugged peaks, while gnome refugees fled here after the fall of Gnomeregan to seek haven with their dwarven allies. Travelers from other kingdoms usually arrive through the grand gates of Ironforge via the Deeprun Tram from Stormwind, or by trekking westward through the mountain passes leading out of Loch Modan.",al={"how did i get here","how did i get to dun morogh","why did i come here"},it="arrival",add="44145090"},{q="What am I supposed to be doing in Dun Morogh?",a="The snowy realm of Ironforge needs every able defender. Hostile Frostmane trolls threaten dwarven settlements from the high ridges, savage troggs have overrun Gol'Bolar Quarry, and mutated leper gnomes prowl the contaminated ruins of Gnomeregan to the west. Local settlements like Kharanos and Brewnall Village desperately need recruits to drive back wild beasts and clear the trails. Lend your strength to secure the region, hone your skills, and prove yourself worthy to answer the broader call of the Alliance.",al={"what should i do here","what is my goal in dun morogh","what am i doing here"},it="purpose",add="8cf74af4"}},ang={["race:Dwarf"]="As a dwarf, you come from this ancestral homeland. From Anvilmar’s hearthfires to the Great Forge’s blazing core, you defend these peaks from trolls and troggs in service to King Magni.",["race:Gnome"]="As a gnome, your lost home of Gnomeregan lies irradiated in the western valley. You make your base in Dun Morogh beside your dwarven cousins while fighting troggs and rogue leper gnomes.",["profession:Mining"]="As a miner, you can find rich surface deposits of Copper Veins in Dun Morogh, especially around Gol'Bolar Quarry and along snowy rock faces.",["profession:Cooking"]="As a cook, you can find hearty fare in Kharanos and Brewnall Village, where hunters and innkeepers make use of boar meat, bear ribs, and dwarven stout against the mountain frost."},kw={"anvilmar","brewnall village","coldridge valley","deeprun tram","dun morogh","frostmane","gnomeregan","gol'bolar","ironforge","kharanos","magni bronzebeard","troggs"},rel={"zone:ironforge","zone:gnomeregan","zone:lochmodan","subzone:kharanos","subzone:coldridge-valley","subzone:deeprun-tram","subzone:gol-bolar-quarry","subzone:anvilmar"},m={levels="1-10"},src={"Dun Morogh (Classic)","Dun Morogh"}}
